window.MYTHICAL_ARCHIVE = {"archiveTitle": "Bestiarium Mundi — Global Archive of Historical Mythical Creature Depictions", "totalCount": 296, "regionCounts": {"Medieval, Celtic & Norse Europe": 31, "East Asia & Eurasian Steppe": 60, "Ancient Near East & Persia": 29, "Egypt & Africa": 28, "South & Southeast Asia": 30, "The Americas & Oceania": 30, "Greece & Aegean": 30, "Etruria, Rome & Byzantium": 28, "Renaissance & Early Modern Europe": 30}, "eraCounts": {"Prehistory & Bronze Age": 31, "Iron Age & Classical Antiquity": 95, "Post-Classical & Medieval": 66, "Renaissance & Early Modern": 55, "Enlightenment & 19th Century": 49}, "morphologyCounts": {"Therianthropic (Human-Beast)": 39, "Draconic & Serpentine": 53, "Composite Chimeras": 59, "Avian & Winged Hybrids": 47, "Single-Horned & Sacred Beasts": 18, "Giants, Demons & Spirits": 47, "Marine & Abyssal Monsters": 33}, "mediumCounts": {"Sculpture & Relief": 108, "Metalwork, Glyptic & Regalia": 44, "Ceramics & Vessels": 26, "Painting & Fresco": 48, "Manuscript & Print": 49, "Mosaic & Glazed Brick": 12, "Textile & Tapestry": 9}, "familyCounts": {"Minotaur, Were-Jaguars & Therianthropes": 18, "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms": 46, "Phoenix, Simurgh, Garuda & Solar Birds": 24, "Griffins & Eagle-Lion Hybrids": 16, "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)": 11, "Unicorns, Qilin & Sacred Horned Beasts": 15, "Gorgons, Taotie, Kirtimukha & Apotropaic Faces": 20, "Chimeras, Ammit, Manticores & Composite Hybrids": 25, "Centaurs, Pegasus, Satyrs & Equine Hybrids": 19, "Lamassu, Apkallu, Buraq & Winged Threshold Spirits": 7, "Cyclopes, Oni, Divs, Giants & Underworld Demons": 31, "Leviathans, Makaras, Kraken & Abyssal Merfolk": 29, "Cerberus, Hydra & Multi-Headed Beasts": 7, "Sirens, Harpies, Kinnara & Avian-Humans": 10, "Sacred Guardian Lions, Bixie, Yali & Tigers": 10, "Kitsune, Tengu, Kappa & Yōkai Metamorphs": 8}, "items": [{"id": "ne-01-lowenmensch", "title": "Löwenmensch (Lion-Man of Hohlenstein-Stadel)", "creature": "Löwenmensch (Lion-Human Therianthrope)", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Löwenmensch", "civilization": "Aurignacian Upper Paleolithic (Swabian Jura)", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Hohlenstein-Stadel Cave, Lonetal, Baden-Württemberg, Germany", "dateDisplay": "c. 38,000 BCE", "yearSort": -38000, "era": "Prehistory & Bronze Age", "medium": "Carved woolly mammoth tusk ivory", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Aurignacian ivory carver", "repository": "Museum Ulm, Ulm, Germany", "commonsFile": "Loewenmensch1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Loewenmensch1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Loewenmensch1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4c/Loewenmensch1.jpg", "anatomy": ["Cave lion head with alert rounded ears and muzzle", "Upright bipedal human torso and legs", "Seven parallel transverse incisions across the left upper arm"], "description": "Carved from a single woolly mammoth tusk using flint stone tools, the 31.1-centimeter Hohlenstein-Stadel figurine is the oldest known zoomorphic-human sculpture in the archaeological record. Combining the head of a European cave lion (Panthera spelaea) with an erect human posture, it offers the earliest material evidence of mythic imagination, shamanic transformation, and supernatural hybridity."}, {"id": "cn-07-sanxingtala-jade-dragon", "title": "C-Shaped Jade Dragon of Sanxingtala", "creature": "Proto-Long (Chinese Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "紅山文化C形玉龍 (C-xíng Yùlóng)", "civilization": "Hongshan Culture (Neolithic China)", "region": "East Asia & Eurasian Steppe", "originLocation": "Sanxingtala, Ongniud Banner, Chifeng, Inner Mongolia", "dateDisplay": "c. 4000–3000 BCE", "yearSort": -3500, "era": "Prehistory & Bronze Age", "medium": "Dark olive-green nephrite jade", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Draconic & Serpentine", "creator": "Unknown Hongshan master lapidary", "repository": "National Museum of China, Beijing", "commonsFile": "Neolithic_jade_dragon,_Hongshan_Culture,_Inner_Mongolia,_1971.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Neolithic_jade_dragon,_Hongshan_Culture,_Inner_Mongolia,_1971.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Neolithic_jade_dragon,_Hongshan_Culture,_Inner_Mongolia,_1971.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/96/Neolithic_jade_dragon,_Hongshan_Culture,_Inner_Mongolia,_1971.jpg", "anatomy": ["sweeping crest-like dorsal mane", "slender C-curved serpentine torso", "elongated upturned snout", "drilled dorsal balancing hole"], "description": "Standing 26 centimeters tall and abraded from a single pebble of dark green nephrite, the Sanxingtala dragon combines an equine or porcine muzzle with a sweeping, wind-blown dorsal mane that curves gracefully above a limbless C-shaped body. Pierced precisely at its center of gravity so it hangs level when suspended on a ritual cord, it bridges Neolithic shamanic jade-working and the classical iconography of the rain-bringing long."}, {"id": "cn-07-hongshan-pig-dragon", "title": "Coiled Jade Pig-Dragon (Zhulong)", "creature": "Zhulong (Pig-Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "玉豬龍 (Yù Zhūlóng)", "civilization": "Hongshan Culture (Neolithic China)", "region": "East Asia & Eurasian Steppe", "originLocation": "Liaoning / Inner Mongolia, China", "dateDisplay": "c. 3500 BCE", "yearSort": -3500, "era": "Prehistory & Bronze Age", "medium": "Carved and polished nephrite jade", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Draconic & Serpentine", "creator": "Unknown Hongshan jade carver", "repository": "British Museum, London", "commonsFile": "British_Museum_Chinese_jade_Neolithic_period_Hongshan_culture_Coiled_dragon_Pig-dragon_11022019_1393.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:British_Museum_Chinese_jade_Neolithic_period_Hongshan_culture_Coiled_dragon_Pig-dragon_11022019_1393.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/British_Museum_Chinese_jade_Neolithic_period_Hongshan_culture_Coiled_dragon_Pig-dragon_11022019_1393.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/dc/British_Museum_Chinese_jade_Neolithic_period_Hongshan_culture_Coiled_dragon_Pig-dragon_11022019_1393.jpg", "anatomy": ["coiled larval C-ring body", "wrinkled porcine snout with tusks", "upright rounded ears", "biconical suspension perforation"], "description": "Carved from pale greenish-buff nephrite during the Late Neolithic Hongshan period, this thick slit-ring pendant curls a plump, embryonic serpent body beneath a blunt, wrinkled boar-like snout and pricked ears. Excavated solely from elite cairn burials across the Liao River basin, the zhulong represents one of the earliest ritual prototypes of the Chinese dragon, linking agrarian fertility with celestial metamorphosis."}, {"id": "ne-01-uruk-serpopard-seal", "title": "Jasper Cylinder Seal with Serpopards and Lion-Headed Eagles", "creature": "Serpopard & Lion-Headed Eagle", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Mušḫuššu / Imdugud prototype", "civilization": "Proto-Sumerian (Late Uruk Period)", "region": "Ancient Near East & Persia", "originLocation": "Southern Mesopotamia (likely Uruk), Iraq", "dateDisplay": "c. 3500–3000 BCE", "yearSort": -3250, "era": "Prehistory & Bronze Age", "medium": "Reddish-brown jasper cylinder seal (MNB 1167)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Unknown Uruk glyptic master", "repository": "Musée du Louvre, Paris", "commonsFile": "Cylinder_seal_lions_Louvre_MNB1167.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Cylinder_seal_lions_Louvre_MNB1167.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Cylinder_seal_lions_Louvre_MNB1167.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8f/Cylinder_seal_lions_Louvre_MNB1167.jpg", "anatomy": ["Muscular feline bodies with elongated, intertwining serpentine necks", "Tufted lion tails curving symmetrically overhead", "Heraldic lion-headed eagles hovering above the intertwined beasts"], "description": "Cut in deep intaglio from polished jasper during Mesopotamia's first urban revolution, this monumental cylinder seal yields a continuous frieze of confronted 'serpopards' whose sinuous necks entwine in perfect symmetry. Above their backs hover early lion-headed raptors, pairing two foundational composite monsters of archaic Near Eastern cosmology."}, {"id": "eg-02-two-dogs-palette-ashmolean", "title": "The Two Dogs Palette ('Oxford Palette') with Serpopards and Winged Griffin", "creature": "Serpopard and Predynastic Comb-Winged Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Sedja / Sefer (Winged Desert Predator)", "civilization": "Predynastic Egypt (Naqada III)", "region": "Egypt & Africa", "originLocation": "Main Deposit, Hierakonpolis (Nekhen), Upper Egypt", "dateDisplay": "c. 3200–3100 BCE", "yearSort": -3150, "era": "Prehistory & Bronze Age", "medium": "Low-relief carved mudstone cosmetic palette", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Predynastic Naqada III sculptor", "repository": "Ashmolean Museum, University of Oxford (AN1896-1908.E.3924)", "commonsFile": "Two_Dogs_Palette_Ashmolean_Museum.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Two_Dogs_Palette_Ashmolean_Museum.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Two_Dogs_Palette_Ashmolean_Museum.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b7/Two_Dogs_Palette_Ashmolean_Museum.jpg", "anatomy": ["serpopards licking a fallen gazelle around the pigment saucer", "raptor-headed feline griffin sprouting comb-like dorsal wings", "jackal-headed flute player charming chaotic desert fauna"], "description": "Framed by two heraldic African wild dogs whose sculpted heads crown the slab, this Predynastic mudstone palette teems with real and supernatural creatures of the untamed desert margin (deshret). Alongside paired long-necked serpopards on the obverse, the reverse preserves one of world art's earliest winged griffins—a slender feline with falcon beak and stiff, comb-patterned wings—pursuing ibexes beside a masked, flute-playing therianthrope."}, {"id": "eg-02-narmer-palette-serpopards", "title": "The Narmer Palette with Intertwined Serpopards", "creature": "Serpopard (Serpent-Necked Leopard)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Sedja (Long-Necked Feline Hybrid)", "civilization": "Early Dynastic Egypt (1st Dynasty)", "region": "Egypt & Africa", "originLocation": "Main Deposit, Temple of Horus at Hierakonpolis (Nekhen)", "dateDisplay": "c. 3100 BCE", "yearSort": -3100, "era": "Prehistory & Bronze Age", "medium": "Carved green-gray siltstone ceremonial palette", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown royal master sculptor of King Narmer", "repository": "Egyptian Museum, Cairo (CG 14716 / JE 32169)", "commonsFile": "Narmer_Palette.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Narmer_Palette.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Narmer_Palette.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/be/Narmer_Palette.jpg", "anatomy": ["lithe leopardess quadruped torso and clawed paws", "impossibly elongated serpentine neck looping in symmetry", "snarling feline head tethered by bearded attendants"], "description": "Dominating the obverse center of this 64-centimeter siltstone ceremonial shield-palette, two confronted serpopards entwine their sinuous, serpent-like necks to frame the circular recess used for grinding malachite eye paint. Adapted from Uruk Mesopotamian glyptic motifs during Egypt's state formation, the tethering of these untamed feline-serpent hybrids symbolizes King Narmer's forcible unification of Upper and Lower Egypt into cosmic order (Maat)."}, {"id": "ne-01-ubaid-imdugud-panel", "title": "Temple Lintel Relief of Imdugud (Anzû) Grasping Two Stags", "creature": "Anzû (Imdugud)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Imdugud / Anzû", "civilization": "Sumerian (Early Dynastic III)", "region": "Ancient Near East & Persia", "originLocation": "Temple of Ninhursag, Tell al-'Ubaid, southern Iraq", "dateDisplay": "c. 2500 BCE", "yearSort": -2500, "era": "Prehistory & Bronze Age", "medium": "Hammered copper alloy sheets over bitumen and wooden core", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Sumerian temple metalworkers", "repository": "British Museum, London (ME 114308)", "commonsFile": "British_Museum_Middle_east_14022019_Panel_Imdugud_2500_BC_3640.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:British_Museum_Middle_east_14022019_Panel_Imdugud_2500_BC_3640.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/British_Museum_Middle_east_14022019_Panel_Imdugud_2500_BC_3640.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/62/British_Museum_Middle_east_14022019_Panel_Imdugud_2500_BC_3640.jpg", "anatomy": ["Roaring lion head projecting fully in the round", "Outspread eagle wings and feathered raptor torso", "Raptor talons clutching the rumps of two antlered stags"], "description": "Excavated at the entrance of the Temple of Ninhursag at Tell al-'Ubaid, this monumental copper-sheathed lintel depicts Imdugud (Akkadian Anzû), the thundercloud bird and divine emblem of Ningirsu. Its three-dimensional roaring lion head projects boldly from the relief plane while its spread eagle wings and talons assert cosmic dominion over twin stags."}, {"id": "eg-02-great-sphinx-giza", "title": "The Great Sphinx of Giza", "creature": "Androsphinx (Royal Solar Sphinx)", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Shesep-ankh ('Living Image') / Hor-em-akhet", "civilization": "Old Kingdom Egypt (4th Dynasty)", "region": "Egypt & Africa", "originLocation": "Giza Plateau, Lower Egypt", "dateDisplay": "c. 2500 BCE", "yearSort": -2500, "era": "Prehistory & Bronze Age", "medium": "Monolithic carved nummulitic limestone bedrock with masonry repairs", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Royal sculptors of Pharaoh Khafre", "repository": "In situ, Giza Necropolis, Egypt", "commonsFile": "Egypt.Giza.Sphinx.01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Egypt.Giza.Sphinx.01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Egypt.Giza.Sphinx.01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c5/Egypt.Giza.Sphinx.01.jpg", "anatomy": ["recumbent leonine body with outstretched forepaws", "human pharaonic head wearing pleated nemes headdress", "brow-mounted royal cobra uraeus (now fragmentary)", "curled feline tail wrapped along the right haunch"], "description": "Excavated directly from the living limestone bedrock of the Giza Plateau beside Khafre's valley causeway, this 73-meter colossus is the oldest known monumental sculpture of Ancient Egypt. Fusing the intellectual sovereignty of the reigning pharaoh with the solar might of a couchant lion, it came to be venerated in the New Kingdom as Hor-em-akhet ('Horus in the Horizon'), eternal sentinel of the western necropolis."}, {"id": "ne-01-entemena-vase-anzu", "title": "Votive Silver Vase of King Entemena Incised with Anzû", "creature": "Anzû (Imdugud)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Imdugud", "civilization": "Sumerian (First Dynasty of Lagash)", "region": "Ancient Near East & Persia", "originLocation": "Girsu (modern Telloh), Dhi Qar Governorate, Iraq", "dateDisplay": "c. 2400 BCE", "yearSort": -2400, "era": "Prehistory & Bronze Age", "medium": "Hammered and engraved silver on a copper base", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Royal workshop of Entemena of Lagash", "repository": "Musée du Louvre, Paris (AO 2674)", "commonsFile": "Vase_dedicated_to_Ningirsu_by_Entemena-Anzu-AO_2674-IMG_9135.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Vase_dedicated_to_Ningirsu_by_Entemena-Anzu-AO_2674-IMG_9135.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Vase_dedicated_to_Ningirsu_by_Entemena-Anzu-AO_2674-IMG_9135.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b6/Vase_dedicated_to_Ningirsu_by_Entemena-Anzu-AO_2674-IMG_9135.jpg", "anatomy": ["Frontal maned lion head on an eagle's feathered body", "Outstretched wings and splayed tail plumage", "Talons seizing pairs of lions and ibexes in heraldic symmetry"], "description": "Dedicated by King Entemena of Lagash to the warrior god Ningirsu in the E-ninnu temple at Girsu, this finely chased silver vessel bears four repetitions of the lion-headed eagle Imdugud. Each emblem grasps pairs of lions, stags, or ibexes, illustrating the storm-bird's mediating power between celestial authority and earthly vitality."}, {"id": "sa-09-indus-unicorn-seal", "title": "Harappan Steatite Stamp Seal with Single-Horned Beast ('Unicorn') and Cult Brazier", "creature": "Indus Unicorn", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Ekashringa (later Sanskrit epithet; undeciphered Indus script)", "civilization": "Indus Valley Civilization", "region": "South & Southeast Asia", "originLocation": "Mohenjo-daro, Sindh (modern Pakistan)", "dateDisplay": "c. 2500–1900 BCE", "yearSort": -2200, "era": "Prehistory & Bronze Age", "medium": "Carved and fired white-slipped steatite intaglio stamp seal", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Single-Horned & Sacred Beasts", "creator": "Unknown Harappan master lapidary", "repository": "Musée national des arts asiatiques – Guimet, Paris (AO 21166)", "commonsFile": "Sceau_Indus_unicorne_Guimet.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sceau_Indus_unicorne_Guimet.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sceau_Indus_unicorne_Guimet.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/71/Sceau_Indus_unicorne_Guimet.jpg", "anatomy": ["single forward-sweeping S-curved horn emerging from the brow", "muscular bovine-antelope torso with hatched neck collar", "long tufted bovine tail and cloven hooves"], "description": "Carved in crisp intaglio into fired steatite beneath a register of undeciphered Indus script signs, this Mature Harappan stamp seal depicts the iconic single-horned bovine-antelope standing before a two-tiered ritual incense burner or cult standard. Appearing on over sixty percent of stamped glyptic seals from Mohenjo-daro and Harappa, the profile beast represents an intentional mythical single-horned emblem rather than two overlapping horns, establishing South Asia's earliest sacred unicorn tradition."}, {"id": "sa-09-indus-pashupati-seal", "title": "The 'Pashupati' ('Lord of Beasts') Horned Anthropomorphic Deity Seal", "creature": "Horned Proto-Pashupati Deity", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Pashupati ('Lord of Beasts')", "civilization": "Indus Valley Civilization", "region": "South & Southeast Asia", "originLocation": "DK-G Area, Mohenjo-daro, Sindh (modern Pakistan)", "dateDisplay": "c. 2350–2000 BCE", "yearSort": -2175, "era": "Prehistory & Bronze Age", "medium": "Carved and fired steatite stamp seal (Seal 420)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Harappan glyptic carver", "repository": "National Museum, New Delhi", "commonsFile": "Pashupati_Seal_from_the_Harappan_Civilization.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Pashupati_Seal_from_the_Harappan_Civilization.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Pashupati_Seal_from_the_Harappan_Civilization.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/36/Pashupati_Seal_from_the_Harappan_Civilization.jpg", "anatomy": ["sweeping water-buffalo horns crowning a central vegetal crest", "polycephalic three-faced anthropomorphic head", "bangle-clad arms resting on knees in heel-to-heel yogic posture"], "description": "Excavated in 1928–1929 at Mohenjo-daro, this famed steatite seal portrays an ithyphallic three-faced, buffalo-horned figure seated in a heel-to-heel yogic posture on a low dais above two ibexes. Surrounded by an elephant, a leaping tiger, a rhinoceros, and a water buffalo beneath seven Indus script glyphs, the therianthropic 'Lord of Beasts' synthesizes human, bovine, and wild-animal sovereignty in Bronze Age urban religion."}, {"id": "ne-01-gudea-libation-vase", "title": "Libation Beaker of Gudea with Mušḫuššu Dragons and Entwined Serpents", "creature": "Mušḫuššu & Winged Horned Serpent", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Mušḫuššu / Bašmu", "civilization": "Neo-Sumerian (Second Dynasty of Lagash)", "region": "Ancient Near East & Persia", "originLocation": "Girsu (modern Telloh), Iraq", "dateDisplay": "c. 2120 BCE", "yearSort": -2120, "era": "Prehistory & Bronze Age", "medium": "Carved green steatite (chlorite)", "mediumCategory": "Ceramics & Vessels", "morphology": "Draconic & Serpentine", "creator": "Court workshop of Gudea, Ensi of Lagash", "repository": "Musée du Louvre, Paris (AO 190)", "commonsFile": "Gobelet-AO190-IMG_6885.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gobelet-AO190-IMG_6885.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gobelet-AO190-IMG_6885.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fe/Gobelet-AO190-IMG_6885.jpg", "anatomy": ["Scaly serpentine-feline bodies standing bipedally with feathered wings", "Horned viper heads, lion forepaws, and raptorial hind talons", "Scorpion-tipped tails flanking a central staff of two entwined serpents"], "description": "Inscribed by Gudea, ruler of Lagash, for his personal protective deity Ningishzida ('Lord of the Good Tree'), this dark green steatite libation beaker preserves one of the earliest canonical images of the horned Mušḫuššu dragon. Two winged dragon-chimeras hold upright standards flanking an axial caduceus-like staff coiled by mating vipers."}, {"id": "ne-01-humbaba-mask-ur", "title": "Apotropaic Terracotta Mask of Humbaba (Huwawa)", "creature": "Humbaba (Guardian of the Cedar Forest)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Huwawa / Ḫumbaba", "civilization": "Old Babylonian", "region": "Ancient Near East & Persia", "originLocation": "Ur (Tell el-Muqayyar), southern Iraq", "dateDisplay": "c. 2004–1595 BCE", "yearSort": -1800, "era": "Prehistory & Bronze Age", "medium": "Molded and incised baked clay", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Old Babylonian coroplast", "repository": "Sulaymaniyah Museum, Iraqi Kurdistan", "commonsFile": "Terracotta_mask_of_Humbaba_(Huwawa)._From_Ur,_Iraq._Old-Babylonian_period_2004-1595_BCE._Sulaymaniyah_Museum,_Iraq.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Terracotta_mask_of_Humbaba_(Huwawa)._From_Ur,_Iraq._Old-Babylonian_period_2004-1595_BCE._Sulaymaniyah_Museum,_Iraq.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Terracotta_mask_of_Humbaba_(Huwawa)._From_Ur,_Iraq._Old-Babylonian_period_2004-1595_BCE._Sulaymaniyah_Museum,_Iraq.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/70/Terracotta_mask_of_Humbaba_(Huwawa)._From_Ur,_Iraq._Old-Babylonian_period_2004-1595_BCE._Sulaymaniyah_Museum,_Iraq.jpg", "anatomy": ["Grimacing monstrous face formed by convoluted, labyrinthine coils", "Bared fangs and wide, staring apotropaic eyes", "Visage evoking the divinatory coils of sacrificial entrails (tirānū)"], "description": "In the Epic of Gilgamesh, the monstrous giant Humbaba guards the sacred Cedar Forest of the gods, terrifying intruders with his supernatural 'auras.' Old Babylonian clay plaques and masks render his grimacing face as a continuous, coiled line resembling sheep intestines examined in Mesopotamian extispicy omen rituals."}, {"id": "eg-02-middle-kingdom-apotropaic-wand", "title": "Middle Kingdom Curved Ivory Apotropaic Wand ('Magic Knife')", "creature": "Procession of Apotropaic Monsters (Griffin, Serpopard, and Taweret)", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Aha ('Fighters' of the Solar Entourage)", "civilization": "Middle Kingdom Egypt (12th–13th Dynasty)", "region": "Egypt & Africa", "originLocation": "Middle or Upper Egypt (likely Lisht or Thebes)", "dateDisplay": "c. 1981–1640 BCE", "yearSort": -1800, "era": "Prehistory & Bronze Age", "medium": "Split and incised hippopotamus canine tusk ivory", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Unknown Middle Kingdom ritual ivory carver", "repository": "Metropolitan Museum of Art, New York (30.8.218)", "commonsFile": "Magic_wand_MET_DP112633.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Magic_wand_MET_DP112633.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Magic_wand_MET_DP112633.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/ae/Magic_wand_MET_DP112633.jpg", "anatomy": ["falcon-headed feline griffin with human head emerging between dorsal wings", "long-necked serpopard biting a serpent", "knife-wielding bipedal hippopotamus demoness and lion-frog genii"], "description": "Fashioned from the curved lower canine tusk of a hippopotamus—Taweret's own sacred animal—this apotropaic wand was drawn in protective circles around birthing beds and infants to repel nocturnal ghosts and venomous creatures. Incised along its gleaming surface marches a fierce militia of solar genii ('fighters'), including a human-crested winged griffin, a snake-devouring serpopard, and knife-bearing leonine and hippopotamus guardians."}, {"id": "ne-01-burney-queen-of-night", "title": "The Burney Relief ('Queen of the Night')", "creature": "Winged Talon-Footed Underworld Goddess or Lilītu", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Ereškigal / Inanna / Lilītu", "civilization": "Old Babylonian", "region": "Ancient Near East & Persia", "originLocation": "Southern Mesopotamia, Iraq", "dateDisplay": "c. 1800–1750 BCE", "yearSort": -1775, "era": "Prehistory & Bronze Age", "medium": "High-relief baked straw-tempered clay plaque with traces of pigment", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Old Babylonian sculptor", "repository": "British Museum, London (ME 2003,0718.1)", "commonsFile": "Queen_of_the_Night_relief_(Burney_relief),_old_Babylonian_period,_1800-1750_BC,_from_Iraq._The_British_Museum.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Queen_of_the_Night_relief_(Burney_relief),_old_Babylonian_period,_1800-1750_BC,_from_Iraq._The_British_Museum.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Queen_of_the_Night_relief_(Burney_relief),_old_Babylonian_period,_1800-1750_BC,_from_Iraq._The_British_Museum.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c2/Queen_of_the_Night_relief_(Burney_relief),_old_Babylonian_period,_1800-1750_BC,_from_Iraq._The_British_Museum.jpg", "anatomy": ["Four-tiered horned crown of divinity and human female torso", "Downward-swept multicolored raptor wings", "Feathered bird-of-prey legs and talons perched atop two recumbent lions"], "description": "Modeled in high-relief terracotta originally painted in brilliant red, black, and white, the Burney Relief portrays a naked, horned female entity with lowered raptor wings and bird talons standing upon two lions between flanking owls. Scholars identify this liminal nocturnal figure with Inanna-Ishtar in her underworld descent, her sister Ereshkigal, or the winged demoness Lilītu."}, {"id": "eg-02-ahmose-griffin-axe", "title": "Ceremonial Parade Axe of Pharaoh Ahmose I with Aegean-Egyptian Griffin", "creature": "Crested Solar Griffin of Montu", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "ꜥḫḫ (Akhekh / Griffin Beloved of Montu)", "civilization": "New Kingdom Egypt (Early 18th Dynasty)", "region": "Egypt & Africa", "originLocation": "Tomb of Queen Ahhotep I, Dra' Abu el-Naga, Western Thebes", "dateDisplay": "c. 1550–1525 BCE", "yearSort": -1538, "era": "Prehistory & Bronze Age", "medium": "Copper blade overlaid with sheet gold, electrum, lapis lazuli, carnelian, and turquoise on cedarwood haft", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Royal Theban goldsmiths of Ahmose I", "repository": "Luxor Museum, Luxor (formerly Egyptian Museum, Cairo, CG 52645)", "commonsFile": "Ceremonial_axe_of_Ahmose_I_(both_sides).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ceremonial_axe_of_Ahmose_I_(both_sides).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ceremonial_axe_of_Ahmose_I_(both_sides).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2b/Ceremonial_axe_of_Ahmose_I_(both_sides).jpg", "anatomy": ["hooked eagle beak with curled spiral neck locks of Minoan inspiration", "notched crest plumes and swept, polychrome-inlaid wings", "couchant leonine body paired with a human-headed Heh sphinx above"], "description": "Recovered from the gilded coffin of Queen Ahhotep at Thebes, this jewel-inlaid ceremonial battle-axe celebrates Pharaoh Ahmose I's expulsion of the Hyksos and reunification of Egypt. Below scenes of the king smiting an enemy and a sphinx offering a severed head, an exquisite cloisonné-inlaid griffin—labeled 'beloved of Montu'—fuses Minoan-Aegean spiral plumes with Egyptian royal war symbolism."}, {"id": "am-10-australia-rainbow-serpent-rock-art", "title": "Arnhem Land Ochre Rock Painting of the Rainbow Serpent", "creature": "Rainbow Serpent", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Ngalyod / Yingarna", "civilization": "Indigenous Australian (Arnhem Land)", "region": "The Americas & Oceania", "originLocation": "Western Arnhem Land escarpment, Northern Territory, Australia", "dateDisplay": "Pre-contact Dreaming rock art tradition (c. 2000 BCE–1500 CE)", "yearSort": -1500, "era": "Prehistory & Bronze Age", "medium": "Natural red and white earth-ochre pigments on sandstone rock-shelter wall", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Unknown ancestral Arnhem Land rock-shelter artist", "repository": "Arnhem Land sandstone escarpment, Northern Territory, Australia (in situ)", "commonsFile": "RainbowSerpent.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:RainbowSerpent.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/RainbowSerpent.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a7/RainbowSerpent.jpg", "anatomy": ["sinuous giant python body cross-hatched with internal anatomical bands", "eared macropod- or crocodile-like head with protruding tongue", "arching rainbow-like posture linking subterranean waterholes and monsoon clouds"], "description": "Painted in iron-rich red ochre across a sheltered sandstone overhang in Northern Australia, this ancestral rock painting depicts the Rainbow Serpent—known in Western Arnhem Land Kunwinjku traditions as Ngalyod or the creator-mother Yingarna. Emerging at the end of the Ice Age in Arnhem Land's rock-art sequence, this colossal composite python-macropod spirit carved river gorges, dwells in permanent billabongs, unleashes regenerative monsoonal storms, and swallows rule-breakers who disturb sacred waters."}, {"id": "eg-02-hatshepsut-sphinx", "title": "Colossal Granite Sphinx of Pharaoh Hatshepsut", "creature": "Maned Royal Androsphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Shesep-ankh en Maatkara", "civilization": "New Kingdom Egypt (18th Dynasty)", "region": "Egypt & Africa", "originLocation": "Mortuary Temple of Hatshepsut at Deir el-Bahari, Western Thebes", "dateDisplay": "c. 1479–1458 BCE", "yearSort": -1468, "era": "Prehistory & Bronze Age", "medium": "Carved and painted Aswan red granite", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Royal Theban sculptors under Senenmut", "repository": "Metropolitan Museum of Art, New York (31.3.166)", "commonsFile": "Sphinx_of_Hatshepsut_MET_DP153112.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sphinx_of_Hatshepsut_MET_DP153112.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sphinx_of_Hatshepsut_MET_DP153112.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/49/Sphinx_of_Hatshepsut_MET_DP153112.jpg", "anatomy": ["muscular couchant lion body weighing over seven tons", "female ruler's idealized face framed by a thick leonine mane and nemes", "ceremonial false pharaonic beard and uraeus", "taut feline forelimbs extended along a rectangular plinth"], "description": "One of at least six monumental red granite sphinxes that lined the lower courtyard processional way of Hatshepsut's terraced temple at Deir el-Bahari, this sculpture casts the female pharaoh with the traditional royal beard and nemes headcloth of kingship. Smashed and buried in quarry pits during Thutmose III's posthumous proscription of her monuments, its reassembled granite fragments preserve subtle yellow and blue pigments accentuating her divine leonine transformation."}, {"id": "gr-03-tiryns-gold-ring-genius", "title": "Great Gold Signet Ring of Tiryns with Procession of Minoan Genii", "creature": "Minoan Genius", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Κρητομυκηναϊκός Δαίμων (Krētomykēnaïkos Daimōn)", "civilization": "Mycenaean Greece", "region": "Greece & Aegean", "originLocation": "Tiryns, Argolid, Peloponnese, Greece", "dateDisplay": "c. 1500–1400 BCE (Late Helladic II)", "yearSort": -1450, "era": "Prehistory & Bronze Age", "medium": "Engraved solid gold signet ring bezel", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Minoan-Mycenaean glyptic master", "repository": "National Archaeological Museum, Athens (N 6208)", "commonsFile": "Gold_ring_with_relief_sitting_goddess_and_genii_Mycenaean,_NAMA_6208_080858.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gold_ring_with_relief_sitting_goddess_and_genii_Mycenaean,_NAMA_6208_080858.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gold_ring_with_relief_sitting_goddess_and_genii_Mycenaean,_NAMA_6208_080858.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5e/Gold_ring_with_relief_sitting_goddess_and_genii_Mycenaean,_NAMA_6208_080858.jpg", "anatomy": ["upright leonine-hippopotamus head", "spiny crocodile-like dorsal carapace", "cinched wasp-waisted bipedal torso", "humanoid forepaws bearing ritual libation ewers"], "description": "The largest surviving Mycenaean gold signet ring, unearthed in the Tiryns Treasure, depicts four upright Minoan Genii marching solemnly toward an enthroned goddess holding a ritual chalice. Adapted in Bronze Age Crete from the Egyptian hippopotamus goddess Taweret, each hybrid daemon wears a pleated dorsal carapace and elevates a tall-spouted libation jug beneath a celestial register of sun and crescent moon."}, {"id": "gr-03-knossos-throne-griffin", "title": "Throne Room Fresco of Couchant Wingless Griffins at Knossos", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Γρύψ (Gryps)", "civilization": "Minoan Crete", "region": "Greece & Aegean", "originLocation": "Palace of Knossos, Crete, Greece", "dateDisplay": "c. 1450–1400 BCE (Late Minoan II–IIIA1)", "yearSort": -1425, "era": "Prehistory & Bronze Age", "medium": "Buon fresco lime plaster wall painting with mineral pigments", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Knossian palace fresco workshop", "repository": "Heraklion Archaeological Museum, Crete", "commonsFile": "Wall_painting_of_griffins_in_landscape_from_Knossos_(Throne_Room)_-_Heraklion_AM_-_01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wall_painting_of_griffins_in_landscape_from_Knossos_(Throne_Room)_-_Heraklion_AM_-_01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wall_painting_of_griffins_in_landscape_from_Knossos_(Throne_Room)_-_Heraklion_AM_-_01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/57/Wall_painting_of_griffins_in_landscape_from_Knossos_(Throne_Room)_-_Heraklion_AM_-_01.jpg", "anatomy": ["hooked raptor beak and piercing avian eye", "plumed spiral crest with rosette markings", "supple elongated feline body", "wingless shoulders with decorative spiral plumage"], "description": "Recovered from the Throne Room of the Palace of Knossos, this Late Minoan wall painting portrays heraldic griffins resting amidst swaying papyrus reeds and undulating sacred landscapes. Remarkably wingless, the creatures combine tawny leonine bodies with white eagle heads, scrolling neck spirals, and plumed crests to guard the epiphany of the ruler or priestess seated upon the gypsum throne."}, {"id": "gr-03-agora-ivory-pyxis-griffin", "title": "Mycenaean Carved Ivory Pyxis with Winged Griffins Attacking Stags", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Γρύψ (Gryps)", "civilization": "Mycenaean Greece", "region": "Greece & Aegean", "originLocation": "Athenian Agora (Tomb on the Areopagus), Athens, Greece", "dateDisplay": "c. 1450–1400 BCE (Late Helladic IIB–IIIA1)", "yearSort": -1420, "era": "Prehistory & Bronze Age", "medium": "Cylindrical elephant ivory cosmetic box carved in relief", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Mycenaean ivory carver", "repository": "Museum of the Ancient Agora, Athens", "commonsFile": "Mycenaean_Ivory_pyxis_with_griffin,_15th_century_BC,_AGMA,_225215.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Mycenaean_Ivory_pyxis_with_griffin,_15th_century_BC,_AGMA,_225215.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycenaean_Ivory_pyxis_with_griffin,_15th_century_BC,_AGMA,_225215.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ec/Mycenaean_Ivory_pyxis_with_griffin,_15th_century_BC,_AGMA,_225215.jpg", "anatomy": ["raptor head with curved predatory beak", "sweeping layered eagle wings", "muscular lion hindquarters and taloned paws", "curling feline tail"], "description": "Excavated from a wealthy Late Bronze Age chamber tomb on the northern slope of the Areopagus in Athens, this cylindrical ivory pyxis captures the violent dynamism of Mycenaean animal combat. Fierce winged griffins plunge from rocky crags to sink their beaks and leonine claws into fleeing stags, blending Minoan naturalism with mainland heroic vigor."}, {"id": "ne-01-alaca-hoyuk-sphinx", "title": "Monumental Sphinx Gate Guardian at Alaca Höyük", "creature": "Anatolian Winged Sphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Awiti / Damnaššara", "civilization": "Hittite Empire", "region": "Ancient Near East & Persia", "originLocation": "Alaca Höyük, Çorum Province, Turkey", "dateDisplay": "c. 1400–1300 BCE", "yearSort": -1350, "era": "Prehistory & Bronze Age", "medium": "Monolithic carved andesite stone orthostat", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Hittite imperial masons", "repository": "In situ / Alaca Höyük Museum, Turkey", "commonsFile": "Sphinx_Gate,_Alaca_Höyük_04.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sphinx_Gate,_Alaca_H%C3%B6y%C3%BCk_04.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sphinx_Gate,_Alaca_H%C3%B6y%C3%BCk_04.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fc/Sphinx_Gate,_Alaca_H%C3%B6y%C3%BCk_04.jpg", "anatomy": ["Human face framed by heavy Hathoric-inspired curled lappets", "Massive leonine chest and forelegs carved into the monolithic jamb", "Double-headed eagle relief carved on the inner flank"], "description": "Flanking the ceremonial city portal at Alaca Höyük in central Anatolia, these two-meter monolithic stone sphinxes synthesize Egyptian Hathoric hair-curls with muscular Hittite leonine forms. As threshold guardians (Damnaššara), they protected the sacred precinct from malevolent forces while bearing imperial Hittite double-headed eagle emblems on their inner sides."}, {"id": "eg-02-seti-sarcophagus-apep", "title": "Alabaster Sarcophagus of Pharaoh Seti I Inscribed with the Book of Gates", "creature": "Apep (Apophis) and Underworld Guardian Serpents", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "ꜥꜣpp / Mehen ('Coiled One')", "civilization": "New Kingdom Egypt (19th Dynasty)", "region": "Egypt & Africa", "originLocation": "Tomb of Seti I (KV17), Valley of the Kings, Western Thebes", "dateDisplay": "c. 1279 BCE", "yearSort": -1279, "era": "Prehistory & Bronze Age", "medium": "Translucent carved calcite (Egyptian alabaster) inlaid with Egyptian blue", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Royal sculptors of the Valley of the Kings", "repository": "Sir John Soane's Museum, London (M1)", "commonsFile": "Sarcophagus_of_Seti_I_2023-02-17e.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sarcophagus_of_Seti_I_2023-02-17e.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sarcophagus_of_Seti_I_2023-02-17e.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2e/Sarcophagus_of_Seti_I_2023-02-17e.jpg", "anatomy": ["towering labyrinthine coils of Apep bound in chains", "protective multi-coiled Mehen serpent enveloping Ra's solar barque", "fire-spitting uraeus guardians flanking the twelve underworld portals"], "description": "Hollowed from a single monolithic block of translucent white calcite discovered by Giovanni Belzoni in 1817, Seti I's sarcophagus preserves the most complete carved text and imagery of the Book of Gates. Across its finely incised registers—originally filled with copper-frit blue paste—the protective serpent Mehen shields the sun god's barque while underworld deities fetter and harpoon the colossal chaos serpent Apep so dawn may be reborn."}, {"id": "eg-02-hunefer-ammit", "title": "The Weighing of the Heart with Ammit, Book of the Dead of Hunefer", "creature": "Ammit ('Devourer of the Dead')", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "ꜥmmt (Ammit / Ammut)", "civilization": "New Kingdom Egypt (19th Dynasty)", "region": "Egypt & Africa", "originLocation": "Thebes, Upper Egypt", "dateDisplay": "c. 1275 BCE", "yearSort": -1275, "era": "Prehistory & Bronze Age", "medium": "Polychrome mineral pigment and ink on papyrus", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Theban funerary scribe-illuminator", "repository": "British Museum, London (EA 9901,3)", "commonsFile": "BD_Hunefer.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:BD_Hunefer.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/BD_Hunefer.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d7/BD_Hunefer.jpg", "anatomy": ["elongated Nilotic crocodile snout and serrated jaws", "maned leonine forequarters and spotted feline torso", "bulbous hippopotamus hindquarters"], "description": "Illuminating Spell 125 for the royal scribe Hunefer, this celebrated papyrus vignette stations the composite female demoness Ammit directly beneath the balance beam where Anubis weighs Hunefer's heart against Maat's ostrich feather. Combining the three deadliest man-killing beasts known along the Nile—crocodile, lion, and hippopotamus—she waits poised to devour any sinner's heart, inflicting an irreversible 'second death' outside Osiris's realm."}, {"id": "eg-02-nefertari-bennu-aker", "title": "The Sacred Bennu Bird and Double-Lion Aker, Tomb of Queen Nefertari (QV66)", "creature": "Bennu Bird (Egyptian Phoenix) and Aker", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Bnw (Bennu) & Aker", "civilization": "New Kingdom Egypt (19th Dynasty)", "region": "Egypt & Africa", "originLocation": "Tomb of Nefertari (QV66), Valley of the Queens, Western Thebes", "dateDisplay": "c. 1255 BCE (documented in 1904 glass-plate negative)", "yearSort": -1255, "era": "Prehistory & Bronze Age", "medium": "Polychrome painted raised plaster relief on limestone", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "Royal artisans of Deir el-Medina under Ramesses II", "repository": "In situ, Tomb QV66, Luxor (1904 Schiaparelli archival plate, Museo Egizio, Turin)", "commonsFile": "Theban_region,_Valley_of_the_Queens,_QV_66,_Tomb_of_Nefertari,_1904,_photo_22_of_227_-_Archivio_fotografico_Museo_Egizio,_Turin_E00531.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Theban_region,_Valley_of_the_Queens,_QV_66,_Tomb_of_Nefertari,_1904,_photo_22_of_227_-_Archivio_fotografico_Museo_Egizio,_Turin_E00531.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Theban_region,_Valley_of_the_Queens,_QV_66,_Tomb_of_Nefertari,_1904,_photo_22_of_227_-_Archivio_fotografico_Museo_Egizio,_Turin_E00531.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7b/Theban_region,_Valley_of_the_Queens,_QV_66,_Tomb_of_Nefertari,_1904,_photo_22_of_227_-_Archivio_fotografico_Museo_Egizio,_Turin_E00531.jpg", "anatomy": ["blue-gray heron plumage with twin swept-back occipital crest feathers", "long wading legs and dagger-like beak of the Heliopolitan phoenix", "conjoined back-to-back lions of Aker cradling the horizon sign (akhet)"], "description": "Captured in Ernesto Schiaparelli's 1904 discovery glass-plate photograph inside Queen Nefertari's burial complex, this vivid relief pairs two cardinal cosmic creatures of Spell 17 of the Book of the Dead. On the left stands the plumed Bennu bird—the self-created avian soul (ba) of Ra and prototype of the Greek phoenix—beside the mummified bier and the double-headed lion earth-guardian Aker supporting the solar disk between Yesterday and Tomorrow."}, {"id": "eg-02-ani-ammit", "title": "Ammit Poised Beside Thoth, Papyrus of Ani", "creature": "Ammit ('Eater of Hearts')", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "ꜥmmt (Ammit)", "civilization": "New Kingdom Egypt (19th Dynasty)", "region": "Egypt & Africa", "originLocation": "Thebes, Upper Egypt", "dateDisplay": "c. 1250 BCE", "yearSort": -1250, "era": "Prehistory & Bronze Age", "medium": "Tempera pigment and black carbon ink on papyrus roll", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Theban workshop scribe-painter", "repository": "British Museum, London (EA 10470,3)", "commonsFile": "BD_Weighing_of_the_Heart.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:BD_Weighing_of_the_Heart.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/BD_Weighing_of_the_Heart.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ee/BD_Weighing_of_the_Heart.jpg", "anatomy": ["greenish scaled crocodilian head and neck", "rosette-spotted leopard-lioness chest and forelegs", "heavy turquoise-tinted hippopotamus haunches"], "description": "In the sumptuous funerary papyrus of the Theban scribe Ani, Ammit crouches alertly behind ibis-headed Thoth as he records the verdict of the psychostasia on his scribal palette. Rather than an agent of chaos, the hybrid monster functions here as an instrument of divine justice, embodying retributive annihilation should the deceased's heart prove heavier than cosmic truth."}, {"id": "eg-02-karnak-criosphinx-avenue", "title": "Avenue of Ram-Headed Sphinxes (Criosphinxes) at Karnak", "creature": "Criosphinx (Ram-Headed Lion)", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Ba-spirit Criosphinx of Amun-Ra", "civilization": "New Kingdom Egypt (19th Dynasty)", "region": "Egypt & Africa", "originLocation": "First Pylon Approach, Precinct of Amun-Ra, Karnak, Luxor", "dateDisplay": "c. 1279–1213 BCE", "yearSort": -1250, "era": "Prehistory & Bronze Age", "medium": "Carved sandstone colossi on stone pedestals", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Royal builders of Pharaoh Ramesses II (later usurped by Pinudjem I)", "repository": "In situ, Karnak Temple Complex, Luxor, Egypt", "commonsFile": "Karnak_Western_Sphinxes_Alley_R01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Karnak_Western_Sphinxes_Alley_R01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Karnak_Western_Sphinxes_Alley_R01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a9/Karnak_Western_Sphinxes_Alley_R01.jpg", "anatomy": ["downward-curving horns of the sacred Ovis platyura ram", "recumbent leonine body flanking the sacred quay avenue", "osiride figure of the pharaoh sheltered beneath each ram's chin"], "description": "Lining the ceremonial dromos linking the Nile harbor quay to the First Pylon of Karnak, forty sandstone criosphinxes fuse the virile curled-horn ram of Amun-Ra with the solar strength of a couchant lion. Between its forepaws, each hybrid guardian cradles a diminutive mummiform effigy of the king, visually enacting divine protection over the monarch along the sacred bark procession route."}, {"id": "cn-07-sanxingdui-zongmu-mask", "title": "Protruding-Eyed Bronze Mask (Zongmu) of Cancong", "creature": "Cancong (Telescopic-Eyed Ancestor Spirit)", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "青銅縱目面具 (Qīngtóng Zòngmù Miànjù)", "civilization": "Sanxingdui Culture (Ancient Shu Kingdom)", "region": "East Asia & Eurasian Steppe", "originLocation": "Sacrificial Pit 2, Sanxingdui, Guanghan, Sichuan, China", "dateDisplay": "c. 1200 BCE", "yearSort": -1200, "era": "Prehistory & Bronze Age", "medium": "Cast bronze with traces of pigment", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Ancient Shu royal bronze workshop", "repository": "Sanxingdui Museum, Guanghan", "commonsFile": "Masque-de-bronze-Sanxingdui.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Masque-de-bronze-Sanxingdui.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Masque-de-bronze-Sanxingdui.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/bf/Masque-de-bronze-Sanxingdui.jpg", "anatomy": ["cylindrical protruding stalks for eyes", "flaring wing-like zoomorphic ears", "scrolling frontal forehead crest", "wide slit-like archaic smile"], "description": "Measuring 1.38 meters across its sweeping beast-like ears, this monumental bronze mask from Sanxingdui Pit 2 projects twin cylindrical pupils 16 centimeters outward from hollow sockets. Scholars link its superhuman anatomy to later chronicles of Cancong, the semi-divine silkworm-king of Shu described as possessing 'vertical protruding eyes' capable of perceiving cosmic realms."}, {"id": "cn-07-shang-taotie-ding", "title": "Bronze Ritual Tripod Cauldron (Ding) with Taotie Masks", "creature": "Taotie (Zoomorphic Glutton Mask)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "饕餮紋銅鼎 (Tāotiè-wén Tóngdǐng)", "civilization": "Shang Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Central Plains (Henan), China", "dateDisplay": "c. 1300–1050 BCE", "yearSort": -1175, "era": "Prehistory & Bronze Age", "medium": "Piece-mold cast bronze", "mediumCategory": "Ceramics & Vessels", "morphology": "Giants, Demons & Spirits", "creator": "Royal Shang foundry workshop", "repository": "Victoria and Albert Museum, London", "commonsFile": "Tripod_for_food_(Ding),_for_rituals_celebrating_the_ancestors._The_surface_is_decorated_with_3_taoties_(zoomorphic_masks)._Shang_Dynasty,_1300-1050_BCE._Bronze._From_China._Victoria_and_Albert_Museum,_London.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tripod_for_food_(Ding),_for_rituals_celebrating_the_ancestors._The_surface_is_decorated_with_3_taoties_(zoomorphic_masks)._Shang_Dynasty,_1300-1050_BCE._Bronze._From_China._Victoria_and_Albert_Museum,_London.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tripod_for_food_(Ding),_for_rituals_celebrating_the_ancestors._The_surface_is_decorated_with_3_taoties_(zoomorphic_masks)._Shang_Dynasty,_1300-1050_BCE._Bronze._From_China._Victoria_and_Albert_Museum,_London.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/86/Tripod_for_food_(Ding),_for_rituals_celebrating_the_ancestors._The_surface_is_decorated_with_3_taoties_(zoomorphic_masks)._Shang_Dynasty,_1300-1050_BCE._Bronze._From_China._Victoria_and_Albert_Museum,_London.jpg", "anatomy": ["bilaterally split zoomorphic mask", "boss-like staring eyes", "inward-curling C-shaped horns", "jawless fanged upper snout"], "description": "Cast in ceramic piece-molds for royal ancestral sacrifices, the rounded belly of this Shang bronze ding cauldron is dominated by three fierce taotie masks set against fine spiral thunder-patterns (leiwen). Defined by protruding ocular bosses, curled horns, and a split bilateral visage lacking a lower jaw, the taotie served as a liminal guardian mediating offerings between living rulers and ancestral spirits."}, {"id": "cn-07-sanxingdui-sacred-tree", "title": "Bronze Sacred Tree No. 1 with Dragon and Nine Sun-Birds", "creature": "Jinwu Sun-Birds & Cosmic Fusang Dragon", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "一號青銅神樹 (Qīngtóng Shénshù)", "civilization": "Sanxingdui Culture (Ancient Shu Kingdom)", "region": "East Asia & Eurasian Steppe", "originLocation": "Sacrificial Pit 2, Sanxingdui, Guanghan, Sichuan, China", "dateDisplay": "c. 1200–1050 BCE", "yearSort": -1150, "era": "Prehistory & Bronze Age", "medium": "Multi-section cast bronze", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Ancient Shu royal bronze workshop", "repository": "Sanxingdui Museum, Guanghan", "commonsFile": "Bronze_Sacred_Tree.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Bronze_Sacred_Tree.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Bronze_Sacred_Tree.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/ad/Bronze_Sacred_Tree.jpg", "anatomy": ["nine crested solar birds perched on blossoms", "sinuous horned dragon descending the trunk", "clawed avian talons", "hooked beaks and plumed tails"], "description": "Rising nearly four meters high on a three-lobed mountain base, this cast-bronze axis mundi materializes the ancient myth of the Fusang and Ruomu world-trees where nine solar birds rest upon three tiers of fruiting branches. Along the main trunk coils a slender, clawed dragon descending headfirst from heaven, uniting avian solar deities and draconic sky-messengers in a single ritual monument."}, {"id": "eg-02-inherkha-cat-apep", "title": "The Great Tomcat of Heliopolis Slaying Apep, Tomb of Inherkha (TT359)", "creature": "Apep (Apophis) and Miuty (Solar Tomcat of Ra)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "ꜥꜣpp (Apep / Apophis)", "civilization": "New Kingdom Egypt (20th Dynasty)", "region": "Egypt & Africa", "originLocation": "Tomb of Inherkha (TT359), Deir el-Medina, Western Thebes", "dateDisplay": "c. 1150 BCE", "yearSort": -1150, "era": "Prehistory & Bronze Age", "medium": "Tempera wall painting on plastered limestone", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Royal necropolis painters of Deir el-Medina", "repository": "In situ, Tomb TT359, Deir el-Medina, Luxor", "commonsFile": "Ra_slays_Apep_(tomb_scene_in_Deir_el-Medina).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ra_slays_Apep_(tomb_scene_in_Deir_el-Medina).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ra_slays_Apep_(tomb_scene_in_Deir_el-Medina).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ea/Ra_slays_Apep_(tomb_scene_in_Deir_el-Medina).jpg", "anatomy": ["undulating multi-coiled giant serpent body", "spotted solar tomcat with hare-like ears wielding a bronze knife", "blood streaming from severed serpentine coils beneath the sacred ished tree"], "description": "Painted on the vaulted burial chamber wall of Inherkha, 'Foreman of the Lord of the Two Lands in the Place of Truth,' this Spell 17 vignette dramatizes the nightly cosmic battle for sunrise. Beneath the foliage of Heliopolis's sacred persea (ished) tree, Ra manifests as the Great Tomcat Miuty, pinning the primeval chaos serpent Apep with one paw while slicing its undulating throat with a curved blade."}, {"id": "ne-01-kudurru-ritti-marduk", "title": "Boundary Stone (Kudurru) of Ritti-Marduk with Scorpion-Man and Mušḫuššu", "creature": "Girtablullu (Scorpion-Man) & Mušḫuššu", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Girtablullu / Mušḫuššu", "civilization": "Middle Babylonian (Second Dynasty of Isin)", "region": "Ancient Near East & Persia", "originLocation": "Sippar (Tell Abu Habbah), Iraq", "dateDisplay": "Reign of Nebuchadnezzar I, c. 1125–1104 BCE", "yearSort": -1115, "era": "Iron Age & Classical Antiquity", "medium": "Carved black limestone stele", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Babylonian royal scribes and sculptors", "repository": "British Museum, London (BM 90858)", "commonsFile": "Kudurru_of_Ritti-Marduk,_from_Sippar,_Iraq,_1125-1104_BCE._British_Museum,_London.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kudurru_of_Ritti-Marduk,_from_Sippar,_Iraq,_1125-1104_BCE._British_Museum,_London.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kudurru_of_Ritti-Marduk,_from_Sippar,_Iraq,_1125-1104_BCE._British_Museum,_London.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fa/Kudurru_of_Ritti-Marduk,_from_Sippar,_Iraq,_1125-1104_BCE._British_Museum,_London.jpg", "anatomy": ["Bearded human archer torso drawing a bow", "Winged avian body with raptor talons", "Segmented, curving scorpion tail and stinger alongside Marduk's horned dragon and giant coiled serpent"], "description": "Granted by King Nebuchadnezzar I to the chariot commander Ritti-Marduk after a campaign in Elam, this limestone kudurru seals its legal curses beneath six registers of astral and monstrous divine emblems. Prominent among them are a bow-wielding Girtablullu (scorpion-man), Marduk's spade resting on a couchant Mušḫuššu dragon, Ea's goat-fish (Suḫurmāšu), and an overarching horned serpent."}, {"id": "gr-03-lefkandi-centaur-chiron", "title": "Terracotta Centaur of Lefkandi (Chiron)", "creature": "Centaur", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Κένταυρος / Χείρων (Kentauros / Cheirōn)", "civilization": "Protogeometric Greece", "region": "Greece & Aegean", "originLocation": "Toumba Cemetery, Lefkandi, Euboea, Greece", "dateDisplay": "c. 950–900 BCE (Late Protogeometric)", "yearSort": -925, "era": "Iron Age & Classical Antiquity", "medium": "Wheel-made and hand-modeled painted terracotta figurine", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Euboean Protogeometric potter-sculptor", "repository": "Archaeological Museum of Eretria, Euboea", "commonsFile": "Centaur_Chiron_of_Lefkandi,_Archaeological_museum_of_Eretria,_Greece.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Centaur_Chiron_of_Lefkandi,_Archaeological_museum_of_Eretria,_Greece.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Centaur_Chiron_of_Lefkandi,_Archaeological_museum_of_Eretria,_Greece.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/81/Centaur_Chiron_of_Lefkandi,_Archaeological_museum_of_Eretria,_Greece.jpg", "anatomy": ["bearded human head and upright torso", "cylindrical equine barrel painted with geometric hatching", "six-fingered right hand", "deliberate gash on the left foreleg knee"], "description": "Deliberately broken in antiquity so that its head and body were buried in two adjacent tombs at Toumba in Lefkandi, this hollow terracotta statuette is the earliest monumental three-dimensional centaur in Greek art. Both its six-fingered hand and a deliberate incision on the left foreknee identify the wise centaur Chiron, wounded by Herakles' poisoned arrow."}, {"id": "ne-01-tell-halaf-scorpion-man", "title": "Basalt Orthostat of a Winged Scorpion-Bird-Man from Tell Halaf", "creature": "Girtablullu (Scorpion-Bird-Man)", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Girtablullu", "civilization": "Aramaean / Syro-Hittite (Bit Bahiani)", "region": "Ancient Near East & Persia", "originLocation": "Western Palace of King Kapara, Tell Halaf (ancient Guzana), Syria", "dateDisplay": "c. 950–850 BCE", "yearSort": -900, "era": "Iron Age & Classical Antiquity", "medium": "Carved vesicular basalt architectural sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Workshop of King Kapara at Guzana", "repository": "Pergamon Museum (Vorderasiatisches Museum), Berlin", "commonsFile": "Tell_Halaf_Skorpionvogelmann.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tell_Halaf_Skorpionvogelmann.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tell_Halaf_Skorpionvogelmann.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/31/Tell_Halaf_Skorpionvogelmann.jpg", "anatomy": ["Bearded human head with inlaid-style wide eyes and braided locks", "Feathered avian chest and folded wings", "Raptor talons and an upturned, segmented scorpion tail"], "description": "Guarding the Scorpion Gate of King Kapara's palace at Guzana (Tell Halaf), this vesicular basalt guardian brings to monumental architectural life the Girtablullu, the mythic scorpion-men who guard the twin peaks of Mount Mashu at the rising and setting of the sun in the Epic of Gilgamesh. Shattered during World War II bombing in Berlin, the sculpture was painstakingly reassembled from hundreds of basalt fragments."}, {"id": "ne-01-nimrud-winged-lion", "title": "Colossal Human-Headed Winged Lion (Lamassu) from Nimrud", "creature": "Lamassu (Human-Headed Winged Lion)", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "Aladlammû / Lamassu", "civilization": "Neo-Assyrian Empire", "region": "Ancient Near East & Persia", "originLocation": "Northwest Palace of Ashurnasirpal II, Nimrud (ancient Kalhu), Iraq", "dateDisplay": "Reign of Ashurnasirpal II, c. 883–859 BCE", "yearSort": -870, "era": "Iron Age & Classical Antiquity", "medium": "Carved Mosul gypsum alabaster", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Royal Assyrian palace sculptors", "repository": "Metropolitan Museum of Art, New York (32.143.1)", "commonsFile": "Human-headed_winged_lion_(lamassu)_MET_DT880.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Human-headed_winged_lion_(lamassu)_MET_DT880.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Human-headed_winged_lion_(lamassu)_MET_DT880.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f5/Human-headed_winged_lion_(lamassu)_MET_DT880.jpg", "anatomy": ["Bearded royal human head wearing a horned polos of divinity", "Sweeping eagle wings and scaled breast plumage", "Muscular five-legged lion body (stationary from the front, striding in profile)"], "description": "Standing over three meters tall at a gateway of Ashurnasirpal II's Northwest Palace at Kalhu, this alabaster guardian fuses human intelligence, avian swiftness, and leonine ferocity into an apotropaic threshold spirit. Assyrian sculptors endowed the monolith with five legs so that viewers approaching straight on saw the beast standing firm, while those passing through the doorway saw it striding purposefully alongside them."}, {"id": "ne-01-nimrud-eagle-apkallu", "title": "Palace Relief of an Eagle-Headed Winged Apkallu Sage", "creature": "Apkallu (Nisroch / Eagle-Headed Protective Spirit)", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "Apkallu / Ūmu-apkallu", "civilization": "Neo-Assyrian Empire", "region": "Ancient Near East & Persia", "originLocation": "Northwest Palace of Ashurnasirpal II, Nimrud (Kalhu), Iraq", "dateDisplay": "c. 865–850 BCE", "yearSort": -860, "era": "Iron Age & Classical Antiquity", "medium": "Carved gypsum alabaster wall orthostat", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Royal Assyrian palace sculptors", "repository": "British Museum, London", "commonsFile": "Wall_relief_depicting_an_eagle-headed_and_winged_man,_Apkallu,_from_Nimrud..JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wall_relief_depicting_an_eagle-headed_and_winged_man,_Apkallu,_from_Nimrud..JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wall_relief_depicting_an_eagle-headed_and_winged_man,_Apkallu,_from_Nimrud..JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/87/Wall_relief_depicting_an_eagle-headed_and_winged_man,_Apkallu,_from_Nimrud..JPG", "anatomy": ["Hooked raptor beak, crested plumage, and curled mane", "Four spread feathered wings radiating from a muscular human body", "Ritual mullilu purifier cone and banduddû bucket held in human hands"], "description": "Carved in crisp low relief across the ceremonial halls of Nimrud and inscribed down the midsection with Ashurnasirpal II's 'Standard Inscription,' this eagle-headed Apkallu represents one of the antediluvian supernatural sages sent by Ea to civilize humanity. Bearing a ritual bucket (banduddû) and purifier cone (mullilu), the winged spirit perpetually sanctifies the king and the sacred palace."}, {"id": "ne-01-carchemish-chimera", "title": "Dual-Headed Winged Chimera Orthostat from the Herald's Wall", "creature": "Syro-Hittite Chimera", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Sphinx-Chimera of Carchemish", "civilization": "Neo-Hittite / Luwian-Aramaean", "region": "Ancient Near East & Persia", "originLocation": "Herald's Wall, Carchemish, Gaziantep Province, Turkey", "dateDisplay": "c. 850–750 BCE", "yearSort": -800, "era": "Iron Age & Classical Antiquity", "medium": "Carved limestone orthostat slab", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Luwian-Hittite sculptors of Carchemish", "repository": "Museum of Anatolian Civilizations, Ankara", "commonsFile": "Museum_of_Anatolian_Civilizations080.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Museum_of_Anatolian_Civilizations080.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Museum_of_Anatolian_Civilizations080.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1a/Museum_of_Anatolian_Civilizations080.jpg", "anatomy": ["Conjoined bearded human head wearing a horned helmet and roaring lion head", "Sickle-curved feathered wings rising from a striding lion body", "Tail terminating in an upright, open-jawed bird or serpent head"], "description": "Excavated along the ceremonial Herald's Wall at Carchemish on the Euphrates, this Neo-Hittite orthostat represents a direct Near Eastern forerunner of the Greek Chimera myth. Striding fiercely to the right, the winged leonine monster sprouts both a horned human head and a roaring lion's jaws from its shoulders, while its tail ends in a third biting zoomorphic head."}, {"id": "eg-02-nimrud-egyptianizing-sphinx", "title": "Phoenician-Egyptianizing Openwork Ivory Plaque of a Crowned Winged Sphinx", "creature": "Pharaonic Winged Androsphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Kerub / Egyptianizing Winged Sphinx", "civilization": "Levantine-Egyptianizing Tradition (found in Neo-Assyrian Nimrud)", "region": "Egypt & Africa", "originLocation": "Fort Shalmaneser, Nimrud (carved in a Phoenician coastal workshop using African elephant ivory)", "dateDisplay": "c. 850–750 BCE", "yearSort": -800, "era": "Iron Age & Classical Antiquity", "medium": "Openwork carved elephant ivory (originally gilded and inlaid)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Phoenician master ivory carver trained in Egyptian royal iconography", "repository": "Cleveland Museum of Art, Cleveland (1968.45)", "commonsFile": "Winged_Sphinx,_Phoenician,_Iraq,_Nimrud,_ivory_-_Cleveland_Museum_of_Art_-_DSC08104.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Winged_Sphinx,_Phoenician,_Iraq,_Nimrud,_ivory_-_Cleveland_Museum_of_Art_-_DSC08104.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Winged_Sphinx,_Phoenician,_Iraq,_Nimrud,_ivory_-_Cleveland_Museum_of_Art_-_DSC08104.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d2/Winged_Sphinx,_Phoenician,_Iraq,_Nimrud,_ivory_-_Cleveland_Museum_of_Art_-_DSC08104.JPG", "anatomy": ["youthful pharaonic profile crowned with the Egyptian pschent (double crown)", "broad usekh collar and royal uraeus apron hanging between striding forelegs", "sickle-curved feathered wings framing lotus and papyrus thickets"], "description": "Carved in delicate à jour openwork from imported African elephant tusk to adorn aristocratic palace furniture, this plaque illustrates the prestigious diffusion of Egyptian hybrid royal imagery across the Iron Age eastern Mediterranean. Striding gracefully amid papyrus umbels, the sphinx wears the pharaonic double crown of Upper and Lower Egypt and a ceremonial apron while unfurling sweeping Levantine falcon wings."}, {"id": "ne-01-luristan-master-finial", "title": "Luristan Bronze Standard Finial of the Hybrid Master of Animals", "creature": "Luristan Demon-Hero & Confronted Long-Necked Monsters", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Master of Animals Idol", "civilization": "Iron Age Luristan (Western Zagros)", "region": "Ancient Near East & Persia", "originLocation": "Lorestan Province, Zagros Mountains, western Iran", "dateDisplay": "8th century BCE", "yearSort": -750, "era": "Iron Age & Classical Antiquity", "medium": "Lost-wax cast arsenical-tin bronze", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Unknown nomadic Luristan bronzesmith", "repository": "Harvard Art Museums (Arthur M. Sackler Museum), Cambridge, MA", "commonsFile": "Master_of_Animals_finial,_Iran,_Luristan,_8th_century_BC,_bronze_-_Arthur_M._Sackler_Museum,_Harvard_University_-_DSC01574.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Master_of_Animals_finial,_Iran,_Luristan,_8th_century_BC,_bronze_-_Arthur_M._Sackler_Museum,_Harvard_University_-_DSC01574.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Master_of_Animals_finial,_Iran,_Luristan,_8th_century_BC,_bronze_-_Arthur_M._Sackler_Museum,_Harvard_University_-_DSC01574.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/19/Master_of_Animals_finial,_Iran,_Luristan,_8th_century_BC,_bronze_-_Arthur_M._Sackler_Museum,_Harvard_University_-_DSC01574.jpg", "anatomy": ["Janus-faced horned anthropomorphic demon-deity with multiple stacked faces", "Sinuous, heraldically confronted felines with dragon-like necks", "Secondary bird-of-prey heads projecting from the hip joints"], "description": "Cast by the lost-wax method for the elite warrior graves of the central Zagros highlands, this tubular bronze finial exemplifies the surreal, metamorphic aesthetic of Iron Age Luristan. A horned, multi-faced supernatural 'Master of Animals' throttles two confronted long-necked feline monsters whose haunches sprout secondary raptor heads."}, {"id": "ne-01-lamashtu-plaque-louvre", "title": "Neo-Assyrian Bronze Exorcism Plaque Against Lamashtu ('Plaque of the Hells')", "creature": "Lamashtu & Pazuzu", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Lamaštu", "civilization": "Neo-Assyrian Empire", "region": "Ancient Near East & Persia", "originLocation": "Northern Mesopotamia / Syria", "dateDisplay": "c. 800–700 BCE", "yearSort": -750, "era": "Iron Age & Classical Antiquity", "medium": "Cast bronze apotropaic amuletic plaque (AO 22205)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Neo-Assyrian āšipu-commissioned metalworker", "repository": "Musée du Louvre, Paris (AO 22205)", "commonsFile": "Lamashtu_plaque_h9168_h9168.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Lamashtu_plaque_h9168_h9168.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Lamashtu_plaque_h9168_h9168.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c7/Lamashtu_plaque_h9168_h9168.jpg", "anatomy": ["Roaring lioness head with donkey ears atop a hairy female body", "Raptor talons kneeling on a donkey within a marsh-boat while suckling a piglet and puppy", "Serpents clutched in each hand, overseen by the rival demon Pazuzu driving her back to the underworld"], "description": "Hung beside the bed of a sick patient or expectant mother, this multi-register bronze exorcism plaque marshals protective spirits and the wind-demon Pazuzu to expel Lamashtu, the dreaded Mesopotamian child-snatching demoness. In the lowest register, lion-headed, talon-footed Lamashtu clutches twin vipers while suckling a pig and dog aboard a donkey-borne bark floating back down the subterranean river to the underworld."}, {"id": "ne-01-khorsabad-lamassu", "title": "Colossal Human-Headed Winged Bull (Lamassu) from Dur-Sharrukin", "creature": "Lamassu / Šêdu (Human-Headed Winged Bull)", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "Šêdu / Aladlammû", "civilization": "Neo-Assyrian Empire", "region": "Ancient Near East & Persia", "originLocation": "Palace of Sargon II, Dur-Sharrukin (modern Khorsabad), Iraq", "dateDisplay": "Reign of Sargon II, c. 713–706 BCE", "yearSort": -710, "era": "Iron Age & Classical Antiquity", "medium": "Carved gypseous alabaster monolith (AO 19857)", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Royal workshops of Sargon II", "repository": "Musée du Louvre, Paris (AO 19857)", "commonsFile": "Lamassu_sous_la_forme_d'un_taureau_androcéphale_-_Musée_du_Louvre_Antiquités_orientales_AO_19857.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Lamassu_sous_la_forme_d'un_taureau_androc%C3%A9phale_-_Mus%C3%A9e_du_Louvre_Antiquit%C3%A9s_orientales_AO_19857.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Lamassu_sous_la_forme_d'un_taureau_androc%C3%A9phale_-_Mus%C3%A9e_du_Louvre_Antiquit%C3%A9s_orientales_AO_19857.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3d/Lamassu_sous_la_forme_d'un_taureau_androc%C3%A9phale_-_Mus%C3%A9e_du_Louvre_Antiquit%C3%A9s_orientales_AO_19857.jpg", "anatomy": ["Crowned human head with intricately curled Assyrian royal beard and bovine ears", "Single sweeping sickle-shaped eagle wing with tiered feathers", "Colossal four-meter bull body with stylized belly curls and cloven hooves"], "description": "Towering over four meters high and weighing nearly thirty tons, this monumental alabaster bull-colossus guarded the royal citadel gates of Sargon II's newly founded capital, Dur-Sharrukin. Unlike earlier five-legged Nimrud guardians, Sargon's sculptors rendered the Khorsabad Lamassu with four stationary legs and a slightly turned head, projecting serene, immovable imperial majesty."}, {"id": "am-10-olmec-kunz-axe", "title": "The Kunz Axe (Votive Were-Jaguar Celt)", "creature": "Olmec Were-Jaguar", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Nahual / Ocelotl", "civilization": "Olmec", "region": "The Americas & Oceania", "originLocation": "Oaxaca, Mexico", "dateDisplay": "c. 1000–400 BCE", "yearSort": -700, "era": "Iron Age & Classical Antiquity", "medium": "Carved and polished blue-green jadeite", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Olmec master lapidary", "repository": "American Museum of Natural History, New York (30/7552)", "commonsFile": "Kunz_axe,_Olmec_-_Mesoamerican_objects_in_the_American_Museum_of_Natural_History_-_DSC06013.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kunz_axe,_Olmec_-_Mesoamerican_objects_in_the_American_Museum_of_Natural_History_-_DSC06013.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kunz_axe,_Olmec_-_Mesoamerican_objects_in_the_American_Museum_of_Natural_History_-_DSC06013.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a3/Kunz_axe,_Olmec_-_Mesoamerican_objects_in_the_American_Museum_of_Natural_History_-_DSC06013.JPG", "anatomy": ["cleft cranial crown associated with maize and earth fissures", "downturned snarling feline mouth with flared nostrils", "flame-shaped eyebrows above almond eyes", "crouching human infant torso clasping a miniature celt"], "description": "Standing 31 cm tall in translucent blue-green Guatemalan jadeite, the Kunz Axe merges a ritual celt blade with the crouching body of a supernatural human-feline infant. Its deeply notched cranium, flame eyebrows, and snarling jaguar maw epitomize the Olmec 'were-jaguar' rain and earth-fertility spirit, likely buried as an elite dedicatory offering rather than used as a utilitarian tool."}, {"id": "ne-01-urartu-winged-deity", "title": "Urartian Gilt-Bronze Winged Bull-Lion Throne Figurine", "creature": "Urartian Winged Composite Guardian", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Winged Throne Spirit of Haldi", "civilization": "Kingdom of Urartu (Biainili)", "region": "Ancient Near East & Persia", "originLocation": "Rusahinili (modern Toprakkale, near Van), eastern Turkey", "dateDisplay": "late 8th–7th century BCE", "yearSort": -700, "era": "Iron Age & Classical Antiquity", "medium": "Cast bronze with traces of gold leaf and stone inlay sockets", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Urartian royal court bronzesmiths", "repository": "State Hermitage Museum, Saint Petersburg", "commonsFile": "Urartian_Art_04b~.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Urartian_Art_04b~.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Urartian_Art_04b~.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6d/Urartian_Art_04b~.jpg", "anatomy": ["Human face recessed for white and dark stone inlays beneath a horned polos", "Upcurved feathered bronze wings originally covered in gold foil", "Recumbent leonine-taurine body supporting a structural throne strut"], "description": "Originally forming a load-bearing element of a sumptuous royal or divine throne in the Urartian temple-fortress at Toprakkale (Rusahinili), this cast-bronze hybrid merges human, avian, and bovine-leonine traits. Deep cells on the face and wings once held contrasting stone or glass paste inlays and gold leaf, showcasing the technical brilliance of Highland Anatolian metallurgy."}, {"id": "ne-01-assur-fish-apkallu", "title": "Cultic Basalt Water Basin with Fish-Cloaked Apkallu Sages", "creature": "Kulullû / Fish-Garbed Apkallu (Oannes)", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "Purādu-apkallu", "civilization": "Neo-Assyrian Empire", "region": "Ancient Near East & Persia", "originLocation": "Temple of Ashur, Assur (Qal'at Sherqat), Iraq", "dateDisplay": "Reign of Sennacherib, 704–681 BCE", "yearSort": -690, "era": "Iron Age & Classical Antiquity", "medium": "Carved monolithic basalt ritual basin", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Royal sculptors of Sennacherib", "repository": "Pergamon Museum (Vorderasiatisches Museum), Berlin", "commonsFile": "God_Ea_(Sumerian_Enki),_flanked_by_fish-cloaked_apkallus,_part_of_a_basalt_water_basin_from_Assur,_Iraq._Reign_of_Sennacherib,_7th_century_BCE._Pergamon_Museum.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:God_Ea_(Sumerian_Enki),_flanked_by_fish-cloaked_apkallus,_part_of_a_basalt_water_basin_from_Assur,_Iraq._Reign_of_Sennacherib,_7th_century_BCE._Pergamon_Museum.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/God_Ea_(Sumerian_Enki),_flanked_by_fish-cloaked_apkallus,_part_of_a_basalt_water_basin_from_Assur,_Iraq._Reign_of_Sennacherib,_7th_century_BCE._Pergamon_Museum.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/35/God_Ea_(Sumerian_Enki),_flanked_by_fish-cloaked_apkallus,_part_of_a_basalt_water_basin_from_Assur,_Iraq._Reign_of_Sennacherib,_7th_century_BCE._Pergamon_Museum.jpg", "anatomy": ["Bearded human sages clad from head to calf in full-body scaled carp skins", "Gaping fish head forming a mitre-like hood above the human brow", "Caudal fins hanging down the back while holding purification buckets"], "description": "Carved on the exterior of King Sennacherib's basalt lustration basin from the courtyard of the Temple of Ashur, pairs of fish-cloaked Apkallu flank the freshwater god Ea with flowing vases. Remembered in Berossus's Babyloniaca as the amphibious sage Oannes who rose from the Persian Gulf to teach humanity writing, arts, and law, these abyssal spirits embodied the primordial wisdom of the Apsû."}, {"id": "eg-02-taharqa-sphinx-kawa", "title": "Granite Maned Sphinx of Kushite Pharaoh Taharqa", "creature": "Kushite Royal Lion-Sphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Shesep-ankh of Taharqo", "civilization": "Kingdom of Kush / 25th Dynasty Egypt", "region": "Egypt & Africa", "originLocation": "Temple T at Kawa (Gematon), Upper Nubia, Sudan", "dateDisplay": "c. 690–664 BCE", "yearSort": -677, "era": "Iron Age & Classical Antiquity", "medium": "Carved gray-pink speckled granite", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Kushite royal workshop at Kawa", "repository": "British Museum, London (EA 1770)", "commonsFile": "SphinxOfTaharqa.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:SphinxOfTaharqa.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/SphinxOfTaharqa.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2e/SphinxOfTaharqa.jpg", "anatomy": ["archaic Middle Kingdom-inspired enveloping lion mane and lion ears", "distinctive Kushite portrait visage with broad cheekbones", "double uraeus cobras signifying rule over Kush and Egypt", "compact recumbent feline torso inscribed with Taharqa's cartouche"], "description": "Excavated from the sandy sanctuary of Temple T at Kawa in Sudan, this compact granite sphinx merges archaizing Egyptian Middle Kingdom leonine conventions—reviving the heavy ruffed mane of Amenemhat III—with the unmistakable physiognomy and double-cobra regalia of the Nubian king Taharqa. Across its chest, a crisp hieroglyphic cartouche proclaims Taharqa beloved of Amun, embodying the dual kingship of Napata and Thebes."}, {"id": "gr-03-eleusis-amphora-polyphemus", "title": "Eleusis Proto-Attic Amphora: Odysseus Blinding the Cyclops Polyphemus", "creature": "Cyclops (Polyphemus)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Κύκλωψ Πολύφημος (Kyklōps Polyphēmos)", "civilization": "Orientalizing / Proto-Attic Greece", "region": "Greece & Aegean", "originLocation": "West Cemetery, Eleusis, Attica, Greece", "dateDisplay": "c. 660–650 BCE", "yearSort": -655, "era": "Iron Age & Classical Antiquity", "medium": "Monumental Proto-Attic funerary neck-amphora in outline and black-and-white slip", "mediumCategory": "Ceramics & Vessels", "morphology": "Giants, Demons & Spirits", "creator": "Polyphemus Painter", "repository": "Archaeological Museum of Eleusis (Inv. 2630)", "commonsFile": "Polyphemus_Eleusis_2630.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Polyphemus_Eleusis_2630.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Polyphemus_Eleusis_2630.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fe/Polyphemus_Eleusis_2630.jpg", "anatomy": ["colossal seated giant towering to the frame border", "gaping mouth roaring in pain", "single frontal eye socket pierced by a sharpened stake", "drunken hand clutching a skyphos wine-cup"], "description": "Standing 142 centimeters tall and used for a child's burial at Eleusis, the name-vase of the Polyphemus Painter bears on its neck one of the earliest narrative scenes from Homeric epic. Painted in white slip to distinguish the hero, Odysseus and two companions drive a long spit into the eye of the seated giant Polyphemus, who clutches the wine cup that lulled him into stupor."}, {"id": "cn-07-saka-eleke-sazy-stag", "title": "Gold Recumbent Stag Plaque with Turquoise Inlays", "creature": "Celestial Golden Stag", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Алтын бұғы (Altyn Bughy)", "civilization": "Early Saka Nomads (Scytho-Siberian Horizon)", "region": "East Asia & Eurasian Steppe", "originLocation": "Kurgan 4, Eleke Sazy, Tarbagatai Mountains, Kazakhstan", "dateDisplay": "8th–6th century BCE", "yearSort": -650, "era": "Iron Age & Classical Antiquity", "medium": "Repoussé sheet gold inlaid with turquoise and lapis lazuli", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Single-Horned & Sacred Beasts", "creator": "Unknown Saka goldsmith", "repository": "East Kazakhstan Regional Museum of Local History, Oskemen", "commonsFile": "Recumbent_stag_plaque_(EKRM_inv._no._KПO93-38625);_gold_with_turquoise_and_lapis_lazuli_inlays;_Kurgan_4,_group_II,_Eleke_Sazy,_Tarbagatai_mountains,_Kazakhstan;_8th_to_6th_century_BC.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Recumbent_stag_plaque_(EKRM_inv._no._K%D0%9FO93-38625)%3B_gold_with_turquoise_and_lapis_lazuli_inlays%3B_Kurgan_4,_group_II,_Eleke_Sazy,_Tarbagatai_mountains,_Kazakhstan%3B_8th_to_6th_century_BC.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Recumbent_stag_plaque_(EKRM_inv._no._K%D0%9FO93-38625)%3B_gold_with_turquoise_and_lapis_lazuli_inlays%3B_Kurgan_4,_group_II,_Eleke_Sazy,_Tarbagatai_mountains,_Kazakhstan%3B_8th_to_6th_century_BC.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d2/Recumbent_stag_plaque_(EKRM_inv._no._K%D0%9FO93-38625)%3B_gold_with_turquoise_and_lapis_lazuli_inlays%3B_Kurgan_4,_group_II,_Eleke_Sazy,_Tarbagatai_mountains,_Kazakhstan%3B_8th_to_6th_century_BC.jpg", "anatomy": ["wave-scroll solar antlers along the spine", "tucked flying-gallop hooves", "turquoise-inlaid shoulder and eye cells", "beak-like stylized muzzle"], "description": "Unearthed from an early Saka royal barrow in the Tarbagatai range of eastern Kazakhstan, this gold plaque renders the sacred steppe stag with legs folded beneath its belly as if hurtling across the heavens. Turquoise and lapis lazuli inlays accentuate the creature's eye, ear, and haunch, embodying the solar swiftness and ancestral protection prized across Eurasian nomadic 'Animal Style' art."}, {"id": "ne-01-pazuzu-statuette-louvre", "title": "Inscribed Neo-Assyrian Bronze Statuette of Pazuzu", "creature": "Pazuzu (King of the Evil Wind Demons)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Pazūzu", "civilization": "Neo-Assyrian / Neo-Babylonian", "region": "Ancient Near East & Persia", "originLocation": "Mesopotamia, Iraq", "dateDisplay": "c. 800–550 BCE", "yearSort": -650, "era": "Iron Age & Classical Antiquity", "medium": "Cast bronze statuette with cuneiform dorsal inscription (MNB 467)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Mesopotamian metalworker", "repository": "Musée du Louvre, Paris (MNB 467)", "commonsFile": "Pazuzu_MNB467_mp3h9179.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Pazuzu_MNB467_mp3h9179.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Pazuzu_MNB467_mp3h9179.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/04/Pazuzu_MNB467_mp3h9179.jpg", "anatomy": ["Snarling canine-leonine face with bulging eyes and goat-like horns", "Emaciated ribcage, four feathered wings, lion paws, and eagle talons", "Scorpion tail and serpentine phallus"], "description": "Inscribed in cuneiform across the back of its wings—'I am Pazuzu, son of Hanpa, king of the evil wind-spirits that issue violently from the mountains'—this fifteen-centimeter bronze statuette sports a suspension loop at the crown of its head. Though terrifying and pestilential himself, Pazuzu was invoked on domestic amulets to terrorize lesser demons and force his rival Lamashtu back into the netherworld."}, {"id": "gr-03-samos-bronze-griffin-protome", "title": "Cast Bronze Griffin Cauldron Protome from Samos", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Γρύψ (Gryps)", "civilization": "Archaic East Greece", "region": "Greece & Aegean", "originLocation": "Heraion of Samos (attributed), Aegean Islands, Greece", "dateDisplay": "c. 640–630 BCE", "yearSort": -635, "era": "Iron Age & Classical Antiquity", "medium": "Hollow-cast bronze cauldron attachment with incised scales", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Samian Orientalizing bronze workshop", "repository": "Antikensammlung, Altes Museum, Berlin", "commonsFile": "Ancient_Greek_Bronze_Griffin_Protome;_c._640-630_BC;_probably_from_Samos,_Greece_(28660237681).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ancient_Greek_Bronze_Griffin_Protome%3B_c._640-630_BC%3B_probably_from_Samos,_Greece_(28660237681).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Greek_Bronze_Griffin_Protome%3B_c._640-630_BC%3B_probably_from_Samos,_Greece_(28660237681).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9e/Ancient_Greek_Bronze_Griffin_Protome%3B_c._640-630_BC%3B_probably_from_Samos,_Greece_(28660237681).jpg", "anatomy": ["gaping curved eagle beak with darting tongue", "tall upright equine-like ears", "central knobbed forehead forelock", "sinuous scaly serpentine neck"], "description": "Riveted in outward-facing rows around the rims of monumental bronze votive cauldrons dedicated at sanctuaries like the Samian Heraion—celebrated by Herodotus—this Orientalizing griffin protome transforms Near Eastern metalwork models into taut Greek sculptural form. Its wide-open raptor beak, upright ears, and tall forehead knob project fierce apotropaic vigilance."}, {"id": "eg-02-cairo-taweret-statue", "title": "Polished Green Greywacke Cult Statue of Taweret", "creature": "Taweret (Apotropaic Hippopotamus-Lion-Crocodile Goddess)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Twꜣrt ('She Who Is Great')", "civilization": "Late Period Egypt (26th Saite Dynasty)", "region": "Egypt & Africa", "originLocation": "Temple of Karnak, Thebes (dedicated under Pabasa and Nitocris I)", "dateDisplay": "c. 620 BCE", "yearSort": -620, "era": "Iron Age & Classical Antiquity", "medium": "Highly polished dark green greywacke (schist)", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Saite royal temple workshop at Thebes", "repository": "Egyptian Museum, Cairo (CG 39194 / JE 36574)", "commonsFile": "Taweret_statue.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Taweret_statue.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Taweret_statue.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f9/Taweret_statue.jpg", "anatomy": ["snarling hippopotamus head wearing a tripartite wig and horned solar crown", "bipedal pregnant belly with pendulous human breasts", "feline lioness limbs and paws resting on braided sa-knots of protection", "broad Nilotic crocodile tail cascading down the spine"], "description": "Carved with mirror-like Saite polish from dense green greywacke and discovered intact inside a limestone naos at Karnak, this 96-centimeter cult figure embodies Egypt's foremost domestic protector of childbirth and mothers. By uniting the maternal ferocity of a female hippopotamus with leonine claws and a dorsal crocodile hide while resting her paws on magical sa-amulets, Taweret turned fearsome riverine predators into an invincible apotropaic shield."}, {"id": "gr-03-corfu-gorgon-pediment", "title": "West Pediment of the Temple of Artemis at Corfu: Archaic Gorgon Medusa", "creature": "Gorgon (Medusa)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Γοργώ Μέδουσα (Gorgō Medousa)", "civilization": "Archaic Greece", "region": "Greece & Aegean", "originLocation": "Sanctuary of Artemis, Kerkyra (Corfu), Greece", "dateDisplay": "c. 580 BCE", "yearSort": -580, "era": "Iron Age & Classical Antiquity", "medium": "Carved limestone architectural high relief", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Corinthian-Corcyraean sculptural workshop", "repository": "Archaeological Museum of Corfu", "commonsFile": "West_facade_of_Temple_of_Artemis,_Gorgoneion,_580_BC,_AM_Corfu,_Krfm10.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:West_facade_of_Temple_of_Artemis,_Gorgoneion,_580_BC,_AM_Corfu,_Krfm10.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/West_facade_of_Temple_of_Artemis,_Gorgoneion,_580_BC,_AM_Corfu,_Krfm10.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7e/West_facade_of_Temple_of_Artemis,_Gorgoneion,_580_BC,_AM_Corfu,_Krfm10.jpg", "anatomy": ["broad grimacing face with boar-like tusks and protruding tongue", "writhing vipers coiled through braided locks", "intertwined two-serpent girdle knotted at the waist", "curved wings and archaic knielauf (kneeling-run) stance"], "description": "Carved in local limestone as the centerpiece of Greece's oldest surviving monumental stone temple pediment, the terrifying Gorgon Medusa rushes forward in the archaic 'kneeling-run' posture. Framed by two recumbent panthers and her newly born offspring Pegasus and Chrysaor, her fanged grimace, protruding tongue, and belt of knotted serpents warded off malevolent forces from the sanctuary of Artemis."}, {"id": "ne-01-ishtar-gate-mushhushshu", "title": "Molded Glazed Brick Relief of a Mušḫuššu Dragon from the Ishtar Gate", "creature": "Mušḫuššu (Sirrush / Dragon of Babylon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Mušḫuššu", "civilization": "Neo-Babylonian Empire", "region": "Ancient Near East & Persia", "originLocation": "Ishtar Gate, Babylon, Babil Governorate, Iraq", "dateDisplay": "Reign of Nebuchadnezzar II, c. 575 BCE", "yearSort": -575, "era": "Iron Age & Classical Antiquity", "medium": "Molded polychrome glazed siliceous bricks", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Draconic & Serpentine", "creator": "Royal brickmakers of Nebuchadnezzar II", "repository": "Pergamon Museum (Vorderasiatisches Museum), Berlin", "commonsFile": "One_dragon_of_the_Ishtar_Gate_of_Babylon,_Iraq,_colored_glazed_and_molded_bricks,_6th_century_BCE._Pergamon_Museum_in_Berlin.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:One_dragon_of_the_Ishtar_Gate_of_Babylon,_Iraq,_colored_glazed_and_molded_bricks,_6th_century_BCE._Pergamon_Museum_in_Berlin.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/One_dragon_of_the_Ishtar_Gate_of_Babylon,_Iraq,_colored_glazed_and_molded_bricks,_6th_century_BCE._Pergamon_Museum_in_Berlin.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4a/One_dragon_of_the_Ishtar_Gate_of_Babylon,_Iraq,_colored_glazed_and_molded_bricks,_6th_century_BCE._Pergamon_Museum_in_Berlin.jpg", "anatomy": ["Horned viper head with forked tongue and elongated scaly neck", "Lion forelegs paired with clawed avian hind talons", "Long scaled body and upturned tail ending in a scorpion stinger"], "description": "Set against a dazzling lapis-blue glazed brick ground along Nebuchadnezzar II's ceremonial Ishtar Gate, alternating rows of golden-white Mušḫuššu ('furious snake') dragons and storm-bulls guarded the northern entrance to Babylon. Sacred servant of the supreme Babylonian god Marduk, the striding composite beast combines viper, lion, eagle, and scorpion anatomy into an unmistakable emblem of divine kingship."}, {"id": "gr-03-acropolis-bluebeard-daemon", "title": "Triple-Bodied Monster ('Bluebeard') from the Hekatompedon Pediment", "creature": "Triple-Bodied Daemon (Typhon / Nereus)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Τρισώματος Δαίμων / Τυφῶν (Trisōmatos Daimōn / Typhōn)", "civilization": "Archaic Greece", "region": "Greece & Aegean", "originLocation": "Athenian Acropolis (Perserschutt deposit), Athens, Greece", "dateDisplay": "c. 570 BCE", "yearSort": -570, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome poros limestone pedimental sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Attic Archaic Acropolis workshop", "repository": "Acropolis Museum, Athens (ACMA 35)", "commonsFile": "ACMA_Triple-Bodied_Monster_on_the_west_pediment_of_the_Old_Temple_of_Athena.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:ACMA_Triple-Bodied_Monster_on_the_west_pediment_of_the_Old_Temple_of_Athena.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/ACMA_Triple-Bodied_Monster_on_the_west_pediment_of_the_Old_Temple_of_Athena.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7c/ACMA_Triple-Bodied_Monster_on_the_west_pediment_of_the_Old_Temple_of_Athena.jpg", "anatomy": ["three smiling bearded male torsos conjoined at the waist", "dark blue-painted beards and hair", "outspread polychrome wings", "intertwined striped serpentine tails"], "description": "Preserving vivid archaic pigments of dark blue, red, and green after being buried on the Acropolis following the Persian sack of 480 BCE, this poros limestone pedimental relief depicts a genial yet monstrous triple-bodied deity ending in twisting snake coils. Holding emblems of water, fire, and air (a bird) in his three left hands, the winged hybrid has been identified variously as Typhon, Proteus, Nereus, or the elemental Tritopatores."}, {"id": "gr-03-delphi-naxian-sphinx", "title": "Colossal Marble Sphinx of the Naxians at Delphi", "creature": "Sphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Σφίγξ (Sphinx)", "civilization": "Archaic Greece", "region": "Greece & Aegean", "originLocation": "Sanctuary of Apollo, Delphi, Phocis, Greece", "dateDisplay": "c. 570–560 BCE", "yearSort": -565, "era": "Iron Age & Classical Antiquity", "medium": "Carved Naxian marble sculpture in the round", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Naxian Cycladic sculptor", "repository": "Archaeological Museum of Delphi", "commonsFile": "Sphix_of_the_Naxians,_570-560_BC,_AM_of_Delphi,_201325.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sphix_of_the_Naxians,_570-560_BC,_AM_of_Delphi,_201325.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sphix_of_the_Naxians,_570-560_BC,_AM_of_Delphi,_201325.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d9/Sphix_of_the_Naxians,_570-560_BC,_AM_of_Delphi,_201325.jpg", "anatomy": ["serene female face with archaic smile and braided kore locks", "sickle-shaped upturned feathered wings", "feathered breastplate over a taut seated feline body", "powerful lion paws resting on an Ionic capital"], "description": "Dedicated by the islanders of Naxos beside the Temple of Apollo at Delphi, this 2.22-meter marble sphinx originally crowned a towering ten-meter Ionic column overlooking the Pythian sanctuary. Blending the enigmatic archaic smile of a Cycladic kore with taut leonine haunches and sweeping sickle-curved wings, she served as a formidable chthonic guardian of the Delphic oracle."}, {"id": "gr-03-laconian-cup-polyphemus", "title": "Laconian Black-Figure Kylix: Odysseus and Companions Blinding Polyphemus", "creature": "Cyclops (Polyphemus)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Κύκλωψ Πολύφημος (Kyklōps Polyphēmos)", "civilization": "Archaic Sparta (Laconia)", "region": "Greece & Aegean", "originLocation": "Laconia, Peloponnese, Greece", "dateDisplay": "c. 565–560 BCE", "yearSort": -562, "era": "Iron Age & Classical Antiquity", "medium": "Laconian black-figure ceramic drinking cup (kylix)", "mediumCategory": "Ceramics & Vessels", "morphology": "Giants, Demons & Spirits", "creator": "Rider Painter", "repository": "Cabinet des Médailles, Bibliothèque nationale de France, Paris (Inv. 190)", "commonsFile": "Odysseus_Polyphemos_Cdm_Paris_190.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Odysseus_Polyphemos_Cdm_Paris_190.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Odysseus_Polyphemos_Cdm_Paris_190.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/45/Odysseus_Polyphemos_Cdm_Paris_190.jpg", "anatomy": ["hulking bearded cannibal giant seated on a rock", "single brow eye impaled by a timber beam", "severed human lower legs clutched in both hands", "serpentine decorative exergue fish below"], "description": "Compressing three moments of Odyssey Book 9 into a single circular tondo, the Laconian Rider Painter shows the monstrous Cyclops Polyphemus simultaneously devouring human limbs, accepting a kantharos of unmixed wine from Odysseus, and being blinded by four heroes hoisting a long stake. A large tuna swims in the exergue beneath their feet, anchoring the cave encounter to Odysseus' perilous sea voyage."}, {"id": "gr-03-corinthian-amphora-ketos", "title": "Late Corinthian Black-Figure Amphora: Perseus, Andromeda, and Ketos", "creature": "Ketos", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Κῆτος (Kētos)", "civilization": "Archaic Greece", "region": "Greece & Aegean", "originLocation": "Made in Corinth; excavated at Cerveteri (Caere), Italy", "dateDisplay": "c. 575–550 BCE", "yearSort": -562, "era": "Iron Age & Classical Antiquity", "medium": "Wheel-thrown ceramic neck-amphora in black-figure with added red and white", "mediumCategory": "Ceramics & Vessels", "morphology": "Marine & Abyssal Monsters", "creator": "Late Corinthian black-figure vase painter", "repository": "Antikensammlung, Altes Museum, Berlin (F 1652)", "commonsFile": "Corinthian_amphora,_Andromeda,_Perseus,_Cetus,_575-550_BC,_Berlin_F_1652,_141650.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Corinthian_amphora,_Andromeda,_Perseus,_Cetus,_575-550_BC,_Berlin_F_1652,_141650.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Corinthian_amphora,_Andromeda,_Perseus,_Cetus,_575-550_BC,_Berlin_F_1652,_141650.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/83/Corinthian_amphora,_Andromeda,_Perseus,_Cetus,_575-550_BC,_Berlin_F_1652,_141650.jpg", "anatomy": ["cavernous white-toothed jaws emerging from the sea", "dog-like snout and glaring predatory eye", "spiny dorsal crest", "massive undulating marine trunk"], "description": "Inscribed in archaic Corinthian script naming Perseus, Andromeda, and Ketos (ΚΕΤΟΣ), this black-figure amphora preserves the earliest known visual survival of the Andromeda myth. Rather than wielding Medusa's severed head, Perseus pelts the colossal fanged sea-monster's gaping white-toothed maw with boulders while Andromeda assists behind him."}, {"id": "gr-03-chalcidian-hydria-typhon", "title": "Chalcidian Black-Figure Hydria: Zeus Hurling His Thunderbolt at Winged Typhon", "creature": "Typhon", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Τυφῶν / Τυφωεύς (Typhōn / Typhōeus)", "civilization": "Archaic Western Greece", "region": "Greece & Aegean", "originLocation": "Euboean-Chalcidian workshop (Rhegion); found at Vulci, Italy", "dateDisplay": "c. 550 BCE", "yearSort": -550, "era": "Iron Age & Classical Antiquity", "medium": "Chalcidian black-figure ceramic water jar (hydria)", "mediumCategory": "Ceramics & Vessels", "morphology": "Draconic & Serpentine", "creator": "Inscription Painter", "repository": "Staatliche Antikensammlungen, Munich (Inv. 596)", "commonsFile": "Typhon_Staatliche_Antikensammlungen_596.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Typhon_Staatliche_Antikensammlungen_596.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Typhon_Staatliche_Antikensammlungen_596.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/93/Typhon_Staatliche_Antikensammlungen_596.jpg", "anatomy": ["bearded anthropoid upper torso and fierce glaring face", "four expansive multicolored wings", "twin coiling serpent legs replacing human limbs", "forked scaly draconic tails"], "description": "On the shoulder-and-belly frieze of this celebrated Chalcidian hydria, the storm-monster Typhon confronts Zeus's raised thunderbolt in a cosmic struggle for sovereignty over the heavens. Rendered with incised precision and rich purple-red highlights, Typhon combines a muscular bearded male torso and sweeping wings with twin writhing, scaly serpent coils in place of legs."}, {"id": "gr-03-louvre-amphora-minotaur", "title": "Attic Black-Figure Amphora: Theseus Slaying the Bull-Headed Minotaur", "creature": "Minotaur", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Μινώταυρος (Minōtauros)", "civilization": "Archaic Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece", "dateDisplay": "c. 540 BCE", "yearSort": -540, "era": "Iron Age & Classical Antiquity", "medium": "Attic black-figure ceramic amphora", "mediumCategory": "Ceramics & Vessels", "morphology": "Therianthropic (Human-Beast)", "creator": "Group of London B 174", "repository": "Musée du Louvre, Paris (F 33)", "commonsFile": "Theseus_Minotaur_Louvre_F33.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Theseus_Minotaur_Louvre_F33.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Theseus_Minotaur_Louvre_F33.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e2/Theseus_Minotaur_Louvre_F33.jpg", "anatomy": ["horned bovine bull head and thick muscled neck", "athletic human male torso, arms, and legs", "bovine tail hanging behind", "hand brandishing a jagged boulder in defense"], "description": "Flanked by Athenian youths and maidens sent as tribute to Crete, the youthful hero Theseus seizes the Minotaur by the horn and drives his sword deep into the monster's throat on this Attic black-figure amphora. Forced onto one knee while clutching a stone in vain resistance, the Cretan hybrid displays the canonical Greek iconography of a powerful human physique surmounted by a horned bull's head."}, {"id": "gr-03-louvre-hydria-cerberus", "title": "Caeretan Black-Figure Hydria: Herakles Presenting Cerberus to Terrified Eurystheus", "creature": "Cerberus", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Κέρβερος (Kerberos)", "civilization": "Archaic East Greece (Ionian-Caeretan)", "region": "Greece & Aegean", "originLocation": "Ionian Greek immigrant workshop at Caere (Cerveteri)", "dateDisplay": "c. 525 BCE", "yearSort": -525, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome black-figure terracotta hydria with red, white, and ochre slips", "mediumCategory": "Ceramics & Vessels", "morphology": "Composite Chimeras", "creator": "Eagle Painter", "repository": "Musée du Louvre, Paris (E 701)", "commonsFile": "Herakles_Kerberos_Eurystheus_Louvre_E701.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Herakles_Kerberos_Eurystheus_Louvre_E701.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Herakles_Kerberos_Eurystheus_Louvre_E701.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1a/Herakles_Kerberos_Eurystheus_Louvre_E701.jpg", "anatomy": ["three snarling canine heads painted in black, red, and white", "mane of venomous snakes sprouting along necks, paws, and back", "coiling serpent-headed tail", "massive hound body restrained on a leash"], "description": "Painted with irrepressible comic flair by an East Greek master from Phocaea working in Caere, this hydria depicts Herakles hauling the Hound of Hades into the daylight while King Eurystheus dives headlong into a sunken storage pithos in terror. Cerberus bristles with coloristic ferocity: his three distinct dog heads—black, russet, and white—are ringed with a living mane of hissing vipers."}, {"id": "gr-03-getty-hydria-hydra", "title": "Caeretan Black-Figure Hydria: Herakles and Iolaos Battling the Lernaean Hydra", "creature": "Lernaean Hydra", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Ὕδρα Λερναία (Hydra Lernaia)", "civilization": "Archaic East Greece (Ionian-Caeretan)", "region": "Greece & Aegean", "originLocation": "Ionian Greek immigrant workshop at Caere (Cerveteri)", "dateDisplay": "c. 525 BCE", "yearSort": -525, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome black-figure ceramic water jar (hydria)", "mediumCategory": "Ceramics & Vessels", "morphology": "Draconic & Serpentine", "creator": "Eagle Painter", "repository": "J. Paul Getty Museum, Getty Villa, Malibu (83.AE.346)", "commonsFile": "Lernaean_Hydra_Getty_Villa_83.AE.346.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Lernaean_Hydra_Getty_Villa_83.AE.346.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Lernaean_Hydra_Getty_Villa_83.AE.346.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/be/Lernaean_Hydra_Getty_Villa_83.AE.346.jpg", "anatomy": ["nine long undulating serpentine necks", "fanged dragon heads with forked darting tongues", "thick braided central serpent trunk", "coiled tail accompanied by Hera's pinching crab"], "description": "Across the front of this vibrant Caeretan hydria, the nine-headed Lernaean Hydra rears up as a writhing knot of fanged serpents while Herakles clubs its necks and his nephew Iolaos cauterizes the stumps with a blazing sickle-brand. Beneath the monster's coils, a giant crab sent by Hera pinches Herakles' heel, capturing every detail of the hero's second labor."}, {"id": "gr-03-bnf-kylix-gorgoneion", "title": "Attic Black-Figure Kylix Tondo: Apotropaic Gorgoneion", "creature": "Gorgon (Gorgoneion)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Γοργόνειον (Gorgoneion)", "civilization": "Archaic Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece (excavated at Cerveteri)", "dateDisplay": "c. 520 BCE", "yearSort": -520, "era": "Iron Age & Classical Antiquity", "medium": "Attic black-figure ceramic kylix with added purple-red and white", "mediumCategory": "Ceramics & Vessels", "morphology": "Giants, Demons & Spirits", "creator": "Leagros Group", "repository": "Cabinet des Médailles, Bibliothèque nationale de France, Paris (Inv. 322)", "commonsFile": "Gorgoneion_Cdm_Paris_322.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gorgoneion_Cdm_Paris_322.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gorgoneion_Cdm_Paris_322.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/55/Gorgoneion_Cdm_Paris_322.jpg", "anatomy": ["strictly frontal mask-like visage", "wide staring eyes and furrowed brow", "gaping grin baring four curved boar tusks", "hanging blood-red tongue and fringed beard"], "description": "Positioned at the center of an Attic black-figure drinking cup, this disembodied Gorgon mask (Gorgoneion) remained hidden beneath dark wine until a symposiast drained the vessel, suddenly locking eyes with Medusa's petrifying stare. Incised curls, glaring white sclera, four projecting tusks, and a bright crimson tongue exemplify the playfully terrifying theatricality of Archaic Greek banquet ware."}, {"id": "ne-01-susa-lion-griffin", "title": "Glazed Brick Frieze of a Winged Lion-Griffin from the Palace of Darius", "creature": "Persian Winged Horned Lion-Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Šīr-dal / Susian Lion-Griffin", "civilization": "Achaemenid Persian Empire", "region": "Ancient Near East & Persia", "originLocation": "Apadana Palace of Darius I, Susa (Shush), Khuzestan, Iran", "dateDisplay": "Reign of Darius I, c. 510 BCE", "yearSort": -510, "era": "Iron Age & Classical Antiquity", "medium": "Molded polychrome glazed siliceous bricks", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Composite Chimeras", "creator": "Imperial Achaemenid craftsmen (Babylonian and Elamite brickmakers)", "repository": "Musée du Louvre, Paris", "commonsFile": "Frieze_of_Griffins,_circa_510_BC,_Apadana,_west_courtyard_of_the_palace,_Susa,_Iran_Susa,_Iran,_Louvre_Museum_(12251831946).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Frieze_of_Griffins,_circa_510_BC,_Apadana,_west_courtyard_of_the_palace,_Susa,_Iran_Susa,_Iran,_Louvre_Museum_(12251831946).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Frieze_of_Griffins,_circa_510_BC,_Apadana,_west_courtyard_of_the_palace,_Susa,_Iran_Susa,_Iran,_Louvre_Museum_(12251831946).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/96/Frieze_of_Griffins,_circa_510_BC,_Apadana,_west_courtyard_of_the_palace,_Susa,_Iran_Susa,_Iran,_Louvre_Museum_(12251831946).jpg", "anatomy": ["Snarling lion head crowned with curved ibex horns and equine ears", "Polychrome turquoise, yellow, and ivory sickle-curved wings", "Lion forelegs paired with powerful feathered eagle hind legs and talons"], "description": "Adorning the west courtyard of Darius the Great's palace at Susa, this molded siliceous brick frieze adapts Neo-Babylonian and Elamite glazing traditions into Achaemenid imperial court style. The striding monster unites a horned lion's head and forequarters with the hind talons of an eagle and jewel-like multicolored wings."}, {"id": "am-10-australia-mimi-anbangbang-rock-art", "title": "Anbangbang Rock-Shelter Painting of Dancing Mimi Spirits", "creature": "Mimi Rock-Cleft Trickster and Teacher Spirits", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Mimi", "civilization": "Bininj / Kunwinjku (Indigenous Australian)", "region": "The Americas & Oceania", "originLocation": "Anbangbang Gallery, Burrunggui (Nourlangie Rock), Kakadu, Northern Territory, Australia", "dateDisplay": "Pre-contact rock art tradition (c. 1000 BCE–1500 CE)", "yearSort": -500, "era": "Iron Age & Classical Antiquity", "medium": "Red haematite ochre pigment on quartzose sandstone overhang", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Attributed in Bininj tradition to the Mimi spirits themselves / ancestral Kakadu artists", "repository": "Kakadu National Park, Northern Territory, Australia (in situ)", "commonsFile": "Anbangbang_gallery_Mimi_rock_art_cropped.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Anbangbang_gallery_Mimi_rock_art_cropped.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Anbangbang_gallery_Mimi_rock_art_cropped.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1d/Anbangbang_gallery_Mimi_rock_art_cropped.jpg", "anatomy": ["impossibly tall, thread-thin limbs and elongated torsos susceptible to strong winds", "elaborate ceremonial headdresses and dilly-bags slung from the neck", "dynamic striding postures wielding multi-pronged spears and spear-throwers"], "description": "Sheltered beneath the sandstone cliffs of Burrunggui (Nourlangie) in Kakadu, these delicate red-ochre figures depict the Mimi—ancient fairy-like spirits of the Arnhem Land plateau who first taught Aboriginal ancestors how to hunt kangaroo, cook with fire, dance, and paint rock walls before humans arrived. Because their bodies are as slender as blades of grass and would snap in a stiff breeze, the Mimi blow open hairline fissures in the sandstone escarpment to live deep inside the rock, emerging only on windless nights."}, {"id": "gr-03-syracuse-amphora-triton", "title": "Attic Black-Figure Amphora: Herakles Wrestling the Sea-God Triton", "creature": "Triton", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Τρίτων (Tritōn)", "civilization": "Late Archaic Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece (found in Sicily)", "dateDisplay": "c. 500 BCE", "yearSort": -500, "era": "Iron Age & Classical Antiquity", "medium": "Attic black-figure ceramic amphora", "mediumCategory": "Ceramics & Vessels", "morphology": "Marine & Abyssal Monsters", "creator": "Pasikles Painter", "repository": "Museo Archeologico Regionale Paolo Orsi, Syracuse", "commonsFile": "Black_figure_amphora,_Heracles,_Triton,_500_BC,_AM_Syracuse,_121392.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Black_figure_amphora,_Heracles,_Triton,_500_BC,_AM_Syracuse,_121392.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Black_figure_amphora,_Heracles,_Triton,_500_BC,_AM_Syracuse,_121392.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d3/Black_figure_amphora,_Heracles,_Triton,_500_BC,_AM_Syracuse,_121392.jpg", "anatomy": ["bearded wreathed male upper torso and arms", "long scaly serpentine piscine body", "serrated dorsal fin crest", "forked fish caudal fin"], "description": "Under the watchful gaze of Athena, Herakles locks his arms around the chest of the merman deity Triton, wrestling the elusive 'Old Man of the Sea' to extract directions to the Garden of the Hesperides. Triton's bearded human upper body transitions seamlessly at the waist into a long, intricately incised fish-scaled tail that coils across the amphora's panel."}, {"id": "ne-01-persepolis-homa-capital", "title": "Double-Headed Eagle-Griffin (Homa) Column Capital at Persepolis", "creature": "Homa (Achaemenid Eagle-Griffin)", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Homā", "civilization": "Achaemenid Persian Empire", "region": "Ancient Near East & Persia", "originLocation": "Persepolis (Takht-e Jamshid), Fars Province, Iran", "dateDisplay": "c. 500–460 BCE", "yearSort": -480, "era": "Iron Age & Classical Antiquity", "medium": "Carved dark grey limestone", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Imperial workshops of Darius I and Xerxes I", "repository": "In situ, Persepolis World Heritage Site, Iran", "commonsFile": "Persepolis_griffin_capitals.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Persepolis_griffin_capitals.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Persepolis_griffin_capitals.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e1/Persepolis_griffin_capitals.jpg", "anatomy": ["Fierce hooked eagle beak, prominent brow ridge, and upright mammalian ears", "Crested neck mane with tightly carved scale-like plumage", "Addorsed double-protome leonine-avian chests designed to cradle roof beams"], "description": "Carved from polished grey limestone for an unfinished monumental hall or gate at Persepolis, these addorsed eagle-griffin column capitals are celebrated in Iranian tradition as representations of the auspicious mythic bird Homā. Combining raptorial beaks and crested manes with alert upright ears and leonine forequarters, the paired protomes epitomize the cosmopolitan synthesis of Achaemenid court sculpture."}, {"id": "gr-03-xanthos-harpy-tomb-relief", "title": "Harpy Tomb Relief from Xanthos: Winged Female Creature Carrying a Soul", "creature": "Harpy / Psychopomp Siren", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Ἅρπυια / Σειρήν (Harpyia / Seirēn)", "civilization": "Archaic Greco-Lycian", "region": "Greece & Aegean", "originLocation": "Acropolis of Xanthos, Lycia (carved in East Greek Archaic style)", "dateDisplay": "c. 480 BCE", "yearSort": -480, "era": "Iron Age & Classical Antiquity", "medium": "Carved white marble tomb-chamber relief slab", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "East Greek / Ionian sculptor at Xanthos", "repository": "British Museum, London (Sculpture B287)", "commonsFile": "The_Harpy_Tomb_reliefs,_north_side,_detail_of_one_of_the_winged_female_creatures_carry_small_figures_perhaps_representing_souls_of_the_dead,_about_480_BC,_Xanthos,_British_Museum,_London_(8825529476).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:The_Harpy_Tomb_reliefs,_north_side,_detail_of_one_of_the_winged_female_creatures_carry_small_figures_perhaps_representing_souls_of_the_dead,_about_480_BC,_Xanthos,_British_Museum,_London_(8825529476).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/The_Harpy_Tomb_reliefs,_north_side,_detail_of_one_of_the_winged_female_creatures_carry_small_figures_perhaps_representing_souls_of_the_dead,_about_480_BC,_Xanthos,_British_Museum,_London_(8825529476).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e2/The_Harpy_Tomb_reliefs,_north_side,_detail_of_one_of_the_winged_female_creatures_carry_small_figures_perhaps_representing_souls_of_the_dead,_about_480_BC,_Xanthos,_British_Museum,_London_(8825529476).jpg", "anatomy": ["archaic female head, coiffure, and human arms", "plump ovoid bird body and feathered tail", "broad layered eagle wings", "raptor legs and talons clutching a diminutive human figure"], "description": "Carved by East Greek sculptors for a dynastic pillar tomb at Xanthos, four winged bird-women soar away from enthroned rulers while tenderly cradling tiny human figures against their feathered breasts. Long known as 'Harpies' after Homer's snatching storm-spirits—though modern scholars also link them to benevolent Siren psychopomps—they embody the gentle transport of mortal souls to the afterlife."}, {"id": "rm-04-capitoline-wolf", "title": "The Capitoline Wolf (Lupa Capitolina)", "creature": "Lupa Romana (Sacred She-Wolf)", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "Lupa Capitolina", "civilization": "Etruscan / Roman", "region": "Etruria, Rome & Byzantium", "originLocation": "Rome, Latium, Italy", "dateDisplay": "5th century BCE (traditional) or 11th–12th century CE (disputed casting)", "yearSort": -480, "era": "Iron Age & Classical Antiquity", "medium": "Hollow-cast bronze (twins added late 15th century CE)", "mediumCategory": "Sculpture & Relief", "morphology": "Single-Horned & Sacred Beasts", "creator": "Unknown Etruscan or medieval Italian bronze-caster (twins attributed to Antonio del Pollaiuolo)", "repository": "Capitoline Museums, Rome (MC 1181)", "commonsFile": "Capitoline_she-wolf_Musei_Capitolini_MC1181.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Capitoline_she-wolf_Musei_Capitolini_MC1181.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Capitoline_she-wolf_Musei_Capitolini_MC1181.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/aa/Capitoline_she-wolf_Musei_Capitolini_MC1181.jpg", "anatomy": ["tense lupine stance with bared fangs", "stylized curling mane along the neck", "distended dugs nursing human founder-twins"], "description": "Standing 75 cm high in hollow-cast bronze, the Capitoline She-Wolf embodies the sacred beast sent by Mars to suckle the exposed twin infants Romulus and Remus on the banks of the Tiber. Long attributed to a 5th-century BCE Veientine Etruscan workshop—though contested by thermoluminescence studies suggesting medieval recasting—its rigid posture, incised neck curls, and fierce apotropaic gaze defined Rome's foundational iconography."}, {"id": "gr-03-vatican-kylix-colchian-dragon", "title": "Attic Red-Figure Kylix by Douris: The Colchian Dragon Regurgitating Jason", "creature": "Colchian Dragon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Δράκων Κολχικός (Drakōn Kolchikos)", "civilization": "Early Classical Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece (excavated at Cerveteri)", "dateDisplay": "c. 480–470 BCE", "yearSort": -475, "era": "Iron Age & Classical Antiquity", "medium": "Attic red-figure ceramic kylix", "mediumCategory": "Ceramics & Vessels", "morphology": "Draconic & Serpentine", "creator": "Douris", "repository": "Museo Gregoriano Etrusco, Vatican Museums (Inv. 16545)", "commonsFile": "Douris_cup_Jason_Vatican_16545.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Douris_cup_Jason_Vatican_16545.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Douris_cup_Jason_Vatican_16545.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/33/Douris_cup_Jason_Vatican_16545.jpg", "anatomy": ["immense speckled serpent body with ventral belly plates", "crested draconic head and fleshy chin beard", "rows of sharp recurved teeth", "distended jaws disgorging a full-grown hero"], "description": "Preserving an otherwise lost variant of the Argonautic myth unknown to extant literary texts, the master vase-painter Douris depicts the sleepless Colchian Dragon regurgitating a limp, bearded Jason at the command of Athena, who stands calmly holding her owl and spear. Behind the giant bearded serpent, the Golden Fleece hangs gleaming from the branches of the sacred grove."}, {"id": "gr-03-bm-stamnos-odysseus-sirens", "title": "The Siren Vase: Attic Red-Figure Stamnos of Odysseus and the Sirens", "creature": "Siren", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Σειρήν (Seirēn)", "civilization": "Early Classical Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece (excavated at Vulci, Italy)", "dateDisplay": "c. 480–470 BCE", "yearSort": -475, "era": "Iron Age & Classical Antiquity", "medium": "Attic red-figure ceramic wine-mixing jar (stamnos)", "mediumCategory": "Ceramics & Vessels", "morphology": "Avian & Winged Hybrids", "creator": "Siren Painter (name-vase)", "repository": "British Museum, London (Vase E 440)", "commonsFile": "Odysseus_Sirens_BM_E440.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Odysseus_Sirens_BM_E440.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Odysseus_Sirens_BM_E440.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/cd/Odysseus_Sirens_BM_E440.jpg", "anatomy": ["diademed female human head with parted lips in song", "plump speckled songbird body and fan tail", "outspread feathered raptor wings", "bird legs with sharp talons perched on sea-cliffs"], "description": "The definitive ancient visualization of Homer's Sirens, this Early Classical stamnos shows Odysseus lashed tightly to the mast of his oared galley as his wax-deafened crew rows past rocky headlands. Two Sirens perch on opposing cliffs singing their fatal melody—one inscribed 'Himeropa' ('Voice of Yearning')—while a third plunges headfirst with closed eyes into the sea in suicide upon failing to lure the hero."}, {"id": "gr-03-vatican-kylix-oedipus-sphinx", "title": "Attic Red-Figure Kylix: Oedipus Pondering the Riddle of the Theban Sphinx", "creature": "Sphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Σφίγξ (Sphinx)", "civilization": "Early Classical Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece (excavated at Vulci, Italy)", "dateDisplay": "c. 470–460 BCE", "yearSort": -465, "era": "Iron Age & Classical Antiquity", "medium": "Attic red-figure ceramic kylix", "mediumCategory": "Ceramics & Vessels", "morphology": "Composite Chimeras", "creator": "Oedipus Painter", "repository": "Museo Gregoriano Etrusco, Vatican Museums (Inv. 16541)", "commonsFile": "Oedipus_being_questioned_by_the_Sphinx,_Attic_red-figured_kylix,_by_the_Oedipus_Painter,_470-460_BC,_inv._16541_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01041.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Oedipus_being_questioned_by_the_Sphinx,_Attic_red-figured_kylix,_by_the_Oedipus_Painter,_470-460_BC,_inv._16541_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01041.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Oedipus_being_questioned_by_the_Sphinx,_Attic_red-figured_kylix,_by_the_Oedipus_Painter,_470-460_BC,_inv._16541_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01041.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Oedipus_being_questioned_by_the_Sphinx,_Attic_red-figured_kylix,_by_the_Oedipus_Painter,_470-460_BC,_inv._16541_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01041.jpg", "anatomy": ["diademed female head leaning forward in interrogation", "seated leonine body perched atop an Ionic column", "spotted and layered avian wings", "tufted feline tail"], "description": "Replacing physical combat with psychological tension, the tondo of this Attic red-figure kylix seats the winged Theban Sphinx high atop an Ionic column face-to-face with the weary traveler Oedipus, who rests chin-in-hand wearing his petasos hat and chlamys cloak. Painted inscriptions record a fragment of her deadly riddle ('and having three [feet]...'), immortalizing the triumph of human intellect over monstrous terror."}, {"id": "gr-03-louvre-kylix-satyr-maenad", "title": "Attic Red-Figure Kylix Tondo: Equine-Tailed Silenus (Satyr) and Maenad", "creature": "Satyr (Silenus)", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Σάτυρος / Σειληνός (Satyros / Seilēnos)", "civilization": "Classical Greece", "region": "Greece & Aegean", "originLocation": "Athens, Attica, Greece (excavated at Vulci)", "dateDisplay": "c. 460–450 BCE", "yearSort": -455, "era": "Iron Age & Classical Antiquity", "medium": "Attic red-figure ceramic kylix", "mediumCategory": "Ceramics & Vessels", "morphology": "Therianthropic (Human-Beast)", "creator": "Penthesilea Painter workshop", "repository": "Musée du Louvre, Paris (G 448)", "commonsFile": "Satyros_mainade_Louvre_G448.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Satyros_mainade_Louvre_G448.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Satyros_mainade_Louvre_G448.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2b/Satyros_mainade_Louvre_G448.jpg", "anatomy": ["bald forehead, snub nose, and shaggy beard", "pointed equine ears", "muscular human body", "long bushy horse tail"], "description": "Framed within a meander border on the interior of an Attic wine cup, a wild woodland satyr (silenos) confronts a thyrsus-bearing maenad from the ecstatic retinue of Dionysus. True to fifth-century Athenian convention—before Hellenistic syncretism with goat-legged Pan—the satyr possesses pointed equine ears, a snub-nosed bestial visage, and a flowing horse's tail."}, {"id": "gr-03-bm-melos-relief-scylla", "title": "Melian Terracotta Relief Plaque of the Sea-Monster Scylla", "creature": "Scylla", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Σκύλλα (Skylla)", "civilization": "Classical Greece", "region": "Greece & Aegean", "originLocation": "Made on Melos; excavated on Aegina, Greece", "dateDisplay": "c. 460–450 BCE", "yearSort": -455, "era": "Iron Age & Classical Antiquity", "medium": "Mold-pressed open-work terracotta relief plaque", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Melian coroplastic workshop", "repository": "British Museum, London (Cat. Terracotta 621)", "commonsFile": "Skylla_BM_621.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Skylla_BM_621.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Skylla_BM_621.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9a/Skylla_BM_621.jpg", "anatomy": ["classical maiden head and upper torso", "pack of snarling hounds springing from the groin and flanks", "spiny coiled sea-serpent tail", "finned marine crest"], "description": "Produced on the Cycladic island of Melos as an ornamental chest or funerary attachment, this open-work terracotta plaque establishes the Classical visual form of Scylla, terror of the Strait of Messina. Unlike Homer's six-necked cave beast, Classical artists envisioned her as a graceful maiden from the waist up whose loins erupt into baying hunting dogs above a long, undulating ketos-like sea tail."}, {"id": "cn-07-tuekta-altai-griffin", "title": "Carved Wooden Horned Griffin from Tuekta Kurgan", "creature": "Altai Eagle-Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Грифон из Туэкты", "civilization": "Pazyryk / Early Altai Scythian Culture", "region": "East Asia & Eurasian Steppe", "originLocation": "Tuekta Kurgan 1, Altai Mountains, Siberia, Russia", "dateDisplay": "5th century BCE", "yearSort": -450, "era": "Iron Age & Classical Antiquity", "medium": "Carved wood and leather (preserved in kurgan permafrost)", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Altai nomadic woodcarver", "repository": "State Hermitage Museum, St. Petersburg", "commonsFile": "35._Samruk_(Griffin)_buriel_mound_Tuekta_(V._B.C.)_Altay.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:35._Samruk_(Griffin)_buriel_mound_Tuekta_(V._B.C.)_Altay.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/35._Samruk_(Griffin)_buriel_mound_Tuekta_(V._B.C.)_Altay.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8d/35._Samruk_(Griffin)_buriel_mound_Tuekta_(V._B.C.)_Altay.JPG", "anatomy": ["hooked raptor beak with cere", "serrated upright dorsal crest", "sweeping slotted wing-slots", "arched avian neck"], "description": "Preserved for over two millennia in the frozen burial lens of Tuekta Kurgan 1 in the high Altai, this sculpted wooden harness finial depicts a fierce eagle-griffin with a deeply curved raptor beak and notched comb. Originally fitted with leather wings and covered in gold foil, such predatory hybrids guarded the horses sacrificed to carry nomadic chieftains into the afterlife."}, {"id": "gr-03-parthenon-metope-centaur", "title": "Parthenon South Metope XXX: Centaur Triumphing Over a Fallen Lapith", "creature": "Centaur", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Κένταυρος (Kentauros)", "civilization": "High Classical Greece", "region": "Greece & Aegean", "originLocation": "Parthenon, Acropolis of Athens, Greece", "dateDisplay": "c. 447–438 BCE", "yearSort": -442, "era": "Iron Age & Classical Antiquity", "medium": "Pentelic marble high-relief architectural metope", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Workshop of Phidias", "repository": "British Museum, London (Sculpture 319)", "commonsFile": "The_Parthenon_Sculptures_–_Centaur_and_Lapith_from_South_metope_XXX,_British_Museum_(26833248410).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:The_Parthenon_Sculptures_%E2%80%93_Centaur_and_Lapith_from_South_metope_XXX,_British_Museum_(26833248410).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/The_Parthenon_Sculptures_%E2%80%93_Centaur_and_Lapith_from_South_metope_XXX,_British_Museum_(26833248410).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/11/The_Parthenon_Sculptures_%E2%80%93_Centaur_and_Lapith_from_South_metope_XXX,_British_Museum_(26833248410).jpg", "anatomy": ["furrowed bestial bearded face and muscular human chest", "seamless anatomical transition at the ribcage and equine withers", "rearing stallion barrel and hindquarters", "sharp equine hooves trampling the adversary"], "description": "Carved in Pentelic marble for the southern Doric frieze of the Parthenon under the supervision of Phidias, South Metope XXX dramatizes the mythical Centauromachy at the wedding of Peirithoos as an allegory of Greek order (nomos) threatened by untamed savagery (hybris). Rearing upon powerful equine hind legs while a panther skin swirls behind him, the centaur plunges his forehooves into the flank of a kneeling Lapith youth."}, {"id": "gr-03-munich-medusa-rondanini", "title": "The Medusa Rondanini", "creature": "Gorgon (Medusa)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Γοργώ Μέδουσα (Gorgō Medousa)", "civilization": "Classical Greece (Roman Imperial copy after a 5th-century BCE Attic original)", "region": "Greece & Aegean", "originLocation": "After an Athenian original of c. 440 BCE attributed to Phidias", "dateDisplay": "Original c. 440 BCE (marble copy 1st–2nd century CE)", "yearSort": -440, "era": "Iron Age & Classical Antiquity", "medium": "Carved Parian marble high-relief mask", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "After Phidias (attributed)", "repository": "Glyptothek, Munich (GL 252)", "commonsFile": "Rondanini_Medusa_Glyptothek_Munich_252_n1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Rondanini_Medusa_Glyptothek_Munich_252_n1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Rondanini_Medusa_Glyptothek_Munich_252_n1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8f/Rondanini_Medusa_Glyptothek_Munich_252_n1.jpg", "anatomy": ["idealized sorrowful Classical female features", "pair of small wings sprouting above the temples", "undulating locks mingling with two scaled serpents", "knotted snake tails tied beneath the chin"], "description": "Widely regarded as a faithful marble reflection of the gilded Gorgoneion set by Phidias at the center of Athena Parthenos' shield, the Medusa Rondanini marks the pivotal transformation of the Gorgon from hideous archaic monster into a hauntingly beautiful woman. Two small wings rise from her brow while twin vipers frame her cheeks and knot their tails beneath her chin, freezing her visage in cool, tragic stillness."}, {"id": "cn-07-zeng-antlered-crane", "title": "Bronze Antlered Crane from the Tomb of Marquis Yi of Zeng", "creature": "Lujiao Lihe (Antlered Spirit-Crane)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "曾侯乙青銅鹿角立鶴 (Lùjiǎo Lìhè)", "civilization": "Zeng State (Warring States Period)", "region": "East Asia & Eurasian Steppe", "originLocation": "Leigudun, Suizhou, Hubei, China", "dateDisplay": "c. 433 BCE", "yearSort": -433, "era": "Iron Age & Classical Antiquity", "medium": "Cast bronze with gold and turquoise inlay", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Court foundry of Marquis Yi of Zeng", "repository": "Hubei Provincial Museum, Wuhan", "commonsFile": "Antlered_crane,_Chinese_bronze,_Warring_States_period.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Antlered_crane,_Chinese_bronze,_Warring_States_period.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Antlered_crane,_Chinese_bronze,_Warring_States_period.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/30/Antlered_crane,_Chinese_bronze,_Warring_States_period.jpg", "anatomy": ["sweeping palmate stag antlers", "long arched crane neck and spear-like bill", "outspread flat bronze wings", "scrolling dragon-and-serpent relief plumage"], "description": "Inscribed along its beak with a dedication for Marquis Yi of Zeng, this 1.4-meter bronze sculpture fuses two emblems of immortality—the sky-faring crane and the antler-shedding stag—into an auspicious psychopomp placed beside the ruler's inner coffin. Its outstretched wings and branched antlers are further incised with curling dragons and turquoise accents to guide the deceased spirit skyward."}, {"id": "rm-04-chimera-arezzo", "title": "Chimera of Arezzo", "creature": "Chimera", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Chimera (tinscvil)", "civilization": "Etruscan", "region": "Etruria, Rome & Byzantium", "originLocation": "Arezzo (ancient Arretium), Tuscany, Italy", "dateDisplay": "c. 400 BCE", "yearSort": -400, "era": "Iron Age & Classical Antiquity", "medium": "Hollow-cast lost-wax bronze", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Etruscan master bronze-caster", "repository": "National Archaeological Museum, Florence (Inv. 1)", "commonsFile": "Chimera_di_Arezzo.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Chimera_di_Arezzo.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Chimera_di_Arezzo.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/bc/Chimera_di_Arezzo.jpg", "anatomy": ["roaring leonine forequarters with bristling mane", "wounded goat's head erupting from the spine", "horned venomous serpent tail biting the goat's horn"], "description": "Unearthed near the Porta San Lorentino in Arezzo in 1553 and inscribed 'TINSCVIL' ('dedicated to Tinia') on its right foreleg, this 80-cm Etruscan votive bronze originally confronted a lost statue of Bellerophon and Pegasus. Every sinew of the composite monster coils in agony as blood drips from the goat-head protruding mid-spine while its restored serpent-tail strikes upward."}, {"id": "am-10-chavin-raimondi-stela", "title": "The Raimondi Stela (Composite Staff Deity)", "creature": "Chavín Feline-Raptor-Serpent Staff God", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Dios de los Báculos", "civilization": "Chavín", "region": "The Americas & Oceania", "originLocation": "Chavín de Huántar, Ancash Highlands, Peru", "dateDisplay": "c. 600–200 BCE", "yearSort": -400, "era": "Iron Age & Classical Antiquity", "medium": "Polished and incised light-grey granite monolith", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Chavín temple sculptor", "repository": "Museo Nacional de Arqueología, Antropología e Historia del Perú, Lima", "commonsFile": "Estela_Raimondi.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Estela_Raimondi.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Estela_Raimondi.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/bb/Estela_Raimondi.JPG", "anatomy": ["snarling jaguar-caiman mouth with crossed saber fangs", "raptor talons on hands and feet gripping elaborate serpentiform staffs", "towering anatropic headdress of stacked feline and caiman jaws sprouting serpent hair"], "description": "Standing nearly two meters high in polished granite, the Raimondi Stela employs ingenious contour rivalry (anatropic double-reading) to portray the supreme composite deity of the Early Horizon Andes. Viewed upright, a squat jaguar-mouthed, talon-footed figure clutches two baroque ceremonial staffs beneath a headdress twice its own height; inverted, that towering crown transforms into a cascading column of nested smiling caiman-feline maws fringed with writhing serpents."}, {"id": "gr-03-knossos-didrachm-minotaur", "title": "Silver Didrachm of Knossos: Running Bull-Headed Minotaur", "creature": "Minotaur", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Μινώταυρος / Ἀστερίων (Minōtauros / Asteriōn)", "civilization": "Classical Cretan Greece", "region": "Greece & Aegean", "originLocation": "Knossos, Crete, Greece", "dateDisplay": "c. 425–360 BCE", "yearSort": -390, "era": "Iron Age & Classical Antiquity", "medium": "Die-struck silver didrachm coin", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Civic mint of Knossos", "repository": "Cabinet des Médailles, Bibliothèque nationale de France, Paris", "commonsFile": "Didrachm_Knossos_425-360BC_obverse_CdM_Paris.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Didrachm_Knossos_425-360BC_obverse_CdM_Paris.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Didrachm_Knossos_425-360BC_obverse_CdM_Paris.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/35/Didrachm_Knossos_425-360BC_obverse_CdM_Paris.jpg", "anatomy": ["horned bull head turned in profile", "muscular nude human torso and striding legs", "tufted bovine tail curving behind", "hands clutching spherical throwing stones"], "description": "Struck by the Classical Greek polis of Knossos—paired on its reverse with a geometric labyrinth emblem—this silver didrachm proudly adopts the city's legendary Bronze Age monster as its civic badge. Retaining the dynamic archaic kneeling-run pose within the circular coin flan, the bull-headed Minotaur brandishes stones in both hands as guardian of the Cretan labyrinth."}, {"id": "gr-03-cleveland-corinthian-stater-pegasus", "title": "Corinthian Silver Stater ('Polos'): Winged Pegasus in Flight", "creature": "Pegasus", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Πήγασος (Pēgasos)", "civilization": "Classical Greece", "region": "Greece & Aegean", "originLocation": "Corinth, Peloponnese, Greece", "dateDisplay": "c. 385 BCE", "yearSort": -385, "era": "Iron Age & Classical Antiquity", "medium": "Die-struck silver stater coin", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Civic mint of Corinth", "repository": "Cleveland Museum of Art (1917.978.a)", "commonsFile": "Greece,_4th_century_BC_-_Corinthian_Stater-_Pegasus_(obverse)_-_1917.978.a_-_Cleveland_Museum_of_Art.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Greece,_4th_century_BC_-_Corinthian_Stater-_Pegasus_(obverse)_-_1917.978.a_-_Cleveland_Museum_of_Art.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Greece,_4th_century_BC_-_Corinthian_Stater-_Pegasus_(obverse)_-_1917.978.a_-_Cleveland_Museum_of_Art.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/86/Greece,_4th_century_BC_-_Corinthian_Stater-_Pegasus_(obverse)_-_1917.978.a_-_Cleveland_Museum_of_Art.jpg", "anatomy": ["thoroughbred stallion head, neck, and hooves", "sweeping feathered raptor wing with layered covert plumes", "airborne galloping forelegs", "archaic koppa (Ϙ) mintmark beneath the belly"], "description": "So ubiquitous across Mediterranean trade that Corinthian silver staters were nicknamed pōloi ('colts'), this coin celebrates Pegasus, the immortal winged stallion tamed by Bellerophon at Corinth's sacred Peirene spring with Athena's golden bridle. Above the archaic letter koppa denoting Corinth, Pegasus surges skyward on finely engraved feathered pinions."}, {"id": "gr-03-athens-kerameikos-siren", "title": "Funerary Marble Statue of a Mourning Siren Playing the Lyre", "creature": "Siren", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Σειρήν (Seirēn)", "civilization": "Classical Greece", "region": "Greece & Aegean", "originLocation": "Kerameikos Cemetery, Athens, Attica, Greece", "dateDisplay": "c. 370 BCE", "yearSort": -370, "era": "Iron Age & Classical Antiquity", "medium": "Carved Pentelic marble funerary sculpture in the round", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Attic Classical sculptor", "repository": "National Archaeological Museum, Athens (Inv. 774)", "commonsFile": "Funerary_statue_of_a_Siren_at_the_National_Archaeological_Museum_of_Athens_on_7_May_2018.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Funerary_statue_of_a_Siren_at_the_National_Archaeological_Museum_of_Athens_on_7_May_2018.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Funerary_statue_of_a_Siren_at_the_National_Archaeological_Museum_of_Athens_on_7_May_2018.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/cf/Funerary_statue_of_a_Siren_at_the_National_Archaeological_Museum_of_Athens_on_7_May_2018.jpg", "anatomy": ["youthful female head, breasts, and human torso", "raised feathered wings framing the shoulders", "feathered bird thighs transitioning at the hips", "raptor legs and talons gripping a rocky plinth"], "description": "Excavated in the Kerameikos necropolis of Athens, where it stood as an acroterial guardian beside grave monuments, this Pentelic marble Siren reimagines Homer's lethal temptress as a compassionate mourner for the dead. Blending a sensitively modeled female upper body with bird thighs, talons, and raised wings, she cradles a tortoiseshell lyre once strung with bronze wires to intone an eternal dirge."}, {"id": "eg-02-metternich-stela-bes", "title": "The Metternich Stela (Magical Cippus of Horus Crowned by Bes)", "creature": "Apotropaic Bes, Winged Pantheistic Spirits, and Noxious Beasts", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Bes & Horus-Shed ('The Savior')", "civilization": "Late Period Egypt (30th Dynasty)", "region": "Egypt & Africa", "originLocation": "Heliopolis (later relocated to Alexandria; commissioned by the priest Esatum)", "dateDisplay": "Reign of Nectanebo II, c. 360–343 BCE", "yearSort": -350, "era": "Iron Age & Classical Antiquity", "medium": "Finely incised dark gray-green greywacke", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Royal Heliopolitan lapidary workshop under Nectanebo II", "repository": "Metropolitan Museum of Art, New York (50.85)", "commonsFile": "Magical_Stela_(Cippus_of_Horus)_MET_50.85_05.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Magical_Stela_(Cippus_of_Horus)_MET_50.85_05.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Magical_Stela_(Cippus_of_Horus)_MET_50.85_05.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9f/Magical_Stela_(Cippus_of_Horus)_MET_50.85_05.jpg", "anatomy": ["ferocious grimacing mask of lion-maned Bes surmounting the central relief", "child Horus standing atop twin crocodiles clutching serpents, scorpions, a lion, and an oryx", "miniature registers of winged composite genii, Taweret, and solar barques"], "description": "The largest and most masterfully carved Egyptian healing cippus ever discovered, the Metternich Stela operated as an active ritual machine: water poured over its dense spell inscriptions and apotropaic figures was collected in a basin and drunk to cure scorpion stings and snakebites. Above the young Horus trampling crocodiles and grasping desert predators in his fists looms the frontal, tongue-baring mask of the dwarf-lion daemon Bes, commanding venomous monsters to yield."}, {"id": "rm-04-winged-horses-tarquinia", "title": "Winged Horses of Tarquinia (Cavalli Alati)", "creature": "Etruscan Winged Steeds", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Cavalli Alati", "civilization": "Etruscan", "region": "Etruria, Rome & Byzantium", "originLocation": "Ara della Regina Sanctuary, Tarquinia, Lazio, Italy", "dateDisplay": "Mid-4th century BCE", "yearSort": -350, "era": "Iron Age & Classical Antiquity", "medium": "Molded polychrome terracotta high relief", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Tarquinian coroplastic workshop", "repository": "Tarquinia National Archaeological Museum, Palazzo Vitelleschi", "commonsFile": "Cavallo_Etrusco_Tarquinia_7b.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Cavallo_Etrusco_Tarquinia_7b.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Cavallo_Etrusco_Tarquinia_7b.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e0/Cavallo_Etrusco_Tarquinia_7b.jpg", "anatomy": ["harnessed equine bodies in synchronized stride", "layered feathered wings sweeping from the shoulders", "arched necks with cropped manes"], "description": "Measuring 114 by 124 cm in fired terracotta, this pedimental plaque once adorned the monumental Ara della Regina temple on the Pian di Civita plateau at ancient Tarquinia. Modelled under late Classical Greek influence, the yoked pair of immortal winged horses drew a divine chariot across the heavens, symbolizing heroic apotheosis in Etruscan civic religion."}, {"id": "cn-07-tovsta-mohyla-pectoral", "title": "Golden Pectoral from Tovsta Mohyla (Griffins Attacking Horses)", "creature": "Scythian Eagle-Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Золота пектораль з Товстої Могили", "civilization": "Royal Scythians", "region": "East Asia & Eurasian Steppe", "originLocation": "Tovsta Mohyla Kurgan, near Pokrov, Dnipropetrovsk Oblast, Ukraine", "dateDisplay": "Second half of 4th century BCE", "yearSort": -340, "era": "Iron Age & Classical Antiquity", "medium": "Cast, chased, granulated, and filigree 24-karat gold with enamel", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Greco-Scythian master goldsmith of the Bosporan workshops", "repository": "Treasury of the National Museum of the History of Ukraine, Kyiv", "commonsFile": "Фрагменты_Пекторали.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%D0%A4%D1%80%D0%B0%D0%B3%D0%BC%D0%B5%D0%BD%D1%82%D1%8B_%D0%9F%D0%B5%D0%BA%D1%82%D0%BE%D1%80%D0%B0%D0%BB%D0%B8.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A4%D1%80%D0%B0%D0%B3%D0%BC%D0%B5%D0%BD%D1%82%D1%8B_%D0%9F%D0%B5%D0%BA%D1%82%D0%BE%D1%80%D0%B0%D0%BB%D0%B8.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/ce/%D0%A4%D1%80%D0%B0%D0%B3%D0%BC%D0%B5%D0%BD%D1%82%D1%8B_%D0%9F%D0%B5%D0%BA%D1%82%D0%BE%D1%80%D0%B0%D0%BB%D0%B8.jpg", "anatomy": ["tearing hooked eagle beaks", "muscular winged feline bodies", "erect serrated neck crests", "grasping raptorial talons"], "description": "Excavated by Borys Mozolevsky in 1971 from a royal Scythian burial mound, this crescentic gold collar divides the cosmos into three tiers, culminating in a dramatic lower register where pairs of winged eagle-griffins sink beaks and claws into rearing steppe horses. Rendered in miniature three-dimensional sculpture, the predation scene encodes Scythian solar-chthonic cosmology and the perpetual struggle between supernatural chaos and pastoral order."}, {"id": "cn-07-pazyryk-horse-mask", "title": "Ceremonial Antlered Stag-and-Tiger Horse Mask", "creature": "Winged Tiger-Horned Stag", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Конская маска с оленьими рогами (Пазырык)", "civilization": "Pazyryk Culture (Altai Scytho-Siberians)", "region": "East Asia & Eurasian Steppe", "originLocation": "Pazyryk Kurgan 1, Altai Mountains, Siberia, Russia", "dateDisplay": "4th–3rd century BCE", "yearSort": -320, "era": "Iron Age & Classical Antiquity", "medium": "Felt, leather, dyed blue fur, and sheet gold foil", "mediumCategory": "Textile & Tapestry", "morphology": "Composite Chimeras", "creator": "Unknown Pazyryk nomadic artisan", "repository": "State Hermitage Museum, St. Petersburg", "commonsFile": "Ancient_Siberian_horse_mask,_Hermitage_Museum,_St._Petersburg.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ancient_Siberian_horse_mask,_Hermitage_Museum,_St._Petersburg.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Siberian_horse_mask,_Hermitage_Museum,_St._Petersburg.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6b/Ancient_Siberian_horse_mask,_Hermitage_Museum,_St._Petersburg.jpg", "anatomy": ["towering leather palmate stag antlers", "pouncing blue-fur tiger with gold discs", "feather-tipped antler tines", "equine facial sheath"], "description": "Fitted over the head of a sacrificed stallion in the frozen chamber of Pazyryk Kurgan 1, this leather-and-felt mask transforms an earthly mount into a mythical antlered beast attacked along the bridge of its nose by a blue-dyed, gold-spangled tiger. By ritually converting horses into horned celestial stags, Pazyryk funerary regalia equipped the deceased chieftain's cortege to traverse upper and lower worlds."}, {"id": "rm-04-tuchulcha-orcus", "title": "The Underworld Demon Tuchulcha Menacing Theseus", "creature": "Tuchulcha", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Tuχulχa", "civilization": "Etruscan", "region": "Etruria, Rome & Byzantium", "originLocation": "Tomb of Orcus II, Monterozzi Necropolis, Tarquinia, Italy", "dateDisplay": "c. 325–300 BCE", "yearSort": -312, "era": "Iron Age & Classical Antiquity", "medium": "Wall fresco on lime plaster over rock-cut tufa", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Tarquinian tomb painter", "repository": "In situ, Tomb of Orcus II, Tarquinia", "commonsFile": "Tomb_of_orcus_II_tuchulcha_and_these.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tomb_of_orcus_II_tuchulcha_and_these.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tomb_of_orcus_II_tuchulcha_and_these.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Tomb_of_orcus_II_tuchulcha_and_these.jpg", "anatomy": ["hooked vulture beak and glaring eyes", "pointed donkey ears rising through disheveled hair", "great mottled wings and bearded venomous snakes coiled round the arms"], "description": "Painted on the subterranean chamber wall of the Tomb of Orcus II at Tarquinia, the chthonic Etruscan daemon labeled 'Tuχulχa' lunges toward the trapped Greek hero Theseus (Θese) during a game in Hades. Combining a carrion-bird's beak, ass's ears, speckled wings, and brandished vipers, Tuchulcha exemplifies the terrifying hybridity of late Classical Etruscan underworld demonology."}, {"id": "rm-04-trapezophoros-griffins", "title": "Trapezophoros with Two Griffins Devouring a Doe", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Gryps", "civilization": "Daunian / Italic-Hellenistic", "region": "Etruria, Rome & Byzantium", "originLocation": "Ascoli Satriano (ancient Ausculum), Apulia, Italy", "dateDisplay": "c. 325–300 BCE", "yearSort": -310, "era": "Iron Age & Classical Antiquity", "medium": "Carved marble with original polychrome pigments", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Tarentine or Magna Graecian master sculptor", "repository": "Polo Museale di Ascoli Satriano, Foggia", "commonsFile": "Trapezophoros_con_due_grifoni_che_sbranano_una_cerva.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Trapezophoros_con_due_grifoni_che_sbranano_una_cerva.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Trapezophoros_con_due_grifoni_che_sbranano_una_cerva.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0f/Trapezophoros_con_due_grifoni_che_sbranano_una_cerva.jpg", "anatomy": ["hooked raptorial eagle beaks", "polychrome feathered wings tinted rose and blue", "crested dorsal spines and muscular lion hindquarters"], "description": "Carved for an aristocratic Daunian princely tomb in southern Italy, this luxury marble table support (trapezophoros) preserves vivid ancient red, yellow, and blue mineral pigments. Two ferocious leonine griffins sink their beaks and claws into a fallen doe, translating a Near Eastern and Greek solar-guardian motif into Italic funerary pomp."}, {"id": "rm-04-charun-krater-vulci", "title": "Red-Figure Calyx-Krater Depicting the Death Demon Charun", "creature": "Charun", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Χarun", "civilization": "Etruscan", "region": "Etruria, Rome & Byzantium", "originLocation": "Vulci, Lazio, Italy", "dateDisplay": "c. 300 BCE", "yearSort": -300, "era": "Iron Age & Classical Antiquity", "medium": "Wheel-thrown red-figure terracotta with added white and yellow slip", "mediumCategory": "Ceramics & Vessels", "morphology": "Giants, Demons & Spirits", "creator": "Vulcian Etruscan red-figure workshop", "repository": "Altes Museum, Staatliche Museen zu Berlin (Inv. F 2952)", "commonsFile": "Etruscan_Red-figure_Ceramic_Calyx_Krater_Charon,_the_Etruscan_death_demon;_c._300_BC,_found_in_Vulci,_Etruria_(28732745955).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Etruscan_Red-figure_Ceramic_Calyx_Krater_Charon,_the_Etruscan_death_demon%3B_c._300_BC,_found_in_Vulci,_Etruria_(28732745955).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Etruscan_Red-figure_Ceramic_Calyx_Krater_Charon,_the_Etruscan_death_demon%3B_c._300_BC,_found_in_Vulci,_Etruria_(28732745955).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7a/Etruscan_Red-figure_Ceramic_Calyx_Krater_Charon,_the_Etruscan_death_demon%3B_c._300_BC,_found_in_Vulci,_Etruria_(28732745955).jpg", "anatomy": ["hooked nose and bestial grimacing fangs", "pointed animalistic ears and wild locks", "sweeping feathered wings and heavy mallet"], "description": "Excavated at Vulci, this funerary red-figure calyx-krater portrays the Etruscan psychopomp and gatekeeper Charun striding forward in a short belted tunic. Unlike the aged Greek ferryman Charon, the Etruscan Χarun appears as a winged, fanged, hook-nosed demon wielding a heavy mallet used to unbolt—and seal—the gates of the underworld."}, {"id": "cn-07-pazyryk-griffin-carpet", "title": "The Pazyryk Knotted-Pile Carpet with Eagle-Griffin Borders", "creature": "Eagle-Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Пазырыкский ковёр", "civilization": "Pazyryk Culture / Achaemenid-Steppe Exchange", "region": "East Asia & Eurasian Steppe", "originLocation": "Pazyryk Kurgan 5, Altai Mountains, Siberia, Russia", "dateDisplay": "c. 4th–3rd century BCE", "yearSort": -300, "era": "Iron Age & Classical Antiquity", "medium": "Symmetrically knotted wool pile textile", "mediumCategory": "Textile & Tapestry", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Central Asian or West Asian master weaver", "repository": "State Hermitage Museum, St. Petersburg", "commonsFile": "Pazyryk_carpet.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Pazyryk_carpet.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Pazyryk_carpet.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b1/Pazyryk_carpet.jpg", "anatomy": ["recurved wings with curled tips", "profile raptor head turned backward", "crested neck", "striding leonine paws"], "description": "Preserved in solid ice inside Pazyryk Kurgan 5, the world's oldest surviving knotted-pile carpet frames its central star-rosette field with concentric friezes of grazing fallow stags, mounted steppe horsemen, and square medallions of winged eagle-griffins. Each griffin turns its crested bird-of-prey head sharply backward with raised wings, illustrating the prestige of Achaemenid and Central Asian monster motifs among high-Altai nomadic elites."}, {"id": "cn-07-chu-lacquer-zhenmushou", "title": "Two-Headed Lacquered Tomb Guardian Beast (Zhenmushou)", "creature": "Zhenmushou (Antlered Tomb-Quelling Beast)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "楚式漆木鎮墓獸 (Zhènmùshòu)", "civilization": "Chu State (Warring States Period)", "region": "East Asia & Eurasian Steppe", "originLocation": "Jiangling, Hubei, China", "dateDisplay": "4th–3rd century BCE", "yearSort": -300, "era": "Iron Age & Classical Antiquity", "medium": "Carved wood, natural deer antlers, and black-and-vermilion lacquer", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Chu lacquer-workshop artisan", "repository": "Portland Art Museum, Portland, Oregon", "commonsFile": "Two-headed_tomb_guardian_(zhenmushou),_Chu_culture,_Jiangling,_Hubei,_China,_Warring_States_period,_300s-200s_BC,_wood,_antlers,_lacquer_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08581.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Two-headed_tomb_guardian_(zhenmushou),_Chu_culture,_Jiangling,_Hubei,_China,_Warring_States_period,_300s-200s_BC,_wood,_antlers,_lacquer_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08581.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Two-headed_tomb_guardian_(zhenmushou),_Chu_culture,_Jiangling,_Hubei,_China,_Warring_States_period,_300s-200s_BC,_wood,_antlers,_lacquer_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08581.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/21/Two-headed_tomb_guardian_(zhenmushou),_Chu_culture,_Jiangling,_Hubei,_China,_Warring_States_period,_300s-200s_BC,_wood,_antlers,_lacquer_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08581.jpg", "anatomy": ["back-to-back twin monstrous heads", "genuine multi-tined deer antlers", "long pendulous red-lacquered tongues", "bulging round apotropaic eyes"], "description": "Characteristic of Chu aristocratic burials in the middle Yangtze valley, this eerie wooden guardian rises in two back-to-back serpentine necks crowned with real stag antlers and painted in scrolling vermilion and black lacquer. With glaring eyes and grotesque protruding tongues hanging to its chest, the zhenmushou warded off subterranean malevolence and pacified restless spirits of the earth."}, {"id": "gr-03-rhodes-mosaic-bellerophon-chimera", "title": "Hellenistic Pebble Mosaic: Bellerophon on Pegasus Slaying the Chimera", "creature": "Chimera", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Χίμαιρα (Chimaira)", "civilization": "Hellenistic Greece", "region": "Greece & Aegean", "originLocation": "City of Rhodes, Dodecanese, Greece", "dateDisplay": "c. 300–270 BCE", "yearSort": -285, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome natural river-pebble floor mosaic with lead strips", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Composite Chimeras", "creator": "Rhodian Hellenistic mosaicist", "repository": "Archaeological Museum of Rhodes", "commonsFile": "Bellerophon_killing_Chimaera_(mosaic_from_Rhodes).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Bellerophon_killing_Chimaera_(mosaic_from_Rhodes).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Bellerophon_killing_Chimaera_(mosaic_from_Rhodes).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/08/Bellerophon_killing_Chimaera_(mosaic_from_Rhodes).jpg", "anatomy": ["tawny maned lion foreparts and roaring jaws", "horned fire-breathing goat head sprouting from the spine", "hissing serpent head forming the tail tip", "paired confrontation with winged Pegasus overhead"], "description": "Laid in finely graded natural pebbles of white, ochre, russet, and black for an elite dining room (andron) in ancient Rhodes, this early Hellenistic floor mosaic captures Bellerophon swooping down astride winged Pegasus to thrust his spear into the Lycian Chimera. True to Hesiod's formula—'lion in front, snake behind, and goat in the middle'—the tripartite beast snarls upward as a goat head erupts from its back and a viper lashes at its tail."}, {"id": "rm-04-vanth-anina-tomb", "title": "Fresco of the Winged Psychopomp Vanth", "creature": "Vanth", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Vanθ", "civilization": "Etruscan", "region": "Etruria, Rome & Byzantium", "originLocation": "Tomb of the Anina, Monterozzi Necropolis, Tarquinia, Italy", "dateDisplay": "3rd century BCE", "yearSort": -250, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome wall fresco on tufa plaster", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Tarquinian Hellenistic tomb painter", "repository": "In situ, Tomb of the Anina, Tarquinia", "commonsFile": "Vanth.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Vanth.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Vanth.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/59/Vanth.jpg", "anatomy": ["vast polychrome wings framing a female torso", "crossed leather baldrics leaving the chest bare", "blazing funerary torch illuminating the underworld path"], "description": "Flanking the entrance inside the aristocratic Tomb of the Anina at Tarquinia opposite her monstrous counterpart Charun, the female underworld spirit Vanth stands sentinel holding a flaming torch. Adorned with high-laced hunting boots, crossed shoulder straps, and expansive feathered wings, Vanth served as a benevolent guide escorting newly departed souls safely into the realm of Aita."}, {"id": "eg-02-pantheistic-bes-bronze", "title": "Pantheistic Inlaid Bronze Figure of Bes (Hor-Asha-Khet)", "creature": "Pantheistic Polymorphic Bes", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Bs / Hor-Asha-Khet ('Horus Rich in Forms')", "civilization": "Late Period–Ptolemaic Egypt", "region": "Egypt & Africa", "originLocation": "Egypt (reportedly Lower Egypt)", "dateDisplay": "c. 4th–2nd century BCE", "yearSort": -250, "era": "Iron Age & Classical Antiquity", "medium": "Solid-cast bronze inlaid with gold, electrum, silver, and black copper alloy", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Giants, Demons & Spirits", "creator": "Egyptian temple metallurgist", "repository": "Metropolitan Museum of Art, New York (29.2.3)", "commonsFile": "Bes-image_of_the_god_Hor-Asha-Khet_MET_DP139129.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Bes-image_of_the_god_Hor-Asha-Khet_MET_DP139129.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Bes-image_of_the_god_Hor-Asha-Khet_MET_DP139129.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ef/Bes-image_of_the_god_Hor-Asha-Khet_MET_DP139129.jpg", "anatomy": ["grotesque dwarf-lion face of Bes surrounded by protruding animal protomes", "four outstretched falcon wings and feathered hawk tail", "human torso covered in inlaid cosmic eyes and jackal-headed feet trampling serpents", "oval plinth encircled by an ouroboros enclosing noxious beasts"], "description": "Cast in precious-metal-inlaid bronze during the first millennium BCE, this theologically dense statuette transforms the household dwarf-lion protector Bes into a cosmic pantheistic supreme being encompassing all divine powers (heka). Sprouting multiple animal heads, four falcon wings, and eyes across its skin while crushing scorpions and snakes inside an ouroboros ring, the hybrid deity rendered the invisible totality of the solar creator visibly invincible against chaos."}, {"id": "gr-03-munich-barberini-faun", "title": "The Barberini Faun (Sleeping Satyr)", "creature": "Satyr", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Σάτυρος (Satyros)", "civilization": "Hellenistic Greece", "region": "Greece & Aegean", "originLocation": "Pergamene Hellenistic school (excavated near Castel Sant'Angelo, Rome)", "dateDisplay": "c. 220 BCE", "yearSort": -220, "era": "Iron Age & Classical Antiquity", "medium": "Over-life-size carved white marble statue", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Pergamene Hellenistic sculptor", "repository": "Glyptothek, Munich (GL 218)", "commonsFile": "Barberini_Faun_front_Glyptothek_Munich_218_n1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Barberini_Faun_front_Glyptothek_Munich_218_n1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Barberini_Faun_front_Glyptothek_Munich_218_n1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f2/Barberini_Faun_front_Glyptothek_Munich_218_n1.jpg", "anatomy": ["ivy-wreathed tousled locks and snub-nosed rustic face", "small pointed caprine-equine ears and neck glands (phereti)", "hyper-muscular sprawling human physique", "animal tail tucked onto the panther-skin rock"], "description": "A tour de force of Hellenistic Baroque naturalism attributed to a Pergamene master, the over-life-size Barberini Faun portrays a drunken woodland satyr sprawled in restless, wine-heavy slumber across a panther pelt. Subtle bestial markers—pointed ears, arched brows, flared nostrils, and a tail resting against the rock—remind the viewer that this sensuous figure belongs to Dionysus's untamed wilderness."}, {"id": "rm-04-etruscan-typhon", "title": "Pillar Fresco of the Serpent-Legged Giant Typhon", "creature": "Typhon (Anguiped Giant)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Tifone", "civilization": "Etruscan", "region": "Etruria, Rome & Byzantium", "originLocation": "Tomb of the Typhon, Monterozzi Necropolis, Tarquinia, Italy", "dateDisplay": "2nd century BCE", "yearSort": -175, "era": "Iron Age & Classical Antiquity", "medium": "Fresco on plastered rock-cut central pillar", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Late Hellenistic Tarquinian painter", "repository": "In situ, Tomb of the Typhon, Tarquinia", "commonsFile": "Etruscan_mural_typhon2.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Etruscan_mural_typhon2.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Etruscan_mural_typhon2.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b6/Etruscan_mural_typhon2.jpg", "anatomy": ["muscular athletic human torso straining upward", "great backswept wings emerging from the scapulae", "twin writhing serpent-legs terminating in bearded snake heads"], "description": "Painted onto the central load-bearing pier of the Tomb of the Pumpu family at Tarquinia, this dynamic Hellenistic fresco depicts a winged anguiped giant acting as an architectural telamon supporting the ceiling. Dramatic chiaroscuro modeling highlights his twisting torso and coiling, crested serpent legs, fusing Pergamene gigantomachy conventions with Etruscan funerary cosmology."}, {"id": "rm-04-pergamon-alkyoneus", "title": "Athena and Nike Slaying the Winged Giant Alkyoneus", "creature": "Gigantes (Winged Serpent-Legged Giant)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Alkyoneus", "civilization": "Hellenistic / Roman Asia Minor", "region": "Etruria, Rome & Byzantium", "originLocation": "Great Altar of Pergamon, Mysia, Asia Minor (modern Bergama, Turkey)", "dateDisplay": "c. 180–160 BCE", "yearSort": -170, "era": "Iron Age & Classical Antiquity", "medium": "High-relief Proconnesian marble frieze", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Royal Attalid sculptural workshops of Pergamon", "repository": "Pergamon Museum, Staatliche Museen zu Berlin", "commonsFile": "Athena_&_Nike,_East_Frieze,_Gigantomachy_Frieze,_Pergamon_Altar,_Pergamon_Museum,_Berlin_(5912953449).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Athena_%26_Nike,_East_Frieze,_Gigantomachy_Frieze,_Pergamon_Altar,_Pergamon_Museum,_Berlin_(5912953449).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Athena_%26_Nike,_East_Frieze,_Gigantomachy_Frieze,_Pergamon_Altar,_Pergamon_Museum,_Berlin_(5912953449).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c6/Athena_%26_Nike,_East_Frieze,_Gigantomachy_Frieze,_Pergamon_Altar,_Pergamon_Museum,_Berlin_(5912953449).jpg", "anatomy": ["heroically muscled humanoid body contorted in pain", "broad feathered wings spread behind the shoulders", "earth-born chthonic kinship with coiled sacred serpents"], "description": "Carved in tumultuous high relief on the east Gigantomachy frieze of the Great Altar of Pergamon—celebrated in Roman antiquity as a marvel of the province of Asia—Athena yanks the winged Giant Alkyoneus by the hair to sever his immortalizing contact with his mother Gaia rising below. Athena's sacred serpent sinks its fangs into the Giant's chest as winged Nike crowns the victorious goddess."}, {"id": "am-10-paracas-oculate-being-mantle", "title": "Funerary Mantle Fragment with the Flying Oculate Being", "creature": "Paracas Oculate Being", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Ser Oculado", "civilization": "Paracas (Late Paracas / Ocucaje)", "region": "The Americas & Oceania", "originLocation": "Carhua(?), Ica / South Coast of Peru", "dateDisplay": "c. 300–1 BCE", "yearSort": -150, "era": "Iron Age & Classical Antiquity", "medium": "Pigment-painted plain-weave cotton textile", "mediumCategory": "Textile & Tapestry", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Paracas textile artist", "repository": "The Cleveland Museum of Art (2005.19)", "commonsFile": "Peru,_South_Coast,_Paracas_(700_BC_-_1_AD),_Carhua?_-_Fragment_of_a_Mantle_with_Oculate_Being_-_2005.19_-_Cleveland_Museum_of_Art.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Peru,_South_Coast,_Paracas_(700_BC_-_1_AD),_Carhua%3F_-_Fragment_of_a_Mantle_with_Oculate_Being_-_2005.19_-_Cleveland_Museum_of_Art.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Peru,_South_Coast,_Paracas_(700_BC_-_1_AD),_Carhua%3F_-_Fragment_of_a_Mantle_with_Oculate_Being_-_2005.19_-_Cleveland_Museum_of_Art.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/92/Peru,_South_Coast,_Paracas_(700_BC_-_1_AD),_Carhua%3F_-_Fragment_of_a_Mantle_with_Oculate_Being_-_2005.19_-_Cleveland_Museum_of_Art.jpg", "anatomy": ["enormous concentric staring discs encircling the eyes", "elongated upturned nose and wide toothy smile", "floating horizontal body trailing serrated serpentiform streamers and trophy heads"], "description": "Preserved by the hyper-arid sands of Peru's southern desert coast, this painted cotton burial-bundle fragment depicts the enigmatic 'Oculate Being' hovering weightlessly in ecstatic flight. Characterized by hypnotic concentric eyes, a wide grinning mouth, and sinuous barbed appendages radiating from its head and torso, this supernatural spirit mediated soul-flight, agricultural regeneration, and ancestral transformation between Paracas mummy bundles and the mythic world."}, {"id": "md-05-tarasque-noves", "title": "The Tarasque of Noves", "creature": "Tarasque", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Tarasque de Noves", "civilization": "Celto-Ligurian (Calyes / Salluvii)", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Noves, Bouches-du-Rhône, Provence, France", "dateDisplay": "c. 200–50 BCE", "yearSort": -120, "era": "Iron Age & Classical Antiquity", "medium": "Carved local limestone freestanding sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Celto-Ligurian sculptor", "repository": "Musée Calvet (Musée Lapidaire), Avignon", "commonsFile": "Tarasque_de_Noves_01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tarasque_de_Noves_01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tarasque_de_Noves_01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/90/Tarasque_de_Noves_01.jpg", "anatomy": ["scaly dorsum and ribbed leonine chest", "gaping wolf-like jaws crushing a human arm", "taloned forepaws resting on two bearded severed heads"], "description": "Unearthed in 1849 near Tarascon in southern Gaul, this menacing Iron Age limestone beast sits on its haunches with a human limb protruding from its toothed maw while resting massive clawed paws atop two bearded, closed-eyed severed heads. Combining a scaly reptilian back with lupine-leonine jaws, the pre-Roman monument embodies the Celto-Ligurian cult of death and foreshadows the medieval Provençal legend of the river-monster Tarasque."}, {"id": "md-05-gundestrup-cernunnos", "title": "Antlered Cernunnos and the Ram-Headed Serpent on the Gundestrup Cauldron", "creature": "Cernunnos and the Ram-Headed Serpent", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Cernunnos", "civilization": "Celtic / Thraco-Celtic Iron Age", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Deposited at Rævemose bog near Gundestrup, Himmerland, Jutland, Denmark", "dateDisplay": "c. 150–50 BCE", "yearSort": -100, "era": "Iron Age & Classical Antiquity", "medium": "Gilded silver repoussé interior vessel plate", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Thraco-Celtic silversmiths", "repository": "National Museum of Denmark (Nationalmuseet), Copenhagen", "commonsFile": "Gundestrup_Cernunnos.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gundestrup_Cernunnos.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gundestrup_Cernunnos.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0f/Gundestrup_Cernunnos.jpg", "anatomy": ["branching stag antlers sprouting from human crown", "coiled serpent bearing curved ram horns", "cross-legged lord of beasts gripping a braided torc"], "description": "Interior Plate A of the disassembled gilded-silver Gundestrup Cauldron depicts the stag-antlered deity usually identified as Cernunnos seated cross-legged as Master of Animals amidst wolves, stags, lions, and a dolphin-rider. In his right hand he elevates a Celtic neck-torc, while his left fist grasps a fierce ram-horned serpent—a signature hybrid guardian of Gallic and Danubian sanctuary iconography."}, {"id": "cn-07-han-qinglong-tile", "title": "Earthenware Roof-Tile End (Wadang) of the Azure Dragon", "creature": "Qinglong (Azure Dragon of the East)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "漢青龍瓦當 (Qīnglóng Wǎdāng)", "civilization": "Western Han Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Chang'an (Xi'an), Shaanxi, China", "dateDisplay": "2nd–1st century BCE", "yearSort": -100, "era": "Iron Age & Classical Antiquity", "medium": "Molded gray earthenware", "mediumCategory": "Ceramics & Vessels", "morphology": "Draconic & Serpentine", "creator": "Imperial Chang'an kiln workshop", "repository": "Xi'an / Shaanxi Archaeological Collections", "commonsFile": "Wadang-qinglong.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wadang-qinglong.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wadang-qinglong.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/15/Wadang-qinglong.jpg", "anatomy": ["S-curved sinuous scaled torso", "wide-flung striding limbs with three claws", "gaping horned jaws", "whip-like curling tail"], "description": "Molded in crisp high relief within a circular eaves-tile medallion, the Azure Dragon twists its lithe, S-curved body dynamically around a central hemispherical boss while striding across the heavens. Placed on the eastern eaves of Western Han ritual and palatial halls in Chang'an, Qinglong governed the vernal constellations of the East and harmonized imperial architecture with the cosmic Five Phases."}, {"id": "cn-07-han-baihu-zhuque-tile", "title": "Roof-Tile End (Wadang) with White Tiger and Vermilion Bird", "creature": "Baihu (White Tiger) & Zhuque (Vermilion Bird)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "西漢四神紋瓦當 (Báihǔ / Zhūquè)", "civilization": "Western Han Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Shaanxi, China", "dateDisplay": "2nd–1st century BCE", "yearSort": -100, "era": "Iron Age & Classical Antiquity", "medium": "Molded gray earthenware", "mediumCategory": "Ceramics & Vessels", "morphology": "Composite Chimeras", "creator": "Western Han architectural kiln", "repository": "Metropolitan Museum of Art, New York", "commonsFile": "西漢_四神紋瓦當（白虎-朱雀）-Roof_Tile_End_MET_39053.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E6%BC%A2_%E5%9B%9B%E7%A5%9E%E7%B4%8B%E7%93%A6%E7%95%B6%EF%BC%88%E7%99%BD%E8%99%8E-%E6%9C%B1%E9%9B%80%EF%BC%89-Roof_Tile_End_MET_39053.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%E8%A5%BF%E6%BC%A2_%E5%9B%9B%E7%A5%9E%E7%B4%8B%E7%93%A6%E7%95%B6%EF%BC%88%E7%99%BD%E8%99%8E-%E6%9C%B1%E9%9B%80%EF%BC%89-Roof_Tile_End_MET_39053.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5e/%E8%A5%BF%E6%BC%A2_%E5%9B%9B%E7%A5%9E%E7%B4%8B%E7%93%A6%E7%95%B6%EF%BC%88%E7%99%BD%E8%99%8E-%E6%9C%B1%E9%9B%80%EF%BC%89-Roof_Tile_End_MET_39053.jpg", "anatomy": ["roaring feline jaws and arched tiger spine", "outspread phoenix-like wings", "streaming tail plumes", "cloud-scroll limbs"], "description": "This Western Han ceramic eaves-tile end belongs to the celebrated Si Shen ('Four Directional Deities') architectural series, pairing fierce directional guardians within circular relief frames to ward off evil spirits from palace roofs. Combining muscular feline stride and sweeping avian plumage, the directional beasts anchored the western autumn and southern summer quadrants of Han correlative cosmology."}, {"id": "eg-02-palestrina-nile-mosaic", "title": "The Nile Mosaic of Palestrina Depicting the Legendary Beasts of Aethiopia", "creature": "Ethiopian Onocentaur, Giant Rock Python, and Frontier Hybrids", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Ὀνοκένταυρος (Onokentauros) & Κροκόττας (Krokottas)", "civilization": "Ptolemaic Alexandrian / Republican Roman Synthesis", "region": "Egypt & Africa", "originLocation": "Sanctuary of Fortuna Primigenia, Praeneste (Palestrina), after an Alexandrian royal painting", "dateDisplay": "c. 100 BCE", "yearSort": -100, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome opus vermiculatum limestone and glass-paste tesserae mosaic", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Composite Chimeras", "creator": "Alexandrian master mosaicists working in Italy (atelier of Demetrios the Topographer tradition)", "repository": "Museo Archeologico Nazionale di Palestrina, Italy", "commonsFile": "NileMosaicOfPalestrina.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:NileMosaicOfPalestrina.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/NileMosaicOfPalestrina.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5e/NileMosaicOfPalestrina.jpg", "anatomy": ["upper-register crags of Nubia and Ethiopia populated by Greek-labeled marvels", "human-headed equine-asinine onocentaur and spotted hyena-lion krokottas", "colossal rock-dwelling serpent coiling beside Kushite hunters"], "description": "Spanning nearly six meters across an apsidal grotto pavement, the Nile Mosaic charts the river's entire course from Hellenistic temples in the Egyptian Delta up to its mythic headwaters in the highlands of Nubia and Ethiopia. In the rugged upper register, Alexandrian naturalism merges seamlessly with ancient teratology as Kushite archers hunt beside exotic fauna and Greek-inscribed frontier marvels—including the human-faced onocentaur, the krokottas, and giant bird-snatching pythons."}, {"id": "rm-04-polyphemus-galatea-boscotrecase", "title": "Polyphemus and Galatea in a Sacro-Idyllic Landscape", "creature": "Cyclops", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Polyphemus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Mythological Room, Villa of Agrippa Postumus, Boscotrecase, Campania, Italy", "dateDisplay": "c. 11 BCE (Augustan Third Style)", "yearSort": -11, "era": "Iron Age & Classical Antiquity", "medium": "Buon fresco on lime plaster", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Imperial Augustan Campanian workshop", "repository": "Metropolitan Museum of Art, New York (20.192.17)", "commonsFile": "Wall_painting-_Polyphemus_and_Galatea_in_a_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DP140711.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wall_painting-_Polyphemus_and_Galatea_in_a_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DP140711.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wall_painting-_Polyphemus_and_Galatea_in_a_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DP140711.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/72/Wall_painting-_Polyphemus_and_Galatea_in_a_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DP140711.jpg", "anatomy": ["colossal sun-bronzed giant's physique", "central third eye on the brow", "rustic panpipes and gnarled shepherd's staff"], "description": "Recovered from the imperial villa of Augustus's grandson Agrippa Postumus on the slopes of Mount Vesuvius, this refined Third Style fresco merges two episodes of the Cyclops myth within one atmospheric seascape. In the foreground, a lovesick Polyphemus sits on a crag clutching his syrinx to serenade the sea-nymph Galatea riding a dolphin, while in the misty background he hurls boulders at Odysseus's fleeing ship."}, {"id": "rm-04-perseus-cetus-boscotrecase", "title": "Perseus Rescuing Andromeda from the Sea-Monster Cetus", "creature": "Cetus (Ketos)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Cetus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Mythological Room, Villa of Agrippa Postumus, Boscotrecase, Campania, Italy", "dateDisplay": "c. 11 BCE (Augustan Third Style)", "yearSort": -10, "era": "Iron Age & Classical Antiquity", "medium": "Buon fresco on lime plaster", "mediumCategory": "Painting & Fresco", "morphology": "Marine & Abyssal Monsters", "creator": "Imperial Augustan Campanian workshop", "repository": "Metropolitan Museum of Art, New York (20.192.16)", "commonsFile": "Wall_painting-_Perseus_and_Andromeda_in_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DT5194.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wall_painting-_Perseus_and_Andromeda_in_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DT5194.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wall_painting-_Perseus_and_Andromeda_in_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DT5194.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/22/Wall_painting-_Perseus_and_Andromeda_in_landscape,_from_the_imperial_villa_at_Boscotrecase_MET_DT5194.jpg", "anatomy": ["gaping wolf-like crocodilian jaws lined with teeth", "spiny aquatic crest and pectoral fins", "coiling serpentine sea-dragon body emerging from the waves"], "description": "Paired opposite the Polyphemus panel in the imperial villa at Boscotrecase, this Augustan wall painting stages Andromeda chained to a towering sea-cliff at center while Perseus flies in on winged sandals from the right. At lower left, the abyssal sea-monster Cetus—dispatched by Poseidon—rears its fanged, crested dragon-snout from the dark green surf toward its intended victim."}, {"id": "rm-04-gemma-augustea-capricorn", "title": "Gemma Augustea Featuring the Imperial Sea-Goat Capricorn", "creature": "Capricornus (Sea-Goat)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Capricornus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Rome, Italy", "dateDisplay": "c. 9–12 CE", "yearSort": 10, "era": "Iron Age & Classical Antiquity", "medium": "Two-layered Arabian onyx cameo in later openwork gold mount", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Attributed to Dioskourides or his imperial workshop", "repository": "Kunsthistorisches Museum, Vienna (Antikensammlung IXa 79)", "commonsFile": "Gemma_Augustea.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gemma_Augustea.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gemma_Augustea.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/80/Gemma_Augustea.jpg", "anatomy": ["horned caprine head and forelegs", "looped scaly fish tail", "radiant eight-pointed star framed within a celestial disc"], "description": "Carved in crisp milky-white relief over a dark brown onyx ground, the 19-by-23-cm Gemma Augustea exalts Emperor Augustus enthroned beside the goddess Roma. Floating above Augustus's brow in a solar medallion is the hybrid sea-goat Capricorn—his personal natal zodiacal sign—proclaiming cosmic destiny over land and sea alike."}, {"id": "eg-02-naqa-apedemak-relief", "title": "Three-Headed, Four-Armed Lion God Apedemak at the Lion Temple of Naqa", "creature": "Polymorphic Apedemak (Kushite Lion-Serpent War and Fertility God)", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Apedemak (Meroitic: Apedemk)", "civilization": "Kingdom of Kush (Meroitic Period)", "region": "Egypt & Africa", "originLocation": "Exterior West Pylon/Rear Wall, Lion Temple at Naqa, Butana Steppe, Sudan", "dateDisplay": "Reign of King Natakamani and Kandake Amanitore, c. 1–20 CE", "yearSort": 10, "era": "Iron Age & Classical Antiquity", "medium": "Carved Nubian sandstone architectural relief", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Royal Meroitic sculptors of Natakamani and Amanitore", "repository": "In situ, Archaeological Site of Naqa, River Nile State, Sudan", "commonsFile": "NaqaLionTempleApedemak3heads4arms.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:NaqaLionTempleApedemak3heads4arms.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/NaqaLionTempleApedemak3heads4arms.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2c/NaqaLionTempleApedemak3heads4arms.jpg", "anatomy": ["three roaring leonine heads facing left, front, and right beneath a triple hemhem crown", "muscular human torso sprouting four outstretched arms making mudra-like gestures", "royal Meroitic sash and kilt"], "description": "Carved onto the sandstone rear wall of the Lion Temple at Naqa—an indigenous Kushite sanctuary deep in Sudan's Butana steppe—this extraordinary relief portrays the Meroitic state deity Apedemak with three lion heads and four human arms facing King Natakamani and Queen Amanitore. Scholars note that its multi-headed, four-armed iconography likely reflects direct Red Sea and Indian Ocean trade contacts between Meroitic Kush and early historic South Asia, fused seamlessly with Nubian leonine theology."}, {"id": "rm-04-scylla-sperlonga", "title": "The Scylla Group from the Imperial Grotto of Sperlonga", "creature": "Scylla", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Scylla", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Grotto of Tiberius, Sperlonga, Lazio, Italy", "dateDisplay": "Early 1st century CE", "yearSort": 20, "era": "Iron Age & Classical Antiquity", "medium": "Carved marble monumental sculpture group", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Signed by the Rhodian sculptors Athanadoros, Hagesandros, and Polydoros", "repository": "Museo Archeologico Nazionale di Sperlonga", "commonsFile": "The_Scylla_group,_Sperlonga_(15616800897).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:The_Scylla_group,_Sperlonga_(15616800897).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/The_Scylla_group,_Sperlonga_(15616800897).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/55/The_Scylla_group,_Sperlonga_(15616800897).jpg", "anatomy": ["colossal female upper torso gripping the ship's steering-oar", "pack of snarling canine heads sprouting from the groin", "coiling pisciform tails dragging sailors into the whirlpool"], "description": "Originally erected on an artificial island at the center of Emperor Tiberius's flooded banquet cave at Sperlonga and signed by the same Rhodian trio credited by Pliny with the Laocoön, this monumental marble group captures Scylla's assault on Odysseus's ship. While the monster's giant hand seizes the helmsman by the scalp, ferocious dog-foreparts lunging from her waist devour his companions."}, {"id": "eg-02-naqa-criosphinx-avenue", "title": "Meroitic Criosphinx Processional Way at the Temple of Amun, Naqa", "creature": "Nubian Criosphinx (Sacred Ram-Sphinx of Napatan-Meroitic Amun)", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Amani Criosphinx", "civilization": "Kingdom of Kush (Meroitic Period)", "region": "Egypt & Africa", "originLocation": "Temple of Amun (Temple 200), Naqa, Sudan", "dateDisplay": "1st century CE", "yearSort": 25, "era": "Iron Age & Classical Antiquity", "medium": "Carved ferruginous Nubian sandstone", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Meroitic royal workshop at Naqa", "repository": "In situ, Temple of Amun, Naqa, Sudan", "commonsFile": "Sudan_Naga_Ram_Temple_01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sudan_Naga_Ram_Temple_01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sudan_Naga_Ram_Temple_01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/64/Sudan_Naga_Ram_Temple_01.jpg", "anatomy": ["curled fleece horns hugging the cheeks of the sacred Nubian ram", "couchant leonine body carved from warm desert sandstone", "paired symmetrical alignment guarding the desert sanctuary portal"], "description": "Stretching beyond the Roman-influenced Kiosk at Naqa, twelve monolithic sandstone ram-sphinxes flank the ceremonial approach to the Meroitic Temple of Amun. Continuing a thousand-year Kushite tradition rooted at Jebel Barkal and Kawa, these desert criosphinxes embody Amani (Amun) in his distinctly Nubian criomorphic manifestation as lord of royal legitimacy and life-giving savanna rains."}, {"id": "cn-07-han-five-directions-brick", "title": "Molded Hollow Tomb Tile of the Four Symbols (Si Xiang)", "creature": "Si Xiang (Four Directional Beasts)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "漢五方四神畫像磚 (Sì Xiàng)", "civilization": "Han Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Henan, China", "dateDisplay": "1st century BCE – 1st century CE", "yearSort": 25, "era": "Iron Age & Classical Antiquity", "medium": "Stamped and molded gray funerary terracotta", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Han funerary brickmaker", "repository": "Musée Cernuschi, Paris", "commonsFile": "Five_cardinal_directions,_a_pottery_tile_of_the_Han_Dynasty,_Cernuschi_Museum,_2006-08-12.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Five_cardinal_directions,_a_pottery_tile_of_the_Han_Dynasty,_Cernuschi_Museum,_2006-08-12.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Five_cardinal_directions,_a_pottery_tile_of_the_Han_Dynasty,_Cernuschi_Museum,_2006-08-12.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/38/Five_cardinal_directions,_a_pottery_tile_of_the_Han_Dynasty,_Cernuschi_Museum,_2006-08-12.jpg", "anatomy": ["directional dragon and tiger flanking cosmic registers", "winged vermilion bird", "intertwined tortoise-and-serpent warrior emblem", "dynamic cloud-borne silhouettes"], "description": "Impressed with intricate dies into wet clay before firing, this monumental hollow tomb brick arranges hunting and celestial scenes around the emblematic guardians of the Five Quarters—East, West, South, North, and Sacred Center. Within subterranean Han tomb chambers, such relief bricks transformed the burial vault into a microcosm of the starry firmament protected by the Four Symbols."}, {"id": "rm-04-grand-camee-pegasus", "title": "Grand Camée de France with the Winged Horse Pegasus", "creature": "Pegasus", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Pegasus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Rome, Italy", "dateDisplay": "c. 23–50 CE (Julio-Claudian dynasty)", "yearSort": 30, "era": "Iron Age & Classical Antiquity", "medium": "Five-layered sardonyx cameo", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Imperial Julio-Claudian court gem-cutter", "repository": "Cabinet des Médailles, Bibliothèque nationale de France, Paris (Camée 264)", "commonsFile": "Great_Cameo_of_France_CdM_Paris_Bab264_n1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Great_Cameo_of_France_CdM_Paris_Bab264_n1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Great_Cameo_of_France_CdM_Paris_Bab264_n1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/87/Great_Cameo_of_France_CdM_Paris_Bab264_n1.jpg", "anatomy": ["rearing stallion carved in translucent white sardonyx", "upswept avian wings bearing an imperial rider", "celestial gallop guided by a flying Amor"], "description": "Measuring 31 by 26.5 cm, the five-layered Grand Camée de France is the largest surviving imperial cameo from Classical antiquity, structured into three cosmic tiers: captive barbarians below, Tiberius and Livia enthroned at center, and the deified Augustus in heaven above. Rising into the upper register on the winged stallion Pegasus is the deceased prince Germanicus, carried skyward toward imperial apotheosis."}, {"id": "am-10-zapotec-bat-god-mask", "title": "Jade Mosaic Mask-Pectoral of the Zapotec Bat God", "creature": "Zapotec Bat Deity", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Pitao Ziy", "civilization": "Zapotec (Monte Albán II)", "region": "The Americas & Oceania", "originLocation": "Mound H, Monte Albán, Oaxaca, Mexico", "dateDisplay": "c. 100 BCE–200 CE", "yearSort": 50, "era": "Iron Age & Classical Antiquity", "medium": "Fitted dark-green jadeite plaques with shell inlays on modeled matrix", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Zapotec royal workshop", "repository": "Museo Nacional de Antropología, Mexico City", "commonsFile": "Mascara_Dios_Murcielago.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Mascara_Dios_Murcielago.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Mascara_Dios_Murcielago.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0f/Mascara_Dios_Murcielago.jpg", "anatomy": ["erect leaf-shaped nasal crest of a phyllostomid bat", "rounded upright chiropteran ears", "humanoid jaws baring interlocking shell teeth", "suspended jadeite ear-spools and tripartite pendant plaques"], "description": "Excavated in an elite offering beneath Mound H at Monte Albán, this 28 cm funerary pectoral is assembled from twenty-five precision-cut plaques of dark-green jadeite accented with marine shell eyes and teeth. Combining an anthropomorphized fanged visage with the erect nose-leaf and rounded ears of the Mesoamerican leaf-nosed bat, the deity governed night, caves, agricultural fertility, and sacrificial decapitation."}, {"id": "sa-09-sanchi-makara-torana", "title": "Torana Architrave Relief of a Warrior Wrestling an Aquatic Makara", "creature": "Makara", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Makara", "civilization": "Early Buddhist India (Satavahana Period)", "region": "South & Southeast Asia", "originLocation": "Stupa No. 3, Sanchi, Madhya Pradesh, India", "dateDisplay": "1st century CE", "yearSort": 50, "era": "Iron Age & Classical Antiquity", "medium": "Carved buff sandstone gateway (torana) relief", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown Sanchi stone-carving guild", "repository": "In situ, Buddhist Monuments at Sanchi, Madhya Pradesh, India", "commonsFile": "Torana_of_Stupa_3_in_Sanchi_Foreigner_fighting_a_Makara.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Torana_of_Stupa_3_in_Sanchi_Foreigner_fighting_a_Makara.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Torana_of_Stupa_3_in_Sanchi_Foreigner_fighting_a_Makara.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9a/Torana_of_Stupa_3_in_Sanchi_Foreigner_fighting_a_Makara.jpg", "anatomy": ["gaping crocodilian jaws lined with serrated teeth", "upturned proboscis-like snout and bulging eyes", "coiling scaled pisciform body terminating in a foliate fin-tail"], "description": "On the sandstone gateway (torana) of Stupa No. 3 at Sanchi, a tunic-clad warrior grapples with the gaping crocodilian jaws of a colossal coiled Makara amidst lotus-filled waters. In early Indian Buddhist and Hindu cosmology, the amphibious Makara embodies both the fecund abundance and perilous untamed waters of rivers and oceans, serving as an auspicious threshold guardian on stupa gateways."}, {"id": "rm-04-theseus-minotaur-pompeii", "title": "Theseus Honored After Slaying the Minotaur", "creature": "Minotaur", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Minotaurus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Exedra of the House of M. Gavius Rufus (VII 2, 16), Pompeii, Italy", "dateDisplay": "c. 45–79 CE (Fourth Style)", "yearSort": 65, "era": "Iron Age & Classical Antiquity", "medium": "Wall fresco detached from plaster", "mediumCategory": "Painting & Fresco", "morphology": "Therianthropic (Human-Beast)", "creator": "Pompeian Fourth Style painter", "repository": "National Archaeological Museum, Naples (MANN Inv. 9043)", "commonsFile": "Theseus_Minotaur_MAN_Napoli_Inv9043.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Theseus_Minotaur_MAN_Napoli_Inv9043.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Theseus_Minotaur_MAN_Napoli_Inv9043.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/51/Theseus_Minotaur_MAN_Napoli_Inv9043.jpg", "anatomy": ["horned bovine bull's head and thick neck", "heavy muscular human body sprawled at the Labyrinth threshold", "clenched human hands in rigor"], "description": "Excavated in the House of Marcus Gavius Rufus at Pompeii and modeled after a celebrated Greek painting, this Fourth Style fresco shows Athenian youths kissing the hand and knees of a victorious Theseus. Sprawled across the lower left doorway of the Cretan Labyrinth lies the corpse of the bull-headed Minotaur, foreshortened to contrast bestial monstrosity with heroic civic deliverance."}, {"id": "rm-04-pan-daphnis-pompeii", "title": "Pan Teaching the Shepherd Daphnis to Play the Syrinx", "creature": "Pan (Goat-Footed God)", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Pan / Faunus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Pompeii, Campania, Italy", "dateDisplay": "1st century CE (after a c. 100 BCE Hellenistic original)", "yearSort": 70, "era": "Iron Age & Classical Antiquity", "medium": "Carved white marble", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Roman sculptor after Heliodoros of Rhodes", "repository": "National Archaeological Museum, Naples (Farnese/Pompeian collection)", "commonsFile": "PanandDaphnis.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:PanandDaphnis.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/PanandDaphnis.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/aa/PanandDaphnis.jpg", "anatomy": ["shaggy caprine thighs and cloven goat hooves", "sprouting goat horns and pointed satyr-ears", "furrowed bestial brow and bearded muzzle"], "description": "Replicating a celebrated late Hellenistic symplegma attributed to Heliodoros, this marble sculpture group contrasts the supple, idealized youth of the mortal shepherd Daphnis with the gnarly, goat-legged woodland god Pan seated beside him. Pan twists his horned head and shaggy hindquarters toward the boy to guide his fingers across the reed panpipes."}, {"id": "rm-04-centaur-mosaic-tivoli", "title": "Battle of Centaurs and Wild Cats of Prey", "creature": "Centaur", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Centaurus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Triclinium of Hadrian's Villa, Tivoli, Lazio, Italy", "dateDisplay": "c. 120–130 CE", "yearSort": 125, "era": "Iron Age & Classical Antiquity", "medium": "Opus vermiculatum polychrome stone and glass tesserae", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Therianthropic (Human-Beast)", "creator": "Hadrianic mosaicists after a Hellenistic original", "repository": "Altes Museum, Staatliche Museen zu Berlin (Mos. 1)", "commonsFile": "Centaur_mosaic_-_Google_Art_Project_retouched.jpeg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Centaur_mosaic_-_Google_Art_Project_retouched.jpeg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Centaur_mosaic_-_Google_Art_Project_retouched.jpeg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/46/Centaur_mosaic_-_Google_Art_Project_retouched.jpeg", "anatomy": ["youthful human torso hoisting a jagged boulder", "dappled chestnut equine barrel and rearing forelegs", "windswept leopard-skin cloak knotted at the throat"], "description": "Executed in microscopic opus vermiculatum tesserae for a banquet hall at Emperor Hadrian's Villa in Tivoli, this 58-by-91-cm emblemata panel achieves painterly gradations of light and shadow across a rocky mountain pass. A male centaur rears above his mortally mauled female companion—who lies bleeding beneath a tiger—as he prepares to crush an attacking lion and leopard with a boulder."}, {"id": "rm-04-furietti-old-centaur", "title": "The Old Furietti Centaur", "creature": "Centaur", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Centaurus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Hadrian's Villa, Tivoli, Lazio, Italy", "dateDisplay": "c. 117–138 CE (Hadrianic period)", "yearSort": 130, "era": "Iron Age & Classical Antiquity", "medium": "Polished dark grey-black bigio morato marble", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Signed by Aristeas and Papias of Aphrodisias", "repository": "Capitoline Museums, Palazzo Nuovo, Rome (MC 658)", "commonsFile": "Old_Centaur_Musei_Capitolini_MC658.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Old_Centaur_Musei_Capitolini_MC658.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Old_Centaur_Musei_Capitolini_MC658.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/51/Old_Centaur_Musei_Capitolini_MC658.jpg", "anatomy": ["bearded, anguished human face crowned with ivy", "arms wrenched taut behind a muscular human back", "glossy dark-marble equine body and prancing hooves"], "description": "Discovered at Hadrian's Villa in 1736 by Monsignor Giuseppe Alessandro Furietti alongside its jubilant 'Young Centaur' counterpart, this virtuoso statue is signed on the plinth by the Carian masters Aristeas and Papias of Aphrodisias. Carved from lustrous dark bigio morato marble to imitate patinated Hellenistic bronze, the aged centaur winces in torment with his wrists bound behind his back by an unseen Eros."}, {"id": "rm-04-amphitrite-hippocampus-ostia", "title": "Amphitrite Riding a Hippocampus Among Tritons", "creature": "Hippocampus & Tritons", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Hippocampus / Triton", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Room 3, Baths of Neptune, Ostia Antica, Lazio, Italy", "dateDisplay": "c. 139 CE (Antonine period)", "yearSort": 139, "era": "Iron Age & Classical Antiquity", "medium": "Black-and-white limestone and marble floor mosaic", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Marine & Abyssal Monsters", "creator": "Ostian mosaic workshop under Antoninus Pius", "repository": "In situ, Terme di Nettuno, Parco Archeologico di Ostia Antica", "commonsFile": "Amphitrite_Terme_di_Nettuno_Ostia_Antica_2006-09-08.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Amphitrite_Terme_di_Nettuno_Ostia_Antica_2006-09-08.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Amphitrite_Terme_di_Nettuno_Ostia_Antica_2006-09-08.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/ca/Amphitrite_Terme_di_Nettuno_Ostia_Antica_2006-09-08.jpg", "anatomy": ["bridled equine forequarters with webbed fin-hooves", "elongated looping serpentine fish-tail", "attendant fish-tailed Tritons blowing conch shells"], "description": "Spanning an entire bathing hall in Rome's port city of Ostia Antica, this monumental Antonine black-and-white pavement celebrates the marine thiasos of Queen Amphitrite. Preceded by winged Hymenaios, the sea-goddess reclines with billowing veil astride a spirited Hippocampus whose horse-chest dissolves into undulating sea-serpent coils surrounded by horn-blowing Tritons."}, {"id": "ne-01-hatra-nergal-cerberus", "title": "Cult Relief of Nergal with Three-Headed Underworld Hound from Hatra", "creature": "Mesopotamian-Parthian Cerberus & Serpent-Scorpions", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Kalbā d-Nergal (Hound of Nergal)", "civilization": "Parthian Era / Kingdom of Araba (Hatra)", "region": "Ancient Near East & Persia", "originLocation": "First Temple, Hatra, Nineveh Governorate, Iraq", "dateDisplay": "2nd century CE", "yearSort": 150, "era": "Iron Age & Classical Antiquity", "medium": "Carved and painted Mosul limestone slab", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Hatran temple sculptor", "repository": "Iraq Museum, Baghdad / Mosul heritage record", "commonsFile": "Ancient_Parthian_relief_carving_of_the_god_Nergal_from_Hatra.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ancient_Parthian_relief_carving_of_the_god_Nergal_from_Hatra.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Parthian_relief_carving_of_the_god_Nergal_from_Hatra.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c5/Ancient_Parthian_relief_carving_of_the_god_Nergal_from_Hatra.jpg", "anatomy": ["Three ferocious canine heads straining from a single collared body on a leash", "Cobra-like serpents springing from the underworld god's belt and shoulders", "Chthonic scorpions, lions, and standard-eagles crowding the sanctuary field"], "description": "Excavated in the First Temple of the desert caravan metropolis of Hatra, this syncretic Parthian-era limestone relief portrays the Mesopotamian underworld god Nergal (syncretized with Heracles-Hades) clad in Iranian tunic and trousers. In his left hand he holds the leash of a snarling three-headed Cerberus hound while scorpions and serpents writhe across the chthonic threshold."}, {"id": "rm-04-glycon-tomis", "title": "Cult Statue of the Prophetic Serpent-God Glycon", "creature": "Glycon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Glykon (Γλύκων)", "civilization": "Roman Empire (Moesia Inferior)", "region": "Etruria, Rome & Byzantium", "originLocation": "Tomis (modern Constanța), Romania", "dateDisplay": "Late 2nd century CE (Antonine–Severan)", "yearSort": 175, "era": "Iron Age & Classical Antiquity", "medium": "Single-block carved white marble", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Provincial Pontic-Roman sculptor", "repository": "Museum of National History and Archeology, Constanța", "commonsFile": "Glycon.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Glycon.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Glycon.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c8/Glycon.JPG", "anatomy": ["anthropomorphic-ovine snout with long flowing human locks", "tightly wound concentric coils of scaly serpent body", "tufted leonine tail raised behind the head"], "description": "Unearthed in 1962 in a ritual cache beneath the former railway station of Constanța (ancient Tomis) and sculpted from a single block of marble whose coiled length measures 4.76 meters, this unique cult statue depicts Glycon—the 'New Asclepius' introduced around 150 CE by the prophet Alexander of Abonoteichus. Combining a long-haired anthropomorphic-ovine head, intricately crosshatched snake coils, and a lion's tail-tuft, it confirms Lucian of Samosata's eyewitness account of the oracle cult."}, {"id": "rm-04-mithraic-leontocephaline", "title": "Mithraic Lion-Headed Time-God (Leontocephaline Aion)", "creature": "Leontocephaline (Aion / Arimanius)", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Aion / Deus Leontocephalus", "civilization": "Roman Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Mithraeum at Ostia Antica, Lazio, Italy", "dateDisplay": "c. 190 CE (Commodan period)", "yearSort": 190, "era": "Iron Age & Classical Antiquity", "medium": "Carved white marble", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Roman Mithraic workshop (dedicated by C. Valerius Heracles)", "repository": "Museo Chiaramonti / Gregorian Profane Museum, Vatican Museums", "commonsFile": "Musei_Vaticani_Leontocephaline11042017_B.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Musei_Vaticani_Leontocephaline11042017_B.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Musei_Vaticani_Leontocephaline11042017_B.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Musei_Vaticani_Leontocephaline11042017_B.jpg", "anatomy": ["roaring maned lion's head atop a rigid human body", "four seasonal wings sprouting from back and hips", "giant cosmic serpent spiraling multiple turns up the legs and torso"], "description": "Dedicated in 190 CE at an Ostian Mithraeum by the priest Caius Valerius Heracles, this esoteric marble cult statue embodies infinite cosmic time (Aion) within the Roman Mysteries of Mithras. A roaring lion-headed man stands at attention clutching the keys of the celestial gates while a colossal serpent—charting the sun's ecliptic path through the zodiac—winds tightly up his legs and rests its head upon his mane."}, {"id": "am-10-teotihuacan-feathered-serpent", "title": "Tenoned Stone Head of the Feathered Serpent", "creature": "Feathered Serpent", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Quetzalcoatl", "civilization": "Teotihuacan", "region": "The Americas & Oceania", "originLocation": "Temple of the Feathered Serpent (Ciudadela), Teotihuacan, Mexico", "dateDisplay": "c. 200 CE", "yearSort": 200, "era": "Iron Age & Classical Antiquity", "medium": "Carved volcanic andesite/basalt with traces of stucco and pigment", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Teotihuacan state sculptors", "repository": "Zona Arqueológica de Teotihuacán, State of Mexico (in situ)", "commonsFile": "Teotihuacan_Feathered_Serpent_(Jami_Dwyer).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Teotihuacan_Feathered_Serpent_(Jami_Dwyer).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Teotihuacan_Feathered_Serpent_(Jami_Dwyer).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0f/Teotihuacan_Feathered_Serpent_(Jami_Dwyer).jpg", "anatomy": ["radial collar of overlapping quetzal tail-plumes", "fanged reptilian jaws with bifurcated snout", "undulating rattlesnake body carved along adjacent talud-tablero panels"], "description": "Projecting dramatically from the stepped talud-tablero facade of the Ciudadela pyramid at Teotihuacan, these monumental tenoned stone heads represent the earliest monumental architectural program dedicated to the Mesoamerican Feathered Serpent. Each snarling rattlesnake head emerges from a blossom-like ruff of carved quetzal feathers, alternating along the balustrade with mosaic-like headdresses of a primordial crocodilian war spirit while undulating serpent bodies swim through carved seashells."}, {"id": "rm-04-medusa-leptis-magna", "title": "Architectural Medallion with Head of the Gorgon Medusa", "creature": "Gorgon (Medusa)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Medusa / Gorgo", "civilization": "Roman North Africa", "region": "Etruria, Rome & Byzantium", "originLocation": "Severan Forum, Leptis Magna, Tripolitania (modern Libya)", "dateDisplay": "c. 200–216 CE (Severan dynasty)", "yearSort": 208, "era": "Iron Age & Classical Antiquity", "medium": "Deeply drilled Proconnesian marble arcade spandrel", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Aphrodisian sculptors in imperial service under Septimius Severus", "repository": "In situ, Severan Forum, Leptis Magna, Libya", "commonsFile": "Forum_Leptis_Magna_04.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Forum_Leptis_Magna_04.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Forum_Leptis_Magna_04.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/62/Forum_Leptis_Magna_04.JPG", "anatomy": ["petrifying wide-eyed gaze beneath furrowed brows", "billowing mane of deeply undercut locks and writhing snakes", "pair of serpent tails knotted beneath the chin and head-wings above"], "description": "Commissioned by the African-born Emperor Septimius Severus to monumentalize his native city of Leptis Magna, scores of colossal marble Gorgoneia and Nereid medallions punctuated the colonnaded arcades of the Severan Forum. Deep running-drill channels cast stark African sunlight and shadow across Medusa's tempestuous locks, brow-wings, and chin-knotted vipers, turning the imperial plaza into an apotropaic shield."}, {"id": "rm-04-odysseus-sirens-dougga", "title": "Mosaic of Odysseus Resisting the Bird-Bodied Sirens", "creature": "Sirens", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Sirenes", "civilization": "Roman North Africa", "region": "Etruria, Rome & Byzantium", "originLocation": "House of Dionysus and Ulysses, Dougga (ancient Thugga), Tunisia", "dateDisplay": "Mid-3rd century CE (c. 240–260 CE)", "yearSort": 250, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome limestone and marble tesserae", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Avian & Winged Hybrids", "creator": "Romano-African mosaic workshop of Thugga", "repository": "Bardo National Museum, Tunis", "commonsFile": "Mosaïque_d'Ulysse_et_les_sirènes.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Mosa%C3%AFque_d'Ulysse_et_les_sir%C3%A8nes.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Mosa%C3%AFque_d'Ulysse_et_les_sir%C3%A8nes.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/16/Mosa%C3%AFque_d'Ulysse_et_les_sir%C3%A8nes.jpg", "anatomy": ["female busts and coiffed heads playing double pipes and lyre", "feathered bird-wings folded against the flanks", "long scaled raptor legs and taloned feet perched on sea-rocks"], "description": "Lifted from an aristocratic peristyle house at Thugga in Roman Africa Proconsularis, this 3.8-meter polychrome pavement depicts Ulysses lashed upright to the mainmast of his gilded, oar-banked galley. Perched on wave-lapped crags to the right stand three hybrid Sirens—women from the waist up with feathered wings and tall raptorial bird-legs—playing aulos and lyre in vain."}, {"id": "am-10-nazca-mythical-killer-whale", "title": "Polychrome Double-Spout Bottle of the Mythical Killer Whale", "creature": "Nazca Anthropomorphic Killer Whale", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Orca Mítica (Boto)", "civilization": "Nazca", "region": "The Americas & Oceania", "originLocation": "Ica / Rio Grande de Nazca Valley, South Coast of Peru", "dateDisplay": "c. 1–500 CE", "yearSort": 250, "era": "Iron Age & Classical Antiquity", "medium": "Polychrome slip-painted burnished earthenware", "mediumCategory": "Ceramics & Vessels", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown Nazca master potter", "repository": "The Metropolitan Museum of Art, New York (64.228.70)", "commonsFile": "Double_Spout_Bottle,_Killer_Whale_MET_64.228.70_d.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Double_Spout_Bottle,_Killer_Whale_MET_64.228.70_d.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Double_Spout_Bottle,_Killer_Whale_MET_64.228.70_d.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6f/Double_Spout_Bottle,_Killer_Whale_MET_64.228.70_d.jpg", "anatomy": ["crescentic cetacean body with prominent dorsal fin and bilobed tail fluke", "fanged jaws smeared with sacrificial blood", "extended human forelimb capable of clutching knives or severed trophy heads"], "description": "Modeled and painted in glossy mineral slips around a globular double-spout-and-bridge bottle, the Mythical Killer Whale (Orca Mítica) ranks as the supreme marine predator deity of Nazca iconography. Merging the sleek piebald body and dorsal fin of Orcinus orca with terrifying serrated jaws and a human arm, the creature personified oceanic power, maritime abundance, and ritual head-taking across the southern Peruvian coast—where its colossal form was also etched into the Nazca desert pampa."}, {"id": "rm-04-phoenix-daphne-antioch", "title": "Pavement Mosaic of the Haloed Phoenix on a Field of Roses", "creature": "Phoenix", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Phoenix", "civilization": "Roman Levant (Late Antiquity)", "region": "Etruria, Rome & Byzantium", "originLocation": "House of the Phoenix, Daphne (suburb of Antioch-on-the-Orontes, modern Antakya, Turkey)", "dateDisplay": "Late 3rd or late 4th century CE", "yearSort": 290, "era": "Iron Age & Classical Antiquity", "medium": "Marble and limestone polychrome floor mosaic", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Single-Horned & Sacred Beasts", "creator": "Antiochene mosaic workshop", "repository": "Musée du Louvre, Paris (Ma 3442 / MND 1948)", "commonsFile": "Phenix_roses_Antioche.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Phenix_roses_Antioche.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Phenix_roses_Antioche.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a4/Phenix_roses_Antioche.jpg", "anatomy": ["radiant solar nimbus with seven projecting rays", "curved crest-plume and long crane-like legs", "iridescent grey-green plumage standing atop a stepped crag"], "description": "Excavated in 1934 at Daphne outside Antioch-on-the-Orontes, this monumental 6-by-4.25-meter pavement centers on the immortal solar bird Phoenix standing atop a rocky pinnacle amid an infinite carpet of rosebuds and stepped rams' horns. Crowned by a rayed nimbus borrowed from Sol Invictus and adopted into Roman imperial coinage as 'FELIX TEMPORUM REPARATIO', the Antiochene Phoenix bridges pagan solar eternity and Early Christian resurrection symbolism."}, {"id": "am-10-moche-ai-apaec-mural", "title": "Polychrome Temple Frieze of Ai Apaec ('The Decapitator')", "creature": "Ai Apaec (Spider-Jaguar Decapitator Monster)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Ai Apaec", "civilization": "Moche", "region": "The Americas & Oceania", "originLocation": "Huaca de la Luna, Moche Valley, La Libertad, Peru", "dateDisplay": "c. 100–700 CE", "yearSort": 450, "era": "Iron Age & Classical Antiquity", "medium": "Molded adobe high-relief mural painted in mineral red, yellow, white, and black pigments", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Unknown Moche temple muralists", "repository": "Complejo Arqueológico Huacas del Sol y de la Luna, Trujillo, Peru (in situ)", "commonsFile": "Moche_decapitator.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Moche_decapitator.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Moche_decapitator.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/94/Moche_decapitator.jpg", "anatomy": ["wrinkled anthropoid visage with bulging eyes and interlocking jaguar fangs", "radiating arachnid or octopoid appendages terminating in snarling zoomorphic heads", "ceremonial tumi sacrificial knife and severed human head held in opposing hands"], "description": "Conserved across the stepped adobe courtyard facades of Huaca de la Luna near Trujillo, this vivid polychrome relief depicts the fearsome Moche supernatural known to archaeologists as 'The Decapitator' (Ai Apaec). Combining the crossed fangs of an Andean jaguar with the ensnaring legs of a trapdoor spider or sea monster, the deity brandishes a crescent blade and a severed trophy head by the hair, presiding over warrior capture sacrifices intended to appease mountain and storm forces."}, {"id": "cn-07-liang-xiao-jing-bixie", "title": "Monumental Stone Bixie at the Spirit Road of Xiao Jing", "creature": "Bixie (Winged Spirit-Road Chimera)", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "蕭景墓石刻辟邪 (Náncháo Shíkè Bìxié)", "civilization": "Liang Dynasty (Southern Dynasties)", "region": "East Asia & Eurasian Steppe", "originLocation": "Qixia District, Nanjing, Jiangsu, China", "dateDisplay": "523 CE", "yearSort": 523, "era": "Post-Classical & Medieval", "medium": "Carved limestone", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Imperial Liang stone-carving workshop", "repository": "In situ, Spirit Path of Marquis Xiao Jing, Nanjing", "commonsFile": "Tomb_of_Xiao_Jing_-_Bixie.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tomb_of_Xiao_Jing_-_Bixie.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tomb_of_Xiao_Jing_-_Bixie.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fa/Tomb_of_Xiao_Jing_-_Bixie.JPG", "anatomy": ["massively puffed barrel chest", "curling plumed shoulder wings", "gaping roaring jaws with protruding tongue", "sinuous muscular spine"], "description": "Guarding the sacred avenue (shendao) of Xiao Jing, cousin to Emperor Wu of Liang, for fifteen centuries, this monolithic limestone chimera arches its back and thrusts out a colossal chest in a display of coiled supernatural power. Widely celebrated today as the civic emblem of Nanjing, Southern Dynasties stone bixie represent the sculptural zenith of early medieval Chinese monumental guardian beasts."}, {"id": "rm-04-great-palace-griffin", "title": "Peristyle Floor Mosaic of the Winged Lion-Griffin", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Gryps (Γρύψ)", "civilization": "Byzantine Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Great Palace of Constantinople, Istanbul, Turkey", "dateDisplay": "6th century CE (Reign of Justinian I or Justin II)", "yearSort": 550, "era": "Post-Classical & Medieval", "medium": "Limestone, terracotta, and colored glass tesserae on mortar", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Composite Chimeras", "creator": "Imperial Constantinopolitan palace mosaicists", "repository": "Great Palace Mosaic Museum, Istanbul", "commonsFile": "Istanbul_Museo_Mosaici_13.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Istanbul_Museo_Mosaici_13.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Istanbul_Museo_Mosaici_13.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/40/Istanbul_Museo_Mosaici_13.JPG", "anatomy": ["tawny leonine body with striped feline musculature", "aquiline raptor head and pointed ears", "polychrome green-and-crimson wings set against a white scale-ground"], "description": "Laid with roughly 40,000 five-millimeter tesserae per square meter across the open peristyle courtyard of the Byzantine emperors' Great Palace in Constantinople, this Early Byzantine floor mosaic preserves Classical naturalism against an abstract fan-patterned white ground. The striding winged lion-griffin radiates sovereign vigilance alongside nearby vignettes of tiger-griffins, Bellerophon's Chimera, and exotic hunts."}, {"id": "jk-08-baekje-bonghwang-censer", "title": "Gilt-Bronze Incense Burner of Baekje", "creature": "Bonghwang and Yong (Korean Phoenix and Dragon)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "봉황·용 (백제 금동대향로)", "civilization": "Baekje Kingdom (Three Kingdoms of Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Neungsan-ri Temple Site, Buyeo, South Chungcheong, Korea", "dateDisplay": "Mid-6th century CE (Sabi Period)", "yearSort": 560, "era": "Post-Classical & Medieval", "medium": "Cast gilt bronze", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Royal Baekje metalworkers", "repository": "Buyeo National Museum / National Museum of Korea", "commonsFile": "Incense_Burner_of_Baekje_in_National_Museum_of_Korea.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Incense_Burner_of_Baekje_in_National_Museum_of_Korea.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Incense_Burner_of_Baekje_in_National_Museum_of_Korea.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/29/Incense_Burner_of_Baekje_in_National_Museum_of_Korea.jpg", "anatomy": ["sweeping crest feathers and arched tail plumes", "magic pearl clasped beneath the phoenix chin", "writhing dragon base supporting a lotus-and-mountain bowl"], "description": "Excavated in 1993 from the muddy sluice pit of a royal temple workshop near Buyeo, this 62.5-centimeter gilt-bronze censer synthesizes Buddhist lotus cosmology with Daoist mountain immortality lore. At its apex perches a poised Bonghwang phoenix clutching a sacred cintamani pearl beneath its beak, while below, a dynamic single-horned Yong dragon coils upward from the circular foot to hold the mountain-tiered bowl in its jaws. Pierced smoke vents hidden among seventy-four miniature peaks and mythical beasts allowed rising incense to animate both celestial creatures in swirling vapor."}, {"id": "jk-08-goguryeo-cheongnyong", "title": "Azure Dragon of the East (Gangseo Great Tomb Mural)", "creature": "Cheongnyong (Azure Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "청룡 (강서대묘 사신도)", "civilization": "Goguryeo Kingdom (Three Kingdoms of Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Gangseo Great Tomb (Gangseo Daemyo), Nampo, South Pyongan, Korea", "dateDisplay": "Late 6th–early 7th century CE", "yearSort": 600, "era": "Post-Classical & Medieval", "medium": "Mineral pigments on polished granite tomb wall", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Unknown Goguryeo court painter", "repository": "In situ, Gangseo Three Tombs (UNESCO World Heritage Site)", "commonsFile": "청룡_조선고적도보.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%EC%B2%AD%EB%A3%A1_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%EC%B2%AD%EB%A3%A1_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/56/%EC%B2%AD%EB%A3%A1_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "anatomy": ["sinuous scaled serpentine body banded in mineral blues, reds, and greens", "swept-back horns and flaming shoulder wings", "outstretched taloned legs striding through empty space"], "description": "Painted directly onto the dressed granite slabs of the eastern burial chamber wall at Gangseo Daemyo without a plaster ground, this mural depicts Cheongnyong, the directional guardian of the East among the Four Symbols (Sasin). The dragon bounds forward with explosive linear energy, its slender neck arched in an S-curve and its jaws parted to exhale auspicious qi flames. Preserved in vivid malachite, cinnabar, and ink outlines, the creature guarded the royal occupant's afterlife realm against eastern malevolent spirits."}, {"id": "jk-08-goguryeo-hyeonmu", "title": "Black Tortoise of the North (Gangseo Great Tomb Mural)", "creature": "Hyeonmu (Entwined Tortoise and Serpent)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "현무 (강서대묘 사신도)", "civilization": "Goguryeo Kingdom (Three Kingdoms of Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Gangseo Great Tomb (Gangseo Daemyo), Nampo, South Pyongan, Korea", "dateDisplay": "Late 6th–early 7th century CE", "yearSort": 600, "era": "Post-Classical & Medieval", "medium": "Mineral pigments on polished granite tomb wall", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Unknown Goguryeo court painter", "repository": "In situ, Gangseo Three Tombs (UNESCO World Heritage Site)", "commonsFile": "현무_조선고적도보.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%ED%98%84%EB%AC%B4_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%ED%98%84%EB%AC%B4_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9b/%ED%98%84%EB%AC%B4_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "anatomy": ["hexagonal-plated tortoise carapace", "coiling scaled serpent knotted tightly around the shell", "confronting reptilian heads locked nose-to-nose"], "description": "Occupying the rear northern wall of the Gangseo Great Tomb, this celebrated Goguryeo masterpiece portrays Hyeonmu, the guardian deity of the North, winter, and the watery underworld. A powerful long-necked tortoise and a muscular spotted serpent loop around one another in a figure-eight knot, twisting their necks backward to lock eyes in intense equilibrium. In East Asian yin-yang symbolism, their union fused terrestrial endurance and regenerative vitality at the threshold of death."}, {"id": "jk-08-goguryeo-jujak", "title": "Vermilion Bird of the South (Gangseo Great Tomb Mural)", "creature": "Jujak (Vermilion Bird)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "주작 (강서대묘 사신도)", "civilization": "Goguryeo Kingdom (Three Kingdoms of Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Gangseo Great Tomb (Gangseo Daemyo), Nampo, South Pyongan, Korea", "dateDisplay": "Late 6th–early 7th century CE", "yearSort": 600, "era": "Post-Classical & Medieval", "medium": "Mineral pigments on polished granite tomb wall", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Goguryeo court painter", "repository": "In situ, Gangseo Three Tombs (UNESCO World Heritage Site)", "commonsFile": "주작_조선고적도보.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%EC%A3%BC%EC%9E%91_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%EC%A3%BC%EC%9E%91_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a3/%EC%A3%BC%EC%9E%91_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "anatomy": ["outspread crimson-tipped wings raised in heraldic display", "curling ornamental head-crest", "sweeping peacock-like tail plumes"], "description": "Flanking the southern entrance passage of the Gangseo Great Tomb, Jujak—the Vermilion Bird of the South and solar fire—spreads its layered pinions to repel impurity from the threshold of the burial chamber. Unlike the terrestrial phoenix Bonghwang, which heralds peaceful rule, Jujak served specifically as a fierce astral sentinel of the southern sky quadrant. Cinnabar highlights and rhythmic calligraphic brushwork lend its fanned tail feathers the visual motion of rising flames."}, {"id": "jk-08-goguryeo-baekho", "title": "White Tiger of the West (Gangseo Great Tomb Mural)", "creature": "Baekho (Celestial White Tiger)", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "백호 (강서대묘 사신도)", "civilization": "Goguryeo Kingdom (Three Kingdoms of Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Gangseo Great Tomb (Gangseo Daemyo), Nampo, South Pyongan, Korea", "dateDisplay": "Late 6th–early 7th century CE", "yearSort": 600, "era": "Post-Classical & Medieval", "medium": "Mineral pigments on polished granite tomb wall", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Unknown Goguryeo court painter", "repository": "In situ, Gangseo Three Tombs (UNESCO World Heritage Site)", "commonsFile": "백호_조선고적도보.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%EB%B0%B1%ED%98%B8_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%EB%B0%B1%ED%98%B8_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9a/%EB%B0%B1%ED%98%B8_%EC%A1%B0%EC%84%A0%EA%B3%A0%EC%A0%81%EB%8F%84%EB%B3%B4.jpg", "anatomy": ["elongated draconic torso striped in pale white and ink", "feathered flame-wings sprouting from the shoulders", "gaping fanged maw with protruding crimson tongue"], "description": "Facing Cheongnyong from the western granite wall of the Gangseo Great Tomb, Baekho embodies the celestial guardian of the West, autumn, and martial metal in Goguryeo funerary cosmology. Rather than a naturalistic feline, the Goguryeo master conceived the White Tiger as a hybrid winged dragon-cat with a whip-thin serpentine spine, feathered forelimbs, and glaring eyes. Its ferocious roar and lunging stride mirror the Azure Dragon across the burial vault to establish a balanced cosmic axis around the stone coffin."}, {"id": "md-05-sutton-hoo-purse", "title": "Interlace Beasts and Wolf-Flanked Figures on the Sutton Hoo Mound 1 Purse Lid", "creature": "Anglo-Saxon Zoomorphic Interlace Beasts", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Wulfas ond Wyrmas", "civilization": "Early Anglo-Saxon (Kingdom of East Anglia)", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Mound 1 Ship Burial, Sutton Hoo, Suffolk, England", "dateDisplay": "c. 610–635 CE", "yearSort": 625, "era": "Post-Classical & Medieval", "medium": "Gold, garnet cloisonné, and millefiori glass mounted on whalebone", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Master goldsmith of the East Anglian royal workshop", "repository": "British Museum, London", "commonsFile": "Sutton.Hoo.PurseLid.RobRoy.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sutton.Hoo.PurseLid.RobRoy.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sutton.Hoo.PurseLid.RobRoy.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/16/Sutton.Hoo.PurseLid.RobRoy.jpg", "anatomy": ["elongated ribbon-bodied beasts with interlocking jaws and limbs", "raptor-like hooked beaks seizing duck-like prey", "heraldic wolf-monsters devouring or whispering into a human figure's ears"], "description": "Recovered from the princely ship burial of Mound 1 at Sutton Hoo, this opulent purse lid features seven gold-and-garnet cloisonné plaques displaying Salin Style II zoomorphic interlace. Flanking central eagles seizing waterfowl are symmetrical plaques of a standing warrior-deity gripped between two rearing lupine monsters, alongside upper mounts whose sinuous, ribbon-limbed beasts twist into intricate Germanic knotwork."}, {"id": "sa-09-mamallapuram-naga-nagini", "title": "Rock-Cut Nāgarāja and Nāginī Ascending the Cleft in Descent of the Ganges", "creature": "Nāga & Nāginī", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Nāgarāja & Nāginī (Nāgam)", "civilization": "Pallava Dynasty (Hindu South India)", "region": "South & Southeast Asia", "originLocation": "Mamallapuram (Mahabalipuram), Tamil Nadu, India", "dateDisplay": "c. 630–668 CE", "yearSort": 650, "era": "Post-Classical & Medieval", "medium": "Monumental open-air granite cliff relief", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Pallava royal sculptors under Narasimhavarman I (Mamalla)", "repository": "In situ, Group of Monuments at Mahabalipuram, Tamil Nadu, India", "commonsFile": "Cleft_Low_Half_Descent_Ganges_Mahabalipuram_Sep22_A7C_02497.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Cleft_Low_Half_Descent_Ganges_Mahabalipuram_Sep22_A7C_02497.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Cleft_Low_Half_Descent_Ganges_Mahabalipuram_Sep22_A7C_02497.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/01/Cleft_Low_Half_Descent_Ganges_Mahabalipuram_Sep22_A7C_02497.jpg", "anatomy": ["regal human upper torsos with palms joined in anjali mudra", "fanning multi-headed cobra hoods (seven-hooded king, three-hooded queen)", "sinuous undulating serpent tails emerging from the water cleft"], "description": "Carved directly into the central vertical fissure of Mamallapuram's immense granite boulder relief—where rainwater once cascaded from a summit cistern to enact the sacred river's descent—a seven-hooded Nāgarāja and his three-hooded Nāginī consort swim upward in reverent adoration. Combining graceful anthropomorphic upper bodies with powerful coiling serpent tails and flaring cobra hoods, these semi-divine subterranean water spirits sanctify the union of heaven, earth, and the underworld (Patala)."}, {"id": "ne-01-sasanian-senmurv-plate", "title": "Sasanian Parcel-Gilt Silver Plate with the Royal Senmurv", "creature": "Senmurv (Sēnmurw / Early Simurgh)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Sēnmurw / Sīmorḡ", "civilization": "Sasanian Persian Empire", "region": "Ancient Near East & Persia", "originLocation": "Iran (found in northern Iran / post-Sasanian Tabaristan tradition)", "dateDisplay": "7th–early 8th century CE", "yearSort": 650, "era": "Post-Classical & Medieval", "medium": "Hammered, chased, and mercury-gilded silver dish", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Sasanian or Dabuyid royal silversmith", "repository": "British Museum, London (124095)", "commonsFile": "Sassanid_silver_plate_by_Nickmard_Khoey.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sassanid_silver_plate_by_Nickmard_Khoey.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sassanid_silver_plate_by_Nickmard_Khoey.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/41/Sassanid_silver_plate_by_Nickmard_Khoey.jpg", "anatomy": ["Snarling canine-leonine head with protruding tongue and upright ears", "Forward-curling feathered wings and clawed feline forepaws", "Lush, foliate peacock tail symbolizing royal xwarrah (divine glory)"], "description": "Wrought in repoussé silver highlighted with mercury gilding, this ceremonial banquet dish centers on the Sēnmurw of Zoroastrian cosmology, which nests atop the world-tree Harwisp-tōxmag and scatters the seeds of all plants with the beat of its wings. Combining a snarling dog-like muzzle, lion paws, upturned wings, and a sweeping peacock tail, the hybrid embodied Sasanian royal khvarenah (divine fortune)."}, {"id": "cn-07-tang-human-faced-zhenmushou", "title": "Earthenware Human-Faced Tomb Guardian Spirit (Zhenmushou)", "creature": "Renmian Zhenmushou (Human-Faced Tomb Guardian)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "唐人面鎮墓獸 (Rénmiàn Zhènmùshòu)", "civilization": "Tang Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Northern China (Chang'an / Luoyang region)", "dateDisplay": "Late 7th – early 8th century CE", "yearSort": 700, "era": "Post-Classical & Medieval", "medium": "Molded earthenware with polychrome and glaze", "mediumCategory": "Ceramics & Vessels", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Tang funerary ceramicist", "repository": "Honolulu Museum of Art, Honolulu", "commonsFile": "Tang_dynasty_tomb_sculpture_of_guardian_figure_with_human_face,_late_7th-early_8th_century,_earthenware,_HAA.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tang_dynasty_tomb_sculpture_of_guardian_figure_with_human_face,_late_7th-early_8th_century,_earthenware,_HAA.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tang_dynasty_tomb_sculpture_of_guardian_figure_with_human_face,_late_7th-early_8th_century,_earthenware,_HAA.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9b/Tang_dynasty_tomb_sculpture_of_guardian_figure_with_human_face,_late_7th-early_8th_century,_earthenware,_HAA.JPG", "anatomy": ["stern human visage with flaring brows", "tall twisted single horn or flame-spike", "flame-fringed shoulder wings", "cloven ungulate hooves on rockwork plinth"], "description": "Seated upright on its haunches atop a craggy pedestal, this Tang funerary guardian merges a furrowed human face with a towering horn, elephantine ears, flaming shoulder-wings, and cloven hooves. Paired at tomb entrances alongside a lion-faced counterpart and armored Lokapalas, the apotropaic hybrid identified as 'Tubo' or 'Qitou' repelled corpse-devouring demons during funerary rites."}, {"id": "jk-08-silla-gwimyeonwa", "title": "Monster-Mask Ridge-End Tile (Gwimyeonwa)", "creature": "Gwimyeon / Dokkaebi (Apotropaic Goblin-Beast Mask)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "귀면와 (도깨비 기와)", "civilization": "Unified Silla Kingdom (Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Former Gapsansa Temple Site, Gyeongju, North Gyeongsang, Korea", "dateDisplay": "7th–8th century CE", "yearSort": 700, "era": "Post-Classical & Medieval", "medium": "Molded and carved gray earthenware", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Unified Silla tile workshop", "repository": "Tokyo National Museum", "commonsFile": "Ridge-end_tile_with_demon_face_design,_excavated_from_former_temple_site_of_Gapsansa_temple,_Gyeongju,_Korea,_Unified_Silla_dynasty,_600s-700s_AD,_clay_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08268.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ridge-end_tile_with_demon_face_design,_excavated_from_former_temple_site_of_Gapsansa_temple,_Gyeongju,_Korea,_Unified_Silla_dynasty,_600s-700s_AD,_clay_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08268.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ridge-end_tile_with_demon_face_design,_excavated_from_former_temple_site_of_Gapsansa_temple,_Gyeongju,_Korea,_Unified_Silla_dynasty,_600s-700s_AD,_clay_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08268.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6d/Ridge-end_tile_with_demon_face_design,_excavated_from_former_temple_site_of_Gapsansa_temple,_Gyeongju,_Korea,_Unified_Silla_dynasty,_600s-700s_AD,_clay_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08268.jpg", "anatomy": ["bulging spherical eyes beneath knotted brows", "bared fangs and flared leonine nostrils", "foliate mane and horned brow ridge"], "description": "Mounted at the exposed hip-ridge terminus of a Buddhist temple roof in royal Gyeongju, this high-relief earthenware tile confronts approaching storms and pestilential spirits with a ferocious monster countenance known in Korean tradition as gwimyeon and popularly linked to the dokkaebi goblin. Deeply undercut eyeballs, upturned tusks, and scrolling beard curls create dramatic chiaroscuro in sunlight while framing a central boss pierced for securing the tile to the wooden ridgepole. Unified Silla roof tiles transformed fierce demonic visages into benevolent architectural guardians of sacred space."}, {"id": "am-10-maya-camazotz-plate", "title": "Polychrome Ceramic Plate of the Underworld Bat (Camazotz)", "creature": "Killer Bat of the Maya Underworld", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Sotz' / Camazotz", "civilization": "Classic Maya", "region": "The Americas & Oceania", "originLocation": "Balamkú, Campeche, Mexico", "dateDisplay": "c. 600–800 CE", "yearSort": 700, "era": "Post-Classical & Medieval", "medium": "Slip-painted polychrome earthenware", "mediumCategory": "Ceramics & Vessels", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Classic Maya ceramicist", "repository": "Museo de Arquitectura Maya, Baluarte de la Soledad / Fuerte de San Miguel, Campeche", "commonsFile": "Murciélago_del_inframundo.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Murci%C3%A9lago_del_inframundo.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Murci%C3%A9lago_del_inframundo.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5b/Murci%C3%A9lago_del_inframundo.JPG", "anatomy": ["outstretched scalloped chiropteran wing membranes marked with death motifs", "upturned leaf-nosed snout and bared fangs", "clawed thumbs and talons flanking a skeletal underworld torso"], "description": "Recovered from an elite Classic Maya tomb at Balamkú in Campeche, this slip-painted ceramic tripod plate centers on a nocturnal vampire-bat spirit spreading dark, scalloped wings across a fiery orange-red ground. In Maya myth—later codified in the Popol Vuh as Camazotz, guardian of the House of Bats in Xibalba—such chiropteran wayob spirits acted as nocturnal agents of bloodletting, darkness, and decapitation."}, {"id": "am-10-maya-vision-serpent-lintel-25", "title": "Yaxchilan Lintel 25: Lady K'abal Xook Conjuring the Vision Serpent", "creature": "Double-Headed Maya Vision Serpent", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Waxaklajuun Ubaah Chan", "civilization": "Classic Maya", "region": "The Americas & Oceania", "originLocation": "Structure 23, Yaxchilan, Chiapas, Mexico", "dateDisplay": "Dedicated 723–726 CE (depicting rite of 681 CE)", "yearSort": 725, "era": "Post-Classical & Medieval", "medium": "Carved fine-grained limestone door lintel", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Classic Maya court sculptor of Yaxchilan", "repository": "The British Museum, London (Am1923, Maud.5)", "commonsFile": "Yaxchilan_(Maya)_Lintel_25_Depicting_Appearance_of_Way_from_Jaws_of_Vision_Serpent_(9817557966).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Yaxchilan_(Maya)_Lintel_25_Depicting_Appearance_of_Way_from_Jaws_of_Vision_Serpent_(9817557966).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Yaxchilan_(Maya)_Lintel_25_Depicting_Appearance_of_Way_from_Jaws_of_Vision_Serpent_(9817557966).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Yaxchilan_(Maya)_Lintel_25_Depicting_Appearance_of_Way_from_Jaws_of_Vision_Serpent_(9817557966).jpg", "anatomy": ["towering S-coiled bicephalic serpent body rising from burning blood-soaked paper", "gaping upper serpent jaws disgorging an armed ancestral warrior", "lower rear serpent head manifesting the rain-war deity Tlaloc"], "description": "Set above the central doorway of Queen Lady K'abal Xook's ritual structure at Yaxchilan, this masterwork of Classic Maya limestone relief captures the climax of a royal bloodletting rite celebrating King Itzamnaaj Bahlam III's accession. From a bowl of burning bark-paper strips saturated with the queen's sacrificial blood coils the double-headed Vision Serpent Waxaklajuun Ubaah Chan, opening its fanged upper jaws tobridge the mortal and supernatural realms as a spear-wielding patron warrior emerges."}, {"id": "cn-07-tang-sancai-zhenmushou-freer", "title": "Sancai-Glazed Lion-Faced Tomb Guardian Beast (Zhenmushou)", "creature": "Shoumian Zhenmushou (Beast-Faced Tomb Guardian)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "唐三彩獸面鎮墓獸 (Sāncǎi Zhènmùshòu)", "civilization": "Tang Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Henan or Shaanxi, China", "dateDisplay": "8th century CE", "yearSort": 730, "era": "Post-Classical & Medieval", "medium": "Earthenware with three-color (sancai) lead-silicate glaze", "mediumCategory": "Ceramics & Vessels", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Tang metropolitan kiln master", "repository": "National Museum of Asian Art (Freer and Sackler Galleries), Washington, D.C.", "commonsFile": "Sancai_earthenware_tomb_guardian,_Tang_Dynasty.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sancai_earthenware_tomb_guardian,_Tang_Dynasty.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sancai_earthenware_tomb_guardian,_Tang_Dynasty.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b1/Sancai_earthenware_tomb_guardian,_Tang_Dynasty.jpg", "anatomy": ["snarling leonine muzzle with fangs", "sweeping bifurcated antlers", "spiked flame-like shoulder wings", "amber, green, and cream sancai glaze drips"], "description": "Drenched in mottled amber, emerald-green, and cream lead glazes, this eighth-century Tang guardian beast bares feline fangs beneath sweeping horns and serrated wing-flames rising from its shoulders. Placed at the threshold of aristocratic subterranean tombs, its ferocious composite form harnessed demonic ferocity to protect the deceased official's soul."}, {"id": "sa-09-kalasan-kala-portal", "title": "Monumental Kala ('Face of Glory') Portal Lintel at Candi Kalasan", "creature": "Kala (Kirtimukha)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Banaspati / Batara Kala", "civilization": "Mataram / Shailendra Dynasty (Central Java)", "region": "South & Southeast Asia", "originLocation": "Candi Kalasan, Sleman, Yogyakarta, Java, Indonesia", "dateDisplay": "c. 778 CE", "yearSort": 778, "era": "Post-Classical & Medieval", "medium": "Carved volcanic andesite stone architectural relief with stucco traces", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Central Javanese Buddhist master sculptor", "repository": "In situ, Candi Kalasan, Yogyakarta, Indonesia", "commonsFile": "Kalasan_Kala.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kalasan_Kala.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kalasan_Kala.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1b/Kalasan_Kala.jpg", "anatomy": ["jawless leonine-demonic upper maw baring curved fangs", "bulging hypnotic eyes beneath foliate horn-brows", "clawed hands grasping vegetal scrolls disgorged from the mouth"], "description": "Crowning the southern sanctuary niche and doorway of Candi Kalasan—the earliest dated Buddhist temple in Central Java—this monumental andesite Kala head glares down with bulging eyes and a fanged, lower-jawless maw framed by exuberant lotus scrolls. Adapted from the Indian Kirtimukha ('Face of Glory') that devoured its own body at Shiva's command, the Javanese Kala swallows time and malevolent forces before they can cross the sacred temple threshold."}, {"id": "md-05-book-of-kells-tetramorph", "title": "Insular Winged Evangelist Beasts in the Book of Kells (Folio 27v)", "creature": "Insular Winged Tetramorph Beasts", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Ceithre Béoata (Four Living Creatures)", "civilization": "Hiberno-Scottish Insular Monasticism", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Abbey of Iona, Inner Hebrides, Scotland (completed or housed at Kells, County Meath, Ireland)", "dateDisplay": "c. 800 CE", "yearSort": 800, "era": "Post-Classical & Medieval", "medium": "Insular pigments (orpiment, woad, kermes, verdigris) and iron-gall ink on calfskin vellum", "mediumCategory": "Manuscript & Print", "morphology": "Avian & Winged Hybrids", "creator": "Columban monastic scriptorium illuminators", "repository": "Trinity College Library, Dublin (MS 58, Folio 27v)", "commonsFile": "KellsFol027v4Evang.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:KellsFol027v4Evang.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/KellsFol027v4Evang.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c2/KellsFol027v4Evang.jpg", "anatomy": ["multi-winged apocalyptic lion, calf, eagle, and angel framed in cruciform compartments", "stylized zoomorphic pelts patterned with Celtic spiral, trumpet, and key ornament", "haloed heads and interlaced pinions fusing Ezekiel's vision with Insular knotwork"], "description": "Divided into four compartments by an intricate stepped cross on Folio 27v of the Book of Kells, the four apocalyptic Living Creatures of Ezekiel and Revelation—winged man, winged lion, winged calf, and eagle—hover in heraldic Insular splendor. Rather than naturalistic anatomy, the Columban monks transform the sacred beasts' bodies into shimmering planes of geometric fretwork, peacock-hued feathers, and spiraling interlace."}, {"id": "md-05-pictish-beast-maiden", "title": "The Pictish Beast on the Maiden Stone", "creature": "Pictish Beast", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Pictish Beast", "civilization": "Pictish Early Medieval Scotland", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Chapel of Garioch, near Inverurie, Aberdeenshire, Scotland", "dateDisplay": "c. 750–850 CE", "yearSort": 800, "era": "Post-Classical & Medieval", "medium": "Relief-carved pink granite Class II cross-slab", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown Pictish master mason", "repository": "In situ at Chapel of Garioch, Aberdeenshire (Historic Environment Scotland)", "commonsFile": "Pictish_Beast_Maiden_Stone.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Pictish_Beast_Maiden_Stone.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Pictish_Beast_Maiden_Stone.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f4/Pictish_Beast_Maiden_Stone.jpg", "anatomy": ["elongated curving dolphin-like snout or trunk", "sweeping crest-scroll trailing behind the head", "curled spiral flipper-feet suggesting aquatic propulsion"], "description": "Dominating the uppermost panel on the reverse of Aberdeenshire's red-granite Maiden Stone is a crisp relief of the enigmatic 'Pictish Beast,' the single most frequent zoomorphic symbol across early medieval Pictland. Characterized by a long tubular snout, a backward-sweeping head lappet, and scrolled limbs folded beneath an arched body, the creature has been interpreted as a mythic sea-kelpie, stylized cetacean, or Insular memory of classical sea-monsters."}, {"id": "sa-09-pawon-kinnara-kinnari", "title": "Wall Relief of Kinnara and Kinnari Flanking the Wish-Fulfilling Kalpataru Tree", "creature": "Kinnara & Kinnari", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Kinara-Kinari", "civilization": "Shailendra Dynasty (Central Java)", "region": "South & Southeast Asia", "originLocation": "Candi Pawon (Borobudur Temple Compounds), Magelang, Central Java, Indonesia", "dateDisplay": "c. 800–825 CE", "yearSort": 815, "era": "Post-Classical & Medieval", "medium": "Carved volcanic andesite bas-relief panel", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Shailendra court sculptor", "repository": "In situ, Candi Pawon, Borobudur Complex, Central Java, Indonesia", "commonsFile": "Kalpataru,_Kinnara-Kinnari,_Apsara-Devata,_Pawon_Temple.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kalpataru,_Kinnara-Kinnari,_Apsara-Devata,_Pawon_Temple.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kalpataru,_Kinnara-Kinnari,_Apsara-Devata,_Pawon_Temple.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5d/Kalpataru,_Kinnara-Kinnari,_Apsara-Devata,_Pawon_Temple.jpg", "anatomy": ["crowned, jewel-bedecked human heads and upper torsos", "plumed avian wings and rounded feathered bird bodies", "taloned bird legs flanking pots of overflowing jewels"], "description": "Carved on the exterior wall of Candi Pawon along the processional axis to Borobudur, a male Kinnara and female Kinnari stand beneath a jewel-hung Kalpataru (wish-fulfilling tree) surrounded by hovering celestial Apsaras. Half-human and half-bird inhabitants of Mount Meru's paradise, the pair guard treasure jars overflowing with riches while embodying eternal conjugal devotion, celestial music, and Buddhist merit."}, {"id": "md-05-oseberg-animal-post", "title": "Carved Dragon-Beast Head Post from the Oseberg Ship Burial", "creature": "Viking Gripping-Beast Dragon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Dyrehodestolpe", "civilization": "Viking Age Norway", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Oseberg Burial Mound, Slagen, Vestfold, Norway", "dateDisplay": "c. 820–834 CE", "yearSort": 834, "era": "Post-Classical & Medieval", "medium": "Deep-relief carved maple wood with silver rivet details", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "The Academician or Baroque Master of the Oseberg workshop", "repository": "Museum of the Viking Age (Kulturhistorisk museum), Oslo", "commonsFile": "Oslo_Norway,_Viking_Ship_Museum-_Animal_Head_Post_9C_-_21203986061.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Oslo_Norway,_Viking_Ship_Museum-_Animal_Head_Post_9C_-_21203986061.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Oslo_Norway,_Viking_Ship_Museum-_Animal_Head_Post_9C_-_21203986061.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/cb/Oslo_Norway,_Viking_Ship_Museum-_Animal_Head_Post_9C_-_21203986061.jpg", "anatomy": ["snarling fanged jaws with bared canines", "bulging round eyes above a curving draconic neck", "dense surface skin composed of writhing gripping-beast interlace"], "description": "Five ritual wooden animal-head posts accompanied two high-ranking women buried inside the oak Oseberg longship in 834 CE, likely carried in ceremonial processions to ward off malevolent spirits. Carved in maple wood, the ferocious roaring head surges from an arched neck entirely blanketed in interlocking Oseberg-style gripping beasts whose tiny paws clutch neighboring necks and borders."}, {"id": "sa-09-prambanan-makara-balustrade", "title": "Andesite Makara Stairway Balustrade Guardian of the Shiva Temple", "creature": "Makara", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Makara", "civilization": "Medang / Mataram Kingdom (Central Java)", "region": "South & Southeast Asia", "originLocation": "Candi Siwa, Prambanan Temple Compounds, Yogyakarta, Java, Indonesia", "dateDisplay": "c. 850 CE", "yearSort": 850, "era": "Post-Classical & Medieval", "medium": "Carved volcanic andesite stone balustrade sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown Mataram royal stone carvers", "repository": "In situ, Prambanan Temple Compounds, Central Java, Indonesia", "commonsFile": "Candi_Prambanan_-_008_Makara,_Siva_Temple_(12042608053).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Candi_Prambanan_-_008_Makara,_Siva_Temple_(12042608053).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Candi_Prambanan_-_008_Makara,_Siva_Temple_(12042608053).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f9/Candi_Prambanan_-_008_Makara,_Siva_Temple_(12042608053).jpg", "anatomy": ["curling elephantine trunk topped with a lotus bud", "wide fanged jaws housing a miniature guardian lion within the maw", "ram-like scrolled horns behind round eyes"], "description": "Terminating the steep staircase balustrades leading up into the central Shiva sanctuary at Prambanan, this volcanic stone Makara curls its elephantine proboscis upward to balance a lotus bud while revealing a small roaring lion seated inside its toothy jaws. Paired with an overarching Kala lintel at the top of the stairs to form the classic Indo-Javanese Kala-Makara frame, the aquatic composite bridges the earthly courtyard and the cosmic mountain of the gods."}, {"id": "sa-09-anuradhapura-nagaraja-guardstone", "title": "Granite Nāgarāja Guardstone (Muragala) Framed by Makara Torana", "creature": "Nāgarāja", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Nāgarāja Muragala", "civilization": "Anuradhapura Kingdom (Buddhist Sri Lanka)", "region": "South & Southeast Asia", "originLocation": "Anuradhapura region, Sri Lanka", "dateDisplay": "c. 800–900 CE", "yearSort": 850, "era": "Post-Classical & Medieval", "medium": "High-relief carved crystalline limestone / granite stele", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Sinhalese monastic sculptor", "repository": "Victoria and Albert Museum, London (IS.8-1966)", "commonsFile": "Nagaraja_Guardstone_from_Sri_Lanka.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Nagaraja_Guardstone_from_Sri_Lanka.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Nagaraja_Guardstone_from_Sri_Lanka.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/be/Nagaraja_Guardstone_from_Sri_Lanka.JPG", "anatomy": ["tiered conical crown backed by a multi-headed cobra hood", "graceful tribhanga princely body holding a blooming pot of plenty (punkalasa)", "miniature Makara arch above and pot-bellied gana dwarf at the feet"], "description": "Placed beside the moonstone threshold of a Sri Lankan Buddhist monastery entrance, this Anuradhapura-period guardstone (muragala) depicts a serpent-king (Nāgarāja) in princely regalia beneath a protective canopy of flared cobra hoods and a miniature Makara arch. Holding a sprouting vase of plenty (punkalasa) in one hand and a flowering branch in the other while trampling or subduing a dwarf yaksha spirit, the Nāga king promises rain, agricultural prosperity, and apotropaic protection to pilgrims."}, {"id": "md-05-tjangvide-sleipnir", "title": "Odin Riding the Eight-Legged Stallion Sleipnir on the Tjängvide Image Stone", "creature": "Sleipnir", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Sleipnir", "civilization": "Viking Age Gotland", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Tjängvide, Alskog parish, Gotland, Sweden", "dateDisplay": "c. 800–900 CE", "yearSort": 850, "era": "Post-Classical & Medieval", "medium": "Low-relief carved limestone picture stone", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Gotlandic stone-carver", "repository": "Swedish History Museum (Historiska museet), Stockholm", "commonsFile": "Ardre_Odin_Sleipnir.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ardre_Odin_Sleipnir.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ardre_Odin_Sleipnir.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/51/Ardre_Odin_Sleipnir.jpg", "anatomy": ["eight striding equine legs arranged in paired fore and hind sets", "arched stallion neck and flowing tail", "supernatural gait crossing between the living world and Valhalla"], "description": "In the upper register of the keyhole-shaped limestone picture stone from Tjängvide on Gotland, a mounted rider enters Valhalla atop Sleipnir, the shamanic eight-legged steed sired by the shape-shifted Loki for Odin. A Valkyrie bearing a drinking horn greets the horse and rider above a sailed Viking longship, rendering in stone the otherworldly mount praised in the Eddas as the swiftest of all horses across sky, sea, and Hel."}, {"id": "sa-09-koh-ker-garuda", "title": "Monumental Sandstone Garuda in Dynamic Koh Ker Style", "creature": "Garuda", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Krut (Khmer: Krุฑ / Garuda)", "civilization": "Khmer Empire", "region": "South & Southeast Asia", "originLocation": "Prasat Thom complex, Koh Ker (Chok Gargyar), Preah Vihear, Cambodia", "dateDisplay": "c. 928–944 CE", "yearSort": 935, "era": "Post-Classical & Medieval", "medium": "Carved grey sandstone sculpture in the round", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Khmer royal sculptor under King Jayavarman IV", "repository": "National Museum of Cambodia, Phnom Penh", "commonsFile": "Garuda_(Koh_Ker_style)-2.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Garuda_(Koh_Ker_style)-2.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Garuda_(Koh_Ker_style)-2.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e1/Garuda_(Koh_Ker_style)-2.jpg", "anatomy": ["fierce hooked raptor beak with bulging eyes and diademed crest", "powerful muscular human torso and raised arms", "spread feathered wings and taloned avian legs"], "description": "Carved in the bold, kinetic sculptural idiom of Jayavarman IV's short-lived capital at Koh Ker, this monumental sandstone Garuda crouches with wings unfurled, fierce hooked beak agape, and muscular arms raised in triumphant power. As the solar eagle-man mount (vahana) of Vishnu and the sworn enemy of the serpentine Nāgas, Garuda served in Khmer imperial iconography as an emblem of royal celestial authority and victory over chaos."}, {"id": "md-05-gosforth-cross-fenrir", "title": "Víðarr Rending the Jaws of the Wolf Fenrir on the Gosforth Cross", "creature": "Fenrir", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Fenrisúlfr", "civilization": "Hiberno-Norse / Anglo-Scandinavian Cumbria", "region": "Medieval, Celtic & Norse Europe", "originLocation": "St Mary's Churchyard, Gosforth, Cumbria, England", "dateDisplay": "c. 920–950 CE", "yearSort": 935, "era": "Post-Classical & Medieval", "medium": "Relief-carved red Permian sandstone high cross", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Anglo-Scandinavian sculptor (the Gosforth Master)", "repository": "In situ at St Mary's Churchyard, Gosforth, Cumbria", "commonsFile": "Gosforth_Cross_Víðarr.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gosforth_Cross_V%C3%AD%C3%B0arr.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gosforth_Cross_V%C3%AD%C3%B0arr.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f7/Gosforth_Cross_V%C3%AD%C3%B0arr.jpg", "anatomy": ["monstrous split wolf-dragon jaws stretched wide", "plaited serpentine body merging into Borre-style ring-chain", "forked tongue and fangs pinned by Víðarr's booted foot and spear"], "description": "Towering 4.4 meters in a Cumbrian churchyard, the Gosforth Cross synthesizes Christian Crucifixion imagery with apocalyptic scenes from Norse Ragnarök. On its east face, Odin's silent son Víðarr braces his heavy boot against the lower jaw of the monstrous, ring-plaited wolf-serpent Fenrir while prying its upper jaw apart with his hand and spear to avenge his father's death."}, {"id": "am-10-lambayeque-naylamp-tumi", "title": "Gold Ceremonial Knife (Tumi) Surmounted by Winged Naylamp", "creature": "Naylamp (Winged Ancestor-Deity)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Ñaymlap / Sicán Deity", "civilization": "Lambayeque (Middle Sicán)", "region": "The Americas & Oceania", "originLocation": "Batán Grande / Lambayeque Valley, North Coast of Peru", "dateDisplay": "c. 900–1100 CE", "yearSort": 1000, "era": "Post-Classical & Medieval", "medium": "Hammered, repoussé, and lost-wax cast gold alloy with crushed turquoise inlay", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Sicán court goldsmith", "repository": "The Metropolitan Museum of Art, New York (1979.206.1247)", "commonsFile": "Ceremonial_Knife_(Tumi)_MET_DP214165.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ceremonial_Knife_(Tumi)_MET_DP214165.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ceremonial_Knife_(Tumi)_MET_DP214165.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6c/Ceremonial_Knife_(Tumi)_MET_DP214165.jpg", "anatomy": ["sprouting avian wings flanking the shoulders", "characteristic comma-shaped upturned avian eyes", "monumental semicircular filigree headdress inlaid with turquoise"], "description": "Rising above a crescentic sacrificial blade, the handle of this Middle Sicán gold tumi portrays the winged founder-deity traditionally identified with Ñaymlap—the legendary maritime ruler who arrived on balsa rafts in the Lambayeque Valley and ultimately sprouted wings to fly heavenward rather than suffer mortal death. Executed in shimmering sheet gold with suspended spangles and turquoise inlays, the figure's comma-shaped bird eyes and feathered pinions embody divine royal ancestry."}, {"id": "rm-04-auxerre-eagle-silk", "title": "Shroud of Saint Germain of Auxerre (Imperial Byzantine Eagle Silk)", "creature": "Imperial Gem-Bearing Eagle", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Vasilikos Aetos (Βασιλικός Ἀετός)", "civilization": "Byzantine Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Imperial gynecaeum workshops, Constantinople (preserved at Auxerre, France)", "dateDisplay": "c. 1000 CE (Macedonian dynasty)", "yearSort": 1000, "era": "Post-Classical & Medieval", "medium": "Samite silk woven with murex-purple, dark blue, and yellow silk threads", "mediumCategory": "Textile & Tapestry", "morphology": "Avian & Winged Hybrids", "creator": "Imperial silk workshops of Constantinople", "repository": "Abbey of Saint-Germain d'Auxerre, France", "commonsFile": "Abbaye_Saint-Germain_d'Auxerre-Suaire_de_saint_Germain_(1).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Abbaye_Saint-Germain_d'Auxerre-Suaire_de_saint_Germain_(1).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye_Saint-Germain_d'Auxerre-Suaire_de_saint_Germain_(1).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a7/Abbaye_Saint-Germain_d'Auxerre-Suaire_de_saint_Germain_(1).jpg", "anatomy": ["monumental heraldic wings patterned with rosettes and hearts", "jeweled ring and pendant clutched in the hooked beak", "fanned tail feathers and taloned feet poised on stepped pedestals"], "description": "Woven in coveted imperial purple samite in the court workshops of Constantinople around 1000 CE and later brought west to wrap the relics of Saint Germain at Auxerre, this 160-by-120-cm silk ranks among the finest surviving Macedonian-era textiles. Colossal heraldic eagles with rosette-studded plumage hold precious gemmed rings in their beaks, embodying the celestial sovereignty of the Byzantine basileus."}, {"id": "md-05-ramsund-fafnir", "title": "Sigurd Piercing the Dragon Fafnir on the Ramsund Carving (Sö 101)", "creature": "Fafnir", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Fáfnir", "civilization": "Viking Age Sweden", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Ramsundsberget, Jäder parish, Eskilstuna, Södermanland, Sweden", "dateDisplay": "c. 1030 CE", "yearSort": 1030, "era": "Post-Classical & Medieval", "medium": "Incised flat gneiss bedrock outcrop", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Commissioned by Sigridr, mother of Alríkr, in memory of Holmgeirr", "repository": "In situ at Ramsundsberget, Södermanland, Sweden", "commonsFile": "Sö_101,_Ramsund.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:S%C3%B6_101,_Ramsund.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B6_101,_Ramsund.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b6/S%C3%B6_101,_Ramsund.jpg", "anatomy": ["colossal ribbon-like serpentine body inscribed with Younger Futhark runes", "curled draconic snout and lappet framing the narrative field", "underbelly pierced from below by Sigurd's sword Gram"], "description": "Spanning nearly five meters across a glaciated granite-gneiss outcrop in Södermanland, the Ramsund carving frames the Völsung legend inside the sinuous rune-inscribed body of the hoard-guarding dragon Fafnir. From outside the serpent band, the hero Sigurd thrusts his sword Gram straight up through Fafnir's belly, while inside the coil he roasts the dragon's heart, tastes its blood, and learns the warning speech of birds."}, {"id": "rm-04-alexander-griffins-san-marco", "title": "Celestial Flight of Alexander the Great Drawn by Two Griffins", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Gryps (Γρύψ)", "civilization": "Byzantine Empire", "region": "Etruria, Rome & Byzantium", "originLocation": "Constantinople (installed as spolia on the north facade of San Marco, Venice)", "dateDisplay": "10th–11th century CE", "yearSort": 1050, "era": "Post-Classical & Medieval", "medium": "Carved marble architectural relief plaque", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Middle Byzantine Constantinopolitan sculptor", "repository": "Exterior north facade, Basilica di San Marco, Venice", "commonsFile": "Alessandro_Magno_(scultura_da_Constantinopoli_XIsec.).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Alessandro_Magno_(scultura_da_Constantinopoli_XIsec.).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Alessandro_Magno_(scultura_da_Constantinopoli_XIsec.).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2a/Alessandro_Magno_(scultura_da_Constantinopoli_XIsec.).jpg", "anatomy": ["symmetrical pair of rampant winged griffins", "straining eagle heads snapping upward toward baited spears", "muscular lion bodies harnessed to a celestial chariot-basket"], "description": "Brought from Constantinople to Venice—likely after the Fourth Crusade of 1204—and set into the north exterior wall of San Marco, this Middle Byzantine marble relief illustrates the legendary 'Ascent of Alexander' from the Greek Alexander Romance. Wearing the jeweled loros and crown of a Byzantine emperor, Alexander stands in a chariot-basket holding out two skewered animal livers on spears to lure a pair of hungry, harnessed griffins ever higher into the sky."}, {"id": "md-05-altuna-jormungandr", "title": "Thor Fishing for the Midgard Serpent Jörmungandr on the Altuna Runestone (U 1161)", "creature": "Jörmungandr (Midgard Serpent)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Miðgarðsormr / Jörmungandr", "civilization": "Viking Age Sweden", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Altuna Church, Enköping, Uppland, Sweden", "dateDisplay": "c. 1050 CE", "yearSort": 1050, "era": "Post-Classical & Medieval", "medium": "Incised granite runestone", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Runemasters Balle and Freysteinn", "repository": "Altuna Churchyard, Uppland, Sweden", "commonsFile": "U1161_Altunastenen_Tors_fiskafänge_2.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:U1161_Altunastenen_Tors_fiskaf%C3%A4nge_2.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/U1161_Altunastenen_Tors_fiskaf%C3%A4nge_2.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9d/U1161_Altunastenen_Tors_fiskaf%C3%A4nge_2.jpg", "anatomy": ["coiled abyssal sea-serpent body writhing beneath the waves", "predatory head striking at an ox-head bait on a fishing line", "cresting tendrils and jaws confronting Thor's raised hammer Mjölnir"], "description": "Signed by the runemaster Balle on a narrow face of the Altuna Runestone, this vivid mythic scene illustrates the Eddic lay Hymiskviða, in which Thor rows into the deep ocean to hook the world-encircling Midgard Serpent Jörmungandr. So violent is the tug-of-war with the coiled sea-monster snapping at the ox-head bait below that Thor's braced foot smashes clean through the wooden hull of his boat as he raises his hammer Mjölnir."}, {"id": "md-05-urnes-beast", "title": "The 'Urnes Beast' (Níðhöggr) and Intertwined Serpents of Urnes Stave Church", "creature": "The Urnes Beast (Níðhöggr)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Urnesdyret / Níðhöggr", "civilization": "Late Viking / Early Christian Norway", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Urnes Stave Church, Luster, Sogn og Fjordane (Vestland), Norway", "dateDisplay": "c. 1060–1080 CE", "yearSort": 1070, "era": "Post-Classical & Medieval", "medium": "High-relief carved pinewood north portal", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown master woodcarver of the Urnes style", "repository": "In situ at Urnes Stave Church, Luster, Norway", "commonsFile": "Urnesportalen.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Urnesportalen.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Urnesportalen.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9d/Urnesportalen.jpg", "anatomy": ["slender quadruped body with swelling chest and tapering waist", "almond-shaped eye extending forward to the snout", "figure-eight loops of biting ribbon-serpents and tendril-dragons"], "description": "Reused from an earlier eleventh-century timber church and set into the north wall of Urnes Stave Church, this keyhole portal defines the final, aristocratic phase of Viking animal ornament. At the base of the left jamb, a great four-legged creature—interpreted alternately as the cosmic dragon Níðhöggr gnawing Yggdrasil or a Christological lion—bites the neck of a coiling, winged serpent amid an upward cascade of writhing snakes."}, {"id": "md-05-pisa-griffin", "title": "The Pisa Griffin (Monumental Bronze Roof Guardian of Pisa Cathedral)", "creature": "Griffin", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Grifone di Pisa", "civilization": "Medieval Pisan / Western Mediterranean Islamic-Christian Exchange", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Cast in Taifa Al-Andalus or Sicily; mounted atop Pisa Cathedral apse, Italy", "dateDisplay": "c. 1050–1100 CE", "yearSort": 1075, "era": "Post-Classical & Medieval", "medium": "Cast bronze with chased plumage, roundels, and Kufic inscription", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Mediterranean Islamic bronze-caster; recontextualized by the Republic of Pisa", "repository": "Museo dell'Opera del Duomo, Pisa", "commonsFile": "Pisa-Opera_del_Duomo-Grifone_islamico000.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Pisa-Opera_del_Duomo-Grifone_islamico000.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Pisa-Opera_del_Duomo-Grifone_islamico000.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Pisa-Opera_del_Duomo-Grifone_islamico000.jpg", "anatomy": ["raptor head with upright equine ears and hooked eagle beak", "riveted bronze wings engraved with stylized scale-feathers", "muscular lion haunches incised with eagle-and-lion roundels"], "description": "Standing over a meter tall, this monumental cast-bronze griffin was brought to Italy as maritime war booty or diplomatic tribute by the Republic of Pisa and hoisted atop the eastern gable of Pisa Cathedral for eight centuries as a civic talisman. Fitted internally with a resonance chamber that may once have emitted wind-driven roars, its hybrid eagle-and-lion body marries Islamic Kufic benedictions with Romanesque cathedral display."}, {"id": "md-05-bayeux-wyvern", "title": "The Golden Wyvern Standard of Wessex on the Bayeux Tapestry", "creature": "Wyvern (Anglo-Saxon Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Draca", "civilization": "Anglo-Norman / Anglo-Saxon England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Probably embroidered in Canterbury, Kent, England, for Bishop Odo of Bayeux", "dateDisplay": "c. 1070–1080 CE", "yearSort": 1077, "era": "Post-Classical & Medieval", "medium": "Crewels of dyed woollen yarn embroidered on tabby-woven linen", "mediumCategory": "Textile & Tapestry", "morphology": "Draconic & Serpentine", "creator": "Anglo-Saxon embroidery workshop (commissioned by Odo, Bishop of Bayeux)", "repository": "Musée de la Tapisserie de Bayeux, Bayeux, Normandy, France", "commonsFile": "Dragon_banner_-_Harold_Rex_interfectus_est.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Dragon_banner_-_Harold_Rex_interfectus_est.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Dragon_banner_-_Harold_Rex_interfectus_est.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/60/Dragon_banner_-_Harold_Rex_interfectus_est.jpg", "anatomy": ["two-legged draconic body distinct from four-legged dragons", "feathered avian wings raised above a scaly torso", "coiling serpentine tail and gaping fanged jaws"], "description": "In Scene 57 of the 70-meter Bayeux Tapestry—just beside the fatal inscription 'Hic Harold Rex interfectus est'—King Harold Godwinson's standard-bearer falls clutching a three-dimensional windsock banner shaped as a winged, two-legged wyvern. Echoing the swarms of confronted wyverns, griffins, and centaurs embroidered throughout the tapestry's upper and lower borders, the standard preserves the royal Anglo-Saxon battle dragon in eleventh-century needlework."}, {"id": "sa-09-angkor-wat-naga-causeway", "title": "Seven-Headed Nāga Causeway Balustrade at Angkor Wat", "creature": "Seven-Headed Nāga", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Neak (Khmer: នាគ / Nāga)", "civilization": "Khmer Empire", "region": "South & Southeast Asia", "originLocation": "Angkor Wat, Siem Reap, Cambodia", "dateDisplay": "c. 1113–1150 CE", "yearSort": 1130, "era": "Post-Classical & Medieval", "medium": "Carved sandstone monumental balustrade sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Khmer imperial stone-carving workshops under King Suryavarman II", "repository": "In situ, Angkor Wat, Siem Reap, Cambodia", "commonsFile": "Angkor_Wat,_calzada_01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Angkor_Wat,_calzada_01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Angkor_Wat,_calzada_01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/05/Angkor_Wat,_calzada_01.jpg", "anatomy": ["fan-shaped aureole of seven crowned serpent heads", "fanged open jaws and flame-like cranial crests", "hundred-meter cylindrical scaled serpent body raised on stone blocks"], "description": "Flanking the sandstone causeways across the vast moat of Angkor Wat, immense seven-headed Nāga balustrades rear their crowned cobra hoods into sculpted fans before stretching their scaled bodies toward the temple-mountain sanctuary. In Khmer state cosmology, these Nāga bridges materialize the rainbow linking the mortal realm to Mount Meru while evoking the cosmic serpent Vasuki used by gods and demons to churn the Ocean of Milk."}, {"id": "jk-08-goryeo-eoryong-ewer", "title": "Celadon Ewer in the Shape of a Fish-Dragon", "creature": "Eoryong (Fish-Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "청자 어룡형 주자 (어룡)", "civilization": "Goryeo Dynasty (Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Goryeo royal kilns (likely Gangjin, South Jeolla), Korea", "dateDisplay": "12th century CE", "yearSort": 1150, "era": "Post-Classical & Medieval", "medium": "Stoneware with incised and carved decoration under celadon glaze, iron-brown eyes", "mediumCategory": "Ceramics & Vessels", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown Goryeo master potter", "repository": "National Museum of Korea, Seoul (National Treasure No. 61)", "commonsFile": "청자_어룡_모양_주전자.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:%EC%B2%AD%EC%9E%90_%EC%96%B4%EB%A3%A1_%EB%AA%A8%EC%96%91_%EC%A3%BC%EC%A0%84%EC%9E%90.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/%EC%B2%AD%EC%9E%90_%EC%96%B4%EB%A3%A1_%EB%AA%A8%EC%96%91_%EC%A3%BC%EC%A0%84%EC%9E%90.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/90/%EC%B2%AD%EC%9E%90_%EC%96%B4%EB%A3%A1_%EB%AA%A8%EC%96%91_%EC%A3%BC%EC%A0%84%EC%9E%90.jpg", "anatomy": ["horned draconic head with upturned snout spout and fanged jaws", "plump scaled carp torso with serrated pectoral fins", "ascending tail fin rising above swirled lotus waves"], "description": "Celebrated as a pinnacle of twelfth-century Goryeo sculptural celadon (sanghyeong cheongja), this ritual wine ewer captures the mythical Eoryong mid-metamorphosis as a carp leaps the Dragon Gate waterfall to become a celestial dragon. The creature's fierce dragon head, accented with underglaze iron-black pupils, forms the pouring spout, while its plump fish body rests upon stylized wave crests and a twisted lotus-stem handle arches behind its dorsal ridge. Translucent jade-green glaze pools into incised scales and fin rays, lending aquatic shimmer to the hybrid beast."}, {"id": "sa-09-hoysaleswara-makara-frieze", "title": "Ornate Soapstone Makara Frieze on the Plinth of Hoysaleswara Temple", "creature": "Makara", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Makara", "civilization": "Hoysala Empire (Hindu South India)", "region": "South & Southeast Asia", "originLocation": "Hoysaleswara Temple, Halebidu, Karnataka, India", "dateDisplay": "c. 1121–1150 CE", "yearSort": 1150, "era": "Post-Classical & Medieval", "medium": "Deeply undercut chloritic schist (soapstone) temple basement frieze", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Hoysala guild sculptors under King Vishnuvardhana and Ketamalla", "repository": "In situ, Hoysaleswara Temple, Halebidu, Karnataka, India", "commonsFile": "1150_CE_Hoysaleswara_temple_Halebidu_Karnataka,_Makara_mythical_animal.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:1150_CE_Hoysaleswara_temple_Halebidu_Karnataka,_Makara_mythical_animal.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/1150_CE_Hoysaleswara_temple_Halebidu_Karnataka,_Makara_mythical_animal.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7b/1150_CE_Hoysaleswara_temple_Halebidu_Karnataka,_Makara_mythical_animal.jpg", "anatomy": ["crocodile jaws with curled elephantine snout and boar tusks", "muscular leonine limbs and scaly porcine-aquatic torso", "extravagant foliate peacock-plumage tail in lace-like openwork"], "description": "Along the star-shaped Jagati plinth of the Hoysaleswara Temple at Halebidu, Hoysala sculptors exploited soft, fine-grained chloritic schist to transform the aquatic Makara into an encyclopedic terrestrial-marine chimera. Combining crocodile jaws, an elephant trunk, boar tusks, lion paws, a monkey's eyes, and a lush cascade of foliate peacock tail-feathers, the creature parades in a dedicated register symbolizing cosmic abundance beneath scenes from the Hindu epics."}, {"id": "jk-08-heian-komainu", "title": "Shrine Guardian Lion-Dog (Komainu)", "creature": "Komainu", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "狛犬", "civilization": "Heian Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Kyoto or Shiga Prefecture, Japan", "dateDisplay": "12th century CE (Late Heian Period)", "yearSort": 1150, "era": "Post-Classical & Medieval", "medium": "Joined-block carved wood (yosegi-zukuri) with traces of pigment", "mediumCategory": "Sculpture & Relief", "morphology": "Single-Horned & Sacred Beasts", "creator": "Unknown Heian Buddhist-Shinto sculptor", "repository": "Portland Art Museum, Oregon", "commonsFile": "Guardian_pair,_1_of_2,_Komainu_(Korean_lion-dog),_Japan,_possibly_Kyoto_or_Shiga_prefecture,_100s-1100s_AD,_wood_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08493.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Guardian_pair,_1_of_2,_Komainu_(Korean_lion-dog),_Japan,_possibly_Kyoto_or_Shiga_prefecture,_100s-1100s_AD,_wood_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08493.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Guardian_pair,_1_of_2,_Komainu_(Korean_lion-dog),_Japan,_possibly_Kyoto_or_Shiga_prefecture,_100s-1100s_AD,_wood_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08493.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a8/Guardian_pair,_1_of_2,_Komainu_(Korean_lion-dog),_Japan,_possibly_Kyoto_or_Shiga_prefecture,_100s-1100s_AD,_wood_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC08493.jpg", "anatomy": ["muscular seated leonine chest and braced forelegs", "tightly curled mane locks cascading over the shoulders", "snarling muzzle forming the cosmic syllable A or Un"], "description": "Adapted from Tang- and Korean-transmitted guardian lions (hence the literal name 'Goguryeo dog'), wooden Komainu pairs stood inside covered Shinto shrine sanctuaries and imperial palace halls during the Heian period before outdoor stone examples became common. Carved from joined wood blocks, this twelfth-century guardian sits tautly upright with broad chest, bulging eyes, and stylized spiral curls worn smooth by centuries of incense and ritual veneration. Paired with an open-mouthed counterpart, the beast embodied the beginning and end of the cosmos while barring malevolent spirits from sacred thresholds."}, {"id": "jk-08-heian-jigoku-oni", "title": "Hell Wardens Tormenting Sinners (Jigoku Zōshi)", "creature": "Gokusotsu Oni (Buddhist Hell Demons)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "獄卒・鬼 (地獄草紙)", "civilization": "Heian–Kamakura Transition Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Kyoto, Japan", "dateDisplay": "Late 12th century CE", "yearSort": 1185, "era": "Post-Classical & Medieval", "medium": "Ink and color on paper handscroll (emakimono)", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Court atelier associated with Cloistered Emperor Go-Shirakawa", "repository": "Tokyo National Museum (National Treasure of Japan)", "commonsFile": "Jigoku-Zoushi.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Jigoku-Zoushi.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Jigoku-Zoushi.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/10/Jigoku-Zoushi.jpg", "anatomy": ["towering crimson- and ochre-skinned muscular bodies", "wild flame-like hair and glaring yellow eyes", "loincloths of animal pelt and iron torture implements"], "description": "Created for the treasury of Cloistered Emperor Go-Shirakawa during the turbulent twilight of the Heian court, the Jigoku Zōshi handscrolls offer some of the earliest surviving Japanese visual codifications of the Oni. In these harrowing scenes from the Sixteen Lesser Hells, giant red-skinned and beast-headed gokusotsu (hell wardens) tower over naked sinners amid swirling tongues of vermilion fire. Dynamic brushwork and grotesque anatomical exaggeration established the visual archetype of the horned, loincloth-clad Oni that dominated subsequent Japanese folklore."}, {"id": "md-05-aguilar-siren-capital", "title": "Twin-Tailed Siren (Sirena Bicaudata) on a Romanesque Capital from Aguilar de Campoo", "creature": "Twin-Tailed Siren / Melusine Prototype", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Sirena de doble cola", "civilization": "Romanesque Castile", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Monasterio de Santa María la Real, Aguilar de Campoo, Palencia, Spain", "dateDisplay": "c. 1180–1200 CE", "yearSort": 1190, "era": "Post-Classical & Medieval", "medium": "Deeply undercut carved limestone engaged capital", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Master of Aguilar de Campoo workshop", "repository": "Museo Arqueológico Nacional, Madrid", "commonsFile": "Capitel_de_Sta_María_la_Real_(Aguilar_de_Campoo)_M.A.N._01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Capitel_de_Sta_Mar%C3%ADa_la_Real_(Aguilar_de_Campoo)_M.A.N._01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Capitel_de_Sta_Mar%C3%ADa_la_Real_(Aguilar_de_Campoo)_M.A.N._01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2d/Capitel_de_Sta_Mar%C3%ADa_la_Real_(Aguilar_de_Campoo)_M.A.N._01.jpg", "anatomy": ["crowned female upper torso with flowing hair", "bifurcated scaly fish tails curving symmetrically upward", "outstretched human hands grasping both tail-fins"], "description": "Carved in high relief on the left face of a late twelfth-century limestone apse capital from the Premonstratensian abbey of Santa María la Real—paired opposite Samson wrestling the lion—a crowned mermaid splays and grips her twin scaly fish tails. Across Romanesque cloisters from Castile to Poitou, this 'sirena bicaudata' warned monastic viewers against worldly seduction while establishing the visual template later absorbed into the fairy Melusine."}, {"id": "md-05-hylestad-fafnir", "title": "Sigurd Slaying the Winged Dragon Fafnir on the Hylestad Stave Church Portal", "creature": "Fafnir", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Fáfnir", "civilization": "Medieval Norway", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Hylestad Stave Church, Valle, Setesdal, Agder, Norway", "dateDisplay": "c. 1175–1200 CE", "yearSort": 1195, "era": "Post-Classical & Medieval", "medium": "Relief-carved pinewood church portal jamb", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Norwegian stave-church master carver", "repository": "Museum of Cultural History (Historisk museum), University of Oslo", "commonsFile": "Hylestad_I,_right_-_Fafnir_and_Sigurd.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Hylestad_I,_right_-_Fafnir_and_Sigurd.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Hylestad_I,_right_-_Fafnir_and_Sigurd.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/03/Hylestad_I,_right_-_Fafnir_and_Sigurd.jpg", "anatomy": ["sinuous Romanesque dragon neck coiled into a medallion loop", "bat-like ribbed wing and clawed reptilian foreleg", "gaping fanged snout spewing foliate tendrils as Gram pierces its chest"], "description": "On the uppermost medallion of the right portal plank salvaged from the demolished Hylestad Stave Church in Setesdal, the mail-clad hero Sigurd crouches in a pit to drive his sword diagonally through the undulating body of the dragon Fafnir. Adapting pre-Christian Eddic heroism into a Christian triumph over the primordial serpent, the carver weaves Fafnir's winged, scaly coils seamlessly into the portal's inhabited vine-scrolls."}, {"id": "md-05-aberdeen-basilisk", "title": "The Basilisk (King of Serpents) in the Aberdeen Bestiary", "creature": "Basilisk (Cockatrice)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Regulus / Basiliscus", "civilization": "Anglo-Norman / Plantagenet England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Northern or Midlands scriptorium, England", "dateDisplay": "c. 1200 CE", "yearSort": 1200, "era": "Post-Classical & Medieval", "medium": "Tempera pigments and burnished gold leaf on vellum (Folio 66r)", "mediumCategory": "Manuscript & Print", "morphology": "Avian & Winged Hybrids", "creator": "Principal illuminator of the Aberdeen Bestiary", "repository": "University of Aberdeen Library (Univ. Lib. MS 24)", "commonsFile": "Aberdeen_Bestiary_Basilisk.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Aberdeen_Bestiary_Basilisk.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Aberdeen_Bestiary_Basilisk.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/cc/Aberdeen_Bestiary_Basilisk.jpg", "anatomy": ["crested rooster head with lethal gaze and hooked beak", "feathered bird wings and two taloned avian legs", "coiled striped serpent tail confronted by its sole mortal foe, the weasel"], "description": "Set against burnished gold leaf on Folio 66r of the Aberdeen Bestiary, the basilisk—hailed by Pliny and Isidore as king of serpents capable of killing with its gaze or breath—appears as a hybrid of crowned cockerel and looping viper. In the miniature's dynamic composition, a lithe brown weasel, the only animal immune to the monster's venom, lunges directly at the basilisk's throat."}, {"id": "sa-09-champa-dragon-makara", "title": "Tháp Mắm Style Sandstone Dragon-Makara Stairway Balustrade", "creature": "Cham Dragon-Makara", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Makara-Nāga (Champa)", "civilization": "Kingdom of Champa (Central Vietnam)", "region": "South & Southeast Asia", "originLocation": "Tháp Mắm, Bình Định Province, Vietnam", "dateDisplay": "12th–13th century CE", "yearSort": 1200, "era": "Post-Classical & Medieval", "medium": "Carved sandstone architectural corner sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Cham sculptor of the Vijaya period", "repository": "Musée national des arts asiatiques – Guimet, Paris", "commonsFile": "Dragon_Makara_(Culture_Cham,_Musée_Guimet)_(5174382704).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Dragon_Makara_(Culture_Cham,_Mus%C3%A9e_Guimet)_(5174382704).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Dragon_Makara_(Culture_Cham,_Mus%C3%A9e_Guimet)_(5174382704).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3c/Dragon_Makara_(Culture_Cham,_Mus%C3%A9e_Guimet)_(5174382704).jpg", "anatomy": ["upturned flame-crested elephantine proboscis and fanged draconic jaws", "crowned serpent-warrior or dragon emerging from the open gullet", "layered scale armor and stylized spiral mane curls"], "description": "Excavated at the monumental Vijaya-period sanctuary of Tháp Mắm in central Vietnam, this sandstone corner piece fuses the Indian Hindu-Buddhist Makara with sinuous East and Southeast Asian draconic motifs. With its upturned trunk, scrolled eyebrows, and scaled neck disgorging a crowned dragon-serpent head, the sculpture exemplifies Champa's maritime synthesis of Indic temple iconography and regional dragon lore."}, {"id": "md-05-royal-caladrius", "title": "The Prophecy Bird Caladrius at the Royal Sickbed (Bestiary Royal MS 12 C XIX)", "creature": "Caladrius", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Caladrius / Charadrius", "civilization": "Plantagenet England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Probably Durham or Northern England", "dateDisplay": "c. 1200–1210 CE", "yearSort": 1205, "era": "Post-Classical & Medieval", "medium": "Opaque pigments, ink, and gold leaf on parchment (Folio 49r)", "mediumCategory": "Manuscript & Print", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Northern English bestiary illuminator", "repository": "British Library, London (Royal MS 12 C XIX)", "commonsFile": "Caladrius_royal_MS_12.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Caladrius_royal_MS_12.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Caladrius_royal_MS_12.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/97/Caladrius_royal_MS_12.jpg", "anatomy": ["spotless snow-white plumage devoid of any dark feather", "long slender neck and diagnostic gaze", "ability to absorb mortal sickness and disperse it toward the sun"], "description": "Perched upon the draped bed of an ailing, crowned king in British Library Royal MS 12 C XIX, the pure-white Caladrius locks eyes with the patient to prophesy and heal his illness. According to the Physiologus and medieval bestiary lore, if the sick man was fated to die the bird turned its head away, whereas if he could be saved the Caladrius drew the disease into itself and flew sunward to burn the taint away—an allegory of Christ's redemptive Passion."}, {"id": "jk-08-kamakura-tentoki", "title": "Lantern-Bearing Demon Tentōki", "creature": "Tentōki (Lantern-Bearing Oni)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "天燈鬼", "civilization": "Kamakura Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "West Golden Hall, Kōfuku-ji, Nara, Japan", "dateDisplay": "1215 CE (Kenpō 3)", "yearSort": 1215, "era": "Post-Classical & Medieval", "medium": "Painted cypress wood (hinoki) with inlaid rock-crystal eyes (gyokugan)", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Kōben (third son of Unkei, Kei School)", "repository": "Kōfuku-ji National Treasure Hall, Nara (National Treasure of Japan)", "commonsFile": "Tentoki_Kofukuji.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tentoki_Kofukuji.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tentoki_Kofukuji.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/70/Tentoki_Kofukuji.jpg", "anatomy": ["short forehead horns and fang-filled grimace", "inlaid crystal eyes glaring upward from beneath furrowed brows", "sinewy three-toed and three-fingered crimson body supporting a temple lantern"], "description": "Sculpted in 1215 by Kei-school master Kōben as a companion to the dragon-wrapped Ryūtōki, this 77.8-centimeter wooden Oni subverts demonic terror with wry, muscular realism. Rather than being trampled underfoot by one of the Four Heavenly Kings, Tentōki has been converted to Buddhist service and stands on his own stocky legs, hoisting a heavy wooden lantern across his left shoulder to illuminate the Buddha's altar. Veined limbs, inlaid rock-crystal eyes, and a defiant upward scowl capture the comic strain of an unruly demon pressed into pious labor."}, {"id": "md-05-rochester-bonnacon", "title": "The Bonnacon Expelling Caustic Fiery Dung in the Rochester Bestiary", "creature": "Bonnacon", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Bonnacon / Bonasus", "civilization": "High Medieval England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "South-Eastern England (Rochester Cathedral Priory, Kent)", "dateDisplay": "c. 1230 CE", "yearSort": 1230, "era": "Post-Classical & Medieval", "medium": "Tempera, ink, and gold leaf on vellum (Folio 16r)", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Master of the Rochester Bestiary", "repository": "British Library, London (Royal MS 12 F XIII)", "commonsFile": "RochesterBestiary_detail_Bonnacon.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:RochesterBestiary_detail_Bonnacon.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/RochesterBestiary_detail_Bonnacon.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4e/RochesterBestiary_detail_Bonnacon.jpg", "anatomy": ["heavy bull torso combined with a flowing equine mane", "thick ram-like horns curling inward so they cannot gore", "scorching stream of corrosive dung blasted backward at pursuers"], "description": "One of the most celebrated comic-grotesque marvels of medieval illumination, Folio 16r of the Rochester Bestiary shows the Asian bull-horse Bonnacon defending itself when cornered by mailed spearmen. Because its inward-curling horns are useless for fighting, the scarlet beast unleashes a fiery, three-acre barrage of caustic dung that forces an armored hunter to recoil behind his heraldic shield."}, {"id": "md-05-rochester-manticore", "title": "The Manticore in the Rochester Bestiary (Folio 24v)", "creature": "Manticore", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Manticora", "civilization": "High Medieval England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "South-Eastern England (Rochester Cathedral Priory, Kent)", "dateDisplay": "c. 1230 CE", "yearSort": 1230, "era": "Post-Classical & Medieval", "medium": "Tempera, ink, and burnished gold leaf on vellum (Folio 24v)", "mediumCategory": "Manuscript & Print", "morphology": "Therianthropic (Human-Beast)", "creator": "Master of the Rochester Bestiary", "repository": "British Library, London (Royal MS 12 F XIII)", "commonsFile": "Manticore_-_British_Library_Royal_12_F_xiii_f24v_(detail).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Manticore_-_British_Library_Royal_12_F_xiii_f24v_(detail).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Manticore_-_British_Library_Royal_12_F_xiii_f24v_(detail).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f4/Manticore_-_British_Library_Royal_12_F_xiii_f24v_(detail).jpg", "anatomy": ["bearded human face wearing a pointed Phrygian cap and triple-row grin", "blood-red leonine body and clawed paws", "tufted scorpion-stinger tail curved over its haunches"], "description": "Derived ultimately from Ctesias's fifth-century BCE reports of Indian monsters, the Manticore of the Rochester Bestiary strides across a hilly green ground against shimmering gold leaf, turning a human face capped in blue toward the viewer. Described in the Latin text as possessing triple rows of teeth, grey eyes, a flute-like voice, and an insatiable appetite for human flesh, its crimson lion body is rendered with bold Gothic contour lines."}, {"id": "md-05-rochester-yale", "title": "The Swivel-Horned Yale (Eale) in the Rochester Bestiary", "creature": "Yale (Eale)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Eale / Centicore", "civilization": "High Medieval England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "South-Eastern England (Rochester Cathedral Priory, Kent)", "dateDisplay": "c. 1230 CE", "yearSort": 1230, "era": "Post-Classical & Medieval", "medium": "Tempera, ink, and gold leaf on vellum (Folio 27r)", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Master of the Rochester Bestiary", "repository": "British Library, London (Royal MS 12 F XIII)", "commonsFile": "RochesterBestiary_detail_Yale.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:RochesterBestiary_detail_Yale.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/RochesterBestiary_detail_Yale.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/52/RochesterBestiary_detail_Yale.jpg", "anatomy": ["enormous independently swiveling horns—one extended forward, one folded back", "horse-sized body with cloven hooves and boar-like jowls", "tufted elephantine tail"], "description": "Framed in red and blue against gold leaf in the Rochester Bestiary, the Ethiopian Eale—ancestor of the Tudor royal heraldic Yale—displays its defining anatomical marvel: long, articulated horns that are not fixed to the skull. When fighting, the beast thrusts one horn forward while folding the other backward in reserve so that if the leading horn is blunted, the second can immediately rotate into battle."}, {"id": "md-05-rochester-unicorn", "title": "The Unicorn Captured in the Lap of a Maiden in the Rochester Bestiary", "creature": "Unicorn", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Unicornis / Monoceros", "civilization": "High Medieval England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "South-Eastern England (made for Rochester Cathedral Priory, Kent)", "dateDisplay": "c. 1230 CE", "yearSort": 1230, "era": "Post-Classical & Medieval", "medium": "Tempera, ink, and gold leaf on vellum (Folio 10v)", "mediumCategory": "Manuscript & Print", "morphology": "Single-Horned & Sacred Beasts", "creator": "Master of the Rochester Bestiary", "repository": "British Library, London (Royal MS 12 F XIII)", "commonsFile": "Unicorn_hunt_-_British_Library_Royal_12_F_xiii_f10v_(detail).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Unicorn_hunt_-_British_Library_Royal_12_F_xiii_f10v_(detail).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Unicorn_hunt_-_British_Library_Royal_12_F_xiii_f10v_(detail).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6c/Unicorn_hunt_-_British_Library_Royal_12_F_xiii_f10v_(detail).jpg", "anatomy": ["single long spiraled horn projecting from the brow", "compact equine-caprine body rendered in cobalt blue", "docile forelegs resting in a virgin's embrace while pierced by a hunter's spear"], "description": "Illuminated against a diapered gold ground on Folio 10v of the Rochester Bestiary, a vivid blue unicorn lays its head submissively in the lap of a seated maiden while a mail-hooded huntsman thrusts a lance through its flank. Medieval theologians read this famous hunt—whereby a beast too swift for any hunter is pacified solely by a virgin—as a figure of Christ's Incarnation in the womb of the Virgin Mary and His earthly betrayal."}, {"id": "cn-07-song-chen-rong-nine-dragons", "title": "Nine Dragons (Jiulong Tu) Handscroll — Detail of Dragon in Clouds", "creature": "Long (Chinese Celestial Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "陳容《九龍圖》 (Jiǔlóng Tú)", "civilization": "Southern Song Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Fujian / Lin'an (Hangzhou), China", "dateDisplay": "1244 CE", "yearSort": 1244, "era": "Post-Classical & Medieval", "medium": "Ink and touches of cinnabar red on paper handscroll", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Chen Rong (陳容, active c. 1235–1262)", "repository": "Museum of Fine Arts, Boston", "commonsFile": "Nine-Dragons1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Nine-Dragons1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Nine-Dragons1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3e/Nine-Dragons1.jpg", "anatomy": ["branching stag-like horns and whiskered snout", "serpentine scaled body vanishing into mist", "four-clawed grasping talons", "flaming dorsal spines and streaming mane"], "description": "Painted in 1244 by the Southern Song scholar-official Chen Rong—renowned for splashing ink while intoxicated and smearing storm-clouds with his cap—Nine Dragons is the supreme masterwork of Chinese dragon painting. Emerging from roiling whirlpools, craggy precipices, and ink-washed thunderheads, its nine dragons embody Daoist cosmic yang energy and ceaseless elemental transformation."}, {"id": "md-05-harley-amphisbaena", "title": "The Two-Headed Winged Amphisbaena in Harley MS 3244", "creature": "Amphisbaena", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Amphisbaena / Amphivena", "civilization": "High Medieval England", "region": "Medieval, Celtic & Norse Europe", "originLocation": "England", "dateDisplay": "c. 1236–1250 CE", "yearSort": 1245, "era": "Post-Classical & Medieval", "medium": "Tinted ink and wash on parchment (Folio 62r)", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Illuminator of British Library Harley MS 3244", "repository": "British Library, London (Harley MS 3244)", "commonsFile": "Amphisbene_3244.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Amphisbene_3244.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Amphisbene_3244.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/37/Amphisbene_3244.jpg", "anatomy": ["two ferocious dragon-serpent heads—one at the neck and a second terminating the tail", "feathered avian wings and two clawed feet", "looping body capable of rolling in either direction like a hoop"], "description": "In this expressive thirteenth-century English bestiary miscellany (Harley MS 3244, f. 62r), the venomous Libyan serpent Amphisbaena—born in classical myth from blood dripping off Medusa's severed head—is transformed into a winged, bipedal dragon whose tail ends in a second snapping head. As Isidore of Seville recounted, its dual heads allowed it to glide forward or backward and keep watch with glowing lamp-like eyes even through winter frost."}, {"id": "am-10-tairona-batman-pendant", "title": "Gold Masked Figure Pendant of the Tairona Bat-Man", "creature": "Tairona Chiropteran-Avian Shaman Spirit", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Hombre-Murciélago", "civilization": "Tairona", "region": "The Americas & Oceania", "originLocation": "Sierra Nevada de Santa Marta, Magdalena, Colombia", "dateDisplay": "c. 900–1550 CE", "yearSort": 1250, "era": "Post-Classical & Medieval", "medium": "Lost-wax cast tumbaga (gold-copper alloy) with surface depletion gilding", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Tairona master goldsmith", "repository": "The Metropolitan Museum of Art, New York (1991.419.31)", "commonsFile": "Masked_Figure_Pendant_MET_DP215717.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Masked_Figure_Pendant_MET_DP215717.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Masked_Figure_Pendant_MET_DP215717.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f1/Masked_Figure_Pendant_MET_DP215717.jpg", "anatomy": ["upturned leaf-nosed bat visor and fanged chiropteran muzzle", "twin soaring frigatebird or macaw heads flanking an openwork braided headdress", "human torso grasping double-ended ceremonial serpent bars"], "description": "Cast by the lost-wax process in high-karat depletion-gilded tumbaga, this intricate pectoral pendant portrays a Tairona priest-cacique in full ontological transformation into the mythical Hombre-Murciélago ('Bat-Man'). Crowned by twin sacred birds and wearing a tubular nose ornament, lip plug, and leaf-nosed bat snout, the nocturnal winged intermediary bridges the dark subterranean underworld of caves with the sunlit peaks of the Sierra Nevada de Santa Marta."}, {"id": "md-05-getty-aspidochelone", "title": "Two Fishermen Lighting a Campfire on the Island-Whale Aspidochelone", "creature": "Aspidochelone", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Aspidochelone / Cetus", "civilization": "Franco-Flemish High Gothic", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Thérouanne or Northern France / Flanders", "dateDisplay": "c. 1270 CE", "yearSort": 1270, "era": "Post-Classical & Medieval", "medium": "Tempera colors, gold leaf, and ink on parchment (MS. Ludwig XV 3, Folio 89v)", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Franco-Flemish illuminator of the Bestiary of Hugh of Fouilloy", "repository": "J. Paul Getty Museum, Los Angeles (MS. Ludwig XV 3)", "commonsFile": "Two_Fishermen_on_an_Aspidochelone,_c._1270_(cropped).JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Two_Fishermen_on_an_Aspidochelone,_c._1270_(cropped).JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Two_Fishermen_on_an_Aspidochelone,_c._1270_(cropped).JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/25/Two_Fishermen_on_an_Aspidochelone,_c._1270_(cropped).JPG", "anatomy": ["colossal scaled sea-monster back mistaken by mariners for a sandy island", "fanged jaws luring schools of fish with sweet-smelling breath", "coiled piscine tail poised to plunge ship and crew into the abyss"], "description": "Against a patterned gold ground in a c. 1270 Franco-Flemish bestiary, mariners moor their vessel to the scaly spine of the giant whale-monster Aspidochelone, mistaking its surfacing bulk for a safe island and fanning a cooking fire with bellows upon its hide. Bestiary moralists likened the creature—which dives into the ocean depths the instant it feels the heat of the flames, dragging anchored ships down with it—to the Devil's deceptive snares."}, {"id": "md-05-amiens-gargoyle", "title": "Gothic Chimera Gargoyle of Amiens Cathedral", "creature": "Gothic Gargoyle", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Gargouille", "civilization": "Gothic Kingdom of France", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Cathédrale Notre-Dame d'Amiens, Picardy, France", "dateDisplay": "c. 1260–1320 CE", "yearSort": 1290, "era": "Post-Classical & Medieval", "medium": "Carved Picard limestone architectural waterspout", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Cathedral masons' lodge of Amiens", "repository": "In situ on Cathédrale Notre-Dame d'Amiens, France", "commonsFile": "Amiens_Gargouille_1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Amiens_Gargouille_1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Amiens_Gargouille_1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/34/Amiens_Gargouille_1.jpg", "anatomy": ["snarling demonic muzzle hollowed as a rainwater conduit", "pointed bat-like ears with a sculpted fly resting on the right ear", "crouching clawed forelimbs projecting from the cathedral cornice"], "description": "Jutting boldly from the upper stone masonry of Amiens Cathedral—the tallest completed High Gothic nave in France—this carved limestone gargoyle channels corrosive roof runoff clear of the buttresses through its open throat. Combining apotropaic guardian magic with playful stonemason wit, including a tiny insect sculpted directly onto its pointed right ear, the hybrid monster embodies the teeming marginalia of thirteenth-century cathedral exteriors."}, {"id": "cn-07-yuan-kesi-fenghuang", "title": "Silk Kesi Tapestry with Fenghuang (Chinese Phoenix) and Deer", "creature": "Fenghuang (Auspicious Chinese Phoenix)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "緙絲鳳凰紋織物 (Fènghuáng)", "civilization": "Yuan Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "China", "dateDisplay": "13th–14th century CE", "yearSort": 1300, "era": "Post-Classical & Medieval", "medium": "Slit-tapestry woven silk (kesi)", "mediumCategory": "Textile & Tapestry", "morphology": "Avian & Winged Hybrids", "creator": "Unknown Yuan imperial silk-weaving workshop", "repository": "Tokyo National Museum, Tokyo", "commonsFile": "Kesi_fragment_with_flower,_butterfly,_phoenix,_and_deer_design_on_yellow_and_white_bands,_China,_Yuan_dynasty,_1200s-1300s_AD,_textile_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08435.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kesi_fragment_with_flower,_butterfly,_phoenix,_and_deer_design_on_yellow_and_white_bands,_China,_Yuan_dynasty,_1200s-1300s_AD,_textile_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08435.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kesi_fragment_with_flower,_butterfly,_phoenix,_and_deer_design_on_yellow_and_white_bands,_China,_Yuan_dynasty,_1200s-1300s_AD,_textile_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08435.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/73/Kesi_fragment_with_flower,_butterfly,_phoenix,_and_deer_design_on_yellow_and_white_bands,_China,_Yuan_dynasty,_1200s-1300s_AD,_textile_-_Tokyo_National_Museum_-_Tokyo,_Japan_-_DSC08435.jpg", "anatomy": ["sweeping serrated tail-streamers", "outstretched multi-tiered wings", "crested pheasant-like head", "slender avian legs in flight"], "description": "Woven in the painstaking slit-tapestry technique known as kesi ('cut silk'), this Yuan dynasty textile pairs a soaring fenghuang with spotted deer, blossoms, and butterflies across luminous yellow and ivory bands. Sovereign of all feathered creatures and emblem of the Empress and virtuous rule, the fenghuang's five-colored plumage traditionally encoded the five Confucian cardinal virtues."}, {"id": "ne-01-ilkhanid-bahram-karg", "title": "Bahram Gur Fights the Karg (Horned Wolf)", "creature": "Karg (Persian Unicorn / Horned Wolf-Monster)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Karg / گرگ شاخدار", "civilization": "Ilkhanid Mongol Persia", "region": "Ancient Near East & Persia", "originLocation": "Tabriz, northwestern Iran (Great Mongol Shahnameh)", "dateDisplay": "c. 1330–1340 CE", "yearSort": 1335, "era": "Post-Classical & Medieval", "medium": "Opaque watercolor, ink, and gold on paper", "mediumCategory": "Manuscript & Print", "morphology": "Single-Horned & Sacred Beasts", "creator": "Royal Ilkhanid scriptorium of Tabriz", "repository": "Harvard Art Museums, Cambridge, MA (1957.193)", "commonsFile": "Bahram_Gur_Fights_the_Horned_Wolf,_folio_from_the_Great_Ilkhanid_Shahnama.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Bahram_Gur_Fights_the_Horned_Wolf,_folio_from_the_Great_Ilkhanid_Shahnama.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Bahram_Gur_Fights_the_Horned_Wolf,_folio_from_the_Great_Ilkhanid_Shahnama.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/99/Bahram_Gur_Fights_the_Horned_Wolf,_folio_from_the_Great_Ilkhanid_Shahnama.jpg", "anatomy": ["Single immense scimitar-like black horn curving from the brow", "Massive lupine-leonine body with flame-like shoulder fur and striped coat", "Clawed paws stretched out across a gnarled Chinese-inspired landscape"], "description": "Among the supreme masterpieces of Ilkhanid manuscript illumination, this dramatic folio from Ferdowsi's Shahnameh shows the Sasanian king Bahram V (Bahram Gur) standing triumphantly over the slain Karg during his journey to India. Rendered with monumental vitality influenced by Yuan Chinese brushwork, the Karg fuses wolf, lion, and rhinoceros traits beneath a single lethal brow-horn."}, {"id": "ne-01-ilkhanid-waqwaq-tree", "title": "Iskandar (Alexander) and the Talking Waq-Waq Tree", "creature": "Talking Tree of Waq-Waq (Zoomorphic Oracle Tree)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Derakht-e Wāqwāq", "civilization": "Ilkhanid Mongol Persia", "region": "Ancient Near East & Persia", "originLocation": "Tabriz, northwestern Iran (Great Mongol Shahnameh)", "dateDisplay": "c. 1330–1340 CE", "yearSort": 1335, "era": "Post-Classical & Medieval", "medium": "Opaque watercolor, ink, gold, and silver on paper", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Royal Ilkhanid scriptorium of Tabriz", "repository": "National Museum of Asian Art (Freer Gallery of Art), Washington, D.C. (F1935.23)", "commonsFile": "Iskandar_(Alexander)_and_the_Talking_Tree,_Folio_from_a_Great_Mongol_Shahnameh.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Iskandar_(Alexander)_and_the_Talking_Tree,_Folio_from_a_Great_Mongol_Shahnameh.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Iskandar_(Alexander)_and_the_Talking_Tree,_Folio_from_a_Great_Mongol_Shahnameh.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/13/Iskandar_(Alexander)_and_the_Talking_Tree,_Folio_from_a_Great_Mongol_Shahnameh.jpg", "anatomy": ["Twin intertwined male and female trunks speaking by day and night", "Branches terminating in living human women's heads and snarling animal muzzles", "Raptors, foxes, felines, and horned beasts sprouting directly as foliage"], "description": "Painted for the monumental Great Mongol (Demotte) Shahnameh in Ilkhanid Tabriz, this folio depicts Iskandar (Alexander the Great) reaching the edge of the known world to consult the prophetic Talking Tree. Its twin trunks blossom into scores of animated human faces and wild animal heads whose nocturnal voices foretell the conqueror's imminent death in a distant land."}, {"id": "am-10-mississippian-rattlesnake-gorget", "title": "Engraved Marine Shell Gorget of the Supernatural Rattlesnake", "creature": "Horned / Plumed Rattlesnake of the Beneath World", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Sinti Holo / Tie-Snake", "civilization": "Mississippian (Southeastern Ceremonial Complex)", "region": "The Americas & Oceania", "originLocation": "Moundville / Tennessee-Cumberland Valley region, Southeastern United States", "dateDisplay": "c. 1300–1500 CE", "yearSort": 1350, "era": "Post-Classical & Medieval", "medium": "Carved, fenestrated, and incised lightning whelk shell (Sinistrofulgur perversum)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Draconic & Serpentine", "creator": "Unknown Mississippian shell engraver", "repository": "Alabama Museum of Natural History, Tuscaloosa", "commonsFile": "Rattlesnake_gorget_anhm.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Rattlesnake_gorget_anhm.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Rattlesnake_gorget_anhm.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b1/Rattlesnake_gorget_anhm.jpg", "anatomy": ["coiled cross-hatched diamondback body encircling an openwork central head", "cosmological cross-in-circle motif framing the supernatural eye", "gaping fanged mouth and segmented tail rattle along the outer rim"], "description": "Cut from the outer whorl of a Gulf Coast marine whelk shell and worn suspended at the throat as high-status regalia, this Mississippian gorget coils a supernatural rattlesnake around its own snarling head. Marked with concentric chevron bands, fenestrated cutouts, and a sacred cross-in-circle eye, the Great Serpent reigned over the watery Beneath World in Southeastern Indigenous cosmology while conferring war medicine, storm power, and renewal."}, {"id": "cn-07-ming-datong-nine-dragon-wall", "title": "Polychrome Glazed-Tile Dragons of the Datong Nine-Dragon Wall", "creature": "Long (Four-Clawed Princely Dragons)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "大同九龍壁 (Jiǔlóngbì)", "civilization": "Ming Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Datong, Shanxi, China", "dateDisplay": "1392 CE", "yearSort": 1392, "era": "Post-Classical & Medieval", "medium": "High-relief polychrome glazed architectural terracotta tiles (liuli)", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Draconic & Serpentine", "creator": "Shanxi imperial liuli tilemasters", "repository": "In situ, Former Palace of Zhu Gui (Prince of Dai), Datong", "commonsFile": "Datong_191.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Datong_191.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Datong_191.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1d/Datong_191.jpg", "anatomy": ["coiling ochre and cobalt-glazed scaled bodies", "four-toed princely talons", "antlered heads with streaming manes", "pursuit of the flaming pearl amid waves"], "description": "Erected in 1392 to screen the palace gate of Zhu Gui, thirteenth son of the Ming founder Hongwu, the 45.5-meter Datong screen is the oldest and largest extant Nine-Dragon Wall in China. Molded in bold polychrome liuli glazed tiles, its writhing dragons sport four claws—adhering strictly to Ming sumptuary law reserving five-clawed dragons for the Emperor alone—as they chase flaming pearls over foaming seas."}, {"id": "am-10-mississippian-underwater-panther-bowl", "title": "Ceramic Effigy Bowl of the Underwater Panther", "creature": "Underwater Panther (Piasa / Horned Feline-Serpent)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Mishipeshu / Piasa", "civilization": "Late Mississippian (Nodena / Walls Phase)", "region": "The Americas & Oceania", "originLocation": "Rhodes Place, Crittenden County, Arkansas, United States", "dateDisplay": "c. 1300–1500 CE", "yearSort": 1400, "era": "Post-Classical & Medieval", "medium": "Modeled, incised, and burnished shell-tempered dark earthenware", "mediumCategory": "Ceramics & Vessels", "morphology": "Composite Chimeras", "creator": "Unknown Late Mississippian ceramic artist", "repository": "National Museum of the American Indian, Smithsonian Institution, Washington, D.C. / New York", "commonsFile": "Underwater_panther_bowl_1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Underwater_panther_bowl_1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Underwater_panther_bowl_1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b6/Underwater_panther_bowl_1.jpg", "anatomy": ["sculpted cougar head rising from the vessel rim with bared fangs and horns", "swirling incised scroll-bands representing whirlpools and scales across the body", "elongated serpentine tail curving around the opposite rim lug"], "description": "Unearthed at the Late Mississippian mound center of Rhodes Place in the Central Mississippi Valley, this polished dark-ware effigy vessel embodies the dread lord of the subaqueous realm: the Underwater Panther. Combining the horned, snarling head of a mountain lion with a long serpent tail and incised vortex scrolls, the chimeric beast governed rivers, whirlpools, and healing medicine in eternal cosmic tension with the Thunderbirds of the Upper World."}, {"id": "md-05-wild-men-tapestry", "title": "Wild Men Combating a Lion, Dragon, and Unicorn (Wild Men and Moors Tapestry)", "creature": "Wild Man (Wilder Mann)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Wilder Mann / Wilde Leute", "civilization": "Late Medieval Upper Rhineland", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Strasbourg, Alsace (Upper Rhine)", "dateDisplay": "c. 1400 CE", "yearSort": 1400, "era": "Post-Classical & Medieval", "medium": "Tapestry weave of dyed wool weft on undyed linen warp", "mediumCategory": "Textile & Tapestry", "morphology": "Giants, Demons & Spirits", "creator": "Strasbourg tapestry workshop (commissioned for the Blümel and Zorn families)", "repository": "Museum of Fine Arts, Boston (Inv. 54.1431)", "commonsFile": "Wild_Men_and_Moors_(Detail_09_of_12).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wild_Men_and_Moors_(Detail_09_of_12).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wild_Men_and_Moors_(Detail_09_of_12).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/45/Wild_Men_and_Moors_(Detail_09_of_12).jpg", "anatomy": ["humanoid woodland body covered from neck to ankles in shaggy blue and ochre fur", "bare hands, feet, and painted facial features", "uprooted tree trunks and boulders wielded against forest beasts"], "description": "Woven in Strasbourg around 1400 for patrician Alsatian households, this vibrant woollen frieze portrays shaggy, pelt-covered 'Wilde Leute'—untamed woodland humans living beyond feudal civilization—battling a lion, a winged dragon, and a unicorn before bringing game home to a wild woman and her children in a rocky crag. In Upper Rhenish tapestry culture, the Wild Man simultaneously embodied primal natural vigor, uncorrupted fidelity, and mastery over monstrous wilderness."}, {"id": "cn-07-ming-wudang-xuanwu", "title": "Gilt-Bronze Sculpture of Xuanwu (Black Tortoise and Snake)", "creature": "Xuanwu (Tortoise-Serpent of the North)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "銅鎏金玄武 (Xuánwǔ)", "civilization": "Ming Dynasty (Yongle Reign)", "region": "East Asia & Eurasian Steppe", "originLocation": "Mount Wudang, Hubei, China", "dateDisplay": "Early 15th century CE (1403–1424)", "yearSort": 1412, "era": "Post-Classical & Medieval", "medium": "Cast copper alloy with mercury gilding", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Draconic & Serpentine", "creator": "Imperial Ming court foundry (commissioned for Mount Wudang)", "repository": "Hubei Provincial Museum, Wuhan", "commonsFile": "Wudanghshan-Xuanwu-in-Beijing-Capital-Museum-3796.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wudanghshan-Xuanwu-in-Beijing-Capital-Museum-3796.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wudanghshan-Xuanwu-in-Beijing-Capital-Museum-3796.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Wudanghshan-Xuanwu-in-Beijing-Capital-Museum-3796.jpg", "anatomy": ["hexagonal-plated tortoise carapace", "tightly coiled scaled serpent", "confronting turtle and snake heads", "clawed reptilian feet"], "description": "Cast and richly gilded by imperial workshops during the Yongle Emperor's massive reconstruction of the Daoist temples on Mount Wudang, this sculpture depicts Xuanwu—the Dark Warrior of the Northern Quadrant—in its primordial zoomorphic form as a tortoise locked in sinuous embrace with a serpent. Revered as both a celestial directional guardian and the martial deity Zhenwu, the dual creature symbolized longevity, water, and cosmic yin-yang union."}, {"id": "cn-07-ming-shen-du-qilin", "title": "Auspicious Qilin Tribute from Bengal (Ruiying Qilin Tu)", "creature": "Qilin (Benevolent One-Horned Auspicious Beast)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "明人畫麒麟沈度頌軸 (Qílín)", "civilization": "Ming Dynasty (Yongle Court)", "region": "East Asia & Eurasian Steppe", "originLocation": "Nanjing / Beijing Imperial Court, China", "dateDisplay": "1414 CE", "yearSort": 1414, "era": "Post-Classical & Medieval", "medium": "Ink and color on silk hanging scroll", "mediumCategory": "Painting & Fresco", "morphology": "Single-Horned & Sacred Beasts", "creator": "Shen Du (沈度, 1357–1434, calligrapher) and Ming court painter", "repository": "National Palace Museum, Taipei", "commonsFile": "ShenDuGiraffePainting.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:ShenDuGiraffePainting.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/ShenDuGiraffePainting.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/78/ShenDuGiraffePainting.jpg", "anatomy": ["fleshy ossicone horns (roujiao)", "reticulated coat likened to luminous scales", "cloven equine-cervid hooves", "towering gentle neck"], "description": "When envoys from Bengal—sailing in the wake of Admiral Zheng He's Indian Ocean Treasure Fleets—presented an East African giraffe to the Yongle court in September 1414, courtiers hailed the exotic creature—called girin in Somali—as a living manifestation of the mythical qilin. Inscribed above by Hanlin calligrapher Shen Du with a celebratory paean, the scroll exemplifies how Imperial Chinese statecraft assimilated natural marvels into classical omen-mythology."}, {"id": "md-05-melusine-lusignan", "title": "Winged Serpent Mélusine Hovering Above Château de Lusignan (Très Riches Heures du Duc de Berry)", "creature": "Melusine", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Mélusine", "civilization": "Valois Court / International Gothic France", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Bourges or Paris, France", "dateDisplay": "c. 1412–1416 (completed c. 1440 CE)", "yearSort": 1416, "era": "Renaissance & Early Modern", "medium": "Tempera, gold, and lapis lazuli on vellum (March calendar miniature, Folio 3v)", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Paul, Jean, and Herman de Limbourg (and Barthélemy d'Eyck)", "repository": "Musée Condé, Château de Chantilly (MS 65)", "commonsFile": "Les_Très_Riches_Heures_du_duc_de_Berry_mars.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_mars.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_mars.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7a/Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_mars.jpg", "anatomy": ["golden winged dragon-serpent form taken after her Saturday bath taboo was broken", "ribbons of ribbed bat-like wings against a lapis lazuli sky", "guardian flight circling the Tour Poitevine of Lusignan Castle"], "description": "High in the ultramarine sky above the white ramparts of the Château de Lusignan in the March calendar leaf of Jean de Berry's Très Riches Heures, a golden winged dragon circles the rightmost tower: the fairy ancestress Mélusine. Celebrated in Jean d'Arras's 1393 romance written for the Duke of Berry himself, Mélusine magically erected the fortress of Lusignan before her husband spied upon her serpent-tailed bath, compelling her to fly away in draconic form and return shrieking above the towers whenever the lordship changed hands."}, {"id": "rm-04-black-george-dragon-icon", "title": "Icon of the Miracle of Saint George and the Dragon ('Black George')", "creature": "Byzantine-Slavic Winged Dragon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Drakon (Δράκων) / Zmiy", "civilization": "Byzantine Commonwealth (Novgorodian / Late Palaiologan tradition)", "region": "Etruria, Rome & Byzantium", "originLocation": "Novgorod Republic (in the Late Byzantine iconographic tradition)", "dateDisplay": "First half of the 15th century CE (c. 1400–1450)", "yearSort": 1425, "era": "Post-Classical & Medieval", "medium": "Egg tempera and gesso on wooden panel", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Byzantine-tradition iconographer of Novgorod", "repository": "British Museum, London (1986,0603.1)", "commonsFile": "Black_St_George_Icon_-_Joy_of_Museums.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Black_St_George_Icon_-_Joy_of_Museums.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Black_St_George_Icon_-_Joy_of_Museums.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/90/Black_St_George_Icon_-_Joy_of_Museums.jpg", "anatomy": ["crested serpentine dragon head pierced through the jaws", "bat-like red-and-ochre wings emerging above two clawed forelegs", "knotted tail coiling out of a subterranean abyssal lair"], "description": "Painted in luminous vermilion, cinnabar, and black egg tempera on a carved limewood panel, the celebrated 'Black George' icon adapts Eastern Christian Byzantine dragon-slayer iconography to its starkest silhouette. Astride a jet-black steed blessed by the hand of God from an arc of heaven, the haloed warrior-saint drives his cross-topped lance straight into the gaping maw of a winged, two-legged serpentine dragon emerging from a dark cavern."}, {"id": "ne-01-baysunghur-white-div", "title": "Rustam Slaying the White Div (Div-e Sepid) in the Cave of Mazandaran", "creature": "Div-e Sepid (The White Demon of Mazandaran)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Dīv-e Sepīd (دیو سپید)", "civilization": "Timurid Persia", "region": "Ancient Near East & Persia", "originLocation": "Herat, Afghanistan (Baysunghur Shahnameh)", "dateDisplay": "1430 CE (833 AH)", "yearSort": 1430, "era": "Post-Classical & Medieval", "medium": "Opaque watercolor, ink, and gold on paper", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Kitabkhana of Prince Baysunghur Mirza", "repository": "Golestan Palace Library, Tehran (UNESCO Memory of the World)", "commonsFile": "Rostam_and_the_White_Div_from_Baysanghar_Shahnameh.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Rostam_and_the_White_Div_from_Baysanghar_Shahnameh.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Rostam_and_the_White_Div_from_Baysanghar_Shahnameh.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/16/Rostam_and_the_White_Div_from_Baysanghar_Shahnameh.jpg", "anatomy": ["Chalk-white pelted giant body with curved black horns", "Fanged grimace, spotted demonic loincloth, and clawed hands and feet", "Severed lower leg beside the pitch-black mouth of his mountain cavern"], "description": "Created in 1430 in the royal Herat workshop of the Timurid prince Baysunghur, this celebrated miniature depicts the climax of Rustam's Seventh Labour in Ferdowsi's Shahnameh. Inside a pitch-black mountain cavern framed by blossoming trees and the bound guide Olad, the tiger-skin-clad hero plunges his dagger into the horned, white-furred chieftain of the Mazandaran demons to retrieve his liver blood and cure King Kay Kavus's blindness."}, {"id": "am-10-borgia-cipactli", "title": "Cipactli, the Primordial Crocodilian Earth Monster (Codex Borgia)", "creature": "Cipactli (Earth Caiman Monster)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Cipactli", "civilization": "Nahua / Puebla-Tlaxcala (Borgia Group)", "region": "The Americas & Oceania", "originLocation": "Puebla-Tlaxcala Valley or Cholula, Central Mexico", "dateDisplay": "c. 1400–1521 CE", "yearSort": 1450, "era": "Post-Classical & Medieval", "medium": "Mineral and organic pigments on gesso-primed deerskin screenfold", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown Nahua tlacuilo (painter-scribe)", "repository": "Biblioteca Apostolica Vaticana, Vatican City (Borg. mess. 1)", "commonsFile": "Cipactli_2.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Cipactli_2.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Cipactli_2.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f0/Cipactli_2.jpg", "anatomy": ["ridge of shark-like dorsal spines along an armored crocodilian back", "upper jaw armed with recurved flint-like fangs and no lower jaw", "clawed reptilian limbs associated with insatiable joint-mouths"], "description": "Painted on gessoed deerskin in the pre-Conquest divinatory manuscript Codex Borgia, Cipactli presides over the very first day-sign of the 260-day tonalpohualli ritual calendar. In Central Mexican cosmogony, the gods Quetzalcoatl and Tezcatlipoca grappled with this voracious caiman-sawfish monster swimming in the primordial waters—tearing its spiny body asunder to fashion the mountains, valleys, and fertile surface of the earth."}, {"id": "am-10-aztec-xiuhcoatl", "title": "Stone Sculpture of Xiuhcoatl (The Turquoise Fire Serpent)", "creature": "Aztec Fire Serpent", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Xiuhcōātl", "civilization": "Aztec (Mexica)", "region": "The Americas & Oceania", "originLocation": "Tenochtitlan (Mexico City), Basin of Mexico", "dateDisplay": "c. 1400–1521 CE", "yearSort": 1450, "era": "Post-Classical & Medieval", "medium": "Carved volcanic basalt", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Mexica imperial sculptor", "repository": "The British Museum, London (Am1825,1210.19)", "commonsFile": "Xiuhcoatl,_British_Museum.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Xiuhcoatl,_British_Museum.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Xiuhcoatl,_British_Museum.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d4/Xiuhcoatl,_British_Museum.jpg", "anatomy": ["recurved horn-like snout studded with seven stellar orbs", "gaping fanged reptilian jaws and clawed forelimbs", "segmented trapezoidal tail terminating in the triangular year-sign and fire-drill rays"], "description": "Carved from dense grey volcanic stone, this Mexica monument embodies Xiuhcoatl, the celestial Turquoise Fire Serpent wielded as a living lightning bolt by the solar war god Huitzilopochtli to slay Coyolxauhqui at Coatepec. Its arched, star-studded snout curves backward above cavernous fangs while its segmented body terminates in the bound A-O solar-year trapeze, uniting meteoric fire, drought, and calendrical renewal."}, {"id": "md-05-livre-merveilles-blemmyes", "title": "Headless Blemmyes and Monstrous Marvels of Ethiopia in the Livre des merveilles du monde", "creature": "Blemmye (Acephali) and Panotii", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Blemmyes", "civilization": "Late Medieval Angevin France", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Angers, Duchy of Anjou, France", "dateDisplay": "c. 1460 CE", "yearSort": 1460, "era": "Renaissance & Early Modern", "medium": "Tempera and gold paint on parchment (MS M.461, Folios 26v–27r)", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Master of the Geneva Boccaccio (Colin d'Amiens?)", "repository": "The Morgan Library & Museum, New York (MS M.461)", "commonsFile": "Livre_des_merveilles_du_monde_MS_M.461,_fols._26v–27r.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Livre_des_merveilles_du_monde_MS_M.461,_fols._26v%E2%80%9327r.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Livre_des_merveilles_du_monde_MS_M.461,_fols._26v%E2%80%9327r.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f5/Livre_des_merveilles_du_monde_MS_M.461,_fols._26v%E2%80%9327r.jpg", "anatomy": ["headless human torso with eyes, nose, and mouth set directly into the chest", "club-wielding Panotii giant with ears hanging down to the shoulders", "horned giant bird of prey and cave-dwelling troglodytes"], "description": "Across a luminous double-page landscape in the Morgan Library's Livre des merveilles du monde, the Master of the Geneva Boccaccio populates the imagined borders of Ethiopia with the 'Plinian races' inherited from classical geography and medieval mappae mundi. Prominent in the foreground stands a headless Blemmye whose facial features gaze directly out from his bare chest, flanked by a huge-eared giant, serpent-eating cave dwellers, and a horned raptor."}, {"id": "am-10-aztec-double-headed-serpent", "title": "Turquoise Mosaic Pectoral of a Double-Headed Serpent", "creature": "Double-Headed Sky Serpent", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Maquizcōātl", "civilization": "Mixtec–Aztec", "region": "The Americas & Oceania", "originLocation": "Puebla-Oaxaca or Tenochtitlan, Mexico", "dateDisplay": "c. 1400–1521 CE", "yearSort": 1460, "era": "Renaissance & Early Modern", "medium": "Turquoise, spiny oyster (Spondylus), and conch shell mosaic on carved Spanish cedar wood", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Draconic & Serpentine", "creator": "Unknown Mixtec-Nahua master lapidary-mosaicist", "repository": "The British Museum, London (Am1894,-.634)", "commonsFile": "Turquoise_Mosaic_of_a_Double-Headed_Serpent_(Mixtec-Aztec,_AD_1400-1521)_-_British_Museum.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Turquoise_Mosaic_of_a_Double-Headed_Serpent_(Mixtec-Aztec,_AD_1400-1521)_-_British_Museum.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Turquoise_Mosaic_of_a_Double-Headed_Serpent_(Mixtec-Aztec,_AD_1400-1521)_-_British_Museum.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e9/Turquoise_Mosaic_of_a_Double-Headed_Serpent_(Mixtec-Aztec,_AD_1400-1521)_-_British_Museum.jpg", "anatomy": ["symmetrical undulating body encrusted with roughly two thousand turquoise tesserae", "twin opposing serpent heads baring white conch-shell fangs", "crimson Spondylus shell gums and nostrils once paired with iron-pyrite eyes"], "description": "Carved from a single block of fragrant Cedrela odorata wood and encrusted with nearly two thousand tesserae of turquoise imported from the American Southwest, this 43 cm pectoral is among the supreme surviving works of Mesoamerican lapidary regalia. Its twin snarling heads—trimmed in crimson thorny oyster and white strombus shell—evoke Maquizcoatl, the ominous double-headed serpent of Aztec sky-portents and priestly Renewal ceremonies, and may have formed part of Moctezuma II's diplomatic treasure sent to Europe in 1519."}, {"id": "sa-09-thang-long-imperial-rong", "title": "Imperial Stone Dragon (Rồng) Stairway Balustrade of Kính Thiên Palace", "creature": "Vietnamese Imperial Dragon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Rồng (Long)", "civilization": "Early Lê Dynasty (Imperial Vietnam)", "region": "South & Southeast Asia", "originLocation": "Kính Thiên Palace Foundation, Imperial Citadel of Thăng Long, Hanoi, Vietnam", "dateDisplay": "1467 CE (reign of Emperor Lê Thánh Tông)", "yearSort": 1467, "era": "Renaissance & Early Modern", "medium": "Monolithic carved grey limestone stairway balustrade", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Imperial court stone-carvers of Đại Việt", "repository": "In situ, Imperial Citadel of Thăng Long, Hanoi, Vietnam", "commonsFile": "Hanoi_Citadel_0355.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Hanoi_Citadel_0355.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Hanoi_Citadel_0355.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7a/Hanoi_Citadel_0355.JPG", "anatomy": ["horned draconic head with flaming mane and grasping pearl in the jaws", "undulating cloud-wreathed serpentine body descending the steps", "five-clawed imperial talons gripping swirling clouds"], "description": "Constructed in 1467 under Emperor Lê Thánh Tông for the audience terrace of Kính Thiên Palace at the heart of the Thăng Long Citadel, four monolithic limestone dragons (Rồng) surge headfirst down the ceremonial steps amidst carved thunderclouds. Bearing five-clawed imperial talons, wind-swept manes, and sacred pearls in their jaws, the dragons embody the Vietnamese sovereign's heaven-mandated authority as well as the rain-bringing lineage of Lạc Long Quân ('Dragon Lord of Lạc')."}, {"id": "rn-06-uccello-st-george-dragon", "title": "Saint George and the Dragon", "creature": "Winged Cave Dragon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Drago", "civilization": "Italian Renaissance (Florence)", "region": "Renaissance & Early Modern Europe", "originLocation": "Florence, Italy", "dateDisplay": "c. 1470 CE", "yearSort": 1470, "era": "Renaissance & Early Modern", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Paolo Uccello", "repository": "National Gallery, London", "commonsFile": "Paolo_Uccello_-_St_George_slaying_the_dragon_-_Google_Art_Project.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Paolo_Uccello_-_St_George_slaying_the_dragon_-_Google_Art_Project.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Paolo_Uccello_-_St_George_slaying_the_dragon_-_Google_Art_Project.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/29/Paolo_Uccello_-_St_George_slaying_the_dragon_-_Google_Art_Project.jpg", "anatomy": ["bipedal serpentine body", "patterned ocellated bat-like wings", "coiled reptilian tail", "fanged jaws pierced by a lance"], "description": "One of the earliest surviving Renaissance paintings on canvas, Paolo Uccello's composition stages the legend of Saint George outside a craggy lair beneath a swirling vortex of storm clouds. The two-legged wyvern-like dragon rears on clawed hindlimbs with vivid eye-spotted wings spread wide, simultaneously pierced by George's lance and bound on a delicate girdle leash held by the tranquil princess."}, {"id": "rn-06-schongauer-temptation-st-anthony", "title": "The Temptation of Saint Anthony", "creature": "Airborne Ichthyomorphic and Hybrid Demons", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Teufel / Dämonen", "civilization": "Northern Renaissance (Upper Rhine)", "region": "Renaissance & Early Modern Europe", "originLocation": "Colmar, Alsace (Holy Roman Empire)", "dateDisplay": "c. 1470–1475 CE", "yearSort": 1473, "era": "Renaissance & Early Modern", "medium": "Copperplate engraving on laid paper", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Martin Schongauer", "repository": "Metropolitan Museum of Art, New York (and multiple print cabinets)", "commonsFile": "The_Temptation_of_Saint_Anthony,_by_Martin_Schongauer.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:The_Temptation_of_Saint_Anthony,_by_Martin_Schongauer.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/The_Temptation_of_Saint_Anthony,_by_Martin_Schongauer.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/ac/The_Temptation_of_Saint_Anthony,_by_Martin_Schongauer.jpg", "anatomy": ["spiny fish scales and dorsal fins", "membranous bat and insectoid wings", "curved rams' horns and tusks", "prehensile talons and reptilian tails"], "description": "Martin Schongauer's virtuosic early engraving suspends the stoic desert hermit mid-air within a tangled whirlwind of nine grotesque hybrid tormentors. Combining meticulous zoological observation of dried skates, lizards, crustaceans, and birds of prey, Schongauer forged an influential Northern Renaissance vocabulary of composite demonic anatomy that deeply inspired both Hieronymus Bosch and the young Michelangelo."}, {"id": "am-10-aztec-coiled-feathered-serpent", "title": "Coiled Feathered Serpent (Quetzalcoatl)", "creature": "Plumed Rattlesnake", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Quetzalcōātl", "civilization": "Aztec (Mexica)", "region": "The Americas & Oceania", "originLocation": "Central Mexico", "dateDisplay": "15th–early 16th century CE", "yearSort": 1480, "era": "Renaissance & Early Modern", "medium": "Carved volcanic basalt", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown Mexica sculptor", "repository": "The Metropolitan Museum of Art, New York (00.5.32)", "commonsFile": "Coiled_serpent_(met).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Coiled_serpent_(met).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Coiled_serpent_(met).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/07/Coiled_serpent_(met).jpg", "anatomy": ["tightly wound muscular coils covered in layered avian plumage", "flared supraorbital brow scales over sunken eyes", "extruded bifurcated serpent tongue and segmented tail rattles"], "description": "Sculpted in the round—including finely incised ventral scales on its underside—this compact volcanic basalt monument fuses the lethal terrestrial power of the Mesoamerican rattlesnake with the iridescent sky-plumage of the resplendent quetzal. Coiled in potent equilibrium with its forked tongue flicking beneath heavy feathered brows, the sculpture embodies Quetzalcoatl as wind-bringer, morning star, and divine patron of Mexica priesthood and kingship."}, {"id": "md-05-laval-tarasque", "title": "Saint Martha Taming the Man-Eating Tarasque in the Hours of Louis de Laval", "creature": "Tarasque", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "La Tarasque", "civilization": "Late Gothic Kingdom of France", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Bourges, Berry, France", "dateDisplay": "c. 1470–1485 CE", "yearSort": 1480, "era": "Renaissance & Early Modern", "medium": "Tempera and liquid gold on vellum (BnF MS Latin 920, Folio 317v)", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Jean Colombe and workshop", "repository": "Bibliothèque nationale de France, Paris (MS Latin 920)", "commonsFile": "Heures_de_Louis_de_Laval_-_BNF_Lat920_f317v_(Sainte_Marthe_et_la_Tarasque).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Heures_de_Louis_de_Laval_-_BNF_Lat920_f317v_(Sainte_Marthe_et_la_Tarasque).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Heures_de_Louis_de_Laval_-_BNF_Lat920_f317v_(Sainte_Marthe_et_la_Tarasque).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/fa/Heures_de_Louis_de_Laval_-_BNF_Lat920_f317v_(Sainte_Marthe_et_la_Tarasque).jpg", "anatomy": ["armored turtle-like carapace spiked along the spine", "lion-like head devouring a human victim feet-first", "six bear-like clawed legs and scaly viper tail subdued by a girdle and holy water"], "description": "Illuminated by Jean Colombe for the Breton nobleman Louis de Laval, Folio 317v visualizes Jacobus de Voragine's Golden Legend account of Saint Martha subduing the amphibious monster of the Rhône at Nerluc (renamed Tarascon). Even as a half-swallowed man's legs kick from its jaws, the spiny-shelled, dragon-tailed Tarasque bows meekly on a leash while Martha sprinkles it with holy water from an aspergillum."}, {"id": "rn-06-botticelli-pallas-centaur", "title": "Pallas and the Centaur", "creature": "Centaur", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Centauro", "civilization": "Italian Renaissance (Florence)", "region": "Renaissance & Early Modern Europe", "originLocation": "Florence, Italy", "dateDisplay": "c. 1482 CE", "yearSort": 1482, "era": "Renaissance & Early Modern", "medium": "Tempera on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Therianthropic (Human-Beast)", "creator": "Sandro Botticelli", "repository": "Uffizi Gallery, Florence", "commonsFile": "Botticelli_Pallas_and_the_Centaur.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Botticelli_Pallas_and_the_Centaur.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Botticelli_Pallas_and_the_Centaur.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/de/Botticelli_Pallas_and_the_Centaur.jpg", "anatomy": ["muscular bearded human torso", "bay equine barrel and four hooves", "pointed satyr-like ears", "tousled locks grasped by Minerva"], "description": "Painted for the Medici circle in Florence as a Neoplatonic allegory of wisdom subduing untamed appetite, Botticelli's life-sized canvas pairs an olive-wreathed Pallas Athena with a melancholic, bow-carrying centaur. Rather than portraying the hybrid as a ferocious monster, Botticelli endows the equine-human creature with a pathos-filled, expressive countenance borrowed from antique sarcophagi of suffering giants."}, {"id": "am-10-aztec-ahuizotl-plaque", "title": "Carved Relief Plaque of the Ahuizotl from Tepoztlán", "creature": "Ahuizotl (Amphibious Hand-Tailed Water Beast)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Āhuizotl", "civilization": "Aztec (Mexica)", "region": "The Americas & Oceania", "originLocation": "Tepoztlán, Morelos, Mexico", "dateDisplay": "c. 1486–1502 CE", "yearSort": 1495, "era": "Renaissance & Early Modern", "medium": "Carved volcanic stone relief", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Unknown Mexica imperial sculptor", "repository": "Museo Nacional de Antropología, Mexico City", "commonsFile": "Lápida_de_Ahuízotl_-_octavo_Huey_Tlatoani_de_los_mexicas.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:L%C3%A1pida_de_Ahu%C3%ADzotl_-_octavo_Huey_Tlatoani_de_los_mexicas.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/L%C3%A1pida_de_Ahu%C3%ADzotl_-_octavo_Huey_Tlatoani_de_los_mexicas.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6b/L%C3%A1pida_de_Ahu%C3%ADzotl_-_octavo_Huey_Tlatoani_de_los_mexicas.jpg", "anatomy": ["lithe otter- or dog-like quadrupedal body surrounded by stylized water-scrolls", "monkey-like clawed paws and pointed canine ears", "long prehensile tail terminating in a dextrous human hand"], "description": "Originally adorning a sacred temple structure at Tepoztlán, this crisp stone relief serves simultaneously as the royal name-glyph of the eighth Mexica Huey Tlatoani, Ahuitzotl (r. 1486–1502), and as a portrait of his namesake lake monster. Feared by fishermen of Lake Texcoco and vividly described in Book XI of the Florentine Codex, the amphibious Ahuizotl lurked in deep whirlpools as servant of the rain gods Tlaloc and Chalchiuhtlicue, luring victims with infant-like cries before dragging them underwater with the human hand at the tip of its tail."}, {"id": "rn-06-piero-death-of-procris", "title": "The Death of Procris (A Satyr Mourning over a Nymph)", "creature": "Faun / Satyr", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Satiro / Fauno", "civilization": "Italian Renaissance (Florence)", "region": "Renaissance & Early Modern Europe", "originLocation": "Florence, Italy", "dateDisplay": "c. 1495 CE", "yearSort": 1495, "era": "Renaissance & Early Modern", "medium": "Oil on poplar wood panel", "mediumCategory": "Painting & Fresco", "morphology": "Therianthropic (Human-Beast)", "creator": "Piero di Cosimo", "repository": "National Gallery, London", "commonsFile": "Piero_di_Cosimo_013.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Piero_di_Cosimo_013.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Piero_di_Cosimo_013.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2f/Piero_di_Cosimo_013.jpg", "anatomy": ["shaggy caprine hindlegs and cloven hooves", "sprouting forehead goat horns", "pointed animal ears", "human torso and grieving hands"], "description": "Executed on a wide horizontal panel likely intended for a Florentine wedding chest (spalliera), Piero di Cosimo's elegiac masterpiece depicts a gentle woodland satyr kneeling tenderly beside a slain nymph along a tranquil estuary. Framed by a sorrowful hunting hound and distant shorebirds, the goat-legged hybrid embodies empathetic natural innocence rather than classical bacchic license."}, {"id": "rn-06-durer-sea-monster", "title": "The Sea Monster (Das Meerwunder)", "creature": "Ichthyocentaur / Horned Triton", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Das Meerwunder", "civilization": "Northern Renaissance (Nuremberg)", "region": "Renaissance & Early Modern Europe", "originLocation": "Nuremberg, Holy Roman Empire", "dateDisplay": "c. 1498 CE", "yearSort": 1498, "era": "Renaissance & Early Modern", "medium": "Engraving on laid paper", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Albrecht Dürer", "repository": "National Gallery of Art, Washington, D.C.", "commonsFile": "Albrecht_Dürer_-_Sea_Monster_(Das_Meerwunder)_(NGA_1943.3.3483).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer_-_Sea_Monster_(Das_Meerwunder)_(NGA_1943.3.3483).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Albrecht_D%C3%BCrer_-_Sea_Monster_(Das_Meerwunder)_(NGA_1943.3.3483).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/62/Albrecht_D%C3%BCrer_-_Sea_Monster_(Das_Meerwunder)_(NGA_1943.3.3483).jpg", "anatomy": ["bearded human torso", "antler-like cranial horns", "scaly serpentine fish tail", "tortoiseshell shield and jawbone club"], "description": "Referred to by Albrecht Dürer himself in his Netherlandish diary simply as Das Meerwunder, this enigmatic copper engraving shows an aging, antlered merman carrying a reclining nude woman across coastal waters while panicked bathers flee ashore. Drawing upon classical accounts of Tritons and 15th-century Adriatic sea-monster reports cited by Poggio Bracciolini, Dürer renders every scale and ripple with crystalline linework."}, {"id": "rn-06-bosch-garden-of-earthly-delights-hell", "title": "The Garden of Earthly Delights (Right Wing: Musical Hell)", "creature": "Bird-Headed Prince of Hell and Hybrid Grylli", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Duivels / Grylli", "civilization": "Early Netherlandish", "region": "Renaissance & Early Modern Europe", "originLocation": "'s-Hertogenbosch, Duchy of Brabant", "dateDisplay": "c. 1490–1505 CE", "yearSort": 1500, "era": "Renaissance & Early Modern", "medium": "Oil on oak panel", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Hieronymus Bosch", "repository": "Museo Nacional del Prado, Madrid", "commonsFile": "Hieronymus_Bosch_-_The_Garden_of_Earthly_Delights_-_Hell.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Hieronymus_Bosch_-_The_Garden_of_Earthly_Delights_-_Hell.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Hieronymus_Bosch_-_The_Garden_of_Earthly_Delights_-_Hell.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/17/Hieronymus_Bosch_-_The_Garden_of_Earthly_Delights_-_Hell.jpg", "anatomy": ["raptor-beaked avian head crowned with a cauldron", "bloated humanoid body swallowing sinners", "hollow eggshell torso of the Tree-Man", "polycephalic and zoomorphic hybrid demons"], "description": "On the nocturnal right wing of Hieronymus Bosch's celebrated oak triptych, an infernal landscape illuminated by burning cities swarms with nightmarish chimeras, monstrous musical instruments, and medieval grylli. Enthroned on a commode chair near the foreground sits the blue bird-headed 'Prince of Hell,' wearing a cauldron crown and ceramic jugs on his feet as he devours and excretes human souls."}, {"id": "md-05-cluny-dame-licorne", "title": "The Lady and the Unicorn: 'À mon seul désir' (La Dame à la licorne)", "creature": "Unicorn", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "La Licorne", "civilization": "Franco-Flemish Late Gothic / Early Renaissance", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Designed in Paris (Master of Anne of Brittany); woven in the Southern Netherlands", "dateDisplay": "c. 1500 CE", "yearSort": 1500, "era": "Renaissance & Early Modern", "medium": "Millefleurs tapestry woven in wool and silk", "mediumCategory": "Textile & Tapestry", "morphology": "Single-Horned & Sacred Beasts", "creator": "Cartoons attributed to Jean d'Ypres (Master of Anne of Brittany); Brussels or Bruges weavers", "repository": "Musée de Cluny – Musée national du Moyen Âge, Paris", "commonsFile": "Tapisserie_de_la_Dame_à_la_Licorne_(Musée_de_Cluny,_Paris).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tapisserie_de_la_Dame_%C3%A0_la_Licorne_(Mus%C3%A9e_de_Cluny,_Paris).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tapisserie_de_la_Dame_%C3%A0_la_Licorne_(Mus%C3%A9e_de_Cluny,_Paris).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3b/Tapisserie_de_la_Dame_%C3%A0_la_Licorne_(Mus%C3%A9e_de_Cluny,_Paris).jpg", "anatomy": ["slender white equine-caprine body with cloven hooves", "long straight spiraled ivory horn and silken goat-beard", "heraldic posture bearing the crescents of the Le Viste coat of arms"], "description": "Crowning a celebrated six-tapestry cycle of the Five Senses woven for the Lyon magistrate Jean IV Le Viste, 'À mon seul désir' stages a noblewoman placing her jewel necklace into a casket before a blue damask pavilion held open by a heraldic lion and a snow-white unicorn. Against a vermilion millefleurs ground teeming with rabbits, birds, and wildflowers, the cloven-hoofed, goat-bearded unicorn embodies courtly chivalry and spiritual purity."}, {"id": "md-05-cloisters-unicorn-captivity", "title": "The Unicorn in Captivity (from The Hunt of the Unicorn Tapestries)", "creature": "Unicorn", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "La Licorne", "civilization": "Franco-Flemish Late Gothic / Early Renaissance", "region": "Medieval, Celtic & Norse Europe", "originLocation": "Designed in Paris; woven in the Southern Netherlands (probably Brussels)", "dateDisplay": "c. 1495–1505 CE", "yearSort": 1502, "era": "Renaissance & Early Modern", "medium": "Wool warp with wool, silk, silver, and gilt-wrapped thread weft", "mediumCategory": "Textile & Tapestry", "morphology": "Single-Horned & Sacred Beasts", "creator": "Parisian cartoonist (circle of Jean d'Ypres) and Southern Netherlandish weavers", "repository": "The Met Cloisters, Metropolitan Museum of Art, New York (37.80.6)", "commonsFile": "The_Unicorn_in_Captivity_-_Google_Art_Project.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:The_Unicorn_in_Captivity_-_Google_Art_Project.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/The_Unicorn_in_Captivity_-_Google_Art_Project.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6a/The_Unicorn_in_Captivity_-_Google_Art_Project.jpg", "anatomy": ["snow-white stallion-goat hybrid with tufted fetlocks and cloven hooves", "long twisted horn rising from the center of the forehead", "flanks flecked with ruby pomegranate juice beneath a golden collar and chain"], "description": "Perhaps the single most iconic textile of the European Middle Ages, the final panel of the Cloisters' Unicorn Tapestries depicts the resurrected or willingly tamed unicorn resting inside a low gilded wooden paddock tethered loosely to a fruit-laden pomegranate tree. Surrounded by more than eighty identifiable botanical species woven in dyed wool, silk, and metallic threads, the radiant beast simultaneously evokes Christ risen in paradise and the bridegroom bound in courtly marriage."}, {"id": "rn-06-carpaccio-st-george-dragon", "title": "Saint George and the Dragon", "creature": "Venetian Winged Dragon", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Drago", "civilization": "Italian Renaissance (Venice)", "region": "Renaissance & Early Modern Europe", "originLocation": "Venice, Republic of Venice", "dateDisplay": "c. 1502–1507 CE", "yearSort": 1504, "era": "Renaissance & Early Modern", "medium": "Tempera and oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Vittore Carpaccio", "repository": "Scuola di San Giorgio degli Schiavoni, Venice", "commonsFile": "Vittore_carpaccio,_san_giorgio_e_il_drago_01.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Vittore_carpaccio,_san_giorgio_e_il_drago_01.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Vittore_carpaccio,_san_giorgio_e_il_drago_01.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Vittore_carpaccio,_san_giorgio_e_il_drago_01.jpg", "anatomy": ["spined bat-like forelimb wings", "sinuous lizard body and curling tail", "webbed reptilian claws", "serrated jaws impaled through the throat"], "description": "Painted as a monumental frieze for the Dalmatian confraternity of San Giorgio degli Schiavoni in Venice, Carpaccio's narrative canvas pits the charging knight against a sinewy, spiky-winged dragon across a sun-bleached wasteland. Littered around the monster's talons are half-devoured human corpses, skulls, vipers, toads, and lizards rendered with unsettling forensic naturalism."}, {"id": "sa-09-hampi-vitthala-yali", "title": "Monolithic Rearing Yali (Vyala) Musical Mandapa Pillars", "creature": "Yali (Vyala)", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "Yāli / Vyāla", "civilization": "Vijayanagara Empire (Hindu South India)", "region": "South & Southeast Asia", "originLocation": "Vitthala Temple Complex, Hampi, Karnataka, India", "dateDisplay": "c. 1426–1542 CE", "yearSort": 1510, "era": "Renaissance & Early Modern", "medium": "Monolithic carved granite composite temple pillars", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Vijayanagara imperial stone-carvers", "repository": "In situ, Vitthala Temple Complex, Group of Monuments at Hampi, Karnataka, India", "commonsFile": "Yali_pillars_in_a_small_open_mantapa_in_the_Vitthala_temple_complex_in_Hampi_2.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Yali_pillars_in_a_small_open_mantapa_in_the_Vitthala_temple_complex_in_Hampi_2.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Yali_pillars_in_a_small_open_mantapa_in_the_Vitthala_temple_complex_in_Hampi_2.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/05/Yali_pillars_in_a_small_open_mantapa_in_the_Vitthala_temple_complex_in_Hampi_2.JPG", "anatomy": ["ferocious leonine body rearing high on muscular hind legs", "snarling fanged head with bulging eyes and stylized mane", "clawed forepaws trampling a miniature Makara or elephant below"], "description": "Hewn from single blocks of Deccan granite at the Vitthala Temple in Hampi, rows of colossal rearing Yalis (also called Vyalas) project outward from composite pavilion piers, often carrying armed riders on their backs while crushing miniature elephants or Makaras underfoot. Revered in South Indian temple architecture as more powerful than both the lion and the war-elephant, the chimeric Yali physically and symbolically bears the weight of the sacred mandapa while warding off chaos."}, {"id": "rn-06-piero-perseus-andromeda", "title": "Perseus Freeing Andromeda", "creature": "Cetus (Tusker Sea Monster)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Orca marina / Ceto", "civilization": "Italian Renaissance (Florence)", "region": "Renaissance & Early Modern Europe", "originLocation": "Florence, Italy", "dateDisplay": "c. 1510–1513 CE", "yearSort": 1511, "era": "Renaissance & Early Modern", "medium": "Oil on poplar wood panel", "mediumCategory": "Painting & Fresco", "morphology": "Marine & Abyssal Monsters", "creator": "Piero di Cosimo", "repository": "Uffizi Gallery, Florence", "commonsFile": "Piero_di_Cosimo_-_Liberazione_di_Andromeda_-_Google_Art_Project.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Piero_di_Cosimo_-_Liberazione_di_Andromeda_-_Google_Art_Project.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Piero_di_Cosimo_-_Liberazione_di_Andromeda_-_Google_Art_Project.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b4/Piero_di_Cosimo_-_Liberazione_di_Andromeda_-_Google_Art_Project.jpg", "anatomy": ["curving boar-like tusks and gaping maw", "gilled piscine neck and armored scales", "webbed amphibious forefeet", "massive coiling cetacean tail"], "description": "Admired by Giorgio Vasari as the most bizarre and delightful sea monster ever conceived, Piero di Cosimo's Cetus surges through turquoise shallows while Perseus stands squarely upon its scaly back raising his falchion. Blending cetacean bulk, porcine tusks, frilled gills, and mossy reptilian hide, the panel exemplifies High Renaissance fascination with plausible zoological hybridity."}, {"id": "rn-06-durer-knight-death-devil", "title": "Knight, Death and the Devil", "creature": "Horned Hybrid Devil", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Der Teufel", "civilization": "Northern Renaissance (Nuremberg)", "region": "Renaissance & Early Modern Europe", "originLocation": "Nuremberg, Holy Roman Empire", "dateDisplay": "1513 CE", "yearSort": 1513, "era": "Renaissance & Early Modern", "medium": "Copperplate engraving on laid paper", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Albrecht Dürer", "repository": "National Gallery of Art, Washington, D.C.", "commonsFile": "Albrecht_Dürer,_Knight,_Death_and_Devil,_1513,_NGA_6637.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer,_Knight,_Death_and_Devil,_1513,_NGA_6637.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Albrecht_D%C3%BCrer,_Knight,_Death_and_Devil,_1513,_NGA_6637.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0a/Albrecht_D%C3%BCrer,_Knight,_Death_and_Devil,_1513,_NGA_6637.jpg", "anatomy": ["single curved central horn and ram's horns", "elongated lupine-porcine snout", "furred biped torso and cloven hooves", "ass-like ears and spiked boar-spear"], "description": "First of Albrecht Dürer's three celebrated Meisterstiche (master engravings), this print accompanies a steadfast Christian knight through a shadowed gorge stalked by corpse-like Death and a grotesque horned Devil. Trailing closely behind the horse's croup, the composite fiend fuses porcine snout, lupine fangs, caprine horns, and shaggy beast pelage into an unforgettable emblem of moral peril."}, {"id": "sa-09-keladi-gandaberunda", "title": "Ceiling Relief of the Two-Headed Gandaberunda Clutching Lions and Elephants", "creature": "Gandaberunda", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Gandabherunda", "civilization": "Keladi Nayaka Kingdom (Karnataka, India)", "region": "South & Southeast Asia", "originLocation": "Rameshwara Temple, Keladi, Shivamogga District, Karnataka, India", "dateDisplay": "early 16th century CE (c. 1500–1540)", "yearSort": 1520, "era": "Renaissance & Early Modern", "medium": "Carved granite mandapa ceiling relief medallion", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Keladi Nayaka temple stone-carvers under Chowdappa and Sadashiva Nayaka", "repository": "In situ, Rameshwara Temple, Keladi, Karnataka, India", "commonsFile": "Relief_of_Gandaberunda_bird_(two_headed)_in_the_Rameshwara_temple_at_Keladi.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Relief_of_Gandaberunda_bird_(two_headed)_in_the_Rameshwara_temple_at_Keladi.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Relief_of_Gandaberunda_bird_(two_headed)_in_the_Rameshwara_temple_at_Keladi.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/dd/Relief_of_Gandaberunda_bird_(two_headed)_in_the_Rameshwara_temple_at_Keladi.jpg", "anatomy": ["two symmetrical eagle-like heads facing opposite directions", "hooked beaks grasping roaring lions that in turn seize elephants", "outspread wings and immense talons lifting war-elephants effortlessly"], "description": "Carved onto the mandapa ceiling of the Rameshwara Temple at Keladi, the royal emblem of Karnataka's rulers—the bicephalic Gandaberunda—spreads its wings while clutching lions in its twin beaks and full-grown elephants in its talons. In Hindu mythology, Vishnu assumed this colossal two-headed bird form to counter Shiva's Sharabha and restore cosmic equilibrium, making the creature an enduring symbol of unmatched imperial might from the Chalukyas and Vijayanagara to the Keladi Nayakas and Mysore Wadiyars."}, {"id": "sa-09-hampi-ugra-narasimha", "title": "Monolithic Ugra Narasimha Sheltered by the Seven-Headed Serpent Shesha", "creature": "Narasimha & Adi Shesha", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "Ugra Narasimha / Lakshmi Narasimha", "civilization": "Vijayanagara Empire (Hindu South India)", "region": "South & Southeast Asia", "originLocation": "Hampi, Vijayanagara, Karnataka, India", "dateDisplay": "1528 CE (reign of Krishnadevaraya)", "yearSort": 1528, "era": "Renaissance & Early Modern", "medium": "Colossal monolithic granite boulder sculpture (6.7 meters high)", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Commissioned by a Brahmin priest Arya Krishna Bhatta under Emperor Krishnadevaraya", "repository": "In situ, Hampi, Karnataka, India", "commonsFile": "Sri_Ugra_Narasimha_Temple-Hampi-Karnataka-DSC_0109.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sri_Ugra_Narasimha_Temple-Hampi-Karnataka-DSC_0109.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sri_Ugra_Narasimha_Temple-Hampi-Karnataka-DSC_0109.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/76/Sri_Ugra_Narasimha_Temple-Hampi-Karnataka-DSC_0109.jpg", "anatomy": ["wrathful roaring lion head with protruding eyes and stylized flame-mane", "four-armed human torso seated in cross-legged yogapatta meditation strap", "canopy of seven-hooded cosmic serpent Adi Shesha arching overhead"], "description": "Commissioned in 1528 CE during the reign of Emperor Krishnadevaraya and carved in situ from a single colossal granite boulder standing 6.7 meters tall, this statue portrays Vishnu's fourth avatar, Narasimha—the man-lion who burst from a palace pillar at twilight to slay the demon king Hiranyakashipu, whom neither man nor beast could kill. Seated in yogic mastery upon the coils of the cosmic serpent Adi Shesha beneath a seven-headed cobra canopy (originally with his consort Lakshmi on his left thigh prior to 1565), the monument radiates awesome protective ferocity."}, {"id": "rn-06-magnus-carta-marina-polypus", "title": "Carta Marina (Detail: Giant Crustacean Polypus Attacking a Sailor)", "creature": "Monstrous Polypus / Proto-Kraken", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Polypus / Gambarus", "civilization": "Nordic-Italian Renaissance Cartography", "region": "Renaissance & Early Modern Europe", "originLocation": "Venice, Italy (depicting waters off the Hebrides and Scandinavia)", "dateDisplay": "1539 CE", "yearSort": 1539, "era": "Renaissance & Early Modern", "medium": "Hand-colored woodcut wall map", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Olaus Magnus", "repository": "Uppsala University Library / Bayerische Staatsbibliothek, Munich", "commonsFile": "Carta_Marina_-polypus_as_lobster_snatches_man.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Carta_Marina_-polypus_as_lobster_snatches_man.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Carta_Marina_-polypus_as_lobster_snatches_man.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/58/Carta_Marina_-polypus_as_lobster_snatches_man.jpg", "anatomy": ["colossal segmented carapace", "serrated lobster-like chelae gripping a swimmer", "spiny crustacean legs and antennae", "barbed fan tail"], "description": "Off the Hebrides and northern isles on Olaus Magnus's 1539 Carta Marina, a gigantic armored crustacean seizes an armored swimmer inside its crushing pincer. Identified by Magnus in his accompanying commentary as a monstrous polypus and interpreted by historians of natural history as an early cartographic ancestor of the Nordic Kraken legend, the woodcut translated sailors' cephalopod and decapod encounters into terrifying visual form."}, {"id": "rn-06-magnus-carta-marina-serpent", "title": "Carta Marina (Detail: The Great Norwegian Sea Serpent)", "creature": "Great Sea Serpent", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Serpens Marinus / Sjøorm", "civilization": "Nordic-Italian Renaissance Cartography", "region": "Renaissance & Early Modern Europe", "originLocation": "Venice, Italy (by exiled Swedish ecclesiastic Olaus Magnus)", "dateDisplay": "1539 CE", "yearSort": 1539, "era": "Renaissance & Early Modern", "medium": "Hand-colored woodcut wall map", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Olaus Magnus", "repository": "Uppsala University Library / Bayerische Staatsbibliothek, Munich", "commonsFile": "Carta_Marina_(sea_serpent).jpeg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Carta_Marina_(sea_serpent).jpeg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Carta_Marina_(sea_serpent).jpeg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3d/Carta_Marina_(sea_serpent).jpeg", "anatomy": ["immense undulating serpentine coils", "flowing neck mane", "flaming eyes and fanged jaws", "body towering above a multi-masted ship"], "description": "Printed in Venice from nine large woodblocks by the exiled Swedish archbishop Olaus Magnus, the Carta Marina populated the North Atlantic and Norwegian Sea with mariners' monsters later cataloged in his 1555 Historia de Gentibus Septentrionalibus. Here the 200-foot Bergen sea serpent rears its maned, fiery-eyed loops high over a helpless merchant vessel, plucking sailors directly from the deck."}, {"id": "ne-01-safavid-buraq-miraj", "title": "The Ascent of the Prophet Muhammad on Buraq (Mi'raj)", "creature": "Al-Buraq (Celestial Human-Headed Winged Steed)", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "Al-Burāq (البراق)", "civilization": "Safavid Persia", "region": "Ancient Near East & Persia", "originLocation": "Tabriz, Iran (Khamsa of Nizami for Shah Tahmasp)", "dateDisplay": "c. 1539–1543 CE", "yearSort": 1541, "era": "Renaissance & Early Modern", "medium": "Opaque watercolor, gold, and ink on polished paper (Or. 2265, fol. 195r)", "mediumCategory": "Manuscript & Print", "morphology": "Therianthropic (Human-Beast)", "creator": "Attributed to Sultan Muhammad", "repository": "British Library, London (Or. 2265)", "commonsFile": "Miraj_by_Sultan_Muhammad.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Miraj_by_Sultan_Muhammad.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Miraj_by_Sultan_Muhammad.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b5/Miraj_by_Sultan_Muhammad.jpg", "anatomy": ["Crowned human female face with delicate Safavid courtly features", "Dappled equine-mule body adorned with a jewel-studded saddlecloth", "Flaming golden halo and peacock-like tail soaring through lapis-blue Chinese clouds"], "description": "Painted for Shah Tahmasp's royal copy of Nizami's Khamsa and attributed to the master Sultan Muhammad, this luminous folio portrays the miraculous night ascent (Mi'raj) of the veiled, flame-haloed Prophet Muhammad through a swirling lapis-lazuli sky. Bearing him past Gabriel and incense-offering angels is Buraq, envisioned in Persianate iconography with a crowned human countenance and swift piebald equine body."}, {"id": "jk-08-muromachi-hyakki-yagyo", "title": "Artifact Spirits in the Night Parade of One Hundred Demons", "creature": "Tsukumogami (Animated Household-Object Yōkai)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "付喪神 (百鬼夜行絵巻)", "civilization": "Muromachi Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Kyoto, Japan", "dateDisplay": "16th century CE (Muromachi Period)", "yearSort": 1550, "era": "Renaissance & Early Modern", "medium": "Ink and color on paper handscroll (emakimono)", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Traditionally attributed to Tosa Mitsunobu", "repository": "Shinju-an Subtemple, Daitoku-ji, Kyoto (Important Cultural Property)", "commonsFile": "Hyakki-Yagyo-Emaki_Tsukumogami_1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Hyakki-Yagyo-Emaki_Tsukumogami_1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Hyakki-Yagyo-Emaki_Tsukumogami_1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3f/Hyakki-Yagyo-Emaki_Tsukumogami_1.jpg", "anatomy": ["discarded straw sandals, parasols, staffs, and robes sprouting arms and legs", "single glaring eyes and grinning mouths emerging from lacquered or woven surfaces", "processional postures parodying court and monastic parades"], "description": "Preserved at the Daitoku-ji subtemple of Shinju-an in Kyoto, this celebrated Muromachi handscroll is the foundational masterpiece of the Hyakki Yagyō ('Night Parade of One Hundred Demons') genre. Without explanatory text, a riotous nocturnal cavalcade of tsukumogami—household utensils, silk robes, parasols, and musical instruments that gained sentient spirits after a century of use—capers across the paper before fleeing the rising morning sun. Its inventive fusion of everyday material culture with monstrous limbs inspired centuries of Edo and modern yōkai imagery."}, {"id": "rn-06-gessner-unicorn", "title": "De Monocerote (The Unicorn), from Historiae Animalium", "creature": "Unicorn", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Monoceros / Einhorn", "civilization": "Swiss Renaissance Natural History", "region": "Renaissance & Early Modern Europe", "originLocation": "Zurich, Swiss Confederacy", "dateDisplay": "1551 CE", "yearSort": 1551, "era": "Renaissance & Early Modern", "medium": "Hand-colored woodcut in printed folio encyclopedia", "mediumCategory": "Manuscript & Print", "morphology": "Single-Horned & Sacred Beasts", "creator": "Conrad Gessner (printed by Christoph Froschauer)", "repository": "Zentralbibliothek Zürich (and major rare book collections)", "commonsFile": "Historiae_animalium_1551_De_Monocerote.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Historiae_animalium_1551_De_Monocerote.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Historiae_animalium_1551_De_Monocerote.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8f/Historiae_animalium_1551_De_Monocerote.jpg", "anatomy": ["long spiraled alicorn projecting from the brow", "equine body and flowing mane", "cloven hooves and tufted lion-like tail", "slender deer-like limbs"], "description": "Published in the inaugural quadruped volume of Conrad Gessner's foundational zoological encyclopedia Historiae Animalium, this woodcut codifies the Renaissance naturalist image of the Monoceros. Treating ancient testimonies by Ctesias and Pliny alongside contemporary apothecaries' narwhal-tusk specimens, Gessner sought empirical evidence for the unicorn's alexipharmic horn."}, {"id": "rn-06-cellini-perseus-medusa", "title": "Perseus with the Head of Medusa", "creature": "Gorgon Medusa", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Medusa", "civilization": "Italian Mannerism (Florence)", "region": "Renaissance & Early Modern Europe", "originLocation": "Florence, Grand Duchy of Tuscany", "dateDisplay": "1545–1554 CE", "yearSort": 1554, "era": "Renaissance & Early Modern", "medium": "Cast bronze sculpture on marble and bronze pedestal", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Benvenuto Cellini", "repository": "Loggia dei Lanzi, Piazza della Signoria, Florence", "commonsFile": "Perseus_Medusa_Cellini_Lanzi_Florence.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Perseus_Medusa_Cellini_Lanzi_Florence.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Perseus_Medusa_Cellini_Lanzi_Florence.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/72/Perseus_Medusa_Cellini_Lanzi_Florence.jpg", "anatomy": ["writhing crown of venomous serpents", "half-closed petrifying eyes", "severed neck spouting cast-bronze torrents of blood", "contorted female torso crushed underfoot"], "description": "Commissioned by Duke Cosimo I de' Medici to stand alongside Donatello's Judith and Michelangelo's David in the Piazza della Signoria, Benvenuto Cellini's monumental single-pour bronze celebrates Medici triumph through classical myth. Perseus hoists Medusa's snake-locked head high above her crumpled body, with solidified jets of bronze blood gushing dramatically from both neck stumps."}, {"id": "rn-06-gessner-sea-monk-bishop", "title": "The Sea Monk and Sea Bishop, from Historiae Animalium (Book IV)", "creature": "Sea Monk and Sea Bishop", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Monachus Marinus & Episcopus Marinus", "civilization": "Swiss Renaissance Natural History", "region": "Renaissance & Early Modern Europe", "originLocation": "Zurich, Swiss Confederacy", "dateDisplay": "1558 CE", "yearSort": 1558, "era": "Renaissance & Early Modern", "medium": "Hand-colored woodcut in printed folio encyclopedia", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Conrad Gessner (after Guillaume Rondelet)", "repository": "Zentralbibliothek Zürich (and major rare book collections)", "commonsFile": "Sea_monk_and_sea_bishop.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sea_monk_and_sea_bishop.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sea_monk_and_sea_bishop.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8d/Sea_monk_and_sea_bishop.jpg", "anatomy": ["tonsured human-like head and clerical cowl of scales", "mitre-shaped cranial crest on the Sea Bishop", "pectoral fins resembling ecclesiastical vestments", "scaly piscine lower body and bifurcated tail"], "description": "Included in Book IV of Conrad Gessner's Historiae Animalium on marine fauna (adapting Guillaume Rondelet's 1554 woodcuts), this double plate pairs the tonsured Sea Monk stranded in the Øresund around 1546 with the mitred Sea Bishop allegedly captured off Poland in 1531. Modern cetologists and ichthyologists link these 16th-century prodigies to misidentified angelsharks, giant squid, or mutilated rays interpreted through Reformation-era portent culture."}, {"id": "rn-06-bomarzo-orcus-mouth", "title": "Mouth of Orcus (Bocca dell'Inferno), Sacro Bosco", "creature": "Orcus (Underworld Ogre)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "L'Orco", "civilization": "Italian Mannerism (Lazio)", "region": "Renaissance & Early Modern Europe", "originLocation": "Bomarzo, Viterbo, Italy", "dateDisplay": "c. 1552–1580 CE", "yearSort": 1565, "era": "Renaissance & Early Modern", "medium": "In-situ carved peperino volcanic tuff boulder", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Pirro Ligorio and Simone Moschino (commissioned by Pier Francesco 'Vicino' Orsini)", "repository": "Parco dei Mostri (Sacred Grove of Bomarzo), Lazio", "commonsFile": "Bomarzo_parco_mostri_orco.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Bomarzo_parco_mostri_orco.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Bomarzo_parco_mostri_orco.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9b/Bomarzo_parco_mostri_orco.jpg", "anatomy": ["cavernous fanged portal mouth", "bulging stone eyes and flared nostrils", "carved epigrammatic lip inscription", "hollow interior banquet chamber"], "description": "Hewn directly out of a colossal outcrop of volcanic peperino stone in Prince Vicino Orsini's Mannerist 'Park of the Monsters' at Bomarzo, the giant head of Orcus turns the classical lord of the underworld into a walkable architectural threshold. Inscribed round its upper lip with the Dante-echoing phrase OGNI PENSIERO VOLA ('Every thought flies'), its roaring jaws open into a cool subterranean grotto fitted with a stone dining table."}, {"id": "rn-06-bomarzo-echidna", "title": "Echidna and the Lions, Sacro Bosco", "creature": "Echidna (Twin-Tailed Serpent-Woman)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Echidna", "civilization": "Italian Mannerism (Lazio)", "region": "Renaissance & Early Modern Europe", "originLocation": "Bomarzo, Viterbo, Italy", "dateDisplay": "c. 1552–1580 CE", "yearSort": 1568, "era": "Renaissance & Early Modern", "medium": "Carved peperino volcanic tuff", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Simone Moschino (commissioned by Pier Francesco 'Vicino' Orsini)", "repository": "Parco dei Mostri (Sacred Grove of Bomarzo), Lazio", "commonsFile": "Echidna_and_lions_-_Parco_dei_Mostri_-_Bomarzo,_Italy_-_DSC02630.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Echidna_and_lions_-_Parco_dei_Mostri_-_Bomarzo,_Italy_-_DSC02630.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Echidna_and_lions_-_Parco_dei_Mostri_-_Bomarzo,_Italy_-_DSC02630.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/b3/Echidna_and_lions_-_Parco_dei_Mostri_-_Bomarzo,_Italy_-_DSC02630.jpg", "anatomy": ["monumental female torso and outstretched arms", "bifurcated serpentine tails replacing legs", "coiled scaly extremities", "paired guardian lions and hybrid brood"], "description": "Facing a sculpted Fury across a terrace of Bomarzo's Sacred Grove, this massive volcanic-stone figure depicts Hesiod's mother of monsters, Echidna, rising on twin diverging serpent tails in the manner of a Mannerist Melusine. Flanked by crouching lions that recall her monstrous offspring—the Chimera, Sphinx, and Nemean Lion—the weathered tuff surface merges raw geological bedrock with mythic teratology."}, {"id": "sa-09-madurai-meenakshi-gajavyala", "title": "Rearing Gajavyala (Lion-Elephant Yali) Pillar in the Thousand-Pillar Hall", "creature": "Gajavyala (Elephant-Headed Yali)", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "Gajavyāla / Yāzhi", "civilization": "Madurai Nayak Dynasty (Tamil South India)", "region": "South & Southeast Asia", "originLocation": "Aayiram Kaal Mandapam (Thousand-Pillar Hall), Meenakshi Amman Temple, Madurai, Tamil Nadu, India", "dateDisplay": "c. 1569 CE", "yearSort": 1569, "era": "Renaissance & Early Modern", "medium": "Monolithic carved grey granite temple pillar", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Commissioned by Ariyanatha Mudaliar, prime minister of Viswanatha Nayak", "repository": "In situ, Meenakshi Amman Temple, Madurai, Tamil Nadu, India", "commonsFile": "Yali_pillar_in_the_Meenakshi_temple_at_Madurai.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Yali_pillar_in_the_Meenakshi_temple_at_Madurai.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Yali_pillar_in_the_Meenakshi_temple_at_Madurai.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/48/Yali_pillar_in_the_Meenakshi_temple_at_Madurai.jpg", "anatomy": ["lion's snarling face fused with a long curling elephantine trunk and tusks", "sinewy feline body rearing vertically on powerful hind claws", "scrolling foliate tail and lotus pedestal base"], "description": "Guarding the central aisle of the celebrated 985-column Aayiram Kaal Mandapam at Madurai's Meenakshi Amman Temple, this monolithic granite Gajavyala fuses the roaring head and agile torso of a lion with the curling proboscis and tusks of an elephant. Known in Tamil as Yazhi, such lion-elephant hybrids epitomize Nayak-period sculptural virtuosity, uniting the supreme predators and royal mounts of the Indian forest into an invincible guardian of the temple precinct."}, {"id": "sa-09-hamzanama-devs-chariot", "title": "Ibrahim Rides into Battle on a Chariot Drawn by Spotted Horned Devs (Hamzanama)", "creature": "Dev (Div)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Dīv / Dev", "civilization": "Mughal Empire", "region": "South & Southeast Asia", "originLocation": "Imperial Mughal Atelier, Fatehpur Sikri or Agra, India", "dateDisplay": "c. 1562–1577 CE (reign of Emperor Akbar)", "yearSort": 1570, "era": "Renaissance & Early Modern", "medium": "Opaque watercolor, ink, and gold on large-format cotton cloth", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Imperial Mughal workshop directed by Mir Sayyid Ali and Abd al-Samad", "repository": "Chester Beatty Library, Dublin (CBL In 01.2)", "commonsFile": "Hamza's_son_Ibrahim_rides_into_a_battle_on_a_demon-drawn_chariot_(CBL_In_01.2).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Hamza's_son_Ibrahim_rides_into_a_battle_on_a_demon-drawn_chariot_(CBL_In_01.2).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Hamza's_son_Ibrahim_rides_into_a_battle_on_a_demon-drawn_chariot_(CBL_In_01.2).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7c/Hamza's_son_Ibrahim_rides_into_a_battle_on_a_demon-drawn_chariot_(CBL_In_01.2).jpg", "anatomy": ["curved bovine-caprine horns and pointed animal ears", "spotted feline-like pelt in pink, orange, and slate hues", "fanged grimacing mouths, clawed feet, and short tails"], "description": "Painted on monumental cotton cloth for Emperor Akbar's fourteen-volume illustrated epic Hamzanama, this dynamic battle folio shows Amir Hamza's son Ibrahim charging across the fray in a wheeled war-chariot harnessed to subdued giant Devs. Synthesizing Persianate demonology with vivid Indian colorism and expressive energy, the Mughal artists rendered the supernatural Devs with leopard-spotted hides, curving horns, fanged grins, and gold-bell collars."}, {"id": "ne-01-safavid-rustam-dragon", "title": "Rustam and Rakhsh Slaying the Dragon (Third Labour)", "creature": "Azhdaha (Persian Fire-Breathing Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Aždahā (اژدها)", "civilization": "Safavid Persia", "region": "Ancient Near East & Persia", "originLocation": "Qazvin / Tabriz, Iran (Shahnameh of Shah Ismail II)", "dateDisplay": "c. 1576 CE", "yearSort": 1576, "era": "Renaissance & Early Modern", "medium": "Opaque watercolor, ink, silver, and gold on paper", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Attributed to Sadiqi Beg", "repository": "Aga Khan Museum, Toronto (AKM100)", "commonsFile": "Rustam_kills_the_dragon,_folio_from_Shahnameh_of_Shah_Ismail_II,_attrib._Sadegi_(Beg),_Iran,_Tabriz,_c._1576_AD,_view_2_-_Aga_Khan_Museum_-_Toronto,_Canada_-_DSC06939.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Rustam_kills_the_dragon,_folio_from_Shahnameh_of_Shah_Ismail_II,_attrib._Sadegi_(Beg),_Iran,_Tabriz,_c._1576_AD,_view_2_-_Aga_Khan_Museum_-_Toronto,_Canada_-_DSC06939.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Rustam_kills_the_dragon,_folio_from_Shahnameh_of_Shah_Ismail_II,_attrib._Sadegi_(Beg),_Iran,_Tabriz,_c._1576_AD,_view_2_-_Aga_Khan_Museum_-_Toronto,_Canada_-_DSC06939.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5d/Rustam_kills_the_dragon,_folio_from_Shahnameh_of_Shah_Ismail_II,_attrib._Sadegi_(Beg),_Iran,_Tabriz,_c._1576_AD,_view_2_-_Aga_Khan_Museum_-_Toronto,_Canada_-_DSC06939.jpg", "anatomy": ["Sinuous, scaled serpentine body with dorsal flame-spines", "Four clawed limbs and horned, fanged East-Asian-inflected dragon head", "Forked fiery breath opposed by Rustam's sword and the stallion Rakhsh's teeth"], "description": "Attributed to the celebrated Safavid court painter Sadiqi Beg for the dispersed Shahnameh of Shah Ismail II, this dynamic folio illustrates Rustam's Third Labour. As the faithful stallion Rakhsh sinks his teeth into the scaly hide of the coiling Azhdaha, Rustam drives his blade into the monster's jaws amidst jagged violet and turquoise rocks."}, {"id": "ne-01-safavid-zal-simurgh", "title": "Zal Returned to Sam by the Simurgh", "creature": "Simurgh (Benevolent Cosmic Phoenix of Mount Alborz)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Sīmorḡ (سیمرغ)", "civilization": "Safavid Persia", "region": "Ancient Near East & Persia", "originLocation": "Qazvin, Iran (Shahnameh of Shah Ismail II)", "dateDisplay": "1576–1577 CE", "yearSort": 1577, "era": "Renaissance & Early Modern", "medium": "Opaque watercolor, ink, and gold on paper", "mediumCategory": "Manuscript & Print", "morphology": "Avian & Winged Hybrids", "creator": "Attributed to Sadiqi Beg", "repository": "Reza Abbasi Museum, Tehran", "commonsFile": "Zal_returned_to_Sam_by_the_Simurgh.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Zal_returned_to_Sam_by_the_Simurgh.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Zal_returned_to_Sam_by_the_Simurgh.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/78/Zal_returned_to_Sam_by_the_Simurgh.jpg", "anatomy": ["Flaming crest and jewel-toned crimson, turquoise, and gold wing plumage", "Streaming ribbon-like tail feathers adapted from Ming feng-huang motifs", "Powerful talons gently bearing the white-haired youth Zal from Mount Alborz"], "description": "Abandoned in infancy on the crags of Mount Alborz because of his shock of white hair, the legendary hero Zal was raised in the eyrie of the wise, primordial Simurgh alongside her chicks. In this glittering Safavid folio from the Shahnameh of Shah Ismail II, the resplendent multicolored bird sweeps down through golden skies to restore the grown youth to his repentant father Sam, leaving Zal a single magic feather to burn in times of peril."}, {"id": "sa-09-basawan-mughal-simurgh", "title": "The Flight of the Simurgh Over a Mountainous Wilderness", "creature": "Simurgh", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Sīmurgh ('Anqā)", "civilization": "Mughal Empire", "region": "South & Southeast Asia", "originLocation": "Lahore, Mughal Empire (modern Pakistan)", "dateDisplay": "c. 1590 CE", "yearSort": 1590, "era": "Renaissance & Early Modern", "medium": "Opaque watercolor and gold on paper", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "Attributed to Basawan", "repository": "Aga Khan Museum, Toronto (AKM128, formerly Sadruddin Aga Khan Collection)", "commonsFile": "Basawan._The_Flight_of_the_Simurgh._ca._1590,_Sadruddin_Aga_Khan_Collection.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Basawan._The_Flight_of_the_Simurgh._ca._1590,_Sadruddin_Aga_Khan_Collection.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Basawan._The_Flight_of_the_Simurgh._ca._1590,_Sadruddin_Aga_Khan_Collection.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/28/Basawan._The_Flight_of_the_Simurgh._ca._1590,_Sadruddin_Aga_Khan_Collection.jpg", "anatomy": ["colossal predatory bird head with powerful hooked beak", "variegated wings of immense span scattering startled beasts below", "streaming iridescent tail-plumes trailing across craggy peaks"], "description": "Attributed to Emperor Akbar's master painter Basawan, this dramatic miniature captures a gigantic Simurgh swooping over a turbulent landscape where terrified elephants, rhinoceroses, lions, and a mounted hero scatter in awe. Transforming the graceful ribbon-tailed phoenix of Timurid and Safavid painting into a viscerally plausible, awe-inspiring avian titan capable of carrying off elephants in Indo-Persian lore, Basawan merges Mughal naturalism with mythic grandeur."}, {"id": "rn-06-caravaggio-medusa", "title": "Medusa (Tournament Parade Shield)", "creature": "Gorgon Medusa", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Medusa", "civilization": "Italian Baroque", "region": "Renaissance & Early Modern Europe", "originLocation": "Rome, Papal States (gifted to Ferdinando I de' Medici in Florence)", "dateDisplay": "c. 1597 CE", "yearSort": 1597, "era": "Renaissance & Early Modern", "medium": "Oil on linen canvas mounted over a convex poplar tournament shield (rotella)", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Michelangelo Merisi da Caravaggio", "repository": "Uffizi Gallery, Florence", "commonsFile": "Caravaggio_-_Medusa_-_Google_Art_Project.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Caravaggio_-_Medusa_-_Google_Art_Project.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Caravaggio_-_Medusa_-_Google_Art_Project.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/15/Caravaggio_-_Medusa_-_Google_Art_Project.jpg", "anatomy": ["tangled nest of live vipers for hair", "wide horror-struck eyes and furrowed brow", "gaping screaming mouth", "freshly severed neck streaming dark arterial blood"], "description": "Commissioned by Cardinal Francesco Maria del Monte as a diplomatic gift for Grand Duke Ferdinando I de' Medici's armory, Caravaggio painted this illusionistic Gorgon head onto a convex wooden parade shield to evoke Athena's own aegis. Using a mirror to model Medusa's agonized scream on his own features, Caravaggio captures the split-second of conscious horror as the decapitated head witnesses its own death amid knotted, hissing adders."}, {"id": "cn-07-shanhaijing-bingyi-hebo", "title": "River God Bingyi (Hebo) Riding Twin Dragons (Shan Hai Jing)", "creature": "Bingyi / Hebo & Twin River-Dragons", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "《山海經》冰夷乘兩龍 (Bīngyí)", "civilization": "Ming Dynasty (Wanli Reign)", "region": "East Asia & Eurasian Steppe", "originLocation": "Jianyang / Jiangnan publishing centers, China", "dateDisplay": "1597 CE", "yearSort": 1597, "era": "Renaissance & Early Modern", "medium": "Woodblock print, ink on paper", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Jiang Yinghao (蔣應鎬, illustrator)", "repository": "Rare Book Editions of the 1597 Illustrated Shan Hai Jing", "commonsFile": "Classic_of_Mountains_and_Seas,_1597,_plate_LXI.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Classic_of_Mountains_and_Seas,_1597,_plate_LXI.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Classic_of_Mountains_and_Seas,_1597,_plate_LXI.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/bb/Classic_of_Mountains_and_Seas,_1597,_plate_LXI.jpg", "anatomy": ["anthropomorphic river spirit astride twin dragons", "horned scaled aquatic serpents", "cresting abyssal river waves", "cloud-and-mist eddies"], "description": "Engraved for the landmark 1597 Wanli woodblock edition of the Classic of Mountains and Seas (Shan Hai Jing), Plate LXI depicts Bingyi—the abyssal lord of the Yellow River depths—gliding across turbulent waters astride a pair of harnessed horned dragons. According to the 'Guideways Within the Seas: North,' Bingyi dwells beneath the icy abysses (yuan) and commands the flood-dragons of China's inland seas."}, {"id": "eg-02-benin-royal-leopard", "title": "Royal Benin Court Brass Leopard Aquamanile (Ekpen)", "creature": "Ekpen (Supernatural King of the Forest and Alter Ego of the Oba)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Ekpen ('Leopard of the Bush' / Counterpart to Ekpen n'Owa)", "civilization": "Kingdom of Benin (Edo Tradition)", "region": "Egypt & Africa", "originLocation": "Royal Palace, Benin City (Edo State, southern Nigeria)", "dateDisplay": "Mid-16th–17th century CE", "yearSort": 1600, "era": "Renaissance & Early Modern", "medium": "Lost-wax cast brass with punched ring-dot pelt engraving", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Single-Horned & Sacred Beasts", "creator": "Royal Guild of Brass Casters (Igun Eronmwon), Benin City", "repository": "Metropolitan Museum of Art, New York (1978.412.321)", "commonsFile": "Figure-_Leopard_MET_DT9712.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Figure-_Leopard_MET_DT9712.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Figure-_Leopard_MET_DT9712.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/de/Figure-_Leopard_MET_DT9712.jpg", "anatomy": ["taut, tubular feline torso covered in stippled double-circle spots", "upright leaf-shaped ears and bared interlocking fangs", "hinged cranial lid and nostril spout for pouring consecrated water", "arching tail curved rigidly forward over the spine"], "description": "Used during royal Igue purification rites to pour consecrated water over the Oba's hands at ancestral palace altars, this cast-brass aquamanile embodies the supernatural bush leopard (Ekpen), ordained by the creator Osanobua as sovereign of the wild forest just as the Oba ('Leopard of the Home') rules humankind. Its stylized vertical ears, geometric double-ring rosettes, and bared fangs visualize the terrifying occult authority (ase) by which the divine king strikes swiftly and without error."}, {"id": "jk-08-edo-shachihoko-nagoya", "title": "Golden Shachihoko Roof Finial of Nagoya Castle", "creature": "Shachihoko (Tiger-Headed Carp Guardian)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "金鯱 (しゃちほこ)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Nagoya Castle Main Keep, Owari Province (Nagoya), Japan", "dateDisplay": "1612 CE (Keichō 17; pre-1945 archival photograph of original finial)", "yearSort": 1612, "era": "Renaissance & Early Modern", "medium": "Cypress wood core plated in hammered gold scales over copper-lead", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Marine & Abyssal Monsters", "creator": "Commissioned by Tokugawa Ieyasu", "repository": "Formerly Nagoya Castle Tenshu (original destroyed in 1945 air raid)", "commonsFile": "Old_Nagoya_Castle_Golden_Shachi-Hoko_Statue.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Old_Nagoya_Castle_Golden_Shachi-Hoko_Statue.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Old_Nagoya_Castle_Golden_Shachi-Hoko_Statue.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4c/Old_Nagoya_Castle_Golden_Shachi-Hoko_Statue.jpg", "anatomy": ["ferocious roaring tiger head with upturned fangs", "overlapping gold-plated carp scales", "vertical tail fin arched skyward to summon rain"], "description": "Installed atop the main keep of Nagoya Castle in 1612 by order of shogun Tokugawa Ieyasu, this monumental 2.6-meter Kinshachi ('golden shachihoko') combined the head of a roaring tiger with the gleaming scaled body and skyward-flung tail of a carp. In Japanese castle architecture, the amphibious Shachihoko was believed to swallow vast quantities of water and spout rain clouds if fire broke out below, doubling as an apotropaic talisman and a dazzling emblem of Tokugawa wealth. This archival pre-1945 photograph records the original Edo-period sculpture encased in its historic anti-theft wire mesh prior to its wartime loss."}, {"id": "rn-06-rubens-snyders-medusa", "title": "Head of Medusa", "creature": "Gorgon Medusa and Spawned Vipers", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Haupt der Medusa", "civilization": "Flemish Baroque", "region": "Renaissance & Early Modern Europe", "originLocation": "Antwerp, Spanish Netherlands", "dateDisplay": "c. 1617–1618 CE", "yearSort": 1618, "era": "Renaissance & Early Modern", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Peter Paul Rubens and Frans Snyders", "repository": "Kunsthistorisches Museum, Vienna", "commonsFile": "Rubens_Medusa.jpeg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Rubens_Medusa.jpeg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Rubens_Medusa.jpeg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6b/Rubens_Medusa.jpeg", "anatomy": ["livid corpse-pale human visage with glassy eyes", "swarming mass of adders and two-headed amphisbaena", "blood droplets generating newborn snakes", "scorpions, salamanders, and spiders"], "description": "A celebrated Baroque collaboration between Peter Paul Rubens and animalier specialist Frans Snyders, this canvas places Medusa's freshly severed, ash-white head upon a rocky ledge crawling with venomous reptiles and arachnids. Following Ovid's Metamorphoses, drops of Gorgon blood spontaneously spawn tiny vipers—including a two-headed amphisbaena—producing a dazzling Kunstkammer display of horror and zoological precision."}, {"id": "cn-07-shanhaijing-xingtian", "title": "The Headless Warrior Xingtian (Shan Hai Jing)", "creature": "Xingtian (Headless Defiant Giant)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "《山海經》刑天 (Xíngtiān)", "civilization": "Ming Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "China", "dateDisplay": "Late 16th – early 17th century CE", "yearSort": 1620, "era": "Renaissance & Early Modern", "medium": "Woodblock print, ink on paper", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Jiang Yinghao (蔣應鎬, illustrator)", "repository": "Illustrated Classic of Mountains and Seas (Haiwai Xijing)", "commonsFile": "Jiang_Yinghao_-_Xingtian.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Jiang_Yinghao_-_Xingtian.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Jiang_Yinghao_-_Xingtian.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c2/Jiang_Yinghao_-_Xingtian.jpg", "anatomy": ["severed neck with no cranium", "twin eyes formed from chest nipples", "grinning mouth formed at the navel", "brandished battle-axe (qi) and rectangular shield (gan)"], "description": "Illustrating the 'Classic of Regions Beyond the Seas: West' in the Shan Hai Jing, Jiang Yinghao's late Ming woodcut portrays Xingtian after the Supreme Deity severed his head in cosmic battle and buried it beneath Mount Changyang. Refusing defeat, the indomitable giant transformed his nipples into staring eyes and his navel into a roaring mouth, dancing eternally with battle-axe and shield."}, {"id": "jk-08-edo-sotatsu-fujin-raijin", "title": "Wind God and Thunder God Screens (Fūjin Raijin-zu)", "creature": "Fūjin and Raijin (Elemental Demon-Kami of Wind and Thunder)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "風神・雷神 (風神雷神図屏風)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Kyoto, Japan", "dateDisplay": "Early 17th century CE", "yearSort": 1630, "era": "Renaissance & Early Modern", "medium": "Ink, mineral pigments, and silver on gold-foiled paper; pair of two-panel folding screens (byōbu)", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Tawaraya Sōtatsu", "repository": "Kennin-ji, Kyoto (entrusted to Kyoto National Museum; National Treasure of Japan)", "commonsFile": "Wind-God-Fujin-and-Thunder-God-Raijin-by-Tawaraya-Sotatsu.png", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Wind-God-Fujin-and-Thunder-God-Raijin-by-Tawaraya-Sotatsu.png", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Wind-God-Fujin-and-Thunder-God-Raijin-by-Tawaraya-Sotatsu.png?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/af/Wind-God-Fujin-and-Thunder-God-Raijin-by-Tawaraya-Sotatsu.png", "anatomy": ["horned oni-like visages in emerald green (Fūjin) and chalk white (Raijin)", "two-clawed feet braced upon swirling dark storm clouds", "billowing wind-bag and circular halo of taiko thunder drums"], "description": "Hovering at the upper corners of an expansive ground of gleaming gold leaf, Tawaraya Sōtatsu's Fūjin and Raijin distill Japan's storm kami into exuberant, Oni-bodied elemental forces. On the right screen, green-skinned Fūjin hurtles into view clutching an inflated cloth sack of gale winds, while on the left, white-skinned Raijin balances amid dark tarashikomi ink clouds inside a ring of thunder drums. As the founding masterpiece of the Rinpa school, Sōtatsu's composition transformed fearsome tempest demons into vital, playful presences of nature."}, {"id": "cn-07-shanhaijing-jiuweihu", "title": "The Nine-Tailed Fox of Mount Qingqiu (Shan Hai Jing)", "creature": "Jiuweihu (Nine-Tailed Fox)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "《山海經》九尾狐 (Jiǔwěihú)", "civilization": "Ming Dynasty (Chongzhen Reign)", "region": "East Asia & Eurasian Steppe", "originLocation": "China", "dateDisplay": "1628–1644 CE", "yearSort": 1635, "era": "Renaissance & Early Modern", "medium": "Woodblock print, ink on mulberry paper", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Jiang Yinghao (蔣應鎬, illustrator) & Li Wenxiao (李文孝, engraver)", "repository": "Harvard-Yenching Library (Chongzhen Edition of Shan Hai Jing)", "commonsFile": "Shahaijing-chongzhen(1628–1644)-nanshanjing1-fol5b-ninetailfox.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Shahaijing-chongzhen(1628%E2%80%931644)-nanshanjing1-fol5b-ninetailfox.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Shahaijing-chongzhen(1628%E2%80%931644)-nanshanjing1-fol5b-ninetailfox.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/ba/Shahaijing-chongzhen(1628%E2%80%931644)-nanshanjing1-fol5b-ninetailfox.jpg", "anatomy": ["fan of nine bushy fox tails", "pointed vulpine snout and pricked ears", "lithe quadrupedal body", "mountainous Qingqiu landscape setting"], "description": "Cut by engraver Li Wenxiao after drawings by Jiang Yinghao for the Chongzhen-era Shan Hai Jing, this folio from the 'Classic of the Southern Mountains' depicts the nine-tailed fox of Mount Qingqiu, whose cry sounds like a human infant. Ambivalent in early Chinese lore—both a man-devouring mountain beast whose flesh wards off gu-poison and an auspicious marital omen before later becoming a shapeshifting trickster—the jiuweihu inspired fox traditions across East Asia."}, {"id": "rn-06-aldrovandi-harpy", "title": "Harpia (The Harpy), from Monstrorum Historia", "creature": "Harpy", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Harpia / Arpia", "civilization": "Italian Baroque Natural History", "region": "Renaissance & Early Modern Europe", "originLocation": "Bologna, Papal States", "dateDisplay": "1642 CE", "yearSort": 1642, "era": "Renaissance & Early Modern", "medium": "Full-page woodcut in printed folio treatise", "mediumCategory": "Manuscript & Print", "morphology": "Avian & Winged Hybrids", "creator": "Ulisse Aldrovandi (edited by Bartolomeo Ambrosini; woodcut by Giovanni Battista Coriolano)", "repository": "University of Bologna / History of Science Collections, University of Oklahoma", "commonsFile": "Aldrovandi-0337.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Aldrovandi-0337.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Aldrovandi-0337.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/12/Aldrovandi-0337.jpg", "anatomy": ["human face framed by feathered ear-tufts", "plumed raptor wings and scaly avian breast", "powerful raptorial talons", "barred tail feathers"], "description": "Published posthumously in Bologna in Ulisse Aldrovandi's encyclopedic Monstrorum Historia (1642), this crisp woodcut by Giovanni Battista Coriolano synthesizes classical myth with early modern cabinet-of-curiosities taxonomy. Standing in profile like an ornithological specimen, the Harpy combines a solemn human countenance and braided ear-tufts with the barred plumage and hooked talons of a bird of prey."}, {"id": "rn-06-bernini-bust-of-medusa", "title": "Bust of Medusa", "creature": "Gorgon Medusa", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Medusa", "civilization": "Italian High Baroque", "region": "Renaissance & Early Modern Europe", "originLocation": "Rome, Papal States", "dateDisplay": "c. 1638–1648 CE", "yearSort": 1644, "era": "Renaissance & Early Modern", "medium": "Carved Carrara marble", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Gian Lorenzo Bernini", "repository": "Capitoline Museums (Palazzo dei Conservatori), Rome", "commonsFile": "Medusa_Bernini_Musei_Capitolini.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Medusa_Bernini_Musei_Capitolini.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Medusa_Bernini_Musei_Capitolini.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ef/Medusa_Bernini_Musei_Capitolini.jpg", "anatomy": ["heavy coiling marble serpents crowning the head", "anguished knitted brow and parted lips", "living portrait bust rather than severed trophy", "deeply undercut chiaroscuro locks"], "description": "Unlike Cellini's and Caravaggio's decapitated trophies, Gian Lorenzo Bernini conceives Medusa as a living, breathing portrait bust caught in the tragic instant of her own metamorphosis into stone. Deep drillwork separates the heavy, muscular snakes writhing above her anguished brow, turning a witty Baroque conceit—a marble sculpture of the monster who petrifies viewers—into an intimate study of spiritual torment."}, {"id": "sa-09-vietnam-nghe-guardian", "title": "Carved Wooden Nghê Sacred Lion-Dog Guardian of Lâu Thượng Communal House", "creature": "Nghê", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "Con Nghê", "civilization": "Restored Lê Dynasty (Vietnam)", "region": "South & Southeast Asia", "originLocation": "Lâu Thượng Communal House (Đình), Việt Trì, Phú Thọ Province, Vietnam", "dateDisplay": "17th century CE", "yearSort": 1650, "era": "Renaissance & Early Modern", "medium": "Carved and lacquered jackfruit/hardwood architectural sculpture", "mediumCategory": "Sculpture & Relief", "morphology": "Single-Horned & Sacred Beasts", "creator": "Unknown Red River Delta village master woodcarver", "repository": "Vietnam National Museum of Fine Arts, Hanoi", "commonsFile": "Legendary_lion_(Nghe),_Lau_Thuong_Communale_house,_Phu_Tho_province,_17th_century_AD,_wood_-_Vietnam_National_Museum_of_Fine_Arts_-_Hanoi,_Vietnam_-_DSC04934.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Legendary_lion_(Nghe),_Lau_Thuong_Communale_house,_Phu_Tho_province,_17th_century_AD,_wood_-_Vietnam_National_Museum_of_Fine_Arts_-_Hanoi,_Vietnam_-_DSC04934.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Legendary_lion_(Nghe),_Lau_Thuong_Communale_house,_Phu_Tho_province,_17th_century_AD,_wood_-_Vietnam_National_Museum_of_Fine_Arts_-_Hanoi,_Vietnam_-_DSC04934.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c3/Legendary_lion_(Nghe),_Lau_Thuong_Communale_house,_Phu_Tho_province,_17th_century_AD,_wood_-_Vietnam_National_Museum_of_Fine_Arts_-_Hanoi,_Vietnam_-_DSC04934.JPG", "anatomy": ["spirited canine torso combined with a leonine-draconic head", "wide grinning fanged mouth, bulging eyes, and flame-curled mane", "sinewy clawed paws and bushy upturned tail"], "description": "Originally perched among the timber rafters of Lâu Thượng village communal house (đình) in Phú Thọ province, this expressive 17th-century wooden Nghê embodies Vietnam's distinctively indigenous guardian beast. Blending the loyal domestic village dog with the auspicious attributes of the celestial lion and dragon-qilin (Kỳ Lân), the Nghê scrutinizes visitors' hearts at temples, shrines, and communal halls to dispel deceit and malevolent spirits."}, {"id": "am-10-rapa-nui-tangata-manu-orongo", "title": "Orongo Basalt Petroglyphs of the Tangata Manu (Birdman)", "creature": "Tangata Manu (Human-Frigatebird Hybrid)", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Tangata Manu", "civilization": "Rapa Nui", "region": "The Americas & Oceania", "originLocation": "Mata Ngarau, Orongo Ceremonial Village, Rano Kau, Rapa Nui (Easter Island)", "dateDisplay": "c. 1500–1860 CE", "yearSort": 1650, "era": "Renaissance & Early Modern", "medium": "Bas-relief pecked and abraded volcanic basalt", "mediumCategory": "Sculpture & Relief", "morphology": "Therianthropic (Human-Beast)", "creator": "Unknown Rapa Nui rongorongo / ritual carvers", "repository": "Rapa Nui National Park, Chile (in situ)", "commonsFile": "PETROGLYPHS_ON_THE_ROCKS_NEAR_ORONGO_VILLAGE_-_EASTER_ISLAND.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:PETROGLYPHS_ON_THE_ROCKS_NEAR_ORONGO_VILLAGE_-_EASTER_ISLAND.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/PETROGLYPHS_ON_THE_ROCKS_NEAR_ORONGO_VILLAGE_-_EASTER_ISLAND.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/a/a5/PETROGLYPHS_ON_THE_ROCKS_NEAR_ORONGO_VILLAGE_-_EASTER_ISLAND.jpg", "anatomy": ["long hooked beak and gular throat pouch of the great frigatebird (makohe)", "crouched anthropomorphic torso with arched spine and flexed knees", "humanoid hand often cradling the sacred first sooty-tern egg (manutara)"], "description": "Carved in dense clusters across the sea-cliff basalt boulders of Mata Ngarau on the rim of Rano Kau volcano, hundreds of bas-relief Tangata Manu figures commemorate victors of Rapa Nui's annual Birdman competition in honor of the creator god Make-Make. Blending a crouched human athlete's body with the hooked bill of a frigatebird, each relief immortalized the sacred ruler whose swimmer retrieved the season's first manutara egg from the offshore islet of Motu Nui."}, {"id": "eg-02-benin-oba-mudfish-legs", "title": "Royal Benin Cast Brass Figure of the Divine Oba with Mudfish Legs", "creature": "Ichthyomorphic Mudfish-Legged Oba (Avatar of Olokun)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Oba / Olokun-Ehen (Sacred Mudfish Transformation)", "civilization": "Kingdom of Benin (Edo Tradition)", "region": "Egypt & Africa", "originLocation": "Royal Palace, Benin City (Edo State, southern Nigeria)", "dateDisplay": "c. 16th–18th century CE", "yearSort": 1650, "era": "Renaissance & Early Modern", "medium": "Lost-wax (cire perdue) cast copper alloy (brass)", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Marine & Abyssal Monsters", "creator": "Royal Guild of Brass Casters (Igun Eronmwon), Benin City", "repository": "Brooklyn Museum, New York (56.6.72)", "commonsFile": "Brooklyn_Museum_56.6.72_Human_Figure_with_Mudfish_legs.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_56.6.72_Human_Figure_with_Mudfish_legs.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Brooklyn_Museum_56.6.72_Human_Figure_with_Mudfish_legs.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c4/Brooklyn_Museum_56.6.72_Human_Figure_with_Mudfish_legs.jpg", "anatomy": ["regal human torso wearing coral-bead collar (odigba) and netted tunic", "twin undulating, whiskered mudfish (Clarias) replacing the ruler's legs", "amphibious gill plates and segmented caudal fins curving outward"], "description": "Cast by the hereditary royal brass-casters' guild of Benin City, this sacred figure portrays the divine Edo monarch (Oba) with his lower limbs transformed into living, undulating West African mudfish—creatures revered for surviving both underwater and across dry riverbeds. The hybrid iconography commemorates the mythical fourteenth-century Oba Ohen and proclaims the king's liminal sovereignty over both the terrestrial realm and the fathomless oceanic palace of Olokun, god of wealth and primordial waters."}, {"id": "cn-07-shanhaijing-yinglong", "title": "The Winged Rain-Dragon Yinglong (Shan Hai Jing)", "creature": "Yinglong (Winged Responsive Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "《山海經》應龍 (Yìnglóng)", "civilization": "Late Ming / Early Qing Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "China", "dateDisplay": "17th century CE", "yearSort": 1650, "era": "Renaissance & Early Modern", "medium": "Woodblock print, ink on paper", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Unknown Ming-Qing woodblock illustrator", "repository": "Early Modern Woodblock Edition of the Shan Hai Jing", "commonsFile": "Shan_Hai_Jing_Yinglong.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Shan_Hai_Jing_Yinglong.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Shan_Hai_Jing_Yinglong.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6f/Shan_Hai_Jing_Yinglong.jpg", "anatomy": ["broad feathered wings sprouting from the shoulders", "coiled scaled serpentine body", "horned draconic head with whiskers", "four clawed limbs"], "description": "Unlike standard Chinese dragons that soar effortlessly through clouds without wings, Yinglong ('Responsive Dragon') is distinguished in classical woodblock editions of the Shan Hai Jing by a pair of sweeping feathered wings. Celebrated in myth as the martial rain-dragon who slew the rebels Chiyou and Kuafu for the Yellow Emperor and later carved river channels across China with his tail for Yu the Great, Yinglong commands both stormwaters and deluge."}, {"id": "jk-08-joseon-unryong-jar", "title": "White Porcelain Dragon Jar (Unryongmun Ho)", "creature": "Yong (Korean Cloud Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "운룡문 백자 항아리 (용)", "civilization": "Joseon Dynasty (Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Bunwon official kilns, Gwangju, Gyeonggi, Korea", "dateDisplay": "17th century CE", "yearSort": 1650, "era": "Renaissance & Early Modern", "medium": "White porcelain painted in underglaze iron-brown oxide", "mediumCategory": "Ceramics & Vessels", "morphology": "Draconic & Serpentine", "creator": "Unknown Joseon court potter", "repository": "National Museum of Korea, Seoul (Dongwon Collection)", "commonsFile": "Jar_with_clouds_and_dragon.Joseon,_17th._c.Dongwon_Collection._National_Museum_of_Korea.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Jar_with_clouds_and_dragon.Joseon,_17th._c.Dongwon_Collection._National_Museum_of_Korea.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Jar_with_clouds_and_dragon.Joseon,_17th._c.Dongwon_Collection._National_Museum_of_Korea.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/95/Jar_with_clouds_and_dragon.Joseon,_17th._c.Dongwon_Collection._National_Museum_of_Korea.jpg", "anatomy": ["whiskered snout and branching antlers", "undulating serpentine body swept in bold iron-oxide brushstrokes", "clawed limbs striding across stylized cloud scrolls"], "description": "When Hideyoshi's late-sixteenth-century invasions disrupted Joseon's imports of cobalt pigment for blue-and-white court wares, royal potters turned to native iron-oxide slip to paint auspicious dragons across milky baekja porcelain jars. Executed with swift, calligraphic freedom around the vessel's swelling shoulder, this Korean Yong darts through scrolling clouds with wind-blown mane and comic vitality rather than rigid imperial menace. Used at court banquets to hold wine or flowers, dragon jars invoked sovereign authority alongside life-giving rain for agriculture."}, {"id": "am-10-agawa-mishipeshu-pictograph", "title": "Agawa Rock Cliff Pictograph of Mishipeshu (The Great Lynx)", "creature": "Mishipeshu (Underwater Lynx)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Mishibizhiw", "civilization": "Anishinaabe (Ojibwe)", "region": "The Americas & Oceania", "originLocation": "Agawa Rock, Lake Superior, Ontario, Canada", "dateDisplay": "c. 1650–1800 CE", "yearSort": 1660, "era": "Renaissance & Early Modern", "medium": "Red iron-oxide ochre mixed with fish-oil binder on sheer granite cliff face", "mediumCategory": "Painting & Fresco", "morphology": "Marine & Abyssal Monsters", "creator": "Attributed in Anishinaabe oral history to the warrior-leader Myeengun", "repository": "Lake Superior Provincial Park, Ontario, Canada (in situ)", "commonsFile": "Stone_canvas_1.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Stone_canvas_1.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Stone_canvas_1.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/49/Stone_canvas_1.JPG", "anatomy": ["twin curved horns crowning a feline head", "sawtooth ridge of dragon-like spines along back and tail", "flanking giant horned water-serpents below an Ojibwe canoe flotilla"], "description": "Painted in red ochre on a sheer granite ledge just above the crashing waves of eastern Lake Superior, the Agawa Rock panel is the most celebrated surviving depiction of Mishibizhiw, the Great Underwater Lynx of Algonquian and Anishinaabe tradition. Guarding Lake Superior's submerged copper deposits and capable of whipping calm waters into sudden tempests with its spiny tail, the horned feline spirit accompanies twin giant serpents and canoes commemorating a perilous cross-lake expedition led by the shaman-chief Myeengun."}, {"id": "eg-02-axum-giyorgis-dragon", "title": "Gondarine Illuminated Vellum Folio: Saint George (Qeddus Giyorgis) Slaying the Dragon", "creature": "Deragon / Arwe (Ethiopian Man-Eating Serpent-Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "ደራጎን / አርዌ (Deragon / Arwe)", "civilization": "Ethiopian Empire (Gondarine Period)", "region": "Egypt & Africa", "originLocation": "Northern Ethiopian Highlands (preserved in Axum, Tigray)", "dateDisplay": "Late 17th–early 18th century CE", "yearSort": 1700, "era": "Renaissance & Early Modern", "medium": "Mineral and organic tempera pigments on prepared goat-skin vellum (branna)", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Ethiopian Orthodox monastic scribe-illuminator", "repository": "Treasury of the Church of Our Lady Mary of Zion, Axum, Ethiopia", "commonsFile": "Ethiopian_St._George_And_The_Dragon_-_Detail_(2848032429).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ethiopian_St._George_And_The_Dragon_-_Detail_(2848032429).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ethiopian_St._George_And_The_Dragon_-_Detail_(2848032429).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/45/Ethiopian_St._George_And_The_Dragon_-_Detail_(2848032429).jpg", "anatomy": ["striated green-and-ochre serpentine body knotted at the bottom margin", "wolf-like fanged snout and horned crest", "spear-pierced jaws beneath the maiden Birhanawit sheltering in a tree"], "description": "Painted in radiant vermilion, orpiment yellow, and malachite green on heavy parchment during Ethiopia's Second Gondarine style, this manuscript miniature celebrates Qeddus Giyorgis—patron warrior-saint of Ethiopia—rescuing the maiden Birhanawit perched high in a sycamore tree. In Ethiopian highland tradition, the defeated dragon resonates directly with indigenous legends of Wainaba / Arwe, the primordial tribute-demanding python king overthrown at Axum's dawn."}, {"id": "sa-09-nepal-kirtimukha-tympanum", "title": "Newar Repoussé Gilt-Copper Kirtimukha (Chepu) Temple Tympanum", "creature": "Chepu (Nepalese Kirtimukha)", "creatureFamily": "Gorgons, Taotie, Kirtimukha & Apotropaic Faces", "localName": "Chepu / Kīrtimukha", "civilization": "Malla / Early Shah Period (Kathmandu Valley, Nepal)", "region": "South & Southeast Asia", "originLocation": "Kathmandu Valley, Nepal", "dateDisplay": "17th–18th century CE", "yearSort": 1700, "era": "Renaissance & Early Modern", "medium": "Gilt-copper repoussé torana crown relief", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Composite Chimeras", "creator": "Newar Shakya or Tamrakar metalwork artisan", "repository": "Temple portal, Kathmandu Valley, Nepal", "commonsFile": "Kirtimukha.Nepal1.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kirtimukha.Nepal1.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kirtimukha.Nepal1.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/eb/Kirtimukha.Nepal1.JPG", "anatomy": ["fierce horned grotesque face with three glaring eyes", "clawed hands gripping writhing Nāga serpents at the corners of the jaws", "flaming aureole crowning a semicircular repoussé torana"], "description": "Hammered in high-relief gilt copper by Newar metalworkers of the Kathmandu Valley, this apex tympanum figure—known locally as Chepu and derived from the pan-Indic Kirtimukha—crowns a sacred temple torana while biting and clutching writhing Nāgas in its clawed hands. In Newar Hindu and Vajrayana Buddhist legend, Chepu is the celestial elder brother of Garuda, immortalized above every sanctum doorway as the supreme guardian of truth and fearlessness."}, {"id": "eg-02-san-game-pass-therianthrope", "title": "San Rock Shelter Painting of an Antelope-Hoofed Therianthrope and Dying Eland ('The Rosetta Stone Panel')", "creature": "San Trance Therianthrope (Antelope-Human Spirit Being)", "creatureFamily": "Minotaur, Were-Jaguars & Therianthropes", "localName": "!Gi:xa / Therianthrope imbued with n/om potency", "civilization": "San (Bushman) Hunter-Gatherer Tradition", "region": "Egypt & Africa", "originLocation": "Game Pass Shelter, Kamberg Nature Reserve, KwaZulu-Natal Drakensberg, South Africa", "dateDisplay": "Pre-colonial era, c. 1600–1800 CE", "yearSort": 1700, "era": "Renaissance & Early Modern", "medium": "Red/yellow iron-oxide ochre, white clay, charcoal, and eland blood binder on sandstone rock face", "mediumCategory": "Painting & Fresco", "morphology": "Therianthropic (Human-Beast)", "creator": "San shaman-artist (!gi:xa)", "repository": "In situ, Game Pass Shelter, uKhahlamba-Drakensberg Park, South Africa", "commonsFile": "Shaman_at_work_Game_Pass_2004_0522_121946AA.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Shaman_at_work_Game_Pass_2004_0522_121946AA.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Shaman_at_work_Game_Pass_2004_0522_121946AA.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/88/Shaman_at_work_Game_Pass_2004_0522_121946AA.jpg", "anatomy": ["elongated human torso wearing a kaross cloak and sprouting bristling trance hairs", "cloven antelope hooves and eared eland head replacing human extremities", "crossed-leg posture mirroring the stumbling, sweat-trembling sacred eland whose tail it grasps"], "description": "Celebrated by archaeologist David Lewis-Williams as the 'Rosetta Stone' of southern African rock art, this polychrome sandstone panel at Game Pass Shelter depicts a San medicine person physically metamorphosing into an antelope-hoofed, eared therianthrope while clutching the tail of a stumbling eland. Painted with ochre mixed with eland blood—itself a reservoir of supernatural potency (n/om)—the scene records the visionary realm of the healing trance dance, in which shamans merged with spirit elands and rain-animals to summon rain and cure affliction."}, {"id": "sa-09-tibet-jokhang-snow-lion", "title": "Gilt-Copper Snow Lion (Sengge) Roof Guardian of the Jokhang Temple", "creature": "Tibetan Snow Lion", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "Gangs Sengge (གངས་སེང་གེ་)", "civilization": "Tibetan Buddhist (Ganden Phodrang Period)", "region": "South & Southeast Asia", "originLocation": "Jokhang Temple, Lhasa, Tibet", "dateDisplay": "17th–18th century CE", "yearSort": 1720, "era": "Enlightenment & 19th Century", "medium": "Hammered and parcel-gilt copper alloy architectural sculpture", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Single-Horned & Sacred Beasts", "creator": "Tibetan-Newar monastery metalworkers", "repository": "In situ, Golden Roof of the Jokhang Temple, Lhasa, Tibet", "commonsFile": "Snow_Lion_waits_for_Kundun_atop_Jokhang_in_2006_Lhasa,_Tibet_(cropped).JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Snow_Lion_waits_for_Kundun_atop_Jokhang_in_2006_Lhasa,_Tibet_(cropped).JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Snow_Lion_waits_for_Kundun_atop_Jokhang_in_2006_Lhasa,_Tibet_(cropped).JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/be/Snow_Lion_waits_for_Kundun_atop_Jokhang_in_2006_Lhasa,_Tibet_(cropped).JPG", "anatomy": ["exuberant curling mane, eyebrow scrolls, and tail tufts", "wide roaring fanged jaws and alert round eyes", "upright seated leonine posture guarding the monastic roofline"], "description": "Standing sentinel high on the gilded roof terraces of Lhasa's sacred Jokhang Temple, this hammered copper Snow Lion (Gangs Sengge) turns its roaring face and tightly coiled flame-curls toward the surrounding Himalayan peaks. Revered across Tibet as the fearless sovereign of snow-clad mountains—traditionally depicted in thangka painting with a white coat and turquoise mane—the Snow Lion symbolizes primordial cheerfulness, unshakeable Buddhist dharma, and the throne of enlightened Buddhas."}, {"id": "cn-07-qing-summer-palace-qilin", "title": "Imperial Bronze Qilin of the Summer Palace", "creature": "Qilin (Imperial Guardian Unicorn-Dragon)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "頤和園仁壽殿銅麒麟 (Tóng Qílín)", "civilization": "Qing Dynasty (Qianlong Reign)", "region": "East Asia & Eurasian Steppe", "originLocation": "Originally Yuanmingyuan; relocated to the Hall of Benevolence and Longevity, Summer Palace, Beijing", "dateDisplay": "Mid-18th century CE (Qianlong Reign, 1736–1795)", "yearSort": 1755, "era": "Renaissance & Early Modern", "medium": "Cast bronze", "mediumCategory": "Sculpture & Relief", "morphology": "Single-Horned & Sacred Beasts", "creator": "Qing Imperial Household Department (Zaobanchu) foundry", "repository": "In situ, Summer Palace (Yiheyuan), Beijing", "commonsFile": "Qilin_Statue_at_the_Summer_Palace_in_Beijing.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Qilin_Statue_at_the_Summer_Palace_in_Beijing.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Qilin_Statue_at_the_Summer_Palace_in_Beijing.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/45/Qilin_Statue_at_the_Summer_Palace_in_Beijing.jpg", "anatomy": ["antlered dragon-like head", "overlapping carp scales covering the body", "cloven ox-like hooves", "bushy curled lion tail and flame-wisps"], "description": "Cast with the imperial reign mark of the Qianlong Emperor on its crown and originally stationed at the Old Summer Palace (Yuanmingyuan) before its 1937 transfer to Yiheyuan, this monumental bronze qilin displays the canonical late-imperial composite anatomy: a dragon's head, deer's antlers, fish-scaled body, ox's hooves, and lion's tail. Standing before the Hall of Benevolence and Longevity, it embodied sagely governance and judicial discernment."}, {"id": "cn-07-qing-forbidden-city-shishi", "title": "Imperial Bronze Guardian Lions (Shishi) of the Forbidden City", "creature": "Shishi (Imperial Guardian Lion)", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "故宮銅獅 (Shíshī / Tóngshī)", "civilization": "Qing Dynasty", "region": "East Asia & Eurasian Steppe", "originLocation": "Forbidden City, Beijing, China", "dateDisplay": "18th century CE", "yearSort": 1760, "era": "Enlightenment & 19th Century", "medium": "Cast and gilded bronze on carved marble pedestals", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Qing Imperial Palace Foundry", "repository": "In situ, Forbidden City (Palace Museum), Beijing", "commonsFile": "Forbidden_City_Imperial_Guardian_Lions.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Forbidden_City_Imperial_Guardian_Lions.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Forbidden_City_Imperial_Guardian_Lions.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/da/Forbidden_City_Imperial_Guardian_Lions.jpg", "anatomy": ["rows of tight snail-shell mane curls (luofa)", "bell-hung ceremonial collar with tassels", "paw resting on embroidered cosmic sphere or cub", "stylized roaring jaws and bulging eyes"], "description": "Flanking the ceremonial thresholds of the Forbidden City in yin-yang pairs, these Qing bronze guardian lions transform the Asiatic lion—originally introduced via Buddhist Silk Road art—into a thoroughly mythologized imperial protector. Crowned with auspicious rows of tight curls reserved for the highest palatial rank, the male lion secures a latticework cosmic sphere beneath his right paw to signify universal sovereignty, while the female nurtures a cub beneath her left."}, {"id": "sa-09-deccani-al-buraq", "title": "Al-Buraq, the Winged Human-Headed Steed of the Prophet's Night Journey", "creature": "Buraq", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "Al-Burāq", "civilization": "Deccani Sultanate / Asaf Jahi School (Hyderabad, India)", "region": "South & Southeast Asia", "originLocation": "Hyderabad, Deccan, India", "dateDisplay": "c. 1770–1775 CE", "yearSort": 1772, "era": "Enlightenment & 19th Century", "medium": "Opaque watercolor and gold on paper", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Unknown Hyderabad court painter", "repository": "National Museum, New Delhi (Acc. No. 58.58/158)", "commonsFile": "Al-Buraq.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Al-Buraq.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Al-Buraq.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/00/Al-Buraq.jpg", "anatomy": ["crowned female human head adorned with pearl and gold jewelry", "dappled equine body fitted with an embroidered royal saddlecloth", "feathered angel wings and fanned iridescent peacock tail (plus cobra-terminated tail)"], "description": "Painted in Hyderabad during the late 18th century, this radiant Deccani miniature portrays Al-Buraq—the lightning-swift celestial mount that bore the Prophet Muhammad from Mecca to Jerusalem and up through the heavens during the Mi'raj (Night Journey). In the distinctive Indo-Islamic visual synthesis of the Deccan, Buraq combines a crowned, jewel-bedecked maiden's face, feathered wings, a dappled steed's body, an iridescent peacock fan, and a protective serpent-headed tail."}, {"id": "jk-08-edo-sekien-kappa", "title": "Kappa from the Illustrated Night Parade of a Hundred Demons", "creature": "Kappa (Amphibious River Child)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "河童 (画図百鬼夜行)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "1776 CE (An'ei 5)", "yearSort": 1776, "era": "Enlightenment & 19th Century", "medium": "Monochrome woodblock book illustration (ehon) on washi paper", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Toriyama Sekien", "repository": "Published in Gazu Hyakki Yagyō (multiple Edo editions preserved in public collections)", "commonsFile": "Kappa_jap_myth.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kappa_jap_myth.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kappa_jap_myth.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8a/Kappa_jap_myth.jpg", "anatomy": ["water-filled cranial dish (sara) ringed by coarse fringe hair", "ridged tortoise-like dorsal shell", "webbed amphibious hands and feet"], "description": "Emerging from a clump of riverbank lotus leaves in Toriyama Sekien's landmark 1776 yōkai compendium Gazu Hyakki Yagyō, the mischievous Kappa crouches with webbed hands and a watchful frog-like gaze. Sekien synthesized regional water-imp lore into a canonical anatomy featuring a scaly child-sized body, a turtle carapace, and the vital recessed dish (sara) atop its skull whose spilled water saps the creature's supernatural strength. Feared for luring horses and swimmers into rivers yet placated with cucumbers and polite bows, the Kappa became Japan's quintessential freshwater spirit."}, {"id": "jk-08-edo-sekien-nekomata", "title": "Nekomata from the Illustrated Night Parade of a Hundred Demons", "creature": "Nekomata (Fork-Tailed Monster Cat)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "猫また (画図百鬼夜行)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "1776 CE (An'ei 5)", "yearSort": 1776, "era": "Enlightenment & 19th Century", "medium": "Monochrome woodblock book illustration (ehon) on washi paper", "mediumCategory": "Manuscript & Print", "morphology": "Therianthropic (Human-Beast)", "creator": "Toriyama Sekien", "repository": "Published in Gazu Hyakki Yagyō (multiple Edo editions preserved in public collections)", "commonsFile": "SekienNekomata.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:SekienNekomata.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/SekienNekomata.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/21/SekienNekomata.jpg", "anatomy": ["bipedal domestic cat standing upright like a human", "distinctive split or twin tail", "shamisen-player kerchief and pawed kimono gestures"], "description": "In Toriyama Sekien's Gazu Hyakki Yagyō, an aged domestic cat that has lived long enough for its tail to split in two rears onto its hind legs beside a folding screen and a discarded shamisen plectrum—a sly visual pun on geisha ('cat') culture and cat-skin shamisen lutes. Whereas medieval chronicles such as Fujiwara no Teika's Meigetsuki described mountain-dwelling Nekomata as dog-sized man-eating beasts, Edo urban print culture recast them as uncanny household shapeshifters capable of speech, necromancy, and nocturnal dance."}, {"id": "jk-08-edo-sekien-tamamo-kitsune", "title": "Tamamo-no-Mae and the Nine-Tailed Fox Spirit", "creature": "Kyūbi no Kitsune (Nine-Tailed Fox Spirit)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "玉藻前・九尾の狐 (今昔画図続百鬼)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "1779 CE (An'ei 8)", "yearSort": 1779, "era": "Enlightenment & 19th Century", "medium": "Monochrome woodblock book illustration (ehon) on washi paper", "mediumCategory": "Manuscript & Print", "morphology": "Therianthropic (Human-Beast)", "creator": "Toriyama Sekien", "repository": "Published in Konjaku Gazu Zoku Hyakki (multiple Edo editions preserved in public collections)", "commonsFile": "SekienTamamo-no-mae.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:SekienTamamo-no-mae.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/SekienTamamo-no-mae.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/ba/SekienTamamo-no-mae.jpg", "anatomy": ["aristocratic Heian court lady enveloped by spectral mist", "emergent fox visage with pointed ears and narrow snout", "fan of nine plumed tails unfurling across the sky"], "description": "Published in Sekien's 1779 sequel encyclopedia Konjaku Gazu Zoku Hyakki, this atmospheric woodcut captures the unmasking of Tamamo-no-Mae, the dazzling court favorite of twelfth-century Emperor Konoe who was exposed by court diviner Abe no Yasuchika as a millennia-old nine-tailed fox spirit. Sekien renders the courtesan in layered Heian robes while her true kyūbi no kitsune form—snarling muzzle and nine billowing tails—rises like smoke from her shoulders. According to legend, when hunted down on the Nasu plain, the slain fox petrified into the poisonous Killing Stone (Sesshō-seki)."}, {"id": "eg-02-debre-berhan-cherubim", "title": "Winged Cherubim Sanctuary Ceiling of Debre Berhan Selassie", "creature": "Kirubel (Ethiopian Winged Cherubic Guardians)", "creatureFamily": "Lamassu, Apkallu, Buraq & Winged Threshold Spirits", "localName": "ኪሩቤል (Kirubel)", "civilization": "Ethiopian Empire (Gondarine Period)", "region": "Egypt & Africa", "originLocation": "Church of Debre Berhan Selassie ('Trinity at the Mount of Light'), Gondar, Ethiopia", "dateDisplay": "Founded c. 1694 CE (ceiling murals painted late 17th–early 19th century, pre-1825)", "yearSort": 1790, "era": "Enlightenment & 19th Century", "medium": "Glue-tempera pigment on primed cotton cloth mounted over juniper wood ceiling beams", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "Gondarine liturgical workshop (traditionally attributed to Haile Meskel's school)", "repository": "In situ, Debre Berhan Selassie Church, Gondar, Ethiopia", "commonsFile": "Ceiling_Angels,_Church_of_Debra_Berhan_Selassie_(2423987689).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ceiling_Angels,_Church_of_Debra_Berhan_Selassie_(2423987689).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ceiling_Angels,_Church_of_Debra_Berhan_Selassie_(2423987689).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/50/Ceiling_Angels,_Church_of_Debra_Berhan_Selassie_(2423987689).jpg", "anatomy": ["disembodied haloed angelic heads with immense almond-shaped watchful eyes", "interlocking crimson, black, and ochre feathered wings replacing corporeal limbs", "rhythmic directional gazes shifting left, right, and center across the firmament"], "description": "Spanning the flat timbered ceiling of Debre Berhan Selassie in the royal capital of Gondar, more than eighty bodiless winged cherubim gaze down in hypnotic rows symbolizing the omniscient heavenly host surrounding the tabot (Ark). Rendered strictly as luminous, wide-eyed faces flanked by patterned red-and-black wings, these celestial guardians gained legendary renown in Ethiopian history when a miraculous swarm of bees reportedly defended the church from Mahdist destruction in 1888."}, {"id": "rn-06-montfort-colossal-octopus", "title": "Le Poulpe Colossal (Colossal Octopus Attacking a Ship)", "creature": "Kraken / Colossal Octopus", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Poulpe Colossal", "civilization": "French Enlightenment Natural History", "region": "Renaissance & Early Modern Europe", "originLocation": "Paris, France", "dateDisplay": "1801 CE", "yearSort": 1801, "era": "Enlightenment & 19th Century", "medium": "Stipple and line engraving on paper", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Pierre Denys de Montfort (engraved by Étienne Claude Voysard)", "repository": "Muséum national d'Histoire naturelle, Paris (Histoire Naturelle des Mollusques, vol. 2)", "commonsFile": "Colossal_octopus_by_Pierre_Denys_de_Montfort.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Colossal_octopus_by_Pierre_Denys_de_Montfort.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Colossal_octopus_by_Pierre_Denys_de_Montfort.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9d/Colossal_octopus_by_Pierre_Denys_de_Montfort.jpg", "anatomy": ["mast-high sucker-lined tentacles", "bulbous cephalopod mantle", "glaring round eye at the waterline", "arms wrapping all three masts of a sailing vessel"], "description": "Published in Pierre Denys de Montfort's Histoire Naturelle Générale et Particulière des Mollusques (1801–1802) after an alleged ex-voto painting in Saint-Malo of a vessel attacked off Angola, this iconic engraving established the modern visual archetype of the Kraken. Towering tentacles thicker than mainmasts coil around the rigging of a three-masted ship while sailors hack desperately at the arms with axes."}, {"id": "jk-08-edo-ningyo-kawaraban", "title": "Prophetic Ningyo Caught in Toyama Bay (Bunka 2 Kawaraban)", "creature": "Ningyo (Japanese Mermaid / Human-Faced Fish)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "人魚 (越中国四方浦人魚之図)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo / Etchū Province (Toyama Bay), Japan", "dateDisplay": "1805 CE (Bunka 2, 5th month)", "yearSort": 1805, "era": "Enlightenment & 19th Century", "medium": "Woodblock-printed news broadside (kawaraban) with hand-applied color", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Anonymous Edo broadside publisher", "repository": "Tsubouchi Memorial Theatre Museum, Waseda University, Tokyo", "commonsFile": "Ningyo-no-zu-Bunka02-05.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Ningyo-no-zu-Bunka02-05.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Ningyo-no-zu-Bunka02-05.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/12/Ningyo-no-zu-Bunka02-05.jpg", "anatomy": ["humanoid female head with flowing black hair and dual horns", "colossal scaled carp torso bearing three circular flank eyes", "webbed bird-like claws beneath the belly"], "description": "Sold on city streets as an ephemeral kawaraban news sheet in the summer of 1805, this woodblock broadside reports a gigantic horned Ningyo allegedly netted off Etchū Province in Toyama Bay. Far removed from Western siren iconography, the Edo Ningyo merges a horned human visage with a massive carp body, three flank-mounted eyes, and clawed limbs. Its printed inscription promises that merely viewing an image of the prodigy confers longevity and wards off epidemic calamity—an auspicious visual talisman closely anticipating the later Amabie broadsides."}, {"id": "rn-06-blake-great-red-dragon", "title": "The Great Red Dragon and the Woman Clothed with the Sun", "creature": "Great Red Dragon of the Apocalypse", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Great Red Dragon", "civilization": "British Romanticism", "region": "Renaissance & Early Modern Europe", "originLocation": "London, United Kingdom", "dateDisplay": "c. 1803–1805 CE", "yearSort": 1805, "era": "Enlightenment & 19th Century", "medium": "Pen and black ink with watercolor over graphite on wove paper", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "William Blake", "repository": "Brooklyn Museum, New York", "commonsFile": "William_Blake_-_The_Great_Red_Dragon_and_the_Woman_Clothed_with_the_Sun_-_Google_Art_ProjectFXD.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:William_Blake_-_The_Great_Red_Dragon_and_the_Woman_Clothed_with_the_Sun_-_Google_Art_ProjectFXD.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/William_Blake_-_The_Great_Red_Dragon_and_the_Woman_Clothed_with_the_Sun_-_Google_Art_ProjectFXD.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/0/0d/William_Blake_-_The_Great_Red_Dragon_and_the_Woman_Clothed_with_the_Sun_-_Google_Art_ProjectFXD.jpg", "anatomy": ["heroic Michelangelesque muscular back", "seven horned heads (implied in crown of horns)", "vast ribbed bat-like wings", "forked serpentine tail sweeping down to earth"], "description": "Created for his patron Thomas Butts as part of a visionary watercolor cycle illustrating the Book of Revelation (12:1–4), William Blake's Great Red Dragon hovers menacingly over the radiant Woman Clothed with the Sun. Fusing apocalyptic demonology with sublime anatomical musculature, the towering winged titan spreads lightning-lit pinions while its whipping tail drags stars from heaven."}, {"id": "jk-08-edo-hokusai-baku", "title": "Baku, the Dream-Devouring Chimera", "creature": "Baku", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "獏", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "Early 19th century CE", "yearSort": 1815, "era": "Enlightenment & 19th Century", "medium": "Color woodblock print on paper", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Katsushika Hokusai", "repository": "Public collections (Edo woodblock impression)", "commonsFile": "Baku_by_Katsushika_Hokusai.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Baku_by_Katsushika_Hokusai.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Baku_by_Katsushika_Hokusai.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/75/Baku_by_Katsushika_Hokusai.jpg", "anatomy": ["curling elephant trunk and curved ivory tusks", "spotted leopard-like pelt and rhinoceros eyes", "ox-like tail and clawed tiger paws"], "description": "Katsushika Hokusai endows the benevolent Baku with coiled muscular torsion, combining an elephant's proboscis and tusks, a spotted feline coat, a flowing mane, and formidable tiger claws. Transmitted from Chinese protective beast lore into Japanese bedroom ritual, the Baku was invoked by sleepers waking from nightmares with the threefold plea 'Baku-san, come eat my dream.' Edo households placed Baku illustrations beneath pillows or carved its chimeric likeness onto temple crossbeams to consume malign portents and pestilence."}, {"id": "rn-06-ingres-roger-freeing-angelica", "title": "Roger Freeing Angelica", "creature": "Hippogriff and the Orc Sea Monster", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Hippogriffe & Orque", "civilization": "French Neoclassicism / Romanticism", "region": "Renaissance & Early Modern Europe", "originLocation": "Rome / Paris, France", "dateDisplay": "1819 CE", "yearSort": 1819, "era": "Enlightenment & 19th Century", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "Jean-Auguste-Dominique Ingres", "repository": "Musée du Louvre, Paris", "commonsFile": "Jean_Auguste_Dominique_Ingres_-_Roger_Delivering_Angelica.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Jean_Auguste_Dominique_Ingres_-_Roger_Delivering_Angelica.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Jean_Auguste_Dominique_Ingres_-_Roger_Delivering_Angelica.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/84/Jean_Auguste_Dominique_Ingres_-_Roger_Delivering_Angelica.jpg", "anatomy": ["feathered eagle head, wings, and foretalons of the Hippogriff", "equine hindquarters and flowing horse tail", "bulbous glowing-eyed marine Orc below", "fanged piscine maw pierced by a knightly lance"], "description": "Inspired by Ludovico Ariosto's Renaissance epic Orlando Furioso, Ingres stages a double mythological encounter on a wave-lashed crag off the Isle of Tears. Mounted astride a magnificent eagle-headed, horse-bodied Hippogriff, the armored knight Ruggiero drives his long lance into the gaping jaws of the monstrous marine Orc surging toward the chained princess Angelica."}, {"id": "rn-06-goya-saturn-devouring-son", "title": "Saturn Devouring His Son", "creature": "Cannibal Titan Saturn (Cronus)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Saturno", "civilization": "Spanish Romanticism", "region": "Renaissance & Early Modern Europe", "originLocation": "Quinta del Sordo, Madrid, Spain", "dateDisplay": "c. 1819–1823 CE", "yearSort": 1821, "era": "Enlightenment & 19th Century", "medium": "Oil mural on plaster transferred to canvas", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Francisco José de Goya y Lucientes", "repository": "Museo Nacional del Prado, Madrid", "commonsFile": "Francisco_de_Goya,_Saturno_devorando_a_su_hijo_(1819-1823).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Francisco_de_Goya,_Saturno_devorando_a_su_hijo_(1819-1823).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Francisco_de_Goya,_Saturno_devorando_a_su_hijo_(1819-1823).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/82/Francisco_de_Goya,_Saturno_devorando_a_su_hijo_(1819-1823).jpg", "anatomy": ["gaunt colossal ogre-like physique", "bulging manic white eyes", "cavernous blood-smeared jaws", "gnarled hands crushing a human body"], "description": "Painted directly onto the dining-room plaster walls of Goya's country house, the Quinta del Sordo, as one of the fourteen private 'Black Paintings,' this harrowing image strips classical Titan myth down to primal monstrousness. Crouching in pitch darkness with wide, terror-crazed eyes, the giant Saturn tears into the headless, bleeding corpse of his own child lest he be overthrown."}, {"id": "jk-08-edo-kirin-censer", "title": "Hirado Porcelain Incense Burner in the Form of a Kirin", "creature": "Kirin (Japanese Qilin)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "麒麟 (平戸焼麒麟香炉)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Mikawachi kilns, Hizen Province (Nagasaki), Japan", "dateDisplay": "Early–mid 19th century CE (Late Edo Period)", "yearSort": 1830, "era": "Enlightenment & 19th Century", "medium": "Molded Hirado porcelain with underglaze cobalt blue and brown details", "mediumCategory": "Ceramics & Vessels", "morphology": "Single-Horned & Sacred Beasts", "creator": "Mikawachi porcelain workshop (Hirado Domain)", "repository": "Walters Art Museum, Baltimore", "commonsFile": "Japanese_-_Incense_Burner_(\"Koro\")_in_the_Form_of_the_Kirin_-_Walters_491731_-_Three_Quarter.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Japanese_-_Incense_Burner_(%22Koro%22)_in_the_Form_of_the_Kirin_-_Walters_491731_-_Three_Quarter.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Japanese_-_Incense_Burner_(%22Koro%22)_in_the_Form_of_the_Kirin_-_Walters_491731_-_Three_Quarter.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Japanese_-_Incense_Burner_(%22Koro%22)_in_the_Form_of_the_Kirin_-_Walters_491731_-_Three_Quarter.jpg", "anatomy": ["single backward-swept horn crowning a draconic head", "slender deer-like body and cloven hooves", "curling shoulder flames and bushy upturned tail"], "description": "Modeled in pure white Hirado porcelain at the domainal kilns of Mikawachi, this sculptural kōro (incense burner) portrays the auspicious Kirin seated haunches-down with its draconic head reared skyward to vent fragrant smoke through its parted jaws. Revered in East Asian cosmology as the noblest of beasts—so gentle that it refuses to tread upon living grass or insects—the Kirin manifests only during the reign of a virtuous sage. Crisp hand-carved flame scrolls and delicate cobalt-blue accents highlight the creature's single horn and supernatural poise."}, {"id": "am-10-maori-manaia-pare-lintel", "title": "Carved Meeting-House Doorway Lintel (Pare) Flanked by Manaia", "creature": "Manaia (Avian-Serpentine Guardian Spirit)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Manaia", "civilization": "Māori", "region": "The Americas & Oceania", "originLocation": "Bay of Plenty / East Coast, North Island, Aotearoa (New Zealand)", "dateDisplay": "Early–mid 19th century (c. 1820–1860)", "yearSort": 1840, "era": "Enlightenment & 19th Century", "medium": "Openwork carved tōtara wood (Podocarpus totara) inlaid with pāua (Haliotis iris) shell", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Unknown 19th-century Māori tohunga whakairo (master carver)", "repository": "The Cleveland Museum of Art (1962.350)", "commonsFile": "Unknown_artist_-_Lintel_(Pare)_-_1962.350_-_Cleveland_Museum_of_Art.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Unknown_artist_-_Lintel_(Pare)_-_1962.350_-_Cleveland_Museum_of_Art.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Unknown_artist_-_Lintel_(Pare)_-_1962.350_-_Cleveland_Museum_of_Art.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/22/Unknown_artist_-_Lintel_(Pare)_-_1962.350_-_Cleveland_Museum_of_Art.jpg", "anatomy": ["strict profile head terminating in a curved bird-like beak", "contorted serpentine torso woven through openwork takarangi spirals", "three-fingered avian-reptilian claws and luminous pāua-shell eye"], "description": "Mounted above the threshold of an ancestral wharenui to mark the perilous transition between the tapu realm inside and the everyday world outside, this openwork tōtara pare lintel flanks a central ancestral figure with two outward-facing manaia guardians. Always rendered in profile with a curved beak, glowing pāua eye, and three-taloned hands, the manaia acts across Māori woodcarving as an unseen messenger and protective spiritual counterpart bridging sky, sea, and human lineages."}, {"id": "jk-08-edo-kuniyoshi-tsuchigumo", "title": "The Earth Spider Generating Monsters at the Mansion of Lord Minamoto no Yorimitsu", "creature": "Tsuchigumo (Giant Demon Spider) and Hyakki Yōkai", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "土蜘蛛 (源頼光公館土蜘作妖怪図)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "1843 CE (Tenpō 14)", "yearSort": 1843, "era": "Enlightenment & 19th Century", "medium": "Polychrome woodblock print triptych (ōban tate-e nishiki-e)", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Utagawa Kuniyoshi", "repository": "Tokyo National Museum / Victoria and Albert Museum (multiple impressions)", "commonsFile": "Raiko_tormented_by_the_earth_spider.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Raiko_tormented_by_the_earth_spider.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Raiko_tormented_by_the_earth_spider.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d8/Raiko_tormented_by_the_earth_spider.jpg", "anatomy": ["bloated mottled arachnid body with glaring demon eyes", "sticky silken web filaments cast over sleeping samurai", "swarming army of horned, three-eyed, and tsukumogami specters"], "description": "Published at the height of the austere Tenpō Reforms in 1843, Utagawa Kuniyoshi's celebrated triptych ostensibly depicts the tenth-century general Minamoto no Yorimitsu (Raikō) bedridden with fever as the monstrous Earth Spider (Tsuchigumo) looms above him, unleashing a swirling legion of ghouls behind his retainers' backs. Edo townspeople immediately read the composition as daring political satire against shogunal chief councilor Mizuno Tadakuni, identifying individual yōkai with censored professions and grievances. Despite authorities confiscating the woodblocks, pirate editions circulated widely across Edo."}, {"id": "jk-08-edo-hokusai-phoenix", "title": "Higashimachi Festival Float Ceiling Painting: Phoenix (Hō-ō)", "creature": "Hō-ō (Japanese Phoenix / Fenghuang)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "鳳凰 (東町祭屋台天井絵 鳳凰図)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Obuse, Shinano Province (Nagano Prefecture), Japan", "dateDisplay": "1844 CE (Tenpō 15 / Kōka 1)", "yearSort": 1844, "era": "Enlightenment & 19th Century", "medium": "Mineral pigments, gold leaf, and animal-skin glue tempera on paulownia wood panel", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "Katsushika Hokusai", "repository": "Hokusai-kan Museum, Obuse, Nagano", "commonsFile": "Matsuri_Yatai_Phoenix_(Hokusaikan_Obuse).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Matsuri_Yatai_Phoenix_(Hokusaikan_Obuse).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Matsuri_Yatai_Phoenix_(Hokusaikan_Obuse).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1a/Matsuri_Yatai_Phoenix_(Hokusaikan_Obuse).jpg", "anatomy": ["fierce golden-eyed avian head crowned with jewel-like crests", "iridescent wings layered in vermilion, azurite, malachite, and gold leaf", "sinuous wheeling neck and peacock-eyed tail streamers"], "description": "Painted by an eighty-five-year-old Katsushika Hokusai for the coffered ceiling of the Higashimachi neighborhood festival float in Obuse, this dazzling 126-centimeter square panel envelopes the viewer in the wheeling plumage of the sacred Hō-ō. Paired with a companion Dragon panel to represent cosmic yin and yang, the celestial bird coils across the paulownia frame in a vortex of cinnabar red, ultramarine, malachite green, and flecks of gold leaf. Hokusai gave the bird three-dimensional intensity so that revelers gazing upward beneath the moving float saw an auspicious omen of harmony blazing overhead."}, {"id": "jk-08-edo-kuniyoshi-gashadokuro", "title": "Takiyasha the Witch and the Skeleton Spectre", "creature": "Gashadokuro (Colossal Skeleton Specter)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "がしゃどくろ・骸骨の怪 (相馬の古内裏)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "c. 1844 CE (Kōka 1)", "yearSort": 1844, "era": "Enlightenment & 19th Century", "medium": "Polychrome woodblock print triptych (ōban tate-e nishiki-e)", "mediumCategory": "Manuscript & Print", "morphology": "Giants, Demons & Spirits", "creator": "Utagawa Kuniyoshi", "repository": "Victoria and Albert Museum, London / Honolulu Museum of Art", "commonsFile": "Takiyasha_the_Witch_and_the_Skeleton_Spectre.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Takiyasha_the_Witch_and_the_Skeleton_Spectre.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Takiyasha_the_Witch_and_the_Skeleton_Spectre.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/1a/Takiyasha_the_Witch_and_the_Skeleton_Spectre.jpg", "anatomy": ["gargantuan human skeleton spanning two full triptych sheets", "anatomically detailed ribcage, clavicle, and articulated phalanges", "hollow eye sockets looming through shredded bamboo palace blinds"], "description": "Arguably the most iconic supernatural triptych in ukiyo-e history, Kuniyoshi's Sōma no furu-dairi condenses an army of spectral skeletons from Santō Kyōden's romance Utö Yasukata Chūgiden into a single monumental colossus tearing through the ruined Soma palace blinds to menace the warrior Ōya Tarō Mitsukuni. Drawing on imported Dutch anatomical engravings, Kuniyoshi rendered the towering ribcage and bony hands with startling osteological precision as Princess Takiyasha chants from a handscroll at left. In twentieth-century folklore revivals, Kuniyoshi's unnamed specter became the definitive visual model for the giant starving-dead yōkai Gashadokuro."}, {"id": "jk-08-edo-kuniyoshi-nue", "title": "Miyamoto Musashi Killing a Giant Nue (Mountain Beast)", "creature": "Nue (Chimera)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "鵺・山鮫魚", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "c. 1845 CE", "yearSort": 1845, "era": "Enlightenment & 19th Century", "medium": "Polychrome woodblock print (ōban tate-e nishiki-e)", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Utagawa Kuniyoshi", "repository": "Public collections (Honchō Suikoden warrior series)", "commonsFile": "Miyamoto_Musashi_killing_a_giant_nue.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Miyamoto_Musashi_killing_a_giant_nue.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Miyamoto_Musashi_killing_a_giant_nue.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/18/Miyamoto_Musashi_killing_a_giant_nue.jpg", "anatomy": ["snarling beast head with jagged fangs and flared nostrils", "striped tiger-like limbs and razor claws", "spined, chimeric mountain-monster torso pinned beneath the swordsman"], "description": "From Kuniyoshi's kinetic warrior series Eight Hundred Heroes of Our Country's Suikoden, this vertical print pits the legendary swordsman Miyamoto Musashi astride a writhing mountain monster deep on the border of Echizen, Mino, and Hida provinces. While the cartouche calls the creature a 'mountain shark-fish' (yamazame), its striped tiger limbs, monstrous fanged head, and hybrid anatomy directly echo the classic Heike Monogatari iconography of the Nue—the night-crying chimera with a monkey's head, tanuki's body, tiger's legs, and snake's tail. Kuniyoshi fills almost the entire frame with the beast's contorted body to heighten the hero's perilous strike."}, {"id": "sa-09-bangkok-yaksha-thotsakan", "title": "Monumental Glazed-Mosaic Yaksha Guardian (Thotsakan) at Wat Phra Kaew", "creature": "Yaksha (Thai Giant Guardian)", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Yak / Thotsakan (ทศกัณฐ์)", "civilization": "Rattanakosin Kingdom (Thailand)", "region": "South & Southeast Asia", "originLocation": "Wat Phra Kaew (Temple of the Emerald Buddha), Grand Palace, Bangkok, Thailand", "dateDisplay": "19th century CE (Rama III–Rama IV period)", "yearSort": 1845, "era": "Enlightenment & 19th Century", "medium": "Brick and stucco colossal statue clad in polychrome ceramic tile and gilt glass mosaic", "mediumCategory": "Mosaic & Glazed Brick", "morphology": "Giants, Demons & Spirits", "creator": "Royal Rattanakosin court sculptors and mosaicists", "repository": "In situ, Wat Phra Kaew, Grand Palace, Bangkok, Thailand", "commonsFile": "Phu_Yak.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Phu_Yak.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Phu_Yak.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5d/Phu_Yak.jpg", "anatomy": ["emerald-green demonic visage with bulging eyes and curling tusks", "tiered multi-faced golden crown (mongkut) of the ten-headed demon king", "towering armored giant body leaning on a heavy war-club (krabong)"], "description": "Towering nearly five meters high beside a gateway of Bangkok's Temple of the Emerald Buddha, one of twelve colossal Yaksha guardians modeled on demon kings from the Thai Ramakien epic—here green-skinned Thotsakan (Ravana)—leans both hands upon his ceremonial mace. Encrusted with thousands of hand-cut polychrome porcelain and gilt-glass tesserae, the ferocious multi-tiered giant converts former mythic adversaries into tireless protectors of Thailand's sacred palladium."}, {"id": "jk-08-edo-amabie-kawaraban", "title": "Appearance of the Prophetic Sea Spirit Amabie in Higo Province", "creature": "Amabie", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "アマビエ (肥後国海中の怪)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (reporting Higo Province / Kumamoto), Japan", "dateDisplay": "1846 CE (Kōka 3, mid-4th month)", "yearSort": 1846, "era": "Enlightenment & 19th Century", "medium": "Woodblock-printed news broadside (kawaraban) on paper", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Anonymous Edo broadside woodcarver", "repository": "Kyoto University Main Library", "commonsFile": "Higo_Amabie.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Higo_Amabie.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Higo_Amabie.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/25/Higo_Amabie.jpg", "anatomy": ["long streaming hair and bird-like beak", "diamond-scaled torso from the neck down", "three fin-like legs standing upright above ocean waves"], "description": "Preserved in a single surviving Edo news broadside (kawaraban) at Kyoto University Library, this naïve yet unforgettable woodcut records a glowing marine spirit that emerged nightly from the sea off Higo Province in the fourth month of 1846. Addressing a local official who rowed out to investigate, the beaked, scaly, three-legged creature identified itself as Amabie, prophesied six years of bountiful harvests, and instructed people to copy and share its portrait should epidemic disease strike. Nearly two centuries later, this exact 1846 woodblock image achieved global renown as an emblem of protection against pestilence."}, {"id": "jk-08-edo-hokusai-fuji-dragon", "title": "Dragon in Smoke Escaping from Mount Fuji (Fujigoshi Ryū-zu)", "creature": "Ryū (Japanese Dragon)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "龍 (富士越龍図)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "1849 CE (Kaei 2, 1st month)", "yearSort": 1849, "era": "Enlightenment & 19th Century", "medium": "Ink and light color on silk hanging scroll (kakemono)", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Katsushika Hokusai", "repository": "Hokusai-kan Museum, Obuse, Nagano", "commonsFile": "Hokusai-fuji-koryuu.png", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Hokusai-fuji-koryuu.png", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Hokusai-fuji-koryuu.png?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/15/Hokusai-fuji-koryuu.png", "anatomy": ["slender black-scaled serpentine body twisting vertically through dark smoke", "three-clawed taloned limbs typical of Japanese dragons", "horned, whiskered head gazing skyward toward the heavens"], "description": "Completed in the first month of 1849—less than four months before Katsushika Hokusai died at the age of eighty-eight—this poignant hanging scroll pairs the snow-draped cone of sacred Mount Fuji with a dark Ryū ascending on a column of black cloud and smoke. Unlike five-clawed Chinese imperial dragons, the Japanese dragon displays three razor-sharp talons per foot as its sinuous spine corkscrews toward heaven. Art historians widely interpret the ascending dragon leaving earthly Fuji behind as Hokusai's spiritual self-portrait at the threshold of artistic immortality."}, {"id": "sa-09-odisha-navagunjara", "title": "Navagunjara, the Nine-Animal Composite Manifestation of Krishna before Arjuna", "creature": "Navagunjara", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Nabagunjara (ନବଗୁଞ୍ଜର)", "civilization": "Odisha Regional Hindu Tradition (Eastern India)", "region": "South & Southeast Asia", "originLocation": "Odisha (Orissa), India", "dateDisplay": "19th century CE", "yearSort": 1850, "era": "Enlightenment & 19th Century", "medium": "Opaque watercolor and ink on layered cloth/paper (Pattachitra court idiom)", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Unknown Chitrakara artist of Odisha", "repository": "Metropolitan Museum of Art, New York (1998.297)", "commonsFile": "MET_DP140154.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:MET_DP140154.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/MET_DP140154.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/c/c8/MET_DP140154.jpg", "anatomy": ["rooster's combed head atop an arched iridescent peacock's neck", "humped bull's back tapering into a slender lion's waist with a raised cobra tail", "four distinct limbs: human arm holding a lotus, elephant leg, tiger paw, and deer hoof"], "description": "Unique to the 15th-century Odia Mahabharata of poet Sarala Dasa, this 19th-century Odisha painting illustrates Krishna testing the warrior Arjuna in the forest by assuming the astonishing form of Navagunjara, an impossible creature assembled from nine distinct beings: rooster head, peacock neck, bull hump, lion waist, serpent tail, and limbs of an elephant, tiger, deer, and lotus-bearing human hand. Realizing that no natural creature could unite nine species in harmony, Arjuna drops his bow and kneels in devotion before the boundless cosmic imagination of Vishnu-Krishna."}, {"id": "sa-09-mysore-sharabha-painting", "title": "Eight-Legged Winged Lion-Bird Sharabha Incarnation of Shiva", "creature": "Sharabha", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Śarabha / Śarabheśvara", "civilization": "South Indian Shaiva Tradition (Mysuru / Tanjore School)", "region": "South & Southeast Asia", "originLocation": "Karnataka or Tamil Nadu, South India", "dateDisplay": "19th century CE", "yearSort": 1855, "era": "Enlightenment & 19th Century", "medium": "Opaque watercolor and gold on paper", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Unknown South Indian traditional painter", "repository": "Published historical collection (South India)", "commonsFile": "Sharabha.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sharabha.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sharabha.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6e/Sharabha.jpg", "anatomy": ["crowned leonine-avian head with curved tusks and divine Shaiva emblems", "golden feathered wings flanking a multi-armed human-lion upper body", "eight powerful clawed legs capable of leaping across mountains"], "description": "Rendered in rich South Indian polychrome and gold, this devotional painting portrays Shiva's ferocious composite avatar Sharabha—part eight-legged lion, part giant winged bird, and part multi-armed deity wielding the deer, battle-axe, snake, and fire. According to Shaiva Puranic myth and Chola-to-Mysuru temple lore, Shiva manifested as the eight-legged Sharabha to pacify the world-shaking wrath of Narasimha after Hiranyakashipu's slaying."}, {"id": "jk-08-edo-namazu-e", "title": "True Depiction of the Kashima Keystone (Kashima Kanameishi Shinzu)", "creature": "Ōnamazu (Giant Subterranean Earthquake Catfish)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "大鯰 (鹿島要石真図・鯰絵)", "civilization": "Edo Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Edo (Tokyo), Japan", "dateDisplay": "1855 CE (Ansei 2)", "yearSort": 1855, "era": "Enlightenment & 19th Century", "medium": "Polychrome woodblock print (namazu-e)", "mediumCategory": "Manuscript & Print", "morphology": "Marine & Abyssal Monsters", "creator": "Anonymous Edo ukiyo-e artist", "repository": "International Research Center for Japanese Studies (Nichibunken), Kyoto", "commonsFile": "Kashima-kanameishi-shinzu-namazu-e.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kashima-kanameishi-shinzu-namazu-e.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kashima-kanameishi-shinzu-namazu-e.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Kashima-kanameishi-shinzu-namazu-e.jpg", "anatomy": ["colossal dark-skinned subterranean catfish body", "long sensory barbels thrashing beneath the earth", "broad flattened head pinned down by a sacred keystone and sword"], "description": "Within days of the devastating Ansei Edo Earthquake of November 1855, hundreds of anonymous namazu-e ('catfish prints') flooded Edo streets as protective talismans and social commentary. Divided into upper and lower registers, this print shows pilgrims venerating the sacred foundation stone (kaname-ishi) at Kashima Shrine above ground while, beneath the earth, the thunder-and-sword deity Takemikazuchi subdues the thrashing giant Ōnamazu whose subterranean tremors toppled castles and storehouses. Buyers pasted such prints to house beams to appease the seismic beast and ward off aftershocks."}, {"id": "sa-09-bangkok-kinnara-wat-phra-kaew", "title": "Gilt-Bronze Kinnorn (Kinnara) Terrace Guardian at Wat Phra Kaew", "creature": "Kinnara (Thai Kinnorn)", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Kinnorn (กินร)", "civilization": "Rattanakosin Kingdom (Thailand)", "region": "South & Southeast Asia", "originLocation": "Upper Terrace around Phra Mondop, Wat Phra Kaew (Temple of the Emerald Buddha), Grand Palace, Bangkok, Thailand", "dateDisplay": "19th century CE (cast under King Rama IV / Rama V)", "yearSort": 1860, "era": "Enlightenment & 19th Century", "medium": "Cast and gilded bronze sculpture with mirrored glass inlays", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Royal Rattanakosin court foundry artisans", "repository": "In situ, Wat Phra Kaew, Grand Palace, Bangkok, Thailand", "commonsFile": "Kinnon_Wat_Phra_Kaew_02.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kinnon_Wat_Phra_Kaew_02.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kinnon_Wat_Phra_Kaew_02.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9a/Kinnon_Wat_Phra_Kaew_02.jpg", "anatomy": ["serene princely human upper body crowned with a Thai tapering chada spire", "layered gilt wings and ornate flaring avian tail-plumage", "slender clawed bird legs poised on a lotus plinth"], "description": "Standing on the upper terrace of Bangkok's Temple of the Emerald Buddha, which architecturally recreates the mythical Himavanta (Himmapan) forest at the foot of Mount Meru, this dazzling gilt-bronze Kinnorn (male Kinnara) wears a pointed Thai royal crown (chada) and jeweled breastplate above feathered bird thighs and talons. Cast by royal Siamese artisans in the 19th century, the hybrid celestial musician exemplifies Thailand's refined visual codification of Buddhist Himmapan creatures."}, {"id": "rn-06-moreau-oedipus-and-sphinx", "title": "Oedipus and the Sphinx", "creature": "Theban Winged Sphinx", "creatureFamily": "Sphinxes (Androsphinx, Criosphinx & Winged Sphinx)", "localName": "Le Sphinx", "civilization": "French Symbolism", "region": "Renaissance & Early Modern Europe", "originLocation": "Paris, France", "dateDisplay": "1864 CE", "yearSort": 1864, "era": "Enlightenment & 19th Century", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Composite Chimeras", "creator": "Gustave Moreau", "repository": "Metropolitan Museum of Art, New York", "commonsFile": "Oedipus_and_the_Sphinx_MET_DP-14201-023.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Oedipus_and_the_Sphinx_MET_DP-14201-023.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Oedipus_and_the_Sphinx_MET_DP-14201-023.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/85/Oedipus_and_the_Sphinx_MET_DP-14201-023.jpg", "anatomy": ["diadem-crowned female head and bust", "tawny leonine body and gripping claws", "upright falcon-like feathered wings", "hypnotic unblinking gaze"], "description": "Exhibited to sensation at the Paris Salon of 1864, Gustave Moreau's breakthrough canvas revitalized mythological painting by staging an intense psychological duel atop a bone-strewn mountain pass. Clinging directly to Oedipus's chest and thigh with leonine claws, the crowned, eagle-winged Sphinx locks eyes with the traveler in a jewel-toned allegory of mind confronting enigma and mortality."}, {"id": "sa-09-mandalay-chinthe-pair", "title": "Monumental Twin Chinthe Leogryph Guardians at the Foot of Mandalay Hill", "creature": "Chinthe", "creatureFamily": "Griffins & Eagle-Lion Hybrids", "localName": "Chinthe (ခြင်္သေ့)", "civilization": "Konbaung Dynasty (Myanmar)", "region": "South & Southeast Asia", "originLocation": "Southern Stairway Entrance, Mandalay Hill, Mandalay, Myanmar", "dateDisplay": "mid-19th century CE (c. 1857–1878, reign of King Mindon; restored 20th c.)", "yearSort": 1865, "era": "Enlightenment & 19th Century", "medium": "Monumental whitewashed brick and carved stucco masonry sculpture with gilt accents", "mediumCategory": "Sculpture & Relief", "morphology": "Single-Horned & Sacred Beasts", "creator": "Konbaung royal master masons", "repository": "In situ, Mandalay Hill Southern Approach, Mandalay, Myanmar", "commonsFile": "Chinthe,_Mandalay_Hill,_Myanmar.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Chinthe,_Mandalay_Hill,_Myanmar.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Chinthe,_Mandalay_Hill,_Myanmar.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/da/Chinthe,_Mandalay_Hill,_Myanmar.JPG", "anatomy": ["colossal whitewashed leonine haunches and muscular chest", "flaring flame-crested mane, pointed ears, and gilded trim", "wide roaring fanged jaws guarding the pilgrim stairway"], "description": "Flanking the southern covered stairway ascending sacred Mandalay Hill, twin towering whitewashed brick-and-stucco Chinthes sit upright on massive haunches with fanged jaws roaring outward over the plain. Rooted in Burmese Buddhist legend—in which a prince born of a lioness erected lion images at pagodas in remorse after slaying his grieving father—paired Chinthe guardians stand watch at virtually every monastery and stupa across Myanmar."}, {"id": "jk-08-joseon-haetae", "title": "Stone Guardian Haetae of Gyeongbokgung Palace", "creature": "Haetae / Haechi (Justice-Sensing Scaly Lion-Beast)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "해태 (해치)", "civilization": "Joseon Dynasty (Korea)", "region": "East Asia & Eurasian Steppe", "originLocation": "Gwanghwamun Gate, Gyeongbokgung Palace, Seoul, Korea", "dateDisplay": "c. 1867 CE (Reconstruction of Gyeongbokgung under King Gojong)", "yearSort": 1867, "era": "Enlightenment & 19th Century", "medium": "Carved granite", "mediumCategory": "Sculpture & Relief", "morphology": "Single-Horned & Sacred Beasts", "creator": "Yi Se-uk (royal master stonemason of the Joseon court)", "repository": "Gyeongbokgung Palace / Gwanghwamun Precinct, Seoul", "commonsFile": "Haetae_In_Gyeongbokgung_Palace.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Haetae_In_Gyeongbokgung_Palace.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Haetae_In_Gyeongbokgung_Palace.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/89/Haetae_In_Gyeongbokgung_Palace.JPG", "anatomy": ["stocky lion-like body covered in carved fish-like scales", "vestigial horn bud atop the crown and bell hung at the chest", "curling eyebrow tufts, broad grin, and short feathered flank wings"], "description": "Carved in local granite by royal master mason Yi Se-uk during Prince Regent Heungseon Daewongun's 1867 reconstruction of Gyeongbokgung Palace, this pair of Haetae (also called Haechi) originally stood before Gwanghwamun Gate beside the Office of the Inspector-General (Saheonbu). In Korean court tradition, the Haetae possessed an innate moral sense to gore corrupt officials while also swallowing destructive fire qi flowing from Mount Gwanaksan toward the wooden palace halls. Its charming rounded muzzle, scalloped body scales, and ornamental chest bell became enduring emblems of Seoul."}, {"id": "rn-06-bocklin-battle-of-centaurs", "title": "Battle of the Centaurs (Kentaurenkampf)", "creature": "Centaurs", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Kentauren", "civilization": "Swiss-German Symbolism", "region": "Renaissance & Early Modern Europe", "originLocation": "Munich, Germany (painted by Swiss master Arnold Böcklin)", "dateDisplay": "1873 CE", "yearSort": 1873, "era": "Enlightenment & 19th Century", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Therianthropic (Human-Beast)", "creator": "Arnold Böcklin", "repository": "Kunstmuseum Basel, Switzerland", "commonsFile": "Battle_of_the_Centaurs_by_Arnold_Böcklin_(Kunstmuseum_Basel).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Battle_of_the_Centaurs_by_Arnold_B%C3%B6cklin_(Kunstmuseum_Basel).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Battle_of_the_Centaurs_by_Arnold_B%C3%B6cklin_(Kunstmuseum_Basel).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4c/Battle_of_the_Centaurs_by_Arnold_B%C3%B6cklin_(Kunstmuseum_Basel).jpg", "anatomy": ["sweat-sheened equine flanks in dapple, chestnut, and black", "heavily muscled bearded human torsos", "rearing hooves trampling fallen rivals", "boulder-heaving arms"], "description": "Rejecting restrained classical statuary in favor of visceral, elemental violence, Arnold Böcklin sets eight colossal horse-men locked in mortal combat across a storm-swept mountain ridge. Hurling massive boulders and grappling flesh-to-hide without a single human hero in sight, Böcklin's centaurs embody untamed telluric force emerging directly from Alpine rock and thundercloud."}, {"id": "am-10-kwakwakawakw-sisiutl-boards", "title": "Ceremonial Dantsikw Power Boards Depicting the Sisiutl", "creature": "Sisiutl (Double-Headed Horned Serpent)", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Sisiutł", "civilization": "Kwakwaka'wakw", "region": "The Americas & Oceania", "originLocation": "Northern Vancouver Island / Queen Charlotte Strait, British Columbia, Canada", "dateDisplay": "19th century (collected 1881)", "yearSort": 1875, "era": "Enlightenment & 19th Century", "medium": "Carved and polychrome-painted red cedar wood", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Unknown 19th-century Kwakwaka'wakw carver", "repository": "Ethnologisches Museum, Staatliche Museen zu Berlin", "commonsFile": "Kwakiutl_power_boards_EthnM_Berlin.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kwakiutl_power_boards_EthnM_Berlin.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kwakiutl_power_boards_EthnM_Berlin.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d6/Kwakiutl_power_boards_EthnM_Berlin.jpg", "anatomy": ["opposing horned serpent heads with curled tongues at either extremity", "central frontal humanoid face with upturned horns", "formline-painted scales imbued with petrifying warrior medicine"], "description": "Collected on the Northwest Coast in 1881 by Johan Adrian Jacobsen for Berlin's Ethnological Museum, these painted wooden dantsikw boards manifest the formidable supernatural power of Sisiutl, the bicephalic horned sea-serpent of Kwakwaka'wakw winter ceremonialism. Flanking a central horned human visage with two outward-facing fanged dragon heads, the amphibious Sisiutl could transform into a self-propelled canoe, turn the unprepared to stone with its gaze, and render warriors invulnerable when its blood bathed their skin."}, {"id": "sa-09-india-kamadhenu-painting", "title": "Kamadhenu (Surabhi), the Wish-Fulfilling Winged Celestial Cow beneath the Parijata Tree", "creature": "Kamadhenu (Surabhi)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Kāmadhenu / Surabhi", "civilization": "Hindu Devotional Tradition (India)", "region": "South & Southeast Asia", "originLocation": "India", "dateDisplay": "19th century CE", "yearSort": 1875, "era": "Enlightenment & 19th Century", "medium": "Polychrome gouache / chromolithographic devotional print on paper", "mediumCategory": "Manuscript & Print", "morphology": "Composite Chimeras", "creator": "Unknown 19th-century Indian devotional artist", "repository": "Historical Indian devotional print archive", "commonsFile": "Kamadhenu_parijata.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Kamadhenu_parijata.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Kamadhenu_parijata.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/7/7a/Kamadhenu_parijata.jpg", "anatomy": ["crowned female deity head with serene Tilaka-marked countenance", "white sacred cow body containing the pantheon of Hindu gods within its flanks", "polychrome feathered eagle wings and fanned peacock tail"], "description": "Standing beneath the celestial Parijata coral-tree that emerged alongside her during the cosmic Churning of the Ocean of Milk (Samudra Manthan), the wish-fulfilling cow-goddess Kamadhenu displays a crowned woman's face, rainbow-feathered wings, a peacock's tail, and a sacred bovine body inhabited by the entire Hindu pantheon. Revered as the divine mother of all cattle and source of inexhaustible nourishment, her composite form visually maps the cosmos onto a single auspicious being."}, {"id": "rn-06-moreau-hercules-lernaean-hydra", "title": "Hercules and the Lernaean Hydra", "creature": "Seven-Headed Lernaean Hydra", "creatureFamily": "Cerberus, Hydra & Multi-Headed Beasts", "localName": "Hydre de Lerne", "civilization": "French Symbolism", "region": "Renaissance & Early Modern Europe", "originLocation": "Paris, France", "dateDisplay": "1876 CE", "yearSort": 1876, "era": "Enlightenment & 19th Century", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Draconic & Serpentine", "creator": "Gustave Moreau", "repository": "Art Institute of Chicago", "commonsFile": "Gustave_Moreau_-_Hercules_and_the_Lernaean_Hydra_-_1964.231_-_Art_Institute_of_Chicago.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Gustave_Moreau_-_Hercules_and_the_Lernaean_Hydra_-_1964.231_-_Art_Institute_of_Chicago.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Gustave_Moreau_-_Hercules_and_the_Lernaean_Hydra_-_1964.231_-_Art_Institute_of_Chicago.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/da/Gustave_Moreau_-_Hercules_and_the_Lernaean_Hydra_-_1964.231_-_Art_Institute_of_Chicago.jpg", "anatomy": ["seven towering cobra-hooded serpent necks", "central dominant dragon-viper head", "colossal coiled reptilian trunk", "charnel marsh littered with pale victims"], "description": "Debuted at the Paris Salon of 1876 in the aftermath of the Franco-Prussian War, Moreau's monumental canvas pits a radiant, sunlit Hercules against a towering, shadow-shrouded Hydra rising above the pestilential marshes of Lerna. Modeled from zoological studies of cobras and sea snakes, its seven swaying necks fan out like a dark floral corona over scores of drained human corpses."}, {"id": "am-10-kwakwakawakw-thunderbird-mask", "title": "'Namgis Thunderbird Transformation Mask", "creature": "Thunderbird", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Kwankwanxwalige' / Kolus", "civilization": "Kwakwaka'wakw ('Namgis)", "region": "The Americas & Oceania", "originLocation": "Alert Bay / Cormorant Island region, British Columbia, Canada", "dateDisplay": "Late 19th century", "yearSort": 1880, "era": "Enlightenment & 19th Century", "medium": "Carved red cedar wood, mineral and commercial pigments, leather hinges, metal, and cordage", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Unknown 19th-century 'Namgis (Kwakwaka'wakw) master carver", "repository": "Brooklyn Museum, New York (08.491.8902)", "commonsFile": "Namgis_(Native_American)._Thunderbird_Transformation_Mask,_19th_century.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Namgis_(Native_American)._Thunderbird_Transformation_Mask,_19th_century.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Namgis_(Native_American)._Thunderbird_Transformation_Mask,_19th_century.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/6c/Namgis_(Native_American)._Thunderbird_Transformation_Mask,_19th_century.jpg", "anatomy": ["massive hooked raptor beak split vertically along hidden rigging cords", "curling supernatural horn-crest feathers atop the head", "hinged outer avian halves opening wide to reveal an ancestral human face within"], "description": "Acquired in British Columbia during Stewart Culin's early museum expeditions, this kinetic 'Namgis transformation mask dramatizes the foundational Kwakwaka'wakw myth in which the celestial Thunderbird descended to earth and shed its avian cloak to become a clan ancestor. Operated by concealed pull-strings in the firelight of the winter tseka ceremonial house, the hooked eagle-like beak and painted wings swing dramatically apart—flashing lightning from its eyes and booming thunder with its pinions—to reveal the human face inside."}, {"id": "rn-06-bocklin-play-of-waves", "title": "In the Play of the Waves (Im Spiel der Wellen)", "creature": "Ichthyocentaur, Triton, and Naiads / Mermaids", "creatureFamily": "Centaurs, Pegasus, Satyrs & Equine Hybrids", "localName": "Meereszentaur, Triton und Meerjungfrauen", "civilization": "Swiss-German Symbolism", "region": "Renaissance & Early Modern Europe", "originLocation": "Florence / Munich (painted by Swiss master Arnold Böcklin)", "dateDisplay": "1883 CE", "yearSort": 1883, "era": "Enlightenment & 19th Century", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Marine & Abyssal Monsters", "creator": "Arnold Böcklin", "repository": "Neue Pinakothek, Munich", "commonsFile": "Arnold_Böcklin_-_Im_Spiel_der_Wellen_(1883).jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Arnold_B%C3%B6cklin_-_Im_Spiel_der_Wellen_(1883).jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Arnold_B%C3%B6cklin_-_Im_Spiel_der_Wellen_(1883).jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5e/Arnold_B%C3%B6cklin_-_Im_Spiel_der_Wellen_(1883).jpg", "anatomy": ["pot-bellied human torso of an aging sea-centaur", "iridescent piscine tails and dorsal fins", "sunburned Triton with kelp-wreathed hair", "webbed aquatic extremities"], "description": "Celebrated as a direct inspiration for Claude Debussy's symphonic tone poem La Mer, Arnold Böcklin's exuberant canvas plunges viewers directly to waterline level amid frolicking pelagic hybrids. A rotund, white-haired sea-centaur lunges clumsily after scattering mermaids while a ruddy, red-eyed Triton surfaces in the turbulent emerald foam with an infant sea-nymph held aloft."}, {"id": "am-10-haida-sea-bear-mask", "title": "Copper and Abalone Crest Mask of the Sea Bear", "creature": "Haida Sea Bear / Oceanic Predator Monster", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Sg̱aana / Taan (Sea-Bear)", "civilization": "Haida", "region": "The Americas & Oceania", "originLocation": "Haida Gwaii, British Columbia, Canada", "dateDisplay": "Late 19th century (c. 1870–1890)", "yearSort": 1885, "era": "Enlightenment & 19th Century", "medium": "Hammered native/trade sheet copper inlaid with Haliotis abalone shell and fur trim", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Marine & Abyssal Monsters", "creator": "Unknown 19th-century Haida metalworker", "repository": "The Metropolitan Museum of Art, New York (1979.206.830)", "commonsFile": "Sea_bear_mask.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Sea_bear_mask.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Sea_bear_mask.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5c/Sea_bear_mask.jpg", "anatomy": ["broad ursine snout and flared nostrils repoussé-worked in lustrous copper", "iridescent abalone-shell irises and bared predatory teeth", "amphibious marine ears and sea-mammal fur crest"], "description": "Hammered from prestigious sheet copper—the ultimate emblem of aristocratic wealth along the Pacific Northwest Coast—this rare Haida mask portrays the supernatural Sea Bear, cousin to the sea-wolf Wasgo (Gonakadet) that inhabits the abyssal trenches off Haida Gwaii. In flickering firelight, its iridescent abalone-shell eyes and teeth flash from the burnished copper surface, embodying the amphibious ocean spirits whose underwater houses mirrored chiefdom lineages ashore."}, {"id": "cn-07-qing-cixi-fenghuang-headdress", "title": "Imperial Ceremonial Headdress (Dianzi) with Pearl-Studded Fenghuang", "creature": "Fenghuang (Imperial Empress Phoenix)", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "點翠嵌珠后妃鳳鈿 (Fèngdiàn)", "civilization": "Qing Dynasty (Late Imperial Court)", "region": "East Asia & Eurasian Steppe", "originLocation": "Beijing, China", "dateDisplay": "Late 19th century CE", "yearSort": 1885, "era": "Enlightenment & 19th Century", "medium": "Gilt silver wire, kingfisher feathers (diancui), freshwater pearls, tourmaline, rubies, and jadeite", "mediumCategory": "Metalwork, Glyptic & Regalia", "morphology": "Avian & Winged Hybrids", "creator": "Qing Imperial Palace Workshops (attributed to regalia of Empress Dowager Cixi)", "repository": "Walters Art Museum, Baltimore", "commonsFile": "Chinese_-_Ceremonial_Headdress_-_Walters_863_-_Back.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Chinese_-_Ceremonial_Headdress_-_Walters_863_-_Back.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Chinese_-_Ceremonial_Headdress_-_Walters_863_-_Back.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4a/Chinese_-_Ceremonial_Headdress_-_Walters_863_-_Back.jpg", "anatomy": ["iridescent kingfisher-feather wings", "pearl-strung scrolling tail plumes", "jeweled avian crests", "trembling spring-mounted beaks holding pearl drops"], "description": "Associated with the court wardrobe of Empress Dowager Cixi, this sumptuous Manchu Qing dianzi headdress swarms with sculpted fenghuang phoenixes crafted from iridescent turquoise kingfisher feathers (diancui), gilt filigree, gemstones, and hundreds of luminous Manchurian pearls. Mounted on delicate wire springs that quivered with every movement of the wearer, the phoenixes proclaimed supreme female imperial authority."}, {"id": "jk-08-meiji-yoshitoshi-sojobo-tengu", "title": "Sōjōbō Instructs Young Yoshitsune in the Sword", "creature": "Daitengu Sōjōbō (King of the Tengu)", "creatureFamily": "Kitsune, Tengu, Kappa & Yōkai Metamorphs", "localName": "大天狗・鞍馬山僧正坊", "civilization": "Meiji Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Tokyo, Japan", "dateDisplay": "1886 CE (Meiji 19; later edition also issued 1897)", "yearSort": 1886, "era": "Enlightenment & 19th Century", "medium": "Polychrome woodblock print diptych (ōban tate-e nishiki-e)", "mediumCategory": "Manuscript & Print", "morphology": "Avian & Winged Hybrids", "creator": "Tsukioka Yoshitoshi", "repository": "National Gallery of Victoria, Melbourne / Los Angeles County Museum of Art", "commonsFile": "Yoshitoshi_Sojobo_Instructs_Yoshitsune_in_the_Sword.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Yoshitoshi_Sojobo_Instructs_Yoshitsune_in_the_Sword.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Yoshitoshi_Sojobo_Instructs_Yoshitsune_in_the_Sword.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4e/Yoshitoshi_Sojobo_Instructs_Yoshitsune_in_the_Sword.jpg", "anatomy": ["flowing white mane, beard, and stern avian-inflected ascetic visage", "yamabushi mountain-priest robes with miniature tokin pillbox cap", "feathered tengu fan (ha-uchiwa) and attendant crow-tengu acolytes"], "description": "Set amid nocturnal mists on sacred Mount Kurama north of Kyoto, Tsukioka Yoshitoshi's dramatic Meiji diptych portrays Sōjōbō, the immortal white-haired King of the Tengu, imparting secret swordsmanship to the exiled boy Minamoto no Yoshitsune (Ushiwakamaru). Wearing the pom-pommed cords and tiny black tokin cap of a Shugendō mountain ascetic while wielding a magical feathered fan, Sōjōbō embodies the mature daitengu ('greater tengu') alongside agile lesser tengu sparring in the pines. Yoshitoshi's crisp Meiji linework captures the uncanny dignity of Japan's martial mountain spirits."}, {"id": "am-10-new-ireland-malagan-mask", "title": "Malagan Ceremonial Mask of an Ancestral Bush and Sea Spirit", "creature": "Malagan Hybrid Spirit", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Malagan / Tatanua", "civilization": "Northern New Ireland (Melanesia)", "region": "The Americas & Oceania", "originLocation": "New Ireland, Bismarck Archipelago, Papua New Guinea", "dateDisplay": "19th century (collected 1887)", "yearSort": 1887, "era": "Enlightenment & 19th Century", "medium": "Carved Alstonia wood, lime, red ochre, charcoal pigment, plant fiber, and Turbo petholatus shell opercula", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown 19th-century New Ireland master carver", "repository": "Etnografiska museet, Stockholm", "commonsFile": "Malagan_funeral_mask,_New_Ireland,_Papua_New_Guinea,_1887_-_Etnografiska_museet_-_Stockholm,_Sweden_-_DSC00940.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Malagan_funeral_mask,_New_Ireland,_Papua_New_Guinea,_1887_-_Etnografiska_museet_-_Stockholm,_Sweden_-_DSC00940.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Malagan_funeral_mask,_New_Ireland,_Papua_New_Guinea,_1887_-_Etnografiska_museet_-_Stockholm,_Sweden_-_DSC00940.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/37/Malagan_funeral_mask,_New_Ireland,_Papua_New_Guinea,_1887_-_Etnografiska_museet_-_Stockholm,_Sweden_-_DSC00940.JPG", "anatomy": ["hypnotic green-eyed gaze formed from sea-snail shell opercula (Turbo petholatus)", "pierced openwork lateral ear-flanges intertwining avian and serpent motifs", "fierce fanged grimace crowned by a sculpted fiber crest"], "description": "Collected in northern New Ireland in 1887, this polychrome openwork wooden mask belonged to the culminating malagan mortuary cycle that liberated the spirits of the dead from the world of the living while transferring clan land and ritual copyrights. Set with luminous sea-snail operculum eyes and flanked by pierced wings of intertwined birds, snakes, and bush spirits (ruruh), such carvings served briefly as living skin-vessels for ancestral life-force before being ritually destroyed or relinquished."}, {"id": "eg-02-bamana-chiwara-headdress", "title": "Bamana Ci Wara (Chiwara) Sacred Antelope-Aardvark Crest Headdress", "creature": "Ci Wara ('Farming Wild Beast' — Divine Offspring of Sky and Cobra)", "creatureFamily": "Unicorns, Qilin & Sacred Horned Beasts", "localName": "Ci Wara Kun (Bamana: 'Head of the Farming Beast')", "civilization": "Bamana People (Mande Cultural Sphere)", "region": "Egypt & Africa", "originLocation": "Ségou or Beledougou region, Mali", "dateDisplay": "Late 19th century CE (c. 1880–1900)", "yearSort": 1890, "era": "Enlightenment & 19th Century", "medium": "Carved wood, brass tacks, metal strips, and plant fiber", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Bamana master blacksmith-sculptor (numu)", "repository": "Brooklyn Museum, New York (77.245.1)", "commonsFile": "Brooklyn_Museum_77.245.1_Dance_Headdress_Ci-wara_Kun.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_77.245.1_Dance_Headdress_Ci-wara_Kun.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Brooklyn_Museum_77.245.1_Dance_Headdress_Ci-wara_Kun.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/85/Brooklyn_Museum_77.245.1_Dance_Headdress_Ci-wara_Kun.jpg", "anatomy": ["soaring lyre-curved horns of the roan antelope symbolizing sprouting millet", "openwork zigzag mane tracing the solar path across the sky", "low-slung burrowing body and tapering snout of the aardvark and scaly pangolin"], "description": "Carved by a Bamana numu (blacksmith-sculptor) and lashed atop a woven basketry cap over a flowing raffia costume, this crest headdress honors Ci Wara—the mythical half-mortal, half-beast born from the primordial goddess Mousso Koroni and a cobra spirit who first taught humanity agriculture with his claws and digging stick. Combining upward-soaring roan antelope horns (sun and sky) with the earth-burrowing snout and back of an aardvark and pangolin (soil and water), male and female Ci Wara pairs danced across Mali's fields to bless tireless cultivators."}, {"id": "sa-09-bali-barong-ket-mask", "title": "Carved and Polychromed Sacred Wooden Mask of Barong Ket ('King of the Spirits')", "creature": "Barong Ket", "creatureFamily": "Sacred Guardian Lions, Bixie, Yali & Tigers", "localName": "Barong Ket / Banaspati Raja", "civilization": "Balinese Hindu Tradition (Indonesia)", "region": "South & Southeast Asia", "originLocation": "Bali, Indonesia", "dateDisplay": "late 19th century CE (collected before 1937)", "yearSort": 1890, "era": "Enlightenment & 19th Century", "medium": "Carved pule wood mask painted in red, black, white, and gold leaf with leather and hair attachments", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Balinese master mask-carver (Undagi Tapel)", "repository": "Wereldmuseum Amsterdam (formerly Tropenmuseum, TMnr 1116-1a-1)", "commonsFile": "COLLECTIE_TROPENMUSEUM_Houten_masker_van_Barong_Ket_TMnr_1116-1a-1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:COLLECTIE_TROPENMUSEUM_Houten_masker_van_Barong_Ket_TMnr_1116-1a-1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/COLLECTIE_TROPENMUSEUM_Houten_masker_van_Barong_Ket_TMnr_1116-1a-1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/92/COLLECTIE_TROPENMUSEUM_Houten_masker_van_Barong_Ket_TMnr_1116-1a-1.jpg", "anatomy": ["bulging round eyes and crimson leonine snout set with curved fangs", "hinged snapping lower jaw for ritual clacking during temple drama", "gilded leather scrollwork ears and towering floral-flamed crown"], "description": "Carved from sacred pule wood and heightened with vermilion lacquer, gold leaf, and pierced leather ornaments, this Balinese ritual mask forms the expressive head of Barong Ket (Banaspati Raja, 'Lord of the Forest'), the lion-like protective spirit king animated by two dancers in temple courtyard performances. Locked in perpetual cosmic equilibrium against Rangda, the fanged queen of witches and leyak spirits, Barong Ket safeguards Balinese villages against pestilence and sorcery."}, {"id": "jk-08-meiji-yoshitoshi-kiyohime", "title": "Kiyohime Changing into a Serpent at Hidaka River", "creature": "Kiyohime (Jealous Dragon-Serpent Woman)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "清姫 (新形三十六怪撰 清姫日高川に蛇躰と成るの図)", "civilization": "Meiji Japan", "region": "East Asia & Eurasian Steppe", "originLocation": "Tokyo, Japan", "dateDisplay": "1890 CE (Meiji 23, January)", "yearSort": 1890, "era": "Enlightenment & 19th Century", "medium": "Polychrome woodblock print (ōban tate-e nishiki-e)", "mediumCategory": "Manuscript & Print", "morphology": "Draconic & Serpentine", "creator": "Tsukioka Yoshitoshi", "repository": "Los Angeles County Museum of Art / British Museum (multiple impressions)", "commonsFile": "Yoshitoshi_Kiyohime.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Yoshitoshi_Kiyohime.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Yoshitoshi_Kiyohime.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/50/Yoshitoshi_Kiyohime.jpg", "anatomy": ["coiling scaled serpent tail emerging from soaked, scale-patterned kimono", "pale demonic visage with wild streaming hair drenched in rain", "draconic claws gripping the stone stairs above the Hidaka River"], "description": "Created for Tsukioka Yoshitoshi's final masterwork series New Forms of Thirty-Six Ghosts (Shinkei Sanjūrokkaisen), this haunting vertical print illustrates the climax of the Dōjō-ji legend, in which the spurned maiden Kiyohime's consuming rage transforms her into a fire-breathing dragon-serpent as she swims the flooded Hidaka River after the monk Anchin. Yoshitoshi subtly fuses woman and reptile: her drenched blue robe clings like fish scales to her limbs while a sinuous serpent tail coils up the stone embankment behind her. Slanted silver-gray rain lines heighten the psychological intensity of late Meiji supernatural printmaking."}, {"id": "eg-02-nalu-baga-serpent-crest", "title": "Nalu-Baga Sacred Rainbow-Python Crest Mask (Mbanchong / Bansonyi)", "creature": "Ninkinanka / Bansonyi (Towering Aquatic Rainbow-Python Spirit)", "creatureFamily": "Dragons, Feathered Serpents, Nāgas & Cosmic Wyrms", "localName": "Mbanchong (Nalu) / A-Mantsho-ña-Tshol or Bansonyi (Baga)", "civilization": "Nalu and Baga Peoples (Upper Guinea Coast)", "region": "Egypt & Africa", "originLocation": "Coastal mangrove estuaries of Guinea", "dateDisplay": "Late 19th century CE", "yearSort": 1890, "era": "Enlightenment & 19th Century", "medium": "Carved wood with polychrome red, white, and black earth pigments", "mediumCategory": "Sculpture & Relief", "morphology": "Draconic & Serpentine", "creator": "Nalu-Baga ritual sculptor", "repository": "Musée du Quai Branly – Jacques Chirac (displayed at Pavillon des Sessions, Palais du Louvre, Paris)", "commonsFile": "Guinea,_nalu,_parte_superiore_di_una_maschera_mbanchong_a_forma_di_serpente,_xix-inizio_xx_sec._01.JPG", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Guinea,_nalu,_parte_superiore_di_una_maschera_mbanchong_a_forma_di_serpente,_xix-inizio_xx_sec._01.JPG", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Guinea,_nalu,_parte_superiore_di_una_maschera_mbanchong_a_forma_di_serpente,_xix-inizio_xx_sec._01.JPG?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/9/9b/Guinea,_nalu,_parte_superiore_di_una_maschera_mbanchong_a_forma_di_serpente,_xix-inizio_xx_sec._01.JPG", "anatomy": ["towering vertical undulating serpent column painted with geometric chevrons", "horned, narrow-snouted python head poised to strike from above", "hollowed basal socket fitted over an initiate dancer's shoulders"], "description": "Rising up to two meters vertically above a raffia-shrouded dancer during generational initiation cycles along Guinea's mangrove coast, this polychrome crest carving embodies the formidable water-and-rainbow python spirit revered by Nalu and Baga communities as Mbanchong, Bansonyi, or Ninkinanka. As paired serpent towers swayed and darted above village rooftops like rival lineage guardians emerging from sacred forest pools, they mediated rain, fertility, and cosmic balance between riverine spirits and human society."}, {"id": "rn-06-waterhouse-ulysses-sirens", "title": "Ulysses and the Sirens", "creature": "Homeric Avian Sirens", "creatureFamily": "Sirens, Harpies, Kinnara & Avian-Humans", "localName": "Sirens (Seirēnes)", "civilization": "British Pre-Raphaelite / Victorian Classicism", "region": "Renaissance & Early Modern Europe", "originLocation": "London, United Kingdom", "dateDisplay": "1891 CE", "yearSort": 1891, "era": "Enlightenment & 19th Century", "medium": "Oil on canvas", "mediumCategory": "Painting & Fresco", "morphology": "Avian & Winged Hybrids", "creator": "John William Waterhouse", "repository": "National Gallery of Victoria, Melbourne", "commonsFile": "John_William_Waterhouse_-_Ulysses_and_the_Sirens_-_Google_Art_Project.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:John_William_Waterhouse_-_Ulysses_and_the_Sirens_-_Google_Art_Project.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/John_William_Waterhouse_-_Ulysses_and_the_Sirens_-_Google_Art_Project.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/f/f2/John_William_Waterhouse_-_Ulysses_and_the_Sirens_-_Google_Art_Project.jpg", "anatomy": ["alluring female heads and cascading hair", "dark iridescent raptor bodies and wings", "curved bird-of-prey talons gripping gunwales", "spread feathered tail fans"], "description": "Breaking decisively with post-medieval mermaid conventions, John William Waterhouse consulted an archaic Greek red-figure stamnos in the British Museum to restore the Homeric Sirens to their authentic classical form as predatory human-headed birds. Seven dark-winged hybrids swoop around the mast-bound Odysseus and perch along the ship's oars, chanting directly into the wax-sealed ears of his straining crew."}, {"id": "am-10-inuit-tupilaq-ivory", "title": "Carved Marine Ivory Tupilaq (Avenging Spirit Monster)", "creature": "Tupilaq", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Tupilaq", "civilization": "Kalaallit (Greenlandic Inuit)", "region": "The Americas & Oceania", "originLocation": "East / West Greenland", "dateDisplay": "Late 19th–early 20th century (c. 1885–1905)", "yearSort": 1895, "era": "Enlightenment & 19th Century", "medium": "Carved sperm-whale tooth or walrus tusk ivory", "mediumCategory": "Sculpture & Relief", "morphology": "Giants, Demons & Spirits", "creator": "Unknown Kalaallit (East Greenlandic) carver", "repository": "Nunatta Katersugaasivia Allagaateqarfialu (Greenland National Museum and Archives), Nuuk", "commonsFile": "Tupilak_1.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Tupilak_1.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Tupilak_1.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/2a/Tupilak_1.jpg", "anatomy": ["grotesque grimacing head with hollowed sockets and bared teeth", "exposed skeletal ribcage fused with seal, bird, and human limbs", "compact hand-held form carved to materialize an invisible shamanic construct"], "description": "In traditional Kalaallit belief, a tupilaq was a perishable avenging monster secretly assembled by a sorcerer from mismatched animal bones, sinew, peat, and hide, brought to life through chant, and launched into the icy sea to hunt down a rival—though a stronger shaman could turn the creature back to devour its maker. Because real ritual tupilait were never seen by uninitiated eyes, late 19th-century East Greenlanders carved dense walrus and whale ivory sculptures like this specimen to show early ethnographers what the terrifying spirit-chimeras looked like."}, {"id": "eg-02-senufo-kponyugo-mask", "title": "Senufo Kponyugo ('Firespitter') Composite Poro Society Helmet Mask", "creature": "Kponyugo (Primordial Bush-Chaos Monster)", "creatureFamily": "Chimeras, Ammit, Manticores & Composite Hybrids", "localName": "Kponyugo / Kunugbaha ('Head of the Poro')", "civilization": "Senufo People", "region": "Egypt & Africa", "originLocation": "Northern Côte d'Ivoire (Korhogo region)", "dateDisplay": "Late 19th–very early 20th century CE (c. 1890–1904)", "yearSort": 1895, "era": "Enlightenment & 19th Century", "medium": "Monoxylous carved hardwood", "mediumCategory": "Sculpture & Relief", "morphology": "Composite Chimeras", "creator": "Senufo master woodcarver (kulebele)", "repository": "Brooklyn Museum, New York (1990.220)", "commonsFile": "Brooklyn_Museum_1990.220_Firespitter_Helmet_Mask_Kponyugo.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_1990.220_Firespitter_Helmet_Mask_Kponyugo.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Brooklyn_Museum_1990.220_Firespitter_Helmet_Mask_Kponyugo.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/49/Brooklyn_Museum_1990.220_Firespitter_Helmet_Mask_Kponyugo.jpg", "anatomy": ["gaping crocodile-hyena jaws bristling with carved teeth", "upturned warthog tusks jutting from the upper snout", "sweeping bushbuck antelope horns framing the domed cranium", "primordial chameleon and hornbill perched atop the helmet"], "description": "Worn horizontally over the masquerader's head during Poro men's initiation funerals and nocturnal anti-witchcraft rites, the Kponyugo synthesizes the deadliest and most magically potent animals of the West African savanna into a single terrifying chimera. Combining hyena-crocodile jaws, warthog tusks, antelope horns, and a cranial chameleon—first creature to tread the newly formed earth in Senufo cosmology—these masks earned the colonial sobriquet 'firespitters' because performers blew glowing embers and burning tinder through their fanged maws into the night."}, {"id": "am-10-maori-marakihau-wairaka", "title": "Carved Amo Post of the Sea-Taniwha Marakihau at Wairaka Wharenui", "creature": "Marakihau (Tubular-Tongued Sea Taniwha)", "creatureFamily": "Leviathans, Makaras, Kraken & Abyssal Merfolk", "localName": "Marakihau", "civilization": "Māori (Ngāti Awa)", "region": "The Americas & Oceania", "originLocation": "Wairaka Marae, Whakatāne, Bay of Plenty, Aotearoa (New Zealand)", "dateDisplay": "Carved c. 1894–1898 (photographed c. 1900)", "yearSort": 1898, "era": "Enlightenment & 19th Century", "medium": "Relief-carved tōtara wood architectural upright (amo); historic glass-plate negative", "mediumCategory": "Sculpture & Relief", "morphology": "Marine & Abyssal Monsters", "creator": "Teira Te Ngarara and Wepiha Apanui (Ngāti Awa master carvers)", "repository": "Wairaka Marae, Whakatāne (archival image: Alexander Turnbull Library, Wellington, 1/2-019091-G)", "commonsFile": "Exterior_view_of_Wairaka_Meeting_House,_Whakatane,_showing_the_marakihau_(mermaid)_carving_on_the_left_amo_ATLIB_291936.png", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Exterior_view_of_Wairaka_Meeting_House,_Whakatane,_showing_the_marakihau_(mermaid)_carving_on_the_left_amo_ATLIB_291936.png", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Exterior_view_of_Wairaka_Meeting_House,_Whakatane,_showing_the_marakihau_(mermaid)_carving_on_the_left_amo_ATLIB_291936.png?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/5/5a/Exterior_view_of_Wairaka_Meeting_House,_Whakatane,_showing_the_marakihau_(mermaid)_carving_on_the_left_amo_ATLIB_291936.png", "anatomy": ["humanoid upper torso and horned head adorned with spiral surface patterning", "long coiled fish tail replacing the lower limbs", "hollow funnel-like tubular tongue (ngongo) sucking in fish and canoes"], "description": "Carved in the 1890s by Ngāti Awa masters Teira Te Ngarara and Wepiha Apanui for the front porch upright (amo) of Wairaka meeting house in Whakatāne, this renowned panel portrays a marakihau—a formidable marine taniwha of eastern Bay of Plenty tradition. Sporting a sinuous coiled fish tail, horned brow, and an elongated hollow funnel-tongue (ngongo), the ocean guardian could inhale entire schools of fish or draw passing waka canoes down into submarine caverns."}, {"id": "am-10-kwakwakawakw-crooked-beak-hokhokw", "title": "Hamatsa Masks of Crooked Beak of Heaven (Galokwudzuwis) and Hokhokw", "creature": "Cannibal Sky-Bird Monsters of Baxwbakwalanuksiwe'", "creatureFamily": "Phoenix, Simurgh, Garuda & Solar Birds", "localName": "Galokwudzuwis & Huxwhukw", "civilization": "Kwakwaka'wakw", "region": "The Americas & Oceania", "originLocation": "Alert Bay, Vancouver Island, British Columbia, Canada", "dateDisplay": "c. 1900", "yearSort": 1900, "era": "Enlightenment & 19th Century", "medium": "Carved and painted red cedar wood, shredded red cedar bark, eagle feathers, and cordage", "mediumCategory": "Sculpture & Relief", "morphology": "Avian & Winged Hybrids", "creator": "Yakuglas (Charlie James, c. 1867–1938)", "repository": "Portland Art Museum, Oregon", "commonsFile": "Crooked_beak_mask_and_Huxwhukw_mask,_by_Yakuglas_Charlie_James_(1875-1938),_Kwakwka'wakw,_c._1900,_red_cedar,_red_cedar_bark,_feathers,_paint,_string_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC09113.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Crooked_beak_mask_and_Huxwhukw_mask,_by_Yakuglas_Charlie_James_(1875-1938),_Kwakwka'wakw,_c._1900,_red_cedar,_red_cedar_bark,_feathers,_paint,_string_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC09113.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Crooked_beak_mask_and_Huxwhukw_mask,_by_Yakuglas_Charlie_James_(1875-1938),_Kwakwka'wakw,_c._1900,_red_cedar,_red_cedar_bark,_feathers,_paint,_string_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC09113.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/3/3e/Crooked_beak_mask_and_Huxwhukw_mask,_by_Yakuglas_Charlie_James_(1875-1938),_Kwakwka'wakw,_c._1900,_red_cedar,_red_cedar_bark,_feathers,_paint,_string_-_Portland_Art_Museum_-_Portland,_Oregon_-_DSC09113.jpg", "anatomy": ["extravagantly curved and scrolled upper beak of Galokwudzuwis", "elongated crane-like skull-cracking beak of Huxwhukw", "hinged clapping lower mandibles framed by blood-red shredded cedar bark"], "description": "Carved around 1900 by the renowned Kwakwaka'wakw master Yakuglas (Charlie James), this dramatic pair of articulated cedar masks embodies two monstrous avian attendants of Baxwbakwalanuksiwe' ('Man-Eater at the North End of the World') in the sacred Hamatsa winter initiation dance. Draped in dyed-red cedar bark and manipulated with hidden cords so their massive wooden mandibles snap thunderously in rhythm with the drums, Huxwhukw cracks human skulls with its lance-like bill while Galokwudzuwis ('Crooked Beak of Heaven') devours flesh from the sky realm."}, {"id": "rn-06-redon-the-cyclops", "title": "The Cyclops (Le Cyclope)", "creature": "Cyclops Polyphemus", "creatureFamily": "Cyclopes, Oni, Divs, Giants & Underworld Demons", "localName": "Le Cyclope", "civilization": "French Symbolism", "region": "Renaissance & Early Modern Europe", "originLocation": "Paris, France", "dateDisplay": "c. 1898–1914 CE", "yearSort": 1900, "era": "Enlightenment & 19th Century", "medium": "Oil on cardboard mounted on wood panel", "mediumCategory": "Painting & Fresco", "morphology": "Giants, Demons & Spirits", "creator": "Odilon Redon", "repository": "Kröller-Müller Museum, Otterlo, Netherlands", "commonsFile": "Odilon_Redon_-_The_Cyclops,_c._1914.jpg", "commonsUrl": "https://commons.wikimedia.org/wiki/File:Odilon_Redon_-_The_Cyclops,_c._1914.jpg", "thumbUrl": "https://commons.wikimedia.org/wiki/Special:FilePath/Odilon_Redon_-_The_Cyclops,_c._1914.jpg?width=640", "fullImageUrl": "https://upload.wikimedia.org/wikipedia/commons/b/be/Odilon_Redon_-_The_Cyclops,_c._1914.jpg", "anatomy": ["single enormous liquid central eye", "domed bulbous cranium rising behind a ridge", "hulking earth-toned giant shoulders", "gentle melancholic expression"], "description": "Conceived around the turn of the century as Odilon Redon transitioned from his dark charcoal 'noirs' to luminous pastel and oil color, Le Cyclope reimagines Ovid's monstrous giant Polyphemus as a shy, dreamlike watcher. Rising like a living mountain ridge behind a shimmering meadow of wildflowers where the sea-nymph Galatea sleeps, the giant's huge single eye radiates tender, unrequited longing rather than menace."}]};
